fn main() {
    let input = HashMap::from([
        ("a".to_string(), vec![1, 2, 3]),
        ("b".to_string(), vec![4, 5]),
        ("c".to_string(), vec![10]),
    ]);

    let output = sum_sequences(&input);
    println!("{:?}", output); // Output: {"a": 6, "b": 9, "c": 10}
}
```

