use polars::prelude::*;

/// Extract all entries from column named "a" in `df` and return them as a Vec<Option<String>>.
/// - Returns an Err(PolarsError) if column "a" does not exist.
/// - Each element is Some(stringified_value) or None for nulls.
fn extract_column_a_as_strings(df: &DataFrame) -> PolarsResult<Vec<Option<String>>> {
    // get the series named "a"
    let series = df.column("a")?;

    let len = series.len();
    let mut out = Vec::with_capacity(len);

    for i in 0..len {
        let any = series.get(i);
        match any {
            AnyValue::Null => out.push(None),
            // Format the AnyValue into a string for a generic representation.
            other => out.push(Some(format!("{}", other))),
        }
    }

    Ok(out)
}

fn main() -> PolarsResult<()> {
    // Example: build a DataFrame with a few types and nulls
    let s_a = Series::new("a", &["apple", "banana", "cherry"]);
    let s_b = Series::new("b", &[1i32, 2, 3]);

    let df = DataFrame::new(vec![s_a, s_b])?;

    let values = extract_column_a_as_strings(&df)?;
    println!("{:?}", values); // prints: [Some("apple"), Some("banana"), Some("cherry")]

    // Example with nulls and mixed types (will stringize values)
    let s_a2 = Series::new("a", &[Some("x"), None, Some("z")]);
    let s_b2 = Series::new("b", &[10i64, 20, 30]);
    let df2 = DataFrame::new(vec![s_a2, s_b2])?;

    let values2 = extract_column_a_as_strings(&df2)?;
    println!("{:?}", values2); // prints: [Some("x"), None, Some("z")]

    Ok(())
}
```

Notes:
- This implementation stringifies each non-null cell. This is convenient when the column type is unknown or mixed and you want a single return type.
- If you want a strongly-typed return (e.g., Vec<Option<i64>> or Vec<Option<String>>), you can access the column as a typed ChunkedArray (e.g., series.i64()? or series.utf8()?) and collect accordingly.

