/// Replaces every group of one or more consecutive '*' characters with a single '*'.
///
/// This implementation uses only the standard library.
pub fn collapse_asterisks(text: &str) -> String {
    let mut result = String::with_capacity(text.len());
    let mut prev_was_star = false;

    for ch in text.chars() {
        if ch == '*' {
            if !prev_was_star {
                result.push('*');
                prev_was_star = true;
            }
        } else {
            result.push(ch);
            prev_was_star = false;
        }
    }

    result
}
```

