/// let result = filter_out_common(&a, &b);
/// assert_eq!(result, vec![1, 4]);
/// ```
pub fn filter_out_common<T, Q>(collection1: &[T], collection2: &[T]) -> Vec<T>
where
    T: Ord + std::hash::Hash + Clone,
    Q: std::hash::BuildHasher + Default,
{
    collection1
        .iter()
        .filter(|x| !collection2.contains(x))
        .cloned()
        .collect()
}

