where
    T: Ord + Clone,
    Q: std::hash::BuildHasher + Default,
{
    collection1
        .iter()
        .cloned()
        .sorted()
        .unique()
        .difference(collection2.iter().cloned().sorted().unique())
        .cloned()
        .collect()
}
