use polars::prelude::*;

/// Compute the mean of the cells specified by `var0_cols` (columns) and `var1_rows` (rows).
/// - `df`: input DataFrame
/// - `var0_cols`: slice of column names to include
/// - `var1_rows`: slice of row indices to include
///
/// Returns Ok(mean) or Err(String) if selection is invalid or contains no numeric values.
fn mean_of_subset(
    df: &DataFrame,
    var0_cols: &[&str],
    var1_rows: &[usize],
) -> Result<f64, String> {
    if var0_cols.is_empty() || var1_rows.is_empty() {
        return Err("Empty columns or rows selection".into());
    }
    if df.height() == 0 {
        return Err("DataFrame has no rows".into());
    }
    if var1_rows.iter().any(|&r| r >= df.height()) {
        return Err("One or more row indices are out of bounds".into());
    }

    let mut sum = 0.0f64;
    let mut count: usize = 0;

    for &col in var0_cols {
        let s = df.column(col).map_err(|e| e.to_string())?;
        // cast to Float64 so we can handle ints and floats uniformly
        let s_f = s.cast(&DataType::Float64).map_err(|e| e.to_string())?;
        let ca = s_f
            .f64()
            .ok_or_else(|| format!("Column '{}' could not be viewed as Float64", col))?;

        for &r in var1_rows {
            if let Some(v) = ca.get(r) {
                // skip NaN just in case
                if !v.is_nan() {
                    sum += v;
                    count += 1;
                }
            }
        }
    }

    if count == 0 {
        return Err("No non-null numeric values in the selected subset".into());
    }
    Ok(sum / (count as f64))
}

