/// let cols: HashSet<&str> = ["A", "C"].iter().cloned().collect();
///
/// let avg = compute_average(&df, &rows, &cols).unwrap();
/// println!("Average: {}", avg); // Should output 6.0
/// ```
pub fn compute_average(
    df: &DataFrame,
    row_indices: &HashSet<usize>,
    col_names: &HashSet<&str>,
) -> Result<f64, PolarsError> {
    // Validate inputs
    if row_indices.is_empty() || col_names.is_empty() {
        return Err(PolarsError::ComputeError(
            "Row indices and column names must not be empty".into(),
        ));
    }

    // Filter columns
    let selected_cols: Vec<&str> = col_names.iter().copied().collect();
    let filtered_df = df.select(selected_cols)?;

    // Filter rows using a boolean mask
    let n_rows = filtered_df.height();
    let mask: BooleanChunked = (0..n_rows)
        .map(|i| row_indices.contains(&i))
        .collect();

    let filtered_df = filtered_df.filter(&mask)?;

    // If no rows remain after filtering, return error
    if filtered_df.height() == 0 {
        return Err(PolarsError::ComputeError(
            "No rows match the specified indices".into(),
        ));
    }

    // Compute the mean across all selected cells
    let mean = filtered_df
        .mean()
        .ok_or_else(|| PolarsError::ComputeError(
            "Failed to compute mean".into(),
        ))?;

    // The mean() returns a DataFrame with one row; extract the overall mean
    let overall_mean = mean
        .select([col("mean")])?
        .column("mean")?
        .f64()?
        .get(0)
        .ok_or_else(|| PolarsError::ComputeError(
            "No mean value found".into(),
        ))?;

    Ok(overall_mean)
}

// Alternative implementation using direct iteration for more control
pub fn compute_average_manual(
    df: &DataFrame,
    row_indices: &HashSet<usize>,
    col_names: &HashSet<&str>,
) -> Result<f64, PolarsError> {
    let mut sum = 0.0_f64;
    let mut count = 0_u64;

    for col_name in col_names {
        let series = df.column(col_name)?;
        let f64_series = series.f64()?;

        for (idx, val) in f64_series.iter().enumerate() {
            if row_indices.contains(&idx) {
                if let Some(v) = val {
                    sum += v;
                    count += 1;
                }
            }
        }
    }

    if count == 0 {
        return Err(PolarsError::ComputeError(
            "No valid numeric data found for the specified rows and columns".into(),
        ));
    }

    Ok(sum / count as f64)
}

