use polars::prelude::*;

/// Compute the average of specified rows and columns in a tabular dataset
/// 
/// # Arguments
/// * `df` - A Polars DataFrame containing the data
/// * `row_indices` - Vector of row indices to include in the average
/// * `column_names` - Vector of column names to include in the average
///
/// # Returns
/// * `Result<f64>` - The computed average value
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "A" => &[1, 2, 3, 4],
///     "B" => &[5, 6, 7, 8],
///     "C" => &[9, 10, 11, 12],
/// }?;
///
/// let rows = vec![0, 2];
/// let cols = vec!["A", "B"];
/// let avg = compute_average(&df, rows, cols)?;
/// println!("Average: {}", avg);
/// # Ok::<(), PolarsError>(())
/// ```
fn compute_average(
    df: &DataFrame,
    row_indices: Vec<usize>,
    column_names: Vec<&str>,
) -> Result<f64, PolarsError> {
    // Filter the DataFrame to specified columns
    let selected_df = df.select(column_names)?;

    // Collect all values from specified rows and columns
    let mut values = Vec::new();

    for col_series in selected_df.iter() {
        for &row_idx in &row_indices {
            if let Some(value) = col_series.get(row_idx) {
                // Try to extract as f64
                if let Ok(num) = value.try_extract::<f64>() {
                    values.push(num);
                }
            }
        }
    }

    // Compute average
    if values.is_empty() {
        return Ok(0.0);
    }

    let sum: f64 = values.iter().sum();
    let average = sum / values.len() as f64;

    Ok(average)
}

