/// // │ 20   ┆ 20   │
/// // │ 3    ┆ 30   │
/// // │ 40   ┆ 40   │
/// // └──────┴──────┘
/// ```
pub fn fill_missing_from_column(
    data0: &DataFrame,
    col0: &str,
    col1: &str,
) -> Result<DataFrame> {
    // Get the two columns as series
    let series0 = data0.column(col0)?;
    let series1 = data0.column(col1)?;

    // Create a boolean mask for null values in col0
    let null_mask = series0.is_null();

    // Use the mask to select values from col1 where col0 is null
    let replacement_values = series1.filter(&null_mask)?;

    // Replace null values in col0 with the selected values from col1
    let filled_series = series0.fill_null(&replacement_values)?;

    // Replace the original column in the DataFrame
    let mut result = data0.clone();
    result.replace(col0, filled_series)?;

    Ok(result)
}

