/// Given an input list of characters, produce a list containing only the characters
/// that immediately follow each slash symbol in the input list.
fn chars_following_slash(input: &[char]) -> Vec<char> {
    // Create a streaming iterator from the input slice
    let mut iter = streaming_iterator::convert(input.iter());

    let mut result = Vec::new();

    while let Some(&current_char) = iter.next() {
        if current_char == '/' {
            // If the current character is a slash, check if there is a next character
            if let Some(&next_char) = iter.peek() {
                result.push(next_char);
                // Move the iterator to the next character to skip it
                iter.next();
            }
        }
    }

    result
