```rust
use ndarray::{Array, ArrayD, IxDyn, s};

/// Deletes elements from an n-dimensional array along a specified dimension,
/// removing every var0-th element.
///
/// # Arguments
/// * `arr0` - The input n-dimensional array
/// * `var0` - The step size (every var0-th element is removed)
/// * `var1` - The dimension along which to remove elements (0-indexed)
///
/// # Returns
/// A new array with elements removed along the specified dimension
///
/// # Panics
/// Panics if var1 is out of bounds for the array dimensions
pub fn delete_elements<T: Clone>(
    arr0: &ArrayD<T>,
    var0: usize,
    var1: usize,
) -> ArrayD<T> {
    assert!(var1 < arr0.ndim(), "Dimension {} out of bounds", var1);
    assert!(var0 > 0, "Step size must be greater than 0");

    let dim_size = arr0.dim()[var1];

    // Create a mask for indices to keep (every var0-th element is skipped)
    let indices_to_keep: Vec<usize> = (0..dim_size)
        .filter(|i| (i + 1) % var0 != 0)
        .collect();

    if indices_to_keep.is_empty() {
        // Return empty array with appropriate shape
        let mut new_shape = arr0.dim().to_vec();
        new_shape[var1] = 0;
        return Array::zeros(IxDyn(&new_shape));
    }

    // Build the result by stacking slices along the dimension
    let mut result_slices = Vec::new();

    for &idx in &indices_to_keep {
        let mut slice_spec = vec![s![..]; arr0.ndim()];
        slice_spec[var1] = s![idx];
        let slice = arr0.slice(&slice_spec.iter().map(|s| *s).collect::<Vec<_>>());
        result_slices.push(slice);
    }

    // Stack the slices back together along the specified dimension
    ndarray::stack(
        ndarray::Axis(var1),
        &result_slices.iter().map(|s| s.view()).collect::<Vec<_>>(),
    )
    .expect("Failed to stack slices")
}

