/// produce a Vec of maps [{ "key1": a0, "key2": b0 }, { "key1": a1, "key2": b1 }, ...].
///
/// Returns Err(...) if either key is missing or the two sequences have different lengths.
pub fn pairwise_maps<T: Clone>(
    input: &HashMap<String, Vec<T>>,
) -> Result<Vec<HashMap<String, T>>, String> {
    let a = input
        .get("key1")
        .ok_or_else(|| "input missing key 'key1'".to_string())?;
    let b = input
        .get("key2")
        .ok_or_else(|| "input missing key 'key2'".to_string())?;

    if a.len() != b.len() {
