Example code:

```rust
// Add this to Cargo.toml:
// [dependencies]
// rand = "0.8"
// rand_xoshiro = "0.6"

use rand::{RngCore, SeedableRng};
use rand_xoshiro::Xoshiro256PlusPlus;

/// Generate a sequence of `len` i32 integers that includes duplicate values.
/// - For len >= 2, duplicates are guaranteed (we draw from only len-1 distinct values).
/// - For len == 0, returns an empty Vec.
/// - For len == 1, returns a single value (duplicates are impossible with length 1).
pub fn generate_with_duplicates(len: usize) -> Vec<i32> {
    if len == 0 {
        return Vec::new();
    }
    if len == 1 {
        return vec![0];
    }

    // Seed the xoshiro RNG using thread_rng to get entropy
    let mut seed = [0u8; 32];
    rand::thread_rng().fill_bytes(&mut seed);
    let mut rng = Xoshiro256PlusPlus::from_seed(seed);

    // Use only `len - 1` distinct values (0..len-2 inclusive), so duplicates are guaranteed.
    let domain_size = (len - 1) as u32;
    let mut out = Vec::with_capacity(len);
    for _ in 0..len {
        // Use next_u32 and reduce modulo domain_size to get a value in 0..domain_size-1.
        // domain_size >= 1 here because len >= 2.
        let val = (rng.next_u32() % domain_size) as i32;
        out.push(val);
    }
    out
}

fn main() {
    let len = 10;
    let seq = generate_with_duplicates(len);
    println!("Generated sequence (len={}): {:?}", len, seq);

    // Quick check: detect whether there is at least one duplicate (should be true for len>=2)
    let mut seen = std::collections::HashSet::new();
    let has_dup = seq.iter().any(|x| !seen.insert(x));
    println!("Contains duplicate? {}", has_dup);
