/// let filtered = filter_ab(&items);
/// assert_eq!(filtered, vec!["hello", "world", "test"]);
/// ```
pub fn filter_ab<'a>(items: &[&'a str]) -> Vec<&'a str> {
    items
        .iter()
        .copied()
        .filter(|item| !contains_ab(item))
        .collect()
}

/// Checks if a string contains the substring "ab" using a sliding window approach.
/// 
/// This is more efficient than using `contains()` for very short patterns
/// as it avoids the overhead of more complex substring search algorithms.
fn contains_ab(s: &str) -> bool {
    let bytes = s.as_bytes();
    let len = bytes.len();

    // Need at least 2 characters to contain "ab"
    if len < 2 {
        return false;
    }

    // Check each adjacent pair of bytes
    for i in 0..len - 1 {
        if bytes[i] == b'a' && bytes[i + 1] == b'b' {
            return true;
        }
    }

    false
}

