fn reorder_rows_by_name_sequence(df: &DataFrame, name_sequence: &[&str]) -> Result<DataFrame> {
    // Create a mapping from name to its index in the provided sequence
    let name_to_index: std::collections::HashMap<&str, usize> = 
        name_sequence.iter().enumerate().map(|(idx, &name)| (name, idx)).collect();

    // Create a new column with the indices based on the name sequence
    let mut indices = Vec::with_capacity(df.height());
    for name in df.column("name")?.utf8()? {
        match name {
            Some(name) => {
                if let Some(&index) = name_to_index.get(name) {
                    indices.push(index);
                } else {
                    // If a name in the DataFrame is not found in the sequence, return an error
                    return Err(PolarsError::ComputeError(
                        format!("Name '{}' not found in the provided sequence", name).into(),
                    ));
                }
            },
            None => {
                // If there is a null value in the 'name' column, return an error
                return Err(PolarsError::ComputeError(
                    "Null value found in the 'name' column".into(),
                ));
            },
        }
    }

    // Convert the indices vector into a Series
    let indices_series = Series::new("reorder_indices", indices);

    // Create a DataFrame with the indices series
    let indices_df = DataFrame::new(vec![indices_series])?;

    // Concatenate the original DataFrame with the indices DataFrame
    let mut df_with_indices = df.clone();
    df_with_indices.hstack(&[&indices_df])?;

    // Sort the DataFrame by the 'reorder_indices' column
    let sorted_df = df_with_indices.sort(["reorder_indices"], false)?;

