pub fn reorder_by_name(df: &DataFrame, order: &[&str]) -> PolarsResult<DataFrame> {
    // Build a lookup map from name -> desired index (0-based).
    let order_map: HashMap<&str, i32> =
        order.iter().enumerate().map(|(i, &s)| (s, i as i32)).collect();

    // Ensure there is a "name" column and obtain it as utf8.
