pub fn reorder_by_name_list(df: &DataFrame, name_order: &[&str]) -> Result<DataFrame, PolarsError> {
    // Check if "name" column exists
    if !df.get_column_names().contains(&"name") {
        return Err(PolarsError::ComputeError(
            "DataFrame must contain a 'name' column".into(),
        ));
    }

    // Create a mapping from name to its desired position
    let name_to_position: HashMap<&str, usize> = name_order
        .iter()
        .enumerate()
        .map(|(i, name)| (*name, i))
        .collect();

    // Add a temporary column with the sort order
    let df_with_order = df
        .lazy()
        .with_column(
            when(col("name").map(
                move |s| {
                    let ca = s.str()?;
                    let out: UInt32Chunked = ca
                        .into_iter()
                        .map(|opt_name| {
                            opt_name.and_then(|name| {
                                name_to_position.get(name).map(|&pos| pos as u32)
                            })
                        })
                        .collect();
                    Ok(Some(out.into_series()))
                },
                GetOutput::from_type(DataType::UInt32),
            ))
            .otherwise(lit(u32::MAX))
            .alias("__sort_order__"),
        )
        .collect()?;

    // Sort by the temporary column and remove it
    let result = df_with_order
        .sort(["__sort_order__"], SortMultipleOptions::default())
        .unwrap()
        .drop("__sort_order__")?;

    Ok(result)
}

// Alternative implementation using join approach (more efficient for large datasets)
pub fn reorder_by_name_list_join(df: &DataFrame, name_order: &[&str]) -> Result<DataFrame, PolarsError> {
    // Check if "name" column exists
    if !df.get_column_names().contains(&"name") {
        return Err(PolarsError::ComputeError(
            "DataFrame must contain a 'name' column".into(),
        ));
    }

    // Create a DataFrame with the desired order
    let order_df = df!(
        "name" => name_order,
        "__order__" => (0..name_order.len() as u32).collect::<Vec<u32>>()
    )?;

    // Join the original DataFrame with the order DataFrame
    let result = df
        .lazy()
        .join(
            order_df.lazy(),
            [col("name")],
            [col("name")],
            JoinType::Inner,
        )
        .sort(["__order__"], SortMultipleOptions::default())
        .select([col("*").exclude(["__order__"])])
        .collect()?;

    Ok(result)
}

