    // Get the name column as strings
    let names = name_col.str()?;

    // Create an index array based on the desired order
    let mut indices: Vec<usize> = (0..df.height()).collect();

    indices.sort_by_key(|&i| {
        let name = names.get(i);
        match name {
            Some(Some(n)) => order_map.get(n).copied().unwrap_or(usize::MAX),
            _ => usize::MAX,
        }
    });

    // Reorder the dataframe using the indices
    df.take(&indices.into())
}

