use regex::Regex;

/// Locate every overlapping match of pattern0 within var0.
/// 
/// # Arguments
/// * `var0` - The text to search within
/// * `pattern0` - The regex pattern to search for
///
/// # Returns
/// A vector of tuples containing (start_position, matched_string)
fn find_overlapping_matches(var0: &str, pattern0: &str) -> Result<Vec<(usize, String)>, regex::Error> {
    let regex = Regex::new(pattern0)?;
    let mut matches = Vec::new();

    // Iterate through all positions in the string
    for i in 0..var0.len() {
        // Try to find a match starting at position i
        if let Some(mat) = regex.find(&var0[i..]) {
            // Only count if the match starts at position 0 of the substring
            // (which means it starts at position i of the original string)
            if mat.start() == 0 {
                matches.push((i, mat.as_str().to_string()));
            }
        }
    }

    Ok(matches)
}

