/// Determines if a list of text entries contains at least one element that matches any of the provided regular expression patterns.
///
/// # Arguments
///
/// * `texts` - A slice of strings representing the text entries.
/// * `patterns` - A slice of strings representing the regular expression patterns.
///
/// # Returns
///
/// * `true` if at least one text entry matches any pattern, `false` otherwise.
fn contains_matching_entry(texts: &[&str], patterns: &[&str]) -> bool {
    // Compile all patterns into a set of Regex objects
    let mut compiled_patterns = HashSet::new();
    for pattern in patterns {
        match Regex::new(pattern) {
            Ok(re) => compiled_patterns.insert(re),
            Err(e) => {
                eprintln!("Invalid regex pattern '{}': {}", pattern, e);
                return false;
            }
        };
