    // For other columns, keep as-is.
    let exprs: Vec<Expr> = df
        .get_columns()
        .iter()
        .map(|s| {
            let name = s.name();
            match s.dtype() {
                // integer and float numeric types we treat as numeric
                DataType::UInt8
                | DataType::UInt16
                | DataType::UInt32
                | DataType::UInt64
                | DataType::Int8
                | DataType::Int16
                | DataType::Int32
                | DataType::Int64
                | DataType::Float32
                | DataType::Float64 => {
                    // (col != 0) gives a boolean mask; cast to UInt8 to get 1/0
                    col(name).neq(lit(0)).cast(DataType::UInt8).alias(name)
                }
                // for all other types (e.g., Utf8, Bool, Date), keep original column
                _ => col(name).alias(name),
            }
        })
        .collect();

    // Use lazy API to evaluate the expressions and collect a new DataFrame
    df.clone().lazy().select(exprs).collect()
}

