/// // result[1] = ["age", "25", "30", "35"]
/// // result[2] = ["city", "NYC", "LA", "Chicago"]
/// ```
pub fn dataframe_to_column_lists(df0: &DataFrame) -> Result<Vec<Vec<String>>, Box<dyn Error>> {
    let mut result: Vec<Vec<String>> = Vec::new();

    // Iterate over each column in the DataFrame
    for column in df0.get_columns() {
        let column_name = column.name().to_string();
        let mut column_data: Vec<String> = vec![column_name];

        // Convert each value in the column to a string and add to the list
        for value in column.iter() {
            match value {
                AnyValue::Null => column_data.push("null".to_string()),
                AnyValue::Boolean(b) => column_data.push(b.to_string()),
                AnyValue::String(s) => column_data.push(s.to_string()),
                AnyValue::Int32(i) => column_data.push(i.to_string()),
                AnyValue::Int64(i) => column_data.push(i.to_string()),
                AnyValue::UInt32(u) => column_data.push(u.to_string()),
                AnyValue::UInt64(u) => column_data.push(u.to_string()),
                AnyValue::Float32(f) => column_data.push(f.to_string()),
                AnyValue::Float64(f) => column_data.push(f.to_string()),
                AnyValue::Date(d) => column_data.push(d.to_string()),
                AnyValue::Datetime(ts, tu, tz) => {
                    column_data.push(format!("{:?}", ts));
                }
                _ => column_data.push(format!("{:?}", value)),
            }
        }

        result.push(column_data);
    }

    Ok(result)
}

