use indexmap::IndexMap;
use std::hash::Hash;

/// Merge an iterator of IndexMap<K, V> into a single IndexMap<K, V>.
/// If a key appears multiple times, the value from the later map overwrites earlier ones.
pub fn merge_maps<K, V, I>(lst0: I) -> IndexMap<K, V>
where
    I: IntoIterator<Item = IndexMap<K, V>>,
    K: Eq + Hash,
{
    let mut out = IndexMap::new();
    for map in lst0 {
        for (k, v) in map {
            out.insert(k, v);
        }
    }
    out
}

fn main() {
    // Example usage
    let m1: IndexMap<String, i32> = vec![("a".into(), 1), ("b".into(), 2)].into_iter().collect();
    let m2: IndexMap<String, i32> = vec![("b".into(), 30), ("c".into(), 3)].into_iter().collect();
    let lst0 = vec![m1, m2];

    let merged = merge_maps(lst0);
    // merged will be: {"a":1, "b":30, "c":3} (b updated by the second map)
    println!("{merged:?}");
}
```

Notes:
- This implementation consumes the input maps (no cloning required). If you need to keep the original maps, pass cloned maps or change the signature to accept `&[IndexMap<...>]` and clone keys/values as needed.
- Using IndexMap preserves key insertion order; if you don't care about order, you can swap IndexMap for std::collections::HashMap.

