/// * `var0` - The index at which to insert elements
/// * `lst1` - The vector containing elements to insert
///
/// # Returns
/// A new Vector with elements inserted at the specified position
///
/// # Panics
/// Panics if var0 is greater than the length of lst0
fn insert_at_index<T: Clone>(lst0: Vector<T>, var0: usize, lst1: Vector<T>) -> Vector<T> {
    // Split lst0 at the insertion point
    let (left, right) = lst0.split_at(var0);

    // Concatenate: left + lst1 + right
    left.append(lst1).append(right)
}

// Alternative implementation using slices for more flexibility:
