    let mut result = Vec::with_capacity(lst0.len() + lst1.len());

    // Add elements before the insertion point
    result.extend_from_slice(&lst0[..var0]);

    // Add all elements from lst1
    result.extend_from_slice(lst1);

    // Add remaining elements from lst0
    result.extend_from_slice(&lst0[var0..]);

    result
}

