pub fn filter_highest_c<T: Clone + PartialEq + std::hash::Hash + std::cmp::Eq>(
    data: Vec<(T, T, i32)>,
) -> Vec<(T, T, i32)> {
    // Use a HashMap to track the maximum C value for each (A, B) combination
    let mut max_values: HashMap<(T, T), i32> = HashMap::new();
    let mut result_map: HashMap<(T, T), (T, T, i32)> = HashMap::new();

