use polars::prelude::*;

/// Append `right` to `left` (left may be empty) and reset the row index column to 0..(n-1).
///
/// - `index_col` is the name of the index column to insert/replace.
/// - Returns a new DataFrame with the index column inserted as the first column.
fn append_and_reset_index(
    mut left: DataFrame,
    right: &DataFrame,
    index_col: &str,
) -> PolarsResult<DataFrame> {
    // Append rows: if left is empty, just clone right; otherwise vstack
    if left.height() == 0 {
        left = right.clone();
    } else {
        left.vstack_mut(right)?;
    }

    // Remove any existing index column with the same name
    if left.column(index_col).is_ok() {
        left.drop_in_place(index_col)?;
    }

    // Create a sequential index series 0..n-1 and insert as the first column
    let n = left.height() as i64;
    let idx_series = Series::new(index_col, (0..n).collect::<Vec<i64>>());
    left.insert_at_idx(0, idx_series)?;

    Ok(left)
}

fn main() -> PolarsResult<()> {
    // Example: two small DataFrames
    let df1 = df![
        "name" => &["alice", "bob"],
        "value" => &[10, 20],
    ]?;

    let df2 = df![
        "name" => &["carol", "dave"],
        "value" => &[30, 40],
    ]?;

    // Append df2 to df1 and reset index column named "index"
    let result = append_and_reset_index(df1, &df2, "index")?;
    println!("{}", &result);

    // Example with empty left DataFrame
    let empty = DataFrame::new(vec![])?;
    let result2 = append_and_reset_index(empty, &df2, "index")?;
    println!("{}", &result2);

    Ok(())
}
```

