use itertools::Itertools;

/// Assigns a rank to each element in the list based on its sorted position.
///
/// Args:
///     lst0 (Vec<i32>): The input list of integers.
///
/// Returns:
///     Vec<usize>: A list of rank values corresponding to each element in the input list.
pub fn assign_ranks(lst0: Vec<i32>) -> Vec<usize> {
    let mut sorted: Vec<(i32, usize)> = lst0
        .into_iter()
        .enumerate()
        .map(|(i, x)| (x, i))
        .sorted()
        .collect();

    let mut ranks = vec![0; lst0.len()];
    let mut current_rank = 1;
    let mut current_value = sorted[0].0;

    for (i, (value, original_index)) in sorted.into_iter().enumerate() {
        if value != current_value {
            current_rank = i + 1;
            current_value = value;
        }

        ranks[original_index] = current_rank;
    }

    ranks
}

