use std::collections::HashMap;

/// Assigns ranks to elements in a list based on their values.
/// Elements with equal values receive the same rank (dense ranking).
/// The original list order is preserved.
///
/// # Arguments
/// * `lst0` - A slice of comparable elements
///
/// # Returns
/// A vector of ranks (1-indexed) corresponding to each element's position in the input
///
/// # Example
/// ```
/// let input = vec![3, 1, 4, 1, 5, 9, 2, 6];
/// let ranks = assign_ranks(&input);
/// assert_eq!(ranks, vec![3, 1, 4, 1, 5, 7, 2, 6]);
/// ```
pub fn assign_ranks<T: Ord + Clone + std::hash::Hash>(lst0: &[T]) -> Vec<usize> {
    if lst0.is_empty() {
        return Vec::new();
    }

    // Create a sorted copy of unique elements
    let mut sorted_unique: Vec<&T> = lst0.iter().collect();
    sorted_unique.sort();
    sorted_unique.dedup();

    // Build a rank map: element -> rank (1-indexed)
    let rank_map: HashMap<&T, usize> = sorted_unique
        .iter()
        .enumerate()
        .map(|(i, &val)| (val, i + 1))
        .collect();

    // Assign ranks to each element in original order
    lst0.iter().map(|x| rank_map[x]).collect()
}

