```

Function and example usage:
```rust
use indexmap::IndexMap;
use std::hash::Hash;

/// Reorder items according to `order`.
///
/// - `items`: an iterable of items that contain an identifier extractable via `id_fn`.
/// - `order`: an iterable of identifier values describing the desired sequence.
/// - `id_fn`: closure mapping an item reference to its identifier (ownership of the id is taken).
///
/// Returns a Vec<T> with items reordered to match `order`. Items with identifiers not in `order` are appended
/// in the order of their first occurrence.
///
/// Example:
/// let items = vec![Item { id: 2, ... }, Item { id: 1, ... }, Item { id: 2, ... }];
/// let order = vec![1, 2];
/// result -> items with id 1 first, then all items with id 2 (in original relative order).
pub fn reorder_by_ids<T, K, I, J, F>(
    items: I,
    order: J,
    id_fn: F,
) -> Vec<T>
where
    I: IntoIterator<Item = T>,
    J: IntoIterator<Item = K>,
    F: Fn(&T) -> K,
    K: Eq + Hash,
{
    // Map id -> Vec<item> to collect items per id preserving item insertion order
    let mut map: IndexMap<K, Vec<T>> = IndexMap::new();

    // Fill the map with items grouped by id in the order they appear
    for item in items {
        let key = id_fn(&item);
        map.entry(key).or_insert_with(Vec::new).push(item);
    }

    let mut result = Vec::new();

    // First, emit items for ids present in `order`, in that order
    for id in order {
        if let Some(group) = map.remove(&id) {
            result.extend(group);
        }
    }

    // Then, emit remaining items for ids not listed in `order`, preserving their first-occurrence order
    for (_id, group) in map.into_iter() {
        result.extend(group);
    }

    result
}

