```rust
use indexmap::IndexMap;

/// Reorders a collection of items so they appear in the sequence defined by identifier order.
/// 
/// # Arguments
/// * `items` - A vector of items that can be converted into (id, item) tuples
/// * `id_sequence` - The desired order of identifiers
/// * `id_fn` - A function that extracts the identifier from an item
/// 
/// # Returns
/// A vector of items reordered according to id_sequence. Items not in id_sequence are appended at the end.
fn reorder_by_ids<T, ID>(
    items: Vec<T>,
    id_sequence: &[ID],
    id_fn: impl Fn(&T) -> ID,
) -> Vec<T>
where
    ID: Eq + std::hash::Hash + Clone,
{
    // Create a map of id -> item for O(1) lookup
    let mut item_map: IndexMap<ID, T> = items
        .into_iter()
        .map(|item| (id_fn(&item).clone(), item))
        .collect();

    let mut result = Vec::new();

    // Add items in the order specified by id_sequence
    for id in id_sequence {
        if let Some((_, item)) = item_map.shift_remove(id) {
            result.push(item);
        }
    }

    // Append any remaining items not in id_sequence
    result.extend(item_map.into_values());

    result
}

