```rust
fn reorder_by_ids_std<T, ID>(
    items: Vec<T>,
    id_sequence: &[ID],
    id_fn: impl Fn(&T) -> ID,
) -> Vec<T>
where
    ID: Eq + Clone,
{
    let mut result = Vec::new();
    let mut remaining = items;

    for id in id_sequence {
        if let Some(pos) = remaining.iter().position(|item| id_fn(item) == *id) {
