use serde::de::DeserializeOwned;
use serde_json::{json, Value};

/// Extracts the values of `key` from each JSON object in `items`.
/// Returns only the values that are present (skips missing keys).
fn pluck_attribute(items: &[Value], key: &str) -> Vec<Value> {
    items
        .iter()
        .filter_map(|item| item.get(key).cloned())
        .collect()
}

/// Like `pluck_attribute`, but attempts to deserialize each found value into `T`.
/// Returns Err if any present value fails to deserialize into T.
fn pluck_attribute_as<T: DeserializeOwned>(
    items: &[Value],
    key: &str,
) -> Result<Vec<T>, serde_json::Error> {
    let mut out = Vec::new();
    for item in items {
        if let Some(v) = item.get(key) {
            // clone the Value so we can consume it with from_value
            let v_cloned = v.clone();
            let t: T = serde_json::from_value(v_cloned)?;
            out.push(t);
        }
    }
    Ok(out)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Example list of items (each item is a JSON object)
    let items = vec![
        json!({"id": 1, "name": "Alice", "active": true}),
        json!({"id": 2, "name": "Bob",   "active": false}),
        json!({"id": 3,             "active": true}), // missing "name"
    ];

    // Simple extraction as JSON values
    let names_json = pluck_attribute(&items, "name");
    println!("Names as JSON values: {names_json:?}");
    // Output: Names as JSON values: [String("Alice"), String("Bob")]

