    println!("Names as Strings: {names:?}");
    // Output: Names as Strings: ["Alice", "Bob"]

    // Extract a boolean attribute directly as Vec<bool>
    let actives: Vec<bool> = pluck_attribute_as(&items, "active")?;
    println!("Active flags: {actives:?}");
    // Output: Active flags: [true, false, true]

    Ok(())
}
```

