use ndarray::{Array2, ArrayView1};

/// Given two sequences of vectors (a_seq and b_seq) of equal length,
/// compute sum_i outer(a_seq[i], b_seq[i]) and return it as an n x m matrix.
/// Returns Err on shape mismatch.
pub fn sum_outer_products(
    a_seq: &[Vec<f64>],
    b_seq: &[Vec<f64>],
) -> Result<Array2<f64>, String> {
    if a_seq.len() != b_seq.len() {
        return Err("Sequences must have the same length.".into());
    }
    if a_seq.is_empty() {
        // No pairs: return an empty 0x0 matrix
        return Ok(Array2::zeros((0, 0)));
    }

    let n = a_seq[0].len();
    let m = b_seq[0].len();

    // Validate consistent inner lengths
    for (i, v) in a_seq.iter().enumerate() {
        if v.len() != n {
            return Err(format!("All vectors in a_seq must have the same length; mismatch at index {}", i));
        }
    }
    for (i, v) in b_seq.iter().enumerate() {
        if v.len() != m {
            return Err(format!("All vectors in b_seq must have the same length; mismatch at index {}", i));
        }
    }

    let mut sum = Array2::<f64>::zeros((n, m));
    for (a, b) in a_seq.iter().zip(b_seq.iter()) {
        let a_view: ArrayView1<f64> = ArrayView1::from(&a[..]);
        let b_view: ArrayView1<f64> = ArrayView1::from(&b[..]);
        // a_view.outer(&b_view) returns an Array2<f64> of shape (n, m)
        sum += &a_view.outer(&b_view);
    }

    Ok(sum)
}

