///
/// # Arguments
/// * `sequences_a` - First sequence of numeric lists
/// * `sequences_b` - Second sequence of numeric lists
///
/// # Returns
/// A 2D array representing the sum of all outer products
///
/// # Example
/// ```
/// let seq_a = vec![vec![1.0, 2.0], vec![3.0, 4.0]];
/// let seq_b = vec![vec![5.0, 6.0], vec![7.0, 8.0]];
/// let result = sum_of_outer_products(&seq_a, &seq_b);
/// // result = [[1*5 + 3*7, 1*6 + 3*8], [2*5 + 4*7, 2*6 + 4*8]]
/// //        = [[26, 30], [34, 40]]
/// ```
fn sum_of_outer_products(
    sequences_a: &[Vec<f64>],
    sequences_b: &[Vec<f64>],
) -> Array2<f64> {
    assert_eq!(
        sequences_a.len(),
        sequences_b.len(),
        "Sequences must have equal length"
    );
    assert!(!sequences_a.is_empty(), "Sequences cannot be empty");

    let m = sequences_a[0].len();
    let n = sequences_b[0].len();

    // Initialize result matrix with zeros
    let mut result = Array2::zeros((m, n));

    // Sum outer products
    for (vec_a, vec_b) in sequences_a.iter().zip(sequences_b.iter()) {
        assert_eq!(
            vec_a.len(),
            m,
            "All vectors in sequence A must have equal length"
        );
        assert_eq!(
            vec_b.len(),
            n,
            "All vectors in sequence B must have equal length"
        );

        // Add outer product: a ⊗ b
        for (i, &a) in vec_a.iter().enumerate() {
            for (j, &b) in vec_b.iter().enumerate() {
                result[[i, j]] += a * b;
            }
        }
    }

    result
