use polars::prelude::*;

/// Insert a new column into `df` at zero-based position `pos`.
/// - `df` is mutated in place.
/// - `pos` is clamped to [0, df.width()] (inserting at df.width() appends).
/// - `name` becomes the column name for `values`.
/// - `values` must have the same length as the DataFrame height.
///
/// Returns a PolarsResult<()>; an error is returned if the lengths mismatch
/// or if underlying insertion fails.
pub fn insert_column_at(
    df: &mut DataFrame,
    pos: usize,
    name: &str,
    mut values: Series,
) -> PolarsResult<()> {
    // Rename the series to the requested column name
    values.rename(name);

    // Check length match
    let df_height = df.height();
    if values.len() != df_height {
        return Err(PolarsError::ShapeMisMatch(
            format!(
                "New column length ({}) does not match DataFrame height ({})",
                values.len(),
                df_height
            )
            .into(),
        ));
    }

    // Clamp position to valid range (append if pos > width)
    let insert_pos = if pos > df.width() { df.width() } else { pos };

    // Insert at index (Polars will error if something else goes wrong)
    df.insert_at_idx(insert_pos, values)
}

fn main() -> PolarsResult<()> {
    // Example usage:
    // Build a simple DataFrame with one column "a"
