use itertools::Itertools;
use std::collections::HashMap;

/// Partitions elements of a list into groups where elements share the same first 5 characters.
/// 
/// # Arguments
/// * `input` - A slice of string slices to partition
/// 
/// # Returns
/// A vector of vectors, where each inner vector contains elements with the same first 5 characters.
/// Elements with fewer than 5 characters are grouped together under their actual length prefix.
/// 
/// # Example
/// ```
/// let input = vec!["hello_world", "hello_there", "world_peace", "hello_again", "test"];
/// let result = partition_by_first_five(&input);
/// assert_eq!(result.len(), 3); // "hello", "world", "test" groups
/// ```
pub fn partition_by_first_five<'a>(input: &[&'a str]) -> Vec<Vec<&'a str>> {
    // Group elements by their first 5 characters (or fewer if string is shorter)
    let groups: HashMap<String, Vec<&str>> = input
        .iter()
        .map(|&s| {
            let key = if s.len() >= 5 {
                s[..5].to_string()
            } else {
                s.to_string()
            };
            (key, s)
        })
        .into_group_map();

    // Convert HashMap into Vec<Vec<&str>>, sorted by key for deterministic output
    groups
        .into_iter()
        .sorted_by(|a, b| a.0.cmp(&b.0))
        .map(|(_, group)| group)
        .collect()
}

