# Rust Function for One-Hot Encoding with `polars` (2023+)

Here's a self-contained Rust function that converts categorical columns into one-hot encoded binary columns using the `polars` crate (released in 2023):

```rust
use polars::prelude::*;
use std::collections::HashMap;

/// Converts categorical columns in a DataFrame to one-hot encoded binary columns
///
/// # Arguments
/// * `df` - Input DataFrame containing categorical columns to encode
/// * `categorical_cols` - Names of columns to one-hot encode (None for all categorical columns)
///
/// # Returns
/// DataFrame with original columns (except encoded ones) and new binary columns
pub fn one_hot_encode(df: DataFrame, categorical_cols: Option<Vec<String>>) -> Result<DataFrame, PolarsError> {
    // Get all categorical columns if none specified
    let cols_to_encode = match categorical_cols {
        Some(cols) => cols,
        None => df.get_column_names()
            .into_iter()
            .filter(|col| df.column(col)?.dtype() == &DataType::Categorical)
            .collect(),
    };

    if cols_to_encode.is_empty() {
        return Ok(df);
    }

    // Process each categorical column
    let mut new_df = df.clone();
    let mut new_cols = Vec::new();

    for col_name in cols_to_encode {
        let col = new_df.column(&col_name)?;
        let categorical = col.cast(&DataType::Categorical)?;

        // Get unique categories
        let categories = categorical
            .utf8()?
            .into_iter()
            .collect::<HashSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();

        // Create binary columns for each category
        for (i, category) in categories.iter().enumerate() {
            let binary_col_name = format!("{}_{}", col_name, category);

            // Create binary column (1 if original == category, 0 otherwise)
            let binary_series = categorical
                .utf8()?
                .map(|s| if s == *category { 1 } else { 0 }, &[])
                .into_object();

            new_df = new_df.with_column(
                Series::new(&binary_col_name, binary_series)
            )?;
        }

        // Remove original categorical column
        new_df = new_df.drop(&col_name)?;
    }

    Ok(new_df)
}

