use polars::prelude::*;
use std::collections::HashSet;

/// One-hot-encode all string / categorical columns in `df`.
/// Returns a new DataFrame with original categorical columns replaced by binary Int32 columns
/// (one column per unique label). Nulls are treated as their own category ("<NULL>").
pub fn one_hot_encode(df: &DataFrame) -> PolarsResult<DataFrame> {
    // helper to sanitize a label into a safe column suffix (alphanumeric -> keep, others -> '_')
    fn sanitize_label(label: &str) -> String {
        if label.is_empty() {
            return "empty".to_string();
        }
        let mut out = String::with_capacity(label.len());
        for c in label.chars() {
            if c.is_ascii_alphanumeric() {
                out.push(c);
            } else {
                out.push('_');
            }
        }
        out
    }

    let mut new_cols: Vec<Series> = Vec::with_capacity(df.width());

    for (i, orig) in df.get_columns().iter().enumerate() {
        // Only transform Utf8 and Categorical columns; keep others as-is.
        match orig.dtype() {
            DataType::Utf8 | DataType::Categorical(_) => {
                // Ensure we have a Utf8 series to inspect values (cast categorical to utf8 if needed)
                let utf8_series = if orig.dtype() == &DataType::Utf8 {
                    orig.clone()
                } else {
                    // cast categorical to Utf8
                    orig.cast(&DataType::Utf8)?
                };
                let utf8 = utf8_series.utf8()?;

                // Collect unique labels in appearance order
                let mut seen: HashSet<Option<String>> = HashSet::new();
                let mut uniques_ordered: Vec<Option<String>> = Vec::new();
                for idx in 0..utf8.len() {
                    let val_opt = utf8.get(idx).map(|s| s.to_string());
                    if seen.insert(val_opt.clone()) {
                        uniques_ordered.push(val_opt);
                    }
                }

                // For each unique label, build a binary Int32 column
                let col_name = orig.name();
                for label_opt in uniques_ordered {
                    let label_str = match &label_opt {
                        Some(s) => s.as_str(),
                        None => "<NULL>",
                    };
                    let suffix = sanitize_label(label_str);
                    let new_name = format!("{}_{}", col_name, suffix);

                    // build Vec<i32> with 1 for match, 0 otherwise
                    let mut binary: Vec<i32> = Vec::with_capacity(utf8.len());
                    for idx in 0..utf8.len() {
                        let match_flag = match (&label_opt, utf8.get(idx)) {
                            (None, None) => 1,
                            (Some(l), Some(v)) if l == v => 1,
                            _ => 0,
                        };
                        binary.push(match_flag);
                    }

                    new_cols.push(Series::new(&new_name, binary));
                }
                // original categorical column is not added (dropped)
            }
            _ => {
                // Non-categorical columns: keep as-is (clone)
                new_cols.push(orig.clone());
            }
        }
    }

    DataFrame::new(new_cols)
}

fn main() -> PolarsResult<()> {
    // Example usage:
    let df0 = df![
        "city" => &["NY", "LA", "NY", "CHI", None::<&str>],
        "color" => &["red", "blue", "red", "green", "blue"],
        "value" => &[10i32, 20, 15, 10, 5]
    ]?;

    println!("Original:\n{:?}", df0);

    let encoded = one_hot_encode(&df0)?;
    println!("One-hot encoded:\n{:?}", encoded);

    Ok(())
}
