# Rust Function for One-Hot Encoding

Here's a self-contained solution using the `polars` library (2023+) for one-hot encoding categorical columns:

```rust
use polars::prelude::*;

/// Convert all categorical columns in a DataFrame into binary columns using one-hot encoding.
/// 
/// # Arguments
/// * `df` - A Polars DataFrame
/// 
/// # Returns
/// * `Result<DataFrame>` - DataFrame with categorical columns converted to binary columns
/// 
/// # Example
/// ```ignore
/// let df = df!("color" => ["red", "blue", "red"],
///              "size" => ["S", "M", "L"],
///              "value" => [1, 2, 3])?;
/// 
/// let result = one_hot_encode(df)?;
/// // Result has columns: color_red, color_blue, size_S, size_M, size_L, value
/// ```
fn one_hot_encode(df: DataFrame) -> PolarsResult<DataFrame> {
    let mut result_df = df.clone();

    // Identify categorical columns
    let categorical_cols: Vec<String> = result_df
        .get_columns()
        .iter()
        .filter_map(|col| {
            if col.dtype() == &DataType::String || col.dtype() == &DataType::Categorical(None, true) {
                Some(col.name().to_string())
            } else {
                None
            }
        })
        .collect();

    // Process each categorical column
    for col_name in categorical_cols {
        // Get unique values
        let col = result_df.column(&col_name)?;
        let unique_vals = col.unique()?.sort(false)?;

        let unique_strings: Vec<String> = unique_vals
            .cast(&DataType::String)?
            .utf8()?
            .into_iter()
            .filter_map(|v| v.map(|s| s.to_string()))
            .collect();

        // Create binary columns for each unique value
        for unique_val in unique_strings {
            let binary_col = col
                .cast(&DataType::String)?
                .equal(&unique_val)?
                .cast(&DataType::Int32)?;

            let new_col_name = format!("{}_{}", col_name, unique_val);
            result_df.with_column(binary_col.alias(&new_col_name))?;
        }

        // Drop the original categorical column
        result_df = result_df.drop(&col_name)?;
    }

    Ok(result_df)
}

fn main() -> PolarsResult<()> {
    // Example usage
    let df = df!(
        "color" => ["red", "blue", "red", "green"],
        "size" => ["S", "M", "L", "S"],
        "quantity" => [1, 2, 3, 4]
    )?;

    println!("Original DataFrame:");
    println!("{}", df);

    let encoded_df = one_hot_encode(df)?;

    println!("\nOne-Hot Encoded DataFrame:");
    println!("{}", encoded_df);

    Ok(())
}
```

