use ndarray::{Array1, Array2, Axis};

/// Repeat a 1-D vector `repeats` times along the requested `axis`.
///
/// - If `axis == 0`, the result has shape (repeats, n) where each row is the input vector.
/// - If `axis == 1`, the result has shape (n, repeats) where each column is the input vector.
///
/// Panics if `axis` is not 0 or 1.
///
/// T must implement Clone because the output owns the cloned elements.
pub fn repeat_vector<T: Clone>(v: &Array1<T>, repeats: usize, axis: usize) -> Array2<T> {
    let n = v.len();
    match axis {
        0 => {
            // shape (1, n) -> broadcast to (repeats, n) -> to_owned
            v.view()
                .insert_axis(Axis(0))
                .broadcast((repeats, n))
                .expect("broadcast failed")
                .to_owned()
        }
        1 => {
            // shape (n, 1) -> broadcast to (n, repeats) -> to_owned
            v.view()
                .insert_axis(Axis(1))
                .broadcast((n, repeats))
                .expect("broadcast failed")
                .to_owned()
        }
        _ => panic!("axis out of bounds for a vector; must be 0 or 1"),
    }
}

