/// ];
/// let result = multiply_vector_matrix(&var0, &var1).unwrap();
/// assert_eq!(result, vec![1.0, 2.0, 3.0]);
/// ```
fn multiply_vector_matrix(var0: &[f64], var1: &[Vec<f64>]) -> Result<Vec<f64>, String> {
    // Validate that matrix is not empty
    if var1.is_empty() {
        return Err("Matrix cannot be empty".to_string());
    }

    // Validate that vector length matches matrix column count
    let matrix_cols = var1[0].len();
    if var0.len() != matrix_cols {
        return Err(format!(
            "Vector length ({}) must match matrix column count ({})",
            var0.len(),
            matrix_cols
        ));
    }

    // Validate all matrix rows have the same length
    if !var1.iter().all(|row| row.len() == matrix_cols) {
        return Err("All matrix rows must have the same length".to_string());
