/// Recursively compare two serde_json::Value values treating JSON objects as
/// unordered maps (i.e., property order doesn't matter).
///
/// - Objects: keys and associated values must match (order-independent).
/// - Arrays: order matters (elements compared positionally).
/// - Primitives: compared by equality.
///
/// Returns true if the two values are equal under these rules.
pub fn equal_unordered_objects(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Object(map_a), Value::Object(map_b)) => {
            if map_a.len() != map_b.len() {
                return false;
            }
            // For each key in map_a, ensure map_b has the same key and the values compare equal recursively.
            for (k, v_a) in map_a {
                match map_b.get(k) {
                    Some(v_b) => {
                        if !equal_unordered_objects(v_a, v_b) {
                            return false;
                        }
                    }
                    None => return false,
                }
            }
            true
        }
        (Value::Array(arr_a), Value::Array(arr_b)) => {
            if arr_a.len() != arr_b.len() {
                return false;
            }
            // Arrays are compared positionally
            arr_a.iter().zip(arr_b.iter()).all(|(ea, eb)| equal_unordered_objects(ea, eb))
        }
        // For all other types (String, Number, Bool, Null), rely on Value's equality.
        _ => a == b,
    }
