/// let top_indices = get_top_n_indices(&data, 2);
/// assert_eq!(top_indices, vec![3, 1]); // indices of 45.3 and 23.1
/// ```
fn get_top_n_indices(lst0: &[f64], n: usize) -> Vec<usize> {
    let n = n.min(lst0.len()); // Handle case where n > lst0.len()

    // Create pairs of (index, value)
    let mut indexed_values: Vec<(usize, f64)> = lst0
        .iter()
        .enumerate()
        .map(|(idx, &val)| (idx, val))
        .collect();

    // Partial sort to find the N largest elements
    // This is more efficient than full sort for large collections
    indexed_values.select_nth_unstable_by(n - 1, |a, b| {
        b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal)
    });

    // Take the first n elements and sort them by value (descending)
    let mut top_n: Vec<(usize, f64)> = indexed_values[..n].to_vec();
    top_n.sort_by(|a, b| {
        b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal)
    });

    // Extract just the indices
    top_n.into_iter().map(|(idx, _)| idx).collect()
}

