/// are enumerated, so y varies fastest.
fn generate_grid(
    var0: f64,
    var1: f64,
    var2: f64,
    var3: f64,
    nx: usize,
    ny: usize,
) -> Vec<(f64, f64)> {
    assert!(nx >= 1 && ny >= 1, "nx and ny must be >= 1");

    let xs: Vec<f64> = if nx == 1 {
        vec![(var0 + var1) / 2.0]
    } else {
        (0..nx)
            .map(|i| var0 + (var1 - var0) * (i as f64) / ((nx - 1) as f64))
            .collect()
    };

    let ys: Vec<f64> = if ny == 1 {
        vec![(var2 + var3) / 2.0]
    } else {
        (0..ny)
            .map(|j| var2 + (var3 - var2) * (j as f64) / ((ny - 1) as f64))
            .collect()
    };

    iproduct!(xs.iter(), ys.iter())
        .map(|(x, y)| (*x, *y))
        .collect()
}

