/// # Returns
///
/// A `Vec<(f64, f64)>` containing all points in the grid.
///
/// # Example
///
/// ```
/// let points = generate_grid(0.0, 1.0, 0.0, 1.0, 3, 3);
/// assert_eq!(points.len(), 9);
/// assert_eq!(points[0], (0.0, 0.0));
/// assert_eq!(points[4], (0.5, 0.5));
/// assert_eq!(points[8], (1.0, 1.0));
/// ```
pub fn generate_grid(
    x_start: f64,
    x_end: f64,
    y_start: f64,
    y_end: f64,
    x_steps: usize,
    y_steps: usize,
) -> Vec<(f64, f64)> {
    // Handle edge case where steps are 0 or 1
    let x_step_size = if x_steps <= 1 {
        0.0
    } else {
        (x_end - x_start) / (x_steps - 1) as f64
    };

    let y_step_size = if y_steps <= 1 {
        0.0
    } else {
        (y_end - y_start) / (y_steps - 1) as f64
    };

