        .map(|i| x_start + i as f64 * x_step_size)
        .collect();

    let y_values: Vec<f64> = (0..y_steps)
        .map(|i| y_start + i as f64 * y_step_size)
        .collect();

    // Use itertools' iproduct! macro for the Cartesian product
    iproduct!(x_values, y_values).collect()
