use ndarray::{Array2, s};

/// Generates a grid of points representing the Cartesian product of two intervals.
/// 
/// # Arguments
/// * `var0` - Start of first interval
/// * `var1` - End of first interval
/// * `var2` - Start of second interval
/// * `var3` - End of second interval
/// * `points_per_interval` - Number of points to generate per interval
/// 
/// # Returns
/// A 2D array where each row is a point [x, y] in the Cartesian product grid
fn cartesian_product_grid(
    var0: f64,
    var1: f64,
    var2: f64,
    var3: f64,
    points_per_interval: usize,
) -> Array2<f64> {
    // Create linear spaces for each interval
    let x_vals: Vec<f64> = linspace(var0, var1, points_per_interval);
    let y_vals: Vec<f64> = linspace(var2, var3, points_per_interval);

    let total_points = points_per_interval * points_per_interval;
    let mut grid = Array2::<f64>::zeros((total_points, 2));

    // Generate Cartesian product
    for (i, &x) in x_vals.iter().enumerate() {
        for (j, &y) in y_vals.iter().enumerate() {
            let idx = i * points_per_interval + j;
            grid[[idx, 0]] = x;
            grid[[idx, 1]] = y;
        }
    }

    grid
}

/// Helper function to create a linearly spaced vector
fn linspace(start: f64, end: f64, num_points: usize) -> Vec<f64> {
    if num_points == 0 {
        return vec![];
    }
    if num_points == 1 {
        return vec![(start + end) / 2.0];
    }

    let step = (end - start) / (num_points - 1) as f64;
    (0..num_points)
        .map(|i| start + i as f64 * step)
        .collect()
}

fn main() {
