use indexmap::IndexMap;
use std::hash::Hash;

/// For each (k1 -> k2) entry in `first`, look up `k2` in `second`.
/// If found, insert (k1 -> v2) into the returned IndexMap.
/// Preserves the iteration order of `first`.
///
/// - first: mapping from K1 to K2
/// - second: mapping from K2 to V2
/// - Returns: mapping from K1 to V2 for all matches found.
///
/// Example:
/// let mut a = IndexMap::new(); a.insert("id1", 10); a.insert("id2", 20);
/// let mut b = IndexMap::new(); b.insert(10, "Alice"); b.insert(20, "Bob");
/// let res = match_maps(&a, &b);
/// // res: { "id1": "Alice", "id2": "Bob" }
pub fn match_maps<K1, K2, V2>(
    first: &IndexMap<K1, K2>,
    second: &IndexMap<K2, V2>,
) -> IndexMap<K1, V2>
where
    K1: Eq + Hash + Clone,
    K2: Eq + Hash,
    V2: Clone,
{
    let mut out = IndexMap::with_capacity(first.len());
    for (k1, k2) in first.iter() {
        if let Some(v2) = second.get(k2) {
            out.insert(k1.clone(), v2.clone());
        }
    }
    out
}

#[cfg(test)]
