    let columns = df0.get_column_names();

    // Filter columns where the second level matches str0
    let selected_columns: Vec<&str> = columns
        .iter()
        .filter(|&&col_name| {
            // Split the column name by the hierarchy separator
            // Polars uses "." as the default separator for multi-level columns
            let parts: Vec<&str> = col_name.split('.').collect();

            // Check if we have at least two levels and the second level matches
