use polars::prelude::*;

/// For each row in `df`, compute the sum of the columns in `cols` and
/// store the result in a new column named `new_col_name`.
///
/// Numeric columns will be cast to Float64. Nulls are treated as 0.0.
/// Returns a PolarsResult<()> so callers can handle missing columns or type errors.
pub fn add_row_sum(df: &mut DataFrame, cols: &[&str], new_col_name: &str) -> PolarsResult<()> {
    // Collect the selected columns as Float64 Series (this clones & casts them)
    let mut float_series: Vec<Series> = Vec::with_capacity(cols.len());
    for &col in cols {
        let s = df.column(col)?.cast(&DataType::Float64)?;
        float_series.push(s);
    }

    let height = df.height();
    let mut sums: Vec<f64> = Vec::with_capacity(height);

    // For each row, sum the values across the selected columns
    for row_idx in 0..height {
        let mut row_sum = 0.0_f64;
        for s in &float_series {
            // get as chunked array and read the optional f64 at this row
            let ca = s.f64()?;
            if let Some(v) = ca.get(row_idx) {
                row_sum += v;
            }
            // if None (null), treat as 0.0
        }
        sums.push(row_sum);
    }

    // Create a new Series and add it to the DataFrame
    let sum_series = Series::new(new_col_name, sums);
    df.with_column(sum_series)?;
    Ok(())
}

fn main() -> PolarsResult<()> {
    // Example usage
    let mut df = df![
        "a" => [1i64, 2, 3],
        "b" => [4.0f64, 5.0, 6.0],
        "c" => [Some(7i64), None, Some(9i64)]
    ]?;

    add_row_sum(&mut df, &["a", "b", "c"], "row_total")?;

    println!("{:?}", df);
    Ok(())
}
```

