pub fn filter_matching_values<T: AsRef<str>>(df0: DataFrame, var0: T, lst0: &[T::Output]) -> Result<DataFrame, PolarsError>
where
    T::Output: Into<String> + Clone,
{
    // Convert the list to a Series for comparison
    let lst_series = Series::new(var0.as_ref(), lst0.iter().map(|s| s.clone().into()).collect::<Vec<_>>())?;

    // Create a boolean mask where var0 is in lst0
    let mask = df0.column(var0.as_ref())?
        .is_in(&lst_series)?;

    // Filter the DataFrame
    Ok(df0.lazy().filter(&mask)?)
        .collect()?
}
