/// Return an IndexMap whose keys are the same as `dict0` but inserted in
/// descending order by the lengths of their associated Vec values.
/// The IndexMap maps each key to the corresponding value length (usize).
pub fn sort_keys_by_value_len_desc<V>(dict0: &HashMap<String, Vec<V>>) -> IndexMap<String, usize> {
    // Collect (key, len) pairs
    let mut pairs: Vec<(&String, usize)> = dict0.iter().map(|(k, v)| (k, v.len())).collect();

