    pairs.sort_unstable_by_key(|&(_, len)| Reverse(len));

    // Insert into an IndexMap in that order
    let mut result = IndexMap::with_capacity(pairs.len());
    for (k, len) in pairs {
        result.insert(k.clone(), len);
    }

    result
