Code:

```rust
use ndarray::prelude::*;
use ndarray::s;

/// Extract columns from index `start_col` up to `end_col` (start inclusive, end exclusive)
/// from a two-dimensional collection `arr0` (slice of rows).
///
/// Returns Err(String) on invalid input (ragged rows or out-of-bounds).
///
/// Example:
/// let arr = vec![vec![1,2,3], vec![4,5,6], vec![7,8,9]];
/// let cols = slice_columns(&arr, 0, 2).unwrap();
/// // cols == vec![vec![1,2], vec![4,5], vec![7,8]]
pub fn slice_columns<T: Clone>(
    arr0: &[Vec<T>],
    start_col: usize,
    end_col: usize,
) -> Result<Vec<Vec<T>>, String> {
    // empty input -> empty output
    if arr0.is_empty() {
        return Ok(Vec::new());
    }

    // ensure all rows have same length
    let nrows = arr0.len();
    let ncols = arr0[0].len();
    for (i, row) in arr0.iter().enumerate() {
        if row.len() != ncols {
            return Err(format!("row {} has length {}, expected {}", i, row.len(), ncols));
        }
    }

    if start_col > end_col {
        return Err("start_col > end_col".to_string());
    }
    if end_col > ncols {
        return Err(format!("end_col {} out of bounds (ncols = {})", end_col, ncols));
    }

    // flatten rows into a single Vec<T> for ndarray
    let mut flat = Vec::with_capacity(nrows * ncols);
    for row in arr0 {
        flat.extend_from_slice(&row[..]);
    }

    // construct ndarray Array2 from flattened data
    let arr = Array2::from_shape_vec((nrows, ncols), flat)
        .map_err(|e| format!("failed to create Array2: {}", e))?;

    // slice columns and convert back to Vec<Vec<T>>
    let view = arr.slice(s![.., start_col..end_col]);
    let mut result: Vec<Vec<T>> = Vec::with_capacity(nrows);
    for row in view.rows() {
        // row is an ArrayView1<T>; convert to Vec<T> by cloning elements
        result.push(row.to_vec());
    }

    Ok(result)
}
```

Notes:
- The indices are interpreted as start inclusive and end exclusive (Rust slice style).
- The function clones elements; T must implement Clone.
- If you prefer standard-library-only implementation (no ndarray), the same logic can be done by slicing each row directly, but the above demonstrates usage of a modern array library.

