use polars::prelude::*;
use regex::Regex;

/// Cleanse the column `col_name` in `df0` by removing every character
/// that is not a Unicode letter or number. Returns a new DataFrame
/// with the same column name replaced by the cleaned strings.
///
/// Example:
/// let cleaned_df = cleanse_col(&df, "col_name")?;
pub fn cleanse_col(df0: &DataFrame, col_name: &str) -> PolarsResult<DataFrame> {
    // Compile Unicode-aware regex: keep only letters and numbers
    let re = Regex::new(r"[^\p{L}\p{N}]+").map_err(|e| PolarsError::Other(format!("{e}").into()))?;

    // Get the column as an UTF8 series
    let series = df0.column(col_name)?;
    let utf8 = series.utf8().map_err(|e| PolarsError::Other(format!("{e}").into()))?;

    // Map each entry: nulls preserved, non-null strings cleaned
    let cleaned: Vec<Option<String>> = utf8
        .into_iter()
        .map(|opt| opt.map(|s| re.replace_all(s, "").to_string()))
        .collect();

    // Create a new Series with same name and replace in the DataFrame
    let new_series = Series::new(col_name, cleaned);
    let new_df = df0.with_column(new_series)?;

    Ok(new_df)
}

