use polars::prelude::*;
use regex::Regex;

/// Cleanses a column in a DataFrame by removing all non-alphanumeric characters
/// 
/// # Arguments
/// * `df0` - The input DataFrame
/// * `col_name` - The name of the column to cleanse
/// 
/// # Returns
/// * `Result<DataFrame>` - A new DataFrame with the cleansed column, or an error
/// 
/// # Example
/// ```rust
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "col_name" => &["Hello! World?", "Test-123", "Special@#$Chars"]
/// ).unwrap();
/// 
/// let result = cleanse_column(&df, "col_name").unwrap();
/// println!("{:?}", result);
/// // Output will show: ["HelloWorld", "Test123", "SpecialChars"]
/// ```
pub fn cleanse_column(df0: &DataFrame, col_name: &str) -> Result<DataFrame, PolarsError> {
    // Compile regex to match any character that is NOT a letter or digit
    let re = Regex::new(r"[^a-zA-Z0-9]").unwrap();

    // Get the column as a Series
    let series = df0.column(col_name)?;

    // Apply the cleansing operation to string values
    let cleansed = series
        .str()?
        .apply_values(|s| {
            // Remove all non-alphanumeric characters
            re.replace_all(s, "").to_string()
        })
        .into_series();

    // Replace the original column with the cleansed version
    let mut df = df0.clone();
    df.replace(col_name, cleansed)?;

    Ok(df)
}

// Example usage
fn main() -> Result<(), PolarsError> {
    // Create a sample DataFrame
    let df = df!(
        "id" => &[1, 2, 3],
        "col_name" => &["Hello! World?", "Test-123", "Special@#$Chars"],
        "other_col" => &["Keep this", "And this", "Untouched"]
    )?;

    println!("Original DataFrame:");
    println!("{:?}", df);

    // Cleanse the column
    let cleansed_df = cleanse_column(&df, "col_name")?;

    println!("\nCleansed DataFrame:");
    println!("{:?}", cleansed_df);

    Ok(())
}
