use ndarray::Array1;

/// Calculate the mean squared error between two lists of numeric values.
///
/// This function computes the average of the squared differences between
/// corresponding elements of two lists.
///
/// # Arguments
/// * `lst0` - First list of f64 values
/// * `lst1` - Second list of f64 values
///
/// # Returns
/// * `Ok(f64)` - The mean squared error
/// * `Err(String)` - Error message if lists have different lengths or are empty
///
/// # Example
/// ```
/// let a = vec![1.0, 2.0, 3.0];
/// let b = vec![4.0, 5.0, 6.0];
/// let mse = mean_squared_error(&a, &b).unwrap();
/// assert_eq!(mse, 9.0); // ((1-4)^2 + (2-5)^2 + (3-6)^2) / 3 = 27/3 = 9
/// ```
pub fn mean_squared_error(lst0: &[f64], lst1: &[f64]) -> Result<f64, String> {
    if lst0.len() != lst1.len() {
        return Err(format!(
            "Lists must have the same length. Got {} and {}",
            lst0.len(),
            lst1.len()
        ));
    }

    if lst0.is_empty() {
        return Err("Lists cannot be empty".to_string());
    }

    // Convert slices to ndarray arrays
    let arr0 = Array1::from_vec(lst0.to_vec());
    let arr1 = Array1::from_vec(lst1.to_vec());

    // Calculate squared differences and mean
    let squared_diff = (&arr0 - &arr1).mapv(|x| x * x);
    let mse = squared_diff.mean().unwrap();

    Ok(mse)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_mse() {
        let a = vec![1.0, 2.0, 3.0];
        let b = vec![4.0, 5.0, 6.0];
        assert_eq!(mean_squared_error(&a, &b).unwrap(), 9.0);
    }

