/// ).unwrap();
///
/// let result = group_and_sum(&df, "A", vec!["B", "C"]).unwrap();
/// println!("{:?}", result);
/// ```
pub fn group_and_sum(
    df: &DataFrame,
    group_by_col: &str,
    sum_cols: Vec<&str>,
) -> Result<DataFrame, Box<dyn Error>> {
    // Ensure the group by column exists
    if !df.column(group_by_col).is_ok() {
        return Err(format!("Column '{}' not found", group_by_col).into());
    }

    // Ensure all sum columns exist
    for col in &sum_cols {
        if !df.column(col).is_ok() {
            return Err(format!("Column '{}' not found", col).into());
        }
    }

    // Group by the specified column
    let grouped = df
        .lazy()
        .group_by([group_by_col])?
        .agg(sum_cols.iter().map(|col| colparse::sum(col)).collect::<Vec<_>>())?
        .collect()?;

    Ok(grouped)
}

