use serde_json::Value;
use num_bigint::BigInt;
use std::str::FromStr;

/// Return true if every element of `items` is a two-item grouping (an array of length 2)
/// where:
///  - the first component can be interpreted as a wide-range integer (BigInt). Accepts
///    either a JSON string containing an integer, or a JSON integer number (i64/u64).
///  - the second component is a standard integer (i64). It must be a JSON integer number
///    that fits in i64.
///
/// Examples of accepted per-item forms:
///   ["123456789012345678901234567890", 42]
///   [12345, -1]
///
/// Non-accepted examples:
///   ["12.34", 5]         // first is not an integer
///   [123, 1.5]           // second is not an integer
///   ["not-a-number", 0]  // first cannot be parsed
pub fn all_two_item_bigint_first(items: &[Value]) -> bool {
    for item in items {
        // Each item must be an array of length 2
        let arr = match item {
            Value::Array(a) if a.len() == 2 => a,
            _ => return false,
        };

        // First element: must be parseable as BigInt.
        let first_ok = match &arr[0] {
            Value::String(s) => BigInt::from_str(s).is_ok(),
            Value::Number(n) => {
                // serde_json::Number internally stores integers as i64/u64 or floats as f64.
                // Accept only integers (i64 or u64).
                if n.is_i64() || n.is_u64() {
                    // parsing to BigInt will succeed, so accept
                    true
                } else {
                    // float or otherwise non-integer
                    false
                }
            }
            _ => false,
        };
        if !first_ok {
            return false;
        }

        // Second element: must be an integer number that fits in i64
        let second_ok = match &arr[1] {
            Value::Number(n) => n.as_i64().is_some(),
            _ => false,
        };
        if !second_ok {
            return false;
        }
    }

    true
}

