        .into_iter()
        .map(|item| {
            // Try to interpret the item as a two-item grouping
            let either: Either<(i64, i32), U> = item.clone().into();

            match either {
                Either::Left((first, second)) => {
                    // Check if first is a wide-range integer (i64) and second is standard (i32)
                    // Since we already have the types, this is always true if we got here
                    true
                }
                Either::Right(_) => false,
            }
        })
        .collect()
}

