/// assert!(!check_two_item_groupings(&invalid));
/// ```
fn check_two_item_groupings<T: ?Sized>(items: &T) -> bool
where
    T: std::convert::AsRef<[(i128, i32)]> + ?Sized,
{
    // This will only compile and return true if items can be converted to &[(i128, i32)]
    let _ = items.as_ref();
    true
}

// Alternative implementation using trait bounds for compile-time checking:
fn check_two_item_groupings_strict(items: &[(i128, i32)]) -> bool {
    // If this function is called, the types are already verified by the compiler
    !items.is_empty()
}

// Runtime type checking version (using std::any from stdlib):
fn check_two_item_groupings_runtime(items: &dyn std::any::Any) -> bool {
    items.downcast_ref::<Vec<(i128, i32)>>().is_some()
        || items.downcast_ref::<[(i128, i32)]>().is_some()
}

fn main() {
    // Example 1: Valid case - compile time checked
    let valid_items: Vec<(i128, i32)> = vec![
