```

Rust source (lib.rs or main.rs):

```rust
use anyhow::{bail, Result};

/// Extract a subset of text entries from `entries`, starting at `start` and ending at `end` (inclusive).
///
/// - `entries`: slice of text entries (any type that can be converted into String via `ToString`).
/// - `start`, `end`: signed indices. Negative indices count from the end (like Python).
///   For example, -1 means the last element.
/// - The indices are clamped to the valid range [0, len-1].
/// - If the computed start is greater than the computed end after clamping, this returns an error.
///
/// Returns a Vec<String> containing the extracted entries in order.
///
/// Examples:
/// ```
/// let items = vec!["a".to_string(), "b".to_string(), "c".to_string(), "d".to_string()];
/// assert_eq!(extract_subset(&items, 1, 2).unwrap(), vec!["b".to_string(), "c".to_string()]);
/// assert_eq!(extract_subset(&items, -3, -1).unwrap(), vec!["b".to_string(), "c".to_string(), "d".to_string()]);
/// assert_eq!(extract_subset(&items, 2, 10).unwrap(), vec!["c".to_string(), "d".to_string()]);
/// ```
pub fn extract_subset<T: ToString>(entries: &[T], start: isize, end: isize) -> Result<Vec<String>> {
    let len = entries.len() as isize;

    if len == 0 {
        bail!("input entries are empty");
    }

    // Convert signed index to 0..len-1, allowing negative indices like Python.
    let convert = |idx: isize| {
        if idx < 0 {
            // negative: count from end
            let v = len + idx; // e.g., -1 => len - 1
            if v < 0 {
                0
            } else {
                v as usize
            }
        } else {
            // positive or zero
            if idx as isize >= len {
                // clamp to last index
                (len - 1) as usize
            } else {
                idx as usize
            }
        }
    };

    let start_usize = convert(start);
    let end_usize = convert(end);

    if start_usize > end_usize {
        bail!(
            "start index ({}) is after end index ({}) after normalization",
            start_usize,
            end_usize
        );
    }

    // Safe slice; end is inclusive so use end_usize + 1 as exclusive bound.
    let upper = end_usize.checked_add(1).ok_or_else(|| anyhow::anyhow!("index overflow"))?;
    let slice = &entries[start_usize..upper];

    Ok(slice.iter().map(|t| t.to_string()).collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic_positive_indices() {
        let items = vec!["a".to_string(), "b".to_string(), "c".to_string(), "d".to_string()];
        let out = extract_subset(&items, 1, 2).unwrap();
        assert_eq!(out, vec!["b".to_string(), "c".to_string()]);
    }

    #[test]
    fn negative_indices() {
        let items = vec!["a".to_string(), "b".to_string(), "c".to_string(), "d".to_string()];
        let out = extract_subset(&items, -3, -1).unwrap();
        assert_eq!(out, vec!["b".to_string(), "c".to_string(), "d".to_string()]);
    }

    #[test]
    fn clamp_out_of_bounds() {
        let items = vec!["a".to_string(), "b".to_string(), "c".to_string(), "d".to_string()];
        let out = extract_subset(&items, 2, 10).unwrap();
        assert_eq!(out, vec!["c".to_string(), "d".to_string()]);
    }

    #[test]
    fn start_after_end_error() {
        let items = vec!["a".to_string(), "b".to_string()];
        assert!(extract_subset(&items, 2, 0).is_err());
    }
}
```

Notes:
- The function is generic over any T: ToString so you can pass Vec<String>, Vec<&str>, etc.
- Start and end are inclusive (common when users say "ending at a specified end index"). If you prefer exclusive end, change `upper = end_usize` rather than `end_usize + 1`.
- I used anyhow for concise errors; remove it and replace Result<anyhow::Error> with std::result::Result if you prefer not to add dependencies.

