```rust
use unicode_segmentation::UnicodeSegmentation;

/// Given rows (Vec of rows, each row is a Vec of text-like values),
/// return a Vec<String> where each element is the longest text found in that column.
///
/// Length is measured in grapheme clusters using unicode-segmentation.
///
/// Example:
/// let rows = vec![
///     vec!["a", "hello", "猫"],
///     vec!["longer", "hi"],
///     vec!["x", "supercalifragilistic", "🐱‍👤"],
/// ];
/// let longest = longest_in_columns(&rows);
/// assert_eq!(longest, vec![ "longer".to_string(), "supercalifragilistic".to_string(), "🐱‍👤".to_string() ]);
pub fn longest_in_columns<T: AsRef<str>>(rows: &[Vec<T>]) -> Vec<String> {
    // Find maximum number of columns across all rows
    let max_cols = rows.iter().map(|r| r.len()).max().unwrap_or(0);

    let mut result = Vec::with_capacity(max_cols);

    for col_idx in 0..max_cols {
        let mut best: Option<String> = None;
        let mut best_len = 0usize;

        for row in rows {
            if let Some(cell) = row.get(col_idx) {
                let s = cell.as_ref();
                // Count grapheme clusters for more correct "visible character" length
                let len = UnicodeSegmentation::graphemes(s, true).count();

                if best.is_none() || len > best_len {
                    best = Some(s.to_string());
                    best_len = len;
                }
            }
        }

        // If no cell was present in this column across all rows, push empty string.
        // (This situation shouldn't occur because max_cols came from rows' lengths,
        // but keep this defensive.)
        result.push(best.unwrap_or_else(String::new));
    }

    result
}

