use ordered_float::OrderedFloat;
use std::num::ParseFloatError;

/// Reorder `lst0` in place, sorting elements in ascending order by their
/// floating-point value (each element is converted with `to_string().parse::<f64>()`).
///
/// Returns Err(ParseFloatError) if any element fails to parse as an f64.
///
/// Example:
/// let mut v = vec!["3.14".to_string(), "2".to_string(), "-1.5".to_string()];
/// reorder_by_float_inplace(&mut v).unwrap();
/// assert_eq!(v, vec!["-1.5", "2", "3.14"].iter().map(ToString::to_string).collect::<Vec<_>>());
pub fn reorder_by_float_inplace<T>(lst0: &mut [T]) -> Result<(), ParseFloatError>
where
    T: ToString + Clone,
{
    // Build a_vec of (parsed_value, original_element)
    let mut pairs: Vec<(OrderedFloat<f64>, T)> = Vec::with_capacity(lst0.len());
    for item in lst0.iter() {
        let s = item.to_string();
        let v: f64 = s.parse()?; // may return ParseFloatError
        pairs.push((OrderedFloat(v), item.clone()));
    }

    // Sort by the parsed f64 (OrderedFloat provides total ordering)
    pairs.sort_by_key(|(ord_f, _)| *ord_f);

    // Write the sorted elements back into the original slice
    for (i, (_, item)) in pairs.into_iter().enumerate() {
        lst0[i] = item;
    }

    Ok(())
}

fn main() {
    let mut v = vec![
        "NaN".to_string(),
        "3.0".to_string(),
        "-0.0".to_string(),
        "2.72".to_string(),
        "-1".to_string(),
    ];

    reorder_by_float_inplace(&mut v).unwrap();

    println!("{:?}", v);
    // Depending on total-order chosen by OrderedFloat, NaNs compare consistently.
}
```

