pub fn reorder_by_float<T: Into<f64> + Clone>(lst0: &mut [T]) {
    // Create a vector of (float_value, original_index) pairs
    let mut indexed: Vec<(f64, usize)> = lst0
        .iter()
        .enumerate()
        .map(|(i, val)| (val.clone().into(), i))
        .collect();

