    let mut pairs: Vec<(String, i64)> = sums.into_iter().collect();
    pairs.sort_unstable_by_key(|(_, v)| std::cmp::Reverse(*v));

    // 3) collect into an IndexMap to preserve sorted order as a mapping
    let mut ordered = IndexMap::with_capacity(pairs.len());
    for (k, v) in pairs {
        ordered.insert(k, v);
    }
    ordered
