use polars::prelude::*;
use std::collections::HashMap;

/// Updates specific cells in df0 based on matching values from df1.
/// 
/// For each row in df1, finds the corresponding row in df0 where the key columns match,
/// and updates the specified target column with the value from df1's source column.
///
/// # Arguments
/// * `df0` - The DataFrame to be updated (will be modified)
/// * `df1` - The DataFrame containing the new values
/// * `key_columns` - Columns used to match rows between the two DataFrames
/// * `target_column` - The column in df0 to update
/// * `source_column` - The column in df1 containing the new values
///
/// # Returns
/// * `Result<DataFrame>` - The updated DataFrame or an error
pub fn update_cells_from_df(
    df0: &DataFrame,
    df1: &DataFrame,
    key_columns: &[&str],
    target_column: &str,
    source_column: &str,
) -> Result<DataFrame> {
    // Validate that all required columns exist
    for col in key_columns {
        if !df0.get_column_names().contains(col) {
            return Err(PolarsError::ComputeError(
                format!("Key column '{}' not found in df0", col).into(),
            ));
        }
        if !df1.get_column_names().contains(col) {
            return Err(PolarsError::ComputeError(
                format!("Key column '{}' not found in df1", col).into(),
            ));
        }
    }

    if !df0.get_column_names().contains(&target_column) {
        return Err(PolarsError::ComputeError(
            format!("Target column '{}' not found in df0", target_column).into(),
        ));
    }

    if !df1.get_column_names().contains(&source_column) {
        return Err(PolarsError::ComputeError(
            format!("Source column '{}' not found in df1", source_column).into(),
        ));
    }

    // Build a lookup map from df1: key -> new value
    let mut lookup: HashMap<Vec<AnyValue>, AnyValue> = HashMap::new();

    for i in 0..df1.height() {
        let key: Vec<AnyValue> = key_columns
            .iter()
            .map(|col| df1.column(col).unwrap().get(i).unwrap())
            .collect();

        let new_value = df1.column(source_column).unwrap().get(i).unwrap();
        lookup.insert(key, new_value);
    }

    // Create a new column with updated values
    let mut new_values: Vec<AnyValue> = Vec::with_capacity(df0.height());

    for i in 0..df0.height() {
        let key: Vec<AnyValue> = key_columns
            .iter()
            .map(|col| df0.column(col).unwrap().get(i).unwrap())
            .collect();

        let current_value = df0.column(target_column).unwrap().get(i).unwrap();

        // If we have a matching key in df1, use the new value; otherwise keep the original
        let updated_value = match lookup.get(&key) {
            Some(new_val) => new_val.clone(),
            None => current_value,
        };

        new_values.push(updated_value);
    }

    // Replace the target column with updated values
    let mut result = df0.clone();
    let series = Series::new(target_column, new_values);
    result.replace(target_column, series)?;

    Ok(result)
