```rust
use polars::prelude::*;

/// Updates specific cells in df0 based on corresponding cells in df1
/// 
/// # Arguments
/// * `df0` - The main dataframe to be updated
/// * `df1` - The source dataframe containing update values
/// * `condition_col` - Column name to use as condition (must exist in both dataframes)
/// * `condition_value` - The value to match in the condition column
/// * `update_cols` - Columns to update (must exist in both dataframes)
/// 
/// # Returns
/// * Updated DataFrame where cells matching the condition are replaced with values from df1
fn update_cells_from_dataframe(
    mut df0: DataFrame,
    df1: &DataFrame,
    condition_col: &str,
    condition_value: &str,
    update_cols: Vec<&str>,
) -> Result<DataFrame> {
    // Get rows from df1 where condition matches
    let mask = df1
        .column(condition_col)?
        .equal(condition_value)?;

    let df1_filtered = df1.filter(&mask)?;

    // Update each specified column
    for col_name in update_cols {
        let update_series = df1_filtered.column(col_name)?;

        // Get the mask for df0 where condition matches
        let df0_mask = df0
            .column(condition_col)?
            .equal(condition_value)?;

        // Get the current column and update matching rows
        let mut current_col = df0.column(col_name)?.clone();

        // Apply the update
        current_col = current_col.zip_with(&df0_mask, update_series)?;

        // Replace the column in df0
        df0 = df0.with_columns([current_col.rename(col_name)])?;
    }

    Ok(df0)
}

