```rust
use polars::prelude::*;

fn update_with_join(
    mut df0: DataFrame,
    df1: &DataFrame,
    join_col: &str,
    update_cols: Vec<&str>,
) -> Result<DataFrame> {
    // Rename update columns in df1 to avoid conflicts
    let df1_renamed = df1
        .select(
            std::iter::once(join_col)
                .chain(update_cols.iter().copied())
                .collect::<Vec<_>>()
        )?
        .rename(
            &update_cols,
            &update_cols.iter().map(|c| format!("{}_new", c)).collect::<Vec<_>>(),
        )?;

    // Left join
    let joined = df0.join(df1_renamed, [join_col], [join_col], JoinType::Left)?;

    // Replace old columns with new ones
    let mut result = joined.drop_many(&update_cols)?;
    for col_name in update_cols {
        let new_col_name = format!("{}_new", col_name);
        result = result.rename(&[new_col_name.as_str()], &[col_name])?;
    }

    Ok(result)
}
```

