/// * `var1` - Column name whose values will be used for comparison and assignment
/// * `var2` - Column name to update with values from `var1`
///
/// # Returns
/// A new DataFrame with the specified updates
pub fn update_matching_rows(df0: &DataFrame, var0: &str, var1: &str, var2: &str) -> Result<DataFrame, PolarsError> {
    // Create a boolean mask where var0 equals var1
    let mask = df0.column(var0)?
        .eq(df0.column(var1)?)
        .unwrap();

    // Create a new column with var1's values where the mask is true, otherwise keep original var2
    let new_var2 = df0.column(var2)?
        .map(|s| {
