use polars::prelude::*;

/// Rename the row label at index `row_idx` to `new_label`.
///
/// - df: input DataFrame (consumed and returned).
/// - row_idx: the zero-based row index whose label to rename.
/// - new_label: the new label string to set.
/// 
/// Assumption: the DataFrame's first column is the "row label" column.
/// Returns a modified DataFrame on success or a Polars error on failure.
pub fn rename_row_label(mut df: DataFrame, row_idx: usize, new_label: &str) -> PolarsResult<DataFrame> {
    // Get the name of the first column (treated as the row-label column).
    let first_col_name = df
        .get_column_names()
        .get(0)
        .ok_or_else(|| PolarsError::NoData("DataFrame has no columns".into()))?
        .clone();

    // Borrow the series for the index column.
    let series = df.column(&first_col_name)?;

    // Ensure the index column is utf8 (string) type.
    let utf = series
        .utf8()
        .map_err(|_| PolarsError::Other("Index column must be Utf8 (string) type".into()))?;

    // Collect values into a Vec<Option<String>> so we can mutate one entry.
    let mut labels: Vec<Option<String>> = utf
        .into_iter()
        .map(|opt| opt.map(|s| s.to_string()))
        .collect();

    // Bounds check.
    if row_idx >= labels.len() {
        return Err(PolarsError::ComputeError(
            format!("row index {} out of bounds (len={})", row_idx, labels.len()).into(),
        ));
    }

    // Replace the requested label.
    labels[row_idx] = Some(new_label.to_string());

    // Create a new series and replace the column in the DataFrame.
    let new_series = Series::new(&first_col_name, labels);
    df.replace(&first_col_name, new_series)?;

    Ok(df)
}
