use std::collections::HashMap;
use serde_json::Value;

/// Update an existing mapping `dict0` by adding or modifying entries with keys/values
/// obtained dynamically from `var0` (a serde_json::Value).
///
/// Supported var0 shapes:
/// - Object: {"k": v, ...} => dict0["k"] = v.to_string()
/// - Array of pairs: [["k", v], ["k2", v2]] => dict0["k"] = v.to_string()
/// - Array of single-key objects: [{"k": v}, {"k2": v2}] => dict0["k"] = v.to_string()
///
/// Returns Ok(()) on success or Err(String) with a human-readable message when
/// var0 is not in a supported shape or contains an invalid key type.
pub fn update_dict_from_var0(
    dict0: &mut HashMap<String, String>,
    var0: &Value,
) -> Result<(), String> {
    match var0 {
        Value::Object(map) => {
            for (k, v) in map {
                dict0.insert(k.clone(), value_to_string(v));
            }
            Ok(())
        }

        Value::Array(arr) => {
            for item in arr {
                match item {
                    // pair form: ["key", value]
                    Value::Array(pair) if pair.len() == 2 => {
                        if let Value::String(k) = &pair[0] {
                            dict0.insert(k.clone(), value_to_string(&pair[1]));
                        } else {
                            return Err("expected string key in pair array".into());
                        }
                    }

                    // single-key object form: {"key": value}
                    Value::Object(single) if single.len() == 1 => {
                        if let Some((k, v)) = single.iter().next() {
                            dict0.insert(k.clone(), value_to_string(v));
                        }
                    }

                    // ignore null/empty items; treat other shapes as error
                    other => {
                        return Err(format!(
                            "unsupported array item shape in var0: {}",
                            other
                        ));
                    }
                }
            }
            Ok(())
        }

        other => Err(format!("unsupported var0 shape: {}", other)),
    }
}

/// Helper: convert a serde_json::Value to String for storage in dict0.
/// Strings are stored without extra quotes; other JSON values are serialized with to_string().
fn value_to_string(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        _ => v.to_string(),
    }
}

