        _ => Err(nom::Err::Failure(nom::error::Error::new(input, nom::error::ErrorKind::TakeWhile1))),
    }
}

// Parser for range expressions (e.g., "between 10 and 20")
fn parse_range(input: &str) -> IResult<&str, (f64, f64)> {
    let (input, _) = tag("between")(input)?;
    let (input, _) = multispace1(input)?;
    let (input, lower) = parse_number(input)?;
    let (input, _) = multispace1(input)?;
    let (input, _) = tag("and")(input)?;
    let (input, _) = multispace1(input)?;
    let (input, upper) = parse_number(input)?;
    Ok((input, (lower, upper)))
}

// Main parser for numerical expressions
fn parse_numerical_expression(input: &str) -> IResult<&str, NumericalExpression> {
    alt((
        // Simple number
        map(parse_number, |v| NumericalExpression::Value(v)),

        // Comparison with number (e.g., "less than 10")
        map(
            pair(
                parse_comparison,
                preceded(multispace1, parse_number),
            ),
            |(op, v)| NumericalExpression::Comparison { value: v, op, range: None },
        ),

        // Range expression (e.g., "between 10 and 20")
        map(
            parse_range,
            |range| NumericalExpression::Comparison {
                value: range.0,
                op: Comparison::Between,
                range: Some(range),
            },
        ),
    ))(input)
}

// Main function to extract all numerical expressions from a string
pub fn extract_numerical_expressions(input: &str) -> Vec<NumericalExpression> {
    let mut remaining = input;
    let mut results = Vec::new();

    while let Ok((remaining_part, expr)) = parse_numerical_expression(remaining) {
        results.push(expr);
        remaining = remaining_part;
    }

    results
}

