        ("ranging from", "between"),
        ("exactly", "exactly"),
        ("equal to", "exactly"),
        ("approximately", "approximately"),
        ("about", "approximately"),
        ("around", "approximately"),
        ("roughly", "approximately"),
        ("nearly", "approximately"),
    ].iter().cloned().collect();

    // Pattern for numerical values (including decimals and ranges)
    let number_pattern = Regex::new(r"\d+(?:\.\d+)?(?:\s*[-–to]\s*\d+(?:\.\d+)?)?").unwrap();

    // Pattern for units (common measurement units)
    let unit_pattern = Regex::new(r"(?i)(?:kg|kilograms?|g|grams?|lb|pounds?|oz|ounces?|cm|centimeters?|m|meters?|km|kilometers?|mi|miles?|years?|months?|days?|hours?|minutes?|seconds?|%|percent|°[CF]|degrees?|€|\$|£|¥|USD|EUR|GBP)").unwrap();

    // First, try to find "between X and Y" patterns
    let between_pattern = Regex::new(r"(?i)(?:between|from|ranging from)\s+(\d+(?:\.\d+)?)\s*(?:and|to|-)\s*(\d+(?:\.\d+)?)\s*(.*?)(?=[,.;]|$)").unwrap();
    for cap in between_pattern.captures_iter(text) {
        let value1 = cap.get(1).map(|m| m.as_str()).unwrap_or("");
        let value2 = cap.get(2).map(|m| m.as_str()).unwrap_or("");
        let rest = cap.get(3).map(|m| m.as_str().trim()).unwrap_or("");

        let unit = unit_pattern.find(rest).map(|m| m.as_str().to_string());
        results.push(("between".to_string(), format!("{}-{}", value1, value2), unit));
    }

    // Find comparison terms and their associated values
    for (pattern, normalized) in &comparison_patterns {
        let re_pattern = format!(r"(?i){}\s+(\d+(?:\.\d+)?(?:\s*[-–to]\s*\d+(?:\.\d+)?)?)\s*(.*?)(?=[,.;]|$)", 
            regex::escape(pattern));

        if let Ok(re) = Regex::new(&re_pattern) {
            for cap in re.captures_iter(text) {
                let value = cap.get(1).map(|m| m.as_str()).unwrap_or("");
                let rest = cap.get(2).map(|m| m.as_str().trim()).unwrap_or("");

                // Skip if this was already captured by the between pattern
                if *normalized == "between" {
                    continue;
                }

                let unit = unit_pattern.find(rest).map(|m| m.as_str().to_string());
                results.push((normalized.to_string(), value.to_string(), unit));
            }
        }
    }

    // Find standalone numerical values (without comparison terms)
    let standalone_pattern = Regex::new(r"(?i)(?:^|[,;.]\s*)(\d+(?:\.\d+)?)\s*(.*?)(?=[,.;]|$)").unwrap();
    for cap in standalone_pattern.captures_iter(text) {
        let value = cap.get(1).map(|m| m.as_str()).unwrap_or("");
        let rest = cap.get(2).map(|m| m.as_str().trim()).unwrap_or("");

        // Check if this value was already captured with a comparison term
        let already_captured = results.iter().any(|(_, v, _)| v == value);
        if !already_captured {
            let unit = unit_pattern.find(rest).map(|m| m.as_str().to_string());
            results.push(("exactly".to_string(), value.to_string(), unit));
        }
    }

    results
