pub fn argmax_col_per_row(df: &DataFrame) -> PolarsResult<Vec<Option<String>>> {
    // Collect numeric columns cast to Float64
    let mut numeric_cols: Vec<(String, ChunkedArray<Float64Type>)> = Vec::new();
    for s in df.get_columns() {
        // Try to cast column to Float64; skip if cast fails
