use itertools::Itertools; // optional convenience; you can remove this line and the dependency if you like

/// Sort a list of version identifiers (numeric segments separated by dots) in ascending order.
///
/// Behavior:
/// - Each dot-separated segment is parsed as u64. Non-numeric segments are treated as zero.
/// - Comparison is lexicographic on the numeric segments. If one version has fewer segments but
///   all compared segments are equal, the shorter version is considered smaller
///   (e.g., "1.2" < "1.2.0").
///
/// Input: any iterable of &str (or String via .as_str())
/// Output: a Vec<String> with versions sorted in ascending order.
pub fn sort_versions<S, I>(versions: I) -> Vec<String>
where
    S: AsRef<str>,
    I: IntoIterator<Item = S>,
{
    // Parse each version string into a vector of numeric segments, pairing with original string.
    let mut parsed: Vec<(Vec<u64>, String)> = versions
        .into_iter()
        .map(|s| {
            let s_ref = s.as_ref();
            let segments: Vec<u64> = s_ref
                .split('.')
                .map(|seg| seg.parse::<u64>().unwrap_or(0))
                .collect();
