/// Remove from `mat0` each column whose index appears in `columns_to_delete`.
///
/// - `mat0`: input 2-D matrix (rows x cols)
/// - `columns_to_delete`: an iterable of column indices to remove (0-based).
/// Returns a new Array2 with the remaining columns in original order.
///
/// Out-of-range indices in `columns_to_delete` are ignored.
pub fn remove_columns<T: Clone>(
    mat0: &Array2<T>,
    columns_to_delete: impl IntoIterator<Item = usize>,
) -> Array2<T> {
    let nrows = mat0.nrows();
    let ncols = mat0.ncols();

    // Collect indices to delete into a HashSet, ignoring out-of-range indices.
    let to_delete: HashSet<usize> = columns_to_delete
        .into_iter()
        .filter(|&i| i < ncols)
        .collect();

    // Build vector of kept column indices in original order.
    let keep_cols: Vec<usize> = (0..ncols).filter(|i| !to_delete.contains(i)).collect();

    // Create new array with shape (nrows, kept_cols.len()) and copy elements.
    Array2::from_shape_fn((nrows, keep_cols.len()), |(r, c)| {
        mat0[(r, keep_cols[c])].clone()
    })
}

