/// Panics if any column index in `columns_to_delete` is out of bounds
/// or if removing all columns
pub fn remove_columns<T: Clone>(
    mat0: &Array2<T>,
    columns_to_delete: &[usize],
) -> Array2<T> {
    let ncols = mat0.ncols();

    // Create a sorted, deduplicated list of columns to keep
    let mut delete_set: Vec<bool> = vec![false; ncols];
    for &col in columns_to_delete {
        assert!(col < ncols, "Column index {} out of bounds (matrix has {} columns)", col, ncols);
        delete_set[col] = true;
    }

    let keep_indices: Vec<usize> = (0..ncols)
        .filter(|&i| !delete_set[i])
        .collect();

    assert!(!keep_indices.is_empty(), "Cannot delete all columns from matrix");

    // Select the columns to keep
    mat0.select(Axis(1), &keep_indices)
}

