/// ```
pub fn count_unique_values(df0: &DataFrame, lst0: &[&str]) -> HashMap<String, HashMap<String, usize>> {
    let mut result = HashMap::new();

    for col_name in lst0 {
        // Get the column from the DataFrame
        match df0.column(col_name) {
            Some(col) => {
                // Create a new HashMap for this column
                let mut col_counts = HashMap::new();

                // Process each value in the column
                for value in col.iter() {
                    // Convert the value to a string representation
                    let value_str = match value {
                        // Handle different data types
                        Value::Utf8(s) => s.to_string(),
                        Value::Int64(i) => i.to_string(),
                        Value::Float64(f) => f.to_string(),
                        Value::Boolean(b) => b.to_string(),
