use polars::prelude::*;
use std::iter::zip;

fn element_wise_difference(df0: &DataFrame, df1: &DataFrame) -> Result<DataFrame> {
    // Ensure both DataFrames have the same schema and number of rows
    if df0.schema() != df1.schema() || df0.height() != df1.height() {
        return Err(PolarsError::ComputeError(
            "DataFrames must have the same schema and number of rows".into(),
        ));
    }

    // Create a new vector to store the resulting Series
    let mut result_series = Vec::with_capacity(df0.width());

    // Iterate over each column name and index
    for (name, idx) in df0.get_column_names().iter().enumerate() {
        // Get the Series for the current column from both DataFrames
        let series0 = df0.column(name)?;
        let series1 = df1.column(name)?;

        // Ensure both Series have the same data type
        if series0.dtype() != series1.dtype() {
            return Err(PolarsError::ComputeError(
                format!("Column '{}' must have the same data type in both DataFrames", name).into(),
            ));
        }

        // Compute the element-wise difference based on the data type
        let diff_series = match series0.dtype() {
            DataType::Int32 => {
                let s0 = series0.i32()?;
                let s1 = series1.i32()?;
                let diff = s0.iter().zip(s1.iter()).map(|(a, b)| match (a, b) {
                    (Some(a), Some(b)) => Some(a - b),
                    _ => None,
                });
                Series::new(name, diff)
            }
            DataType::Int64 => {
                let s0 = series0.i64()?;
                let s1 = series1.i64()?;
                let diff = s0.iter().zip(s1.iter()).map(|(a, b)| match (a, b) {
                    (Some(a), Some(b)) => Some(a - b),
                    _ => None,
                });
                Series::new(name, diff)
            }
            DataType::Float32 => {
                let s0 = series0.f32()?;
                let s1 = series1.f32()?;
                let diff = s0.iter().zip(s1.iter()).map(|(a, b)| match (a, b) {
                    (Some(a), Some(b)) => Some(a - b),
                    _ => None,
                });
                Series::new(name, diff)
            }
            DataType::Float64 => {
                let s0 = series0.f64()?;
                let s1 = series1.f64()?;
                let diff = s0.iter().zip(s1.iter()).map(|(a, b)| match (a, b) {
                    (Some(a), Some(b)) => Some(a - b),
                    _ => None,
                });
                Series::new(name, diff)
            }
            _ => {
                return Err(PolarsError::ComputeError(
                    format!("Unsupported data type for column '{}'", name).into(),
                ));
            }
        };

        // Add the resulting Series to the vector
        result_series.push(diff_series);
    }

    // Create a new DataFrame from the resulting Series
    DataFrame::new(result_series)
}

fn main() -> Result<()> {
    // Example usage
    let df0 = df![
        "A" => &[1, 2, 3],
        "B" => &[4.0, 5.5, 6.1],
        "C" => &[7, 8, 9]
    ]?;

    let df1 = df![
        "A" => &[0, 2, 1],
        "B" => &[1.0, 4.5, 5.1],
        "C" => &[6, 8, 8]
