/// Compute element-wise difference df0 - df1 for two identically-shaped DataFrames.
///
/// - Requires same shape and same column names (and column order).
/// - All columns are cast to Float64 and subtracted; result columns are Float64.
/// - Returns an error if shapes or column names differ or a cast/arithmetic fails.
pub fn elementwise_diff(df0: &DataFrame, df1: &DataFrame) -> PolarsResult<DataFrame> {
    // Check shapes (rows, cols)
    if df0.shape() != df1.shape() {
        return Err(PolarsError::ComputeError(
            format!(
                "DataFrames must have the same shape: got {:?} and {:?}",
                df0.shape(),
                df1.shape()
            )
            .into(),
        ));
    }

    // Check same column names (and order)
    let names0 = df0.get_column_names();
    let names1 = df1.get_column_names();
    if names0 != names1 {
        return Err(PolarsError::ComputeError(
            "DataFrames must have the same column names in the same order".into(),
        ));
    }

    let mut cols: Vec<Series> = Vec::with_capacity(df0.width());
    for name in names0 {
        let s0 = df0.column(&name)?;
        let s1 = df1.column(&name)?;

        // Cast both sides to Float64 (so mixed integer/float columns are handled uniformly).
        // If a column cannot be cast to Float64, this will return an error.
        let s0f = s0.cast(&DataType::Float64)?;
        let s1f = s1.cast(&DataType::Float64)?;

        // Element-wise subtraction: series implements Sub
        let diff = &s0f - &s1f;

        // Ensure the resulting series has the original column name
        let diff = diff.rename(&name);
        cols.push(diff);
    }

    DataFrame::new(cols)
}

