///     "col2" => &["a", "b", "a", "b", "a"]
/// );
/// let result = count_pairs(&df, "col1", "col2");
/// assert_eq!(result.len(), 3);
/// ```
pub fn count_pairs(df: &DataFrame, col1: &str, col2: &str) -> Vec<(String, i64)> {
    // Create a new DataFrame with the concatenated columns
    let df_pairs = df
        .clone()
        .lazy()
        .with_column(
            colars::prelude::concat(
                col1,
                &col2,
                Some("pair"),
                Some(concat_str::ConcatSeparator::Literal("|".to_string())),
            ),
        )
        .collect()
        .unwrap();

