    let result = df_pairs
        .lazy()
        .group_by([colars::prelude::col("pair")])
        .agg([col("pair").count()])
        .collect()
        .unwrap();

    // Convert to the desired output format
    let mut output = Vec::new();
    for row in result.rows() {
        let pair = row.get(0).unwrap().as_str().unwrap().to_string();
        let count = row.get(1).unwrap().i64().unwrap();
        output.push((pair, count));
    }

    output
}

