Below is a self-contained Rust function that uses the Polars crate (actively maintained with releases in 2023+) to compute the frequency of each unique pair of values in two columns ("col1" and "col2") of an input DataFrame. The function returns a Vec of ((String, String), usize) tuples: ((value_from_col1, value_from_col2), count). Rows with nulls in either column are skipped.

Cargo dependency (add to your Cargo.toml):
- polars = "0.31"  (or any recent 2023+ release)

Code:

```rust
use polars::prelude::*;
use std::collections::HashMap;

/// Compute frequency of each unique (col1, col2) pair in `df`.
/// Returns a Vec of ((value_col1, value_col2), count) sorted by descending count.
/// Rows where either column is null are skipped.
pub fn pair_frequencies(
    df: &DataFrame,
    col1: &str,
    col2: &str,
) -> PolarsResult<Vec<((String, String), usize)>> {
    let a = df.column(col1)?.utf8()?;
    let b = df.column(col2)?.utf8()?;

    if a.len() != b.len() {
        return Err(PolarsError::ComputeError(
            "columns have different lengths".into(),
        ));
    }

    let mut map: HashMap<(String, String), usize> = HashMap::new();

    for idx in 0..a.len() {
        match (a.get(idx), b.get(idx)) {
            (Some(s1), Some(s2)) => {
                *map.entry((s1.to_string(), s2.to_string())).or_insert(0) += 1;
            }
            _ => {
                // skip rows where either value is null
            }
        }
    }

    let mut vec: Vec<_> = map.into_iter().collect();
    // sort by count descending
    vec.sort_by(|a, b| b.1.cmp(&a.1));
    Ok(vec)
}

fn main() -> PolarsResult<()> {
    // Example usage
    let s1 = Series::new("col1", &["A", "B", "A", "A", "B"]);
    let s2 = Series::new("col2", &["X", "X", "X", "Y", "X"]);
    let df = DataFrame::new(vec![s1, s2])?;

    let freqs = pair_frequencies(&df, "col1", "col2")?;
    for ((v1, v2), cnt) in freqs {
        println!("({}, {}) => {}", v1, v2, cnt);
    }

    Ok(())
}
```

