///     "value" => &[10.0, 20.0, 30.0]
/// ).unwrap();
///
/// let result = moving_average_time_window(df, "timestamp", "value", "2d").unwrap();
/// println!("{:?}", result);
/// ```
pub fn moving_average_time_window(
    df0: DataFrame,
    str0: &str,
    value_col: &str,
    var0: &str,
) -> Result<DataFrame> {
    // Parse the window duration
    let window_duration = parse_duration(var0)?;

    // Ensure the timestamp column is sorted
    let df = df0
        .clone()
        .lazy()
        .sort(
            [col(str0)],
            SortOptions {
                descending: false,
                nulls_last: true,
                ..Default::default()
            },
        )
        .collect()?;

    // Get the timestamp column as a Series
    let timestamps = df.column(str0)?.datetime()?;
    let values = df.column(value_col)?;

    // Convert to Vec for processing
    let timestamps_vec: Vec<i64> = timestamps
        .into_iter()
        .map(|opt| opt.unwrap())
        .collect();

    let values_vec: Vec<f64> = values
        .f64()?
        .into_iter()
        .map(|opt| opt.unwrap())
        .collect();

    // Calculate moving averages
    let window_ns = duration_to_nanoseconds(&window_duration);
    let mut moving_averages: Vec<Option<f64>> = Vec::with_capacity(timestamps_vec.len());

    for i in 0..timestamps_vec.len() {
        let current_ts = timestamps_vec[i];
        let window_start = current_ts.sub(window_ns);

        // Find all values within the window
        let mut sum = 0.0;
        let mut count = 0;

        for j in (0..=i).rev() {
            if timestamps_vec[j] >= window_start {
                sum += values_vec[j];
                count += 1;
            } else {
                break; // Since timestamps are sorted, we can break early
            }
        }

        if count > 0 {
            moving_averages.push(Some(sum / count as f64));
        } else {
            moving_averages.push(None);
        }
    }

    // Add the moving average column to the DataFrame
    let result = df
        .clone()
        .lazy()
        .with_column(
            Series::new("moving_avg", moving_averages)
                .into_series()
                .alias("moving_avg"),
        )
        .collect()?;

    Ok(result)
}

/// Parse a duration string into a Duration struct
fn parse_duration(duration_str: &str) -> Result<Duration> {
    let duration_str = duration_str.trim().to_lowercase();

    let (value_str, unit) = duration_str.split_at(
        duration_str.len() - 1
    );

    let value: i64 = value_str
        .parse()
        .map_err(|_| PolarsError::ComputeError(
            format!("Invalid duration value: {}", value_str).into()
        ))?;

    match unit {
        "d" => Ok(Duration::parse(format!("{}d", value).as_str())),
        "h" => Ok(Duration::parse(format!("{}h", value).as_str())),
        "m" => Ok(Duration::parse(format!("{}m", value).as_str())),
        "s" => Ok(Duration::parse(format!("{}s", value).as_str())),
        _ => Err(PolarsError::ComputeError(
            format!("Invalid duration unit: {}. Use d, h, m, or s", unit).into()
        )),
    }
}

/// Convert a Duration to nanoseconds
fn duration_to_nanoseconds(duration: &Duration) -> i64 {
    // Duration in polars is stored as nanoseconds
    // We need to extract the actual nanosecond value
    // This is a simplified conversion - in practice you'd use Duration's methods
    let duration_str = format!("{:?}", duration);
    let parts: Vec<&str> = duration_str.split_whitespace().collect();

    if parts.len() >= 2 {
        let value: i64 = parts[0].parse().unwrap_or(0);
        let unit = parts[1];

        match unit {
            "ns" => value,
            "us" => value * 1000,
            "ms" => value * 1_000_000,
            "s" => value * 1_000_000_000,
            "m" => value * 60_000_000_000,
            "h" => value * 3_600_000_000_000,
            "d" => value * 86_400_000_000_000,
            _ => value,
        }
    } else {
        0
    }
}

