/// Create a two-level index column from `col0` and `col1` and move it to the first column.
/// Returns a new DataFrame with the combined index column (named `index_name`) and
/// with the original `col0` and `col1` removed.
///
/// Note: Polars does not implement a pandas-style MultiIndex; this function encodes the
/// two levels into a single composite string column "(level0,level1)". If you prefer
/// a different encoding (e.g. "level0||level1"), pass a different `sep` string.
pub fn set_two_level_index(
    mut df: DataFrame,
    col0: &str,
    col1: &str,
    index_name: &str,
    sep: &str,
) -> PolarsResult<DataFrame> {
    // Ensure columns exist
    if df.find_idx_by_name(col0).is_none() {
        return Err(PolarsError::NotFound(format!("column '{}' not found", col0).into()));
    }
    if df.find_idx_by_name(col1).is_none() {
        return Err(PolarsError::NotFound(format!("column '{}' not found", col1).into()));
    }

    // Obtain Utf8Chunked for both columns; cast to Utf8 if necessary.
    let s0_series = df.column(col0)?;
    let s0_utf8 = match s0_series.utf8() {
        Ok(u) => u.clone(),
        Err(_) => s0_series.cast(&DataType::Utf8)?.utf8()?.clone(),
    };

    let s1_series = df.column(col1)?;
    let s1_utf8 = match s1_series.utf8() {
        Ok(u) => u.clone(),
        Err(_) => s1_series.cast(&DataType::Utf8)?.utf8()?.clone(),
    };

    // Build the composite index as Vec<Option<String>>
    let iter0 = s0_utf8.into_iter();
    let iter1 = s1_utf8.into_iter();

    let idx_vec: Vec<Option<String>> = iter0
        .zip(iter1)
        .map(|(o0, o1)| match (o0, o1) {
            (Some(a), Some(b)) => Some(format!("({}{}{})", a, sep, b)),
            (Some(a), None) => Some(format!("({}{}{})", a, sep, "")),
            (None, Some(b)) => Some(format!("({}{}{})", "" , sep, b)),
            (None, None) => None,
        })
        .collect();

    let index_series = Series::new(index_name, idx_vec);

    // Drop original columns and insert the new index at position 0
    df = df.drop([col0, col1])?;
    df.insert_at_idx(0, index_series)?;

    Ok(df)
}

fn main() -> PolarsResult<()> {
    // Example DataFrame: df0 with columns "str0", "str1", and "value"
    let s0 = Series::new("str0", &["a", "a", "b"]);
    let s1 = Series::new("str1", &["x", "y", "x"]);
    let vals = Series::new("value", &[10, 20, 30]);
    let df0 = DataFrame::new(vec![s0, s1, vals])?;

    println!("Original df0:\n{:?}", df0);

    // Create a two-level index from "str0" and "str1"
    let df_with_index = set_two_level_index(df0, "str0", "str1", "multi_index", ", ")?;

    println!("\nDataFrame with two-level index (as composite column):\n{:?}", df_with_index);

    Ok(())
}
```

What this produces (roughly):
- Original df0:
  str0 | str1 | value
  a    | x    | 10
  a    | y    | 20
  b    | x    | 30

- After set_two_level_index(..., index_name="multi_index", sep=", "):
  multi_index   | value
  (a, x)        | 10
  (a, y)        | 20
  (b, x)        | 30

