/// 
/// let df = df!(
///     "group" => &["A", "A", "B", "B"],
///     "subgroup" => &["x", "y", "x", "y"],
///     "value" => &[1, 2, 3, 4]
/// ).unwrap();
/// 
/// let result = set_hierarchical_index(df, "group", "subgroup").unwrap();
/// println!("{:?}", result);
/// ```
pub fn set_hierarchical_index(
    df0: DataFrame,
    str0: &str,
    str1: &str,
) -> Result<DataFrame, Box<dyn Error>> {
    // Validate that both columns exist
    if !df0.get_column_names_str().any(|name| name == str0) {
        return Err(format!("Column '{}' not found in DataFrame", str0).into());
    }
    if !df0.get_column_names_str().any(|name| name == str1) {
        return Err(format!("Column '{}' not found in DataFrame", str1).into());
    }

    // Create a unique identifier for each row based on the two columns
    let hierarchical_index = df0
        .lazy()
        .with_column(
            concat_str(
                [col(str0).cast(DataType::Utf8), col(str1).cast(DataType::Utf8)],
                "",
                true,
            )
            .alias("__hierarchical_index__"),
        )
        .collect()?;

    // Remove the original columns used for indexing
    let mut df = df0.drop([str0, str1])?;

    // Add the hierarchical index as the first column
    let index_col = hierarchical_index.column("__hierarchical_index__")?.clone();
    df.insert_at_idx(0, index_col)?;

    // Rename the index column to indicate it's a hierarchical index
    let index_name = format!("({}, {})", str0, str1);
    unsafe {
        df.get_column_names_mut()[0] = index_name.as_str();
    }

    Ok(df)
}

// Alternative implementation using Polars' built-in multi-index support
pub fn set_hierarchical_index_v2(
    df0: DataFrame,
    str0: &str,
    str1: &str,
) -> Result<DataFrame, Box<dyn Error>> {
    // Validate columns exist
    if !df0.get_column_names_str().any(|name| name == str0) {
