use polars::prelude::*;
use std::error::Error;

fn filter_dataframe(
    df: &DataFrame,
    conditions: Vec<(String, Operator, AnyValue)>,
) -> Result<DataFrame, Box<dyn Error>> {
    let mut mask = Series::new("mask", vec![true; df.height()]); // Start with all true

    for (column_name, operator, value) in conditions {
        let series = df.column(&column_name)?;
        let new_mask = match operator {
            Operator::Eq => series.eq(value),
            Operator::Ne => series.neq(value),
            Operator::Gt => series.gt(value),
            Operator::Lt => series.lt(value),
            Operator::Ge => series.gt_eq(value),
            Operator::Le => series.lt_eq(value),
        }?;

        mask = mask.zip(&new_mask)?;
    }

    let filtered_df = df.filter(&mask)?;
    Ok(filtered_df)
}

