```rust
use polars::prelude::*;

/// Filter rows in a 2D table according to multiple specified conditions.
///
/// # Arguments
///
/// * `df`: The input DataFrame.
/// * `conditions`: A vector of conditions. Each condition is a tuple containing the column name, the operator, and the value.
///
/// # Returns
///
/// A new DataFrame with the filtered rows.
fn filter_rows(df: &DataFrame, conditions: Vec<(&str, &str, &str)>) -> DataFrame {
    let mut filtered_df = df.clone();

    for (column, operator, value) in conditions {
        filtered_df = match operator {
            "eq" => filtered_df.filter(filtered_df.column(column).unwrap().eq(value)),
            "neq" => filtered_df.filter(filtered_df.column(column).unwrap().neq(value)),
            "lt" => filtered_df.filter(filtered_df.column(column).unwrap().lt(value)),
            "gt" => filtered_df.filter(filtered_df.column(column).unwrap().gt(value)),
            "lte" => filtered_df.filter(filtered_df.column(column).unwrap().lte(value)),
            "gte" => filtered_df.filter(filtered_df.column(column).unwrap().gte(value)),
            _ => panic!("Unsupported operator"),
        };
    }

    filtered_df
}

fn main() {
    // Create a sample DataFrame
    let s = Series::new("A", &[1, 2, 3, 4, 5]);
    let s2 = Series::new("B", &[10, 20, 30, 40, 50]);
    let df = DataFrame::new(vec![s, s2]).unwrap();

    // Define the conditions
    let conditions = vec![
        ("A", "gt", "2"),
        ("B", "lt", "40"),
