use polars::prelude::*;
use std::error::Error;

/// Comparison operators supported for filtering.
#[derive(Debug, Clone)]
pub enum Operator {
    Eq,
    Neq,
    Gt,
    Lt,
    Gte,
    Lte,
    Contains, // substring match (for string columns)
}

/// A single filter condition: column name, operator, and a string representation of the value.
/// For numeric comparisons (Gt/Lt/Gte/Lte) the value is parsed as f64; for Eq/N
/// it will try numeric equality if parsing succeeds, otherwise string equality is used.
#[derive(Debug, Clone)]
pub struct Condition {
    pub column: String,
    pub op: Operator,
    pub value: String,
}

/// Filter a 2D table (first row = header) by multiple conditions combined with AND.
///
/// - `table`: Vec<Vec<String>> where table[0] is header (column names), subsequent rows are data rows.
/// - `conditions`: list of conditions combined with logical AND.
///
/// Returns filtered table (header + matching rows) or an error.
///
/// Example usage:
/// let input = vec![
///     vec!["name".into(), "age".into(), "city".into()],
///     vec!["Alice".into(), "30".into(), "London".into()],
///     vec!["Bob".into(), "25".into(), "Paris".into()],
///     vec!["Carol".into(), "35".into(), "London".into()],
/// ];
///
/// let conds = vec![
///     Condition { column: "city".into(), op: Operator::Eq, value: "London".into() },
///     Condition { column: "age".into(), op: Operator::Gt, value: "29".into() },
/// ];
///
/// let filtered = filter_table(input, conds)?;
pub fn filter_table(
    table: Vec<Vec<String>>,
    conditions: Vec<Condition>,
) -> Result<Vec<Vec<String>>, Box<dyn Error>> {
    if table.is_empty() {
        return Ok(Vec::new());
    }

    let header = &table[0];
    let ncols = header.len();
    let rows = &table[1..];

    // Build columns as Vec<&str> for Series construction
    let mut series_vec: Vec<Series> = Vec::with_capacity(ncols);
    for col_idx in 0..ncols {
        let col_name = header[col_idx].clone();
        let mut vals_ref: Vec<&str> = Vec::with_capacity(rows.len());
        for row in rows.iter() {
            // If the row is shorter than header, use empty string
            let s = row.get(col_idx).map(|s| s.as_str()).unwrap_or("");
            vals_ref.push(s);
        }
        series_vec.push(Series::new(&col_name, vals_ref));
    }

    let df = DataFrame::new(series_vec)?;

    // Helper: convert a Condition into a Polars Expr
    fn cond_to_expr(cond: &Condition) -> Result<Expr, Box<dyn Error>> {
        let col_expr = col(&cond.column);

        match cond.op {
            Operator::Contains => {
                // string substring match
                Ok(col_expr.utf8()?.str().contains(lit(&cond.value)))
            }
            Operator::Eq | Operator::Neq => {
                // Try numeric equality if value parses to f64; otherwise string compare
                if let Ok(num) = cond.value.parse::<f64>() {
                    let expr = col_expr.cast(DataType::Float64)?.eq(lit(num));
                    if let Operator::Neq = cond.op {
                        Ok(expr.not())
                    } else {
                        Ok(expr)
                    }
                } else {
                    let expr = col_expr.eq(lit(&cond.value));
                    if let Operator::Neq = cond.op {
                        Ok(expr.not())
                    } else {
                        Ok(expr)
                    }
                }
            }
            Operator::Gt | Operator::Lt | Operator::Gte | Operator::Lte => {
                // Numeric comparisons require the value to parse as f64.
                let num = cond
                    .value
                    .parse::<f64>()
                    .map_err(|e| format!("Failed to parse '{}' as number for numeric comparison: {}", cond.value, e))?;
                let casted = col_expr.cast(DataType::Float64)?;
                let expr = match cond.op {
                    Operator::Gt => casted.gt(lit(num)),
                    Operator::Lt => casted.lt(lit(num)),
                    Operator::Gte => casted.gt_eq(lit(num)),
                    Operator::Lte => casted.lt_eq(lit(num)),
                    _ => unreachable!(),
                };
                Ok(expr)
            }
        }
    }

    // Build combined filter expression (AND of all conditions). If no conditions, pass everything.
    let filter_expr = if conditions.is_empty() {
        // trivial true expression: lit(true)
        lit(true)
    } else {
        let mut iter = conditions.iter();
        let first = cond_to_expr(iter.next().unwrap())?;
        let combined = iter.try_fold(first, |acc, c| {
            let e = cond_to_expr(c)?;
            Ok(acc.and(e))
        })?;
        combined
    };

    // Execute lazy filter
    let lf = df.lazy().filter(filter_expr);
    let result_df = lf.collect()?;

    // Convert DataFrame back to Vec<Vec<String>> (header + rows)
    let mut out: Vec<Vec<String>> = Vec::with_capacity(result_df.height() + 1);
    // header
    out.push(
        result_df
            .get_columns()
            .iter()
            .map(|s| s.name().to_string())
            .collect(),
    );

    let height = result_df.height();
    let cols = result_df.get_columns();
    for row_idx in 0..height {
        let mut row_vec = Vec::with_capacity(cols.len());
        for s in cols.iter() {
            // get AnyValue and convert to string (Null-> "null" by default; convert that to empty string)
            let any = s.get(row_idx);
            let mut s = any.to_string();
            if s == "null" {
                s.clear();
            }
            row_vec.push(s);
        }
        out.push(row_vec);
    }

    Ok(out)
}

// Simple test / example demonstrating usage
#[cfg(test)]
