    use super::*;

    #[test]
    fn example_filter() {
        let input = vec![
            vec!["name".into(), "age".into(), "city".into()],
            vec!["Alice".into(), "30".into(), "London".into()],
            vec!["Bob".into(), "25".into(), "Paris".into()],
            vec!["Carol".into(), "35".into(), "London".into()],
            vec!["Dan".into(), "".into(), "London".into()], // missing age
        ];

        let conds = vec![
            Condition {
                column: "city".into(),
                op: Operator::Eq,
                value: "London".into(),
            },
