use polars::prelude::*;
use std::collections::HashMap;

/// Filter a two-dimensional table based on multiple conditions
///
/// # Arguments
/// * `data` - A vector of vectors representing the table rows
/// * `headers` - Column headers for the table
/// * `conditions` - A HashMap where keys are column names and values are filter criteria
///   - For numeric columns: ("eq", value), ("gt", value), ("lt", value), ("gte", value), ("lte", value)
///   - For string columns: ("eq", value), ("contains", value), ("starts_with", value)
///
/// # Returns
/// A Result containing the filtered table as Vec<Vec<String>>, or an error message
pub fn filter_table(
    data: &[Vec<String>],
    headers: &[String],
    conditions: &HashMap<String, (String, String)>,
) -> Result<Vec<Vec<String>>, String> {
    // Validate input
    if data.is_empty() || headers.is_empty() {
        return Err("Empty data or headers".to_string());
    }

    // Convert data to Polars DataFrame
    let mut series_vec: Vec<Series> = Vec::new();

    for (col_idx, header) in headers.iter().enumerate() {
        let col_data: Vec<&str> = data.iter().map(|row| row[col_idx].as_str()).collect();

        // Try to parse as numeric first, fall back to string
        if let Ok(nums) = col_data.iter().map(|s| s.parse::<f64>()).collect::<Result<Vec<f64>, _>>() {
            series_vec.push(Series::new(header, &nums));
        } else {
            series_vec.push(Series::new(header, col_data));
        }
    }

    let df = DataFrame::new(series_vec).map_err(|e| format!("Failed to create DataFrame: {}", e))?;

    // Build filter expression
    let mut filter_expr: Option<Expr> = None;

    for (col_name, (operator, value)) in conditions {
        let col_expr = col(col_name);
        let condition = match operator.as_str() {
            "eq" => {
                // Try numeric comparison first
                if let Ok(num_val) = value.parse::<f64>() {
                    col_expr.eq(lit(num_val))
                } else {
                    col_expr.eq(lit(value.as_str()))
                }
            }
            "gt" => col_expr.gt(lit(value.parse::<f64>().map_err(|_| 
                format!("Invalid numeric value for gt operator: {}", value))?)),
            "lt" => col_expr.lt(lit(value.parse::<f64>().map_err(|_| 
                format!("Invalid numeric value for lt operator: {}", value))?)),
            "gte" => col_expr.gt_eq(lit(value.parse::<f64>().map_err(|_| 
                format!("Invalid numeric value for gte operator: {}", value))?)),
            "lte" => col_expr.lt_eq(lit(value.parse::<f64>().map_err(|_| 
                format!("Invalid numeric value for lte operator: {}", value))?)),
            "contains" => col_expr.str().contains(lit(value.as_str()), false),
            "starts_with" => col_expr.str().starts_with(lit(value.as_str())),
            _ => return Err(format!("Unknown operator: {}", operator)),
        };

        filter_expr = match filter_expr {
            None => Some(condition),
            Some(prev) => Some(prev.and(condition)),
        };
    }

    // Apply filter
    let filtered_df = match filter_expr {
        Some(expr) => df.filter(&expr).map_err(|e| format!("Filter failed: {}", e))?,
        None => df,
    };

    // Convert back to Vec<Vec<String>>
    let result: Vec<Vec<String>> = filtered_df
        .iter()
        .map(|row| {
            row.iter()
                .map(|any_val| any_val.to_string())
                .collect()
        })
        .collect();

    Ok(result)
}

// Example usage
