use polars::prelude::*;

/// Filters a 2D table based on multiple conditions
/// 
/// # Arguments
/// * `data` - A HashMap where keys are column names and values are vectors of data
/// * `conditions` - A vector of tuples (column_name, operator, value) for filtering
/// 
/// # Returns
/// A DataFrame containing only rows matching all conditions
/// 
/// # Example
/// ```ignore
/// let mut data = std::collections::HashMap::new();
/// data.insert("age".to_string(), vec![25, 30, 35, 28]);
/// data.insert("name".to_string(), vec!["Alice", "Bob", "Charlie", "Diana"]);
/// 
/// let conditions = vec![
///     ("age", ">", "25"),
///     ("age", "<", "35"),
/// ];
/// 
/// let result = filter_table_data(&data, &conditions).unwrap();
/// ```
fn filter_table_data(
    data: &std::collections::HashMap<String, Vec<String>>,
    conditions: &[(&str, &str, &str)],
) -> Result<DataFrame, PolarsError> {
    // Convert HashMap to DataFrame
    let mut df_dict = std::collections::HashMap::new();

    for (col_name, values) in data.iter() {
        // Try to parse as integers first, fall back to strings
        let series: Series = if let Ok(int_vals) = values
            .iter()
            .map(|v| v.parse::<i64>())
            .collect::<Result<Vec<_>, _>>()
        {
            Series::new(col_name, int_vals)
        } else {
            Series::new(col_name, values.clone())
        };
        df_dict.insert(col_name.clone(), series);
    }

    let mut df = DataFrame::new(df_dict.into_values().collect::<Vec<_>>())?;

    // Apply each condition
    for (col_name, operator, value) in conditions {
        let col = df.column(col_name)?;

        let mask = match *operator {
            ">" => {
                if let Ok(val) = value.parse::<i64>() {
                    col.i64()?.gt(val)
                } else {
                    col.str()?.gt(value)
                }
            }
            "<" => {
                if let Ok(val) = value.parse::<i64>() {
                    col.i64()?.lt(val)
                } else {
                    col.str()?.lt(value)
                }
            }
            ">=" => {
                if let Ok(val) = value.parse::<i64>() {
                    col.i64()?.gt_eq(val)
                } else {
                    col.str()?.gt_eq(value)
                }
            }
            "<=" => {
                if let Ok(val) = value.parse::<i64>() {
                    col.i64()?.lt_eq(val)
                } else {
                    col.str()?.lt_eq(value)
                }
            }
            "==" => {
                if let Ok(val) = value.parse::<i64>() {
                    col.i64()?.equal(val)
                } else {
                    col.str()?.equal(value)
                }
            }
            "!=" => {
                if let Ok(val) = value.parse::<i64>() {
                    col.i64()?.not_equal(val)
                } else {
                    col.str()?.not_equal(value)
                }
            }
            _ => return Err(PolarsError::ComputeError("Unknown operator".into())),
        };

        df = df.filter(&mask)?;
    }

    Ok(df)
}

fn main() -> Result<(), PolarsError> {
    // Example usage
    let mut data = std::collections::HashMap::new();
    data.insert("age".to_string(), vec![
        "25".to_string(),
        "30".to_string(),
        "35".to_string(),
        "28".to_string(),
    ]);
    data.insert("name".to_string(), vec![
        "Alice".to_string(),
        "Bob".to_string(),
        "Charlie".to_string(),
        "Diana".to_string(),
    ]);
    data.insert("city".to_string(), vec![
        "NYC".to_string(),
        "LA".to_string(),
        "NYC".to_string(),
        "Chicago".to_string(),
    ]);

    // Filter: age > 25 AND age < 35 AND city == "NYC"
    let conditions = vec![
        ("age", ">", "25"),
        ("age", "<", "35"),
        ("city", "==", "NYC"),
    ];

    let result = filter_table_data(&data, &conditions)?;
    println!("{}", result);

    Ok(())
}
