use indexmap::IndexMap;

/// Reorders entries of a key-to-sequence mapping so they are sorted in descending order
/// based on the highest number in each associated sequence.
///
/// # Arguments
/// * `map` - An IndexMap where keys are strings and values are vectors of integers
///
/// # Returns
/// A new IndexMap with entries sorted by the maximum value in each sequence (descending)
///
/// # Example
/// ```
/// use indexmap::IndexMap;
///
/// let mut map = IndexMap::new();
/// map.insert("a".to_string(), vec![1, 5, 3]);
/// map.insert("b".to_string(), vec![10, 2]);
/// map.insert("c".to_string(), vec![7, 8, 9]);
///
/// let sorted = sort_by_highest_number(map);
/// // Order should be: "c" (max=9), "b" (max=10), "a" (max=5)
/// // Wait - let's check: "b" has max=10, "c" has max=9, "a" has max=5
/// // So descending order: "b" (10), "c" (9), "a" (5)
/// let keys: Vec<&str> = sorted.keys().map(|k| k.as_str()).collect();
/// assert_eq!(keys, vec!["b", "c", "a"]);
/// ```
pub fn sort_by_highest_number(map: IndexMap<String, Vec<i32>>) -> IndexMap<String, Vec<i32>> {
    // Handle empty map case
    if map.is_empty() {
        return map;
    }

    // Create a vector of (key, max_value) tuples for sorting
    let mut key_max_pairs: Vec<(&String, i32)> = map
        .iter()
        .map(|(key, sequence)| {
            // Find the maximum value in the sequence, defaulting to i32::MIN for empty sequences
            let max_value = sequence.iter().copied().max().unwrap_or(i32::MIN);
            (key, max_value)
        })
        .collect();

    // Sort in descending order by max value
    key_max_pairs.sort_by(|a, b| b.1.cmp(&a.1));

    // Build the new sorted IndexMap
    let mut sorted_map = IndexMap::new();
    for (key, _) in key_max_pairs {
        // Clone the key and value since we need owned data
        if let Some(value) = map.get(key) {
            sorted_map.insert(key.clone(), value.clone());
        }
    }

    sorted_map
}

