# Rust Function: Sort Key-to-Sequence Mapping by Highest Value

```rust
use indexmap::IndexMap;

/// Reorders a key-to-sequence mapping so entries are sorted in descending order
/// based on the highest number in each associated sequence.
///
/// # Arguments
/// * `map` - An IndexMap where keys map to vectors of numbers
///
/// # Returns
/// A new IndexMap with entries sorted by the maximum value in each sequence (descending)
fn sort_by_max_descending(
    map: IndexMap<String, Vec<i32>>,
) -> IndexMap<String, Vec<i32>> {
    let mut entries: Vec<_> = map.into_iter().collect();

    // Sort by the maximum value in each sequence in descending order
    entries.sort_by(|a, b| {
        let max_a = a.1.iter().max().copied().unwrap_or(i32::MIN);
        let max_b = b.1.iter().max().copied().unwrap_or(i32::MIN);
        max_b.cmp(&max_a) // Descending order
    });

    entries.into_iter().collect()
}

fn main() {
    let mut map = IndexMap::new();
    map.insert("fruits".to_string(), vec![3, 1, 5, 2]);
    map.insert("colors".to_string(), vec![10, 8, 9]);
    map.insert("animals".to_string(), vec![7, 4, 6]);
    map.insert("numbers".to_string(), vec![2, 15, 3]);

    println!("Original map:");
    for (key, values) in &map {
        println!("  {}: {:?} (max: {})", key, values, values.iter().max().unwrap());
    }

    let sorted = sort_by_max_descending(map);

    println!("\nSorted by max value (descending):");
    for (key, values) in &sorted {
        println!("  {}: {:?} (max: {})", key, values, values.iter().max().unwrap());
    }
}
```

## Dependencies

Add this to your `Cargo.toml`:

```toml
[dependencies]
indexmap = "2.0"
```

