use polars::prelude::*;

/// Filter rows from table A based on matching rows in table B.
///
/// # Arguments
///
/// * `table_a` - The DataFrame to filter.
/// * `table_b` - The DataFrame containing the rows to match.
/// * `column_name` - The name of the column to match between the two DataFrames.
///
/// # Returns
///
