use polars::prelude::*;

/// Return rows from `df_a` that have matching rows in `df_b` on the given key columns.
/// Uses a Semi join so only columns from df_a are returned.
///
/// `keys` may contain one or more column names for composite keys.
/// Returns a PolarsResult<DataFrame>.
fn filter_rows_with_matches(
    df_a: &DataFrame,
    df_b: &DataFrame,
    keys: &[&str],
) -> PolarsResult<DataFrame> {
    if keys.is_empty() {
        return Err(PolarsError::ComputeError(
            "keys must contain at least one column".into(),
        ));
    }
    // Semi join: returns rows from left (df_a) that have at least one match in right (df_b)
    df_a.join(df_b, keys, keys, JoinType::Semi, None)
}

fn main() -> PolarsResult<()> {
    // Example data for A
    let df_a = df![
        "id" => &[1i32, 2, 3, 4],
        "name" => &["alice", "bob", "carol", "dave"]
    ]?;

    // Example data for B (only ids 2 and 4 exist here)
    let df_b = df![
        "id" => &[2i32, 4],
        "value" => &[100i32, 200]
    ]?;

    // Filter df_a to rows that have matching "id" in df_b
    let filtered = filter_rows_with_matches(&df_a, &df_b, &["id"])?;

    println!("Filtered rows from A that match B:\n{}", filtered);
    Ok(())
}
