        }
        if !table_b.get_column_names().contains(col) {
            return Err(format!("Column '{}' not found in table B", col).into());
        }
    }

    // Create a unique identifier for each row in table_a
    let mut a_with_id = table_a.clone();
    let row_count = a_with_id.height();
    let row_ids: Vec<u32> = (0..row_count as u32).collect();
    a_with_id.with_column(Series::new("__row_id__", &row_ids))?;

    // Perform inner join to find matching rows
    let mut join_cols_with_id = join_columns.to_vec();
    join_cols_with_id.push("__row_id__");

    let matched = a_with_id.join(
        &table_b,
        join_columns,
        join_columns,
        JoinType::Inner,
        None,
    )?;

    // Get unique row IDs that had matches
    let matched_ids: Vec<u32> = matched
        .column("__row_id__")?
        .u32()?
        .into_iter()
        .flatten()
        .collect();

    // Filter original table_a using the matched IDs
    let mask = Series::new("__mask__", row_ids.iter().map(|id| matched_ids.contains(id)));
    let result = table_a.filter(&mask)?;

    Ok(result)
