///     println!("{:?}", result);
///     Ok(())
/// }
/// ```
pub fn calculate_column_means(df: &DataFrame) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Group columns by their name
    let mut column_groups: HashMap<String, Vec<&Column>> = HashMap::new();

    for col in df.get_columns() {
        let col_name = col.name().to_string();
        column_groups.entry(col_name).or_default().push(col);
    }

    // Create a new DataFrame to store the results
    let mut result_df = DataFrame::default();

    // Process each column group
    for (col_name, columns) in column_groups {
        // Check if all columns in the group are numeric
        let mut all_numeric = true;
        for col in columns {
            if !col.dtype().is_numeric() {
                all_numeric = false;
                break;
            }
        }

        if !all_numeric {
            return Err(format!("Non-numeric column found in group '{}'", col_name).into());
        }

        // Concatenate all columns in the group horizontally
        let concatenated = df.lazy().select(columns.iter().map(|c| c.name().to_string()))?
            .collect()?;

        // Calculate mean for each column in the group
        let mut means = Vec::new();
        for col in columns {
            let mean = concatenated.column(col.name())?
                .mean()?
                .unwrap_or(0.0); // Handle null case if needed
            means.push(mean);
        }

        // Create a new column with the mean value (repeated for each row)
        let mean_col = Series::new(&format!("{}_{}", col_name, "mean"), &means)
            .into_object()
            .unwrap();

        // Append to the result DataFrame
        result_df = df.clone().hstack(&[mean_col.into_column()])?;
    }

    Ok(result_df)
}

