use polars::prelude::*;
use std::collections::HashMap;

/// Compute the mean for each set of columns that share the same name in `df`.
/// Returns a HashMap mapping column name -> mean (f64).
/// Non-numeric columns are ignored. Nulls are skipped when computing means.
pub fn mean_by_column_name(df: &DataFrame) -> PolarsResult<HashMap<String, f64>> {
    let mut sums: HashMap<String, f64> = HashMap::new();
    let mut counts: HashMap<String, u64> = HashMap::new();

    for s in df.get_columns() {
        let name = s.name().to_string();

        // Cast column to Float64 if possible (this will convert integer/float types).
        // If cast fails or column type is not numeric, skip this series.
        let s_f64 = match s.cast(&DataType::Float64) {
            Ok(ser) => ser,
            Err(_) => continue,
        };

        // Access float chunked; if not available skip.
        let ca = match s_f64.f64() {
            Some(c) => c,
            None => continue,
        };

        // Sum returns Option<f64>, None means all nulls.
        let sum_val = ca.sum().unwrap_or(0.0);
        let non_null_count = (ca.len() - ca.null_count()) as u64;

        if non_null_count == 0 {
            // no non-null values in this series; treat as zero contribution
            continue;
        }

        *sums.entry(name.clone()).or_insert(0.0) += sum_val;
        *counts.entry(name).or_insert(0) += non_null_count;
    }

    // Compute means
    let mut means: HashMap<String, f64> = HashMap::with_capacity(sums.len());
    for (k, sum) in sums {
        if let Some(&cnt) = counts.get(&k) {
            if cnt > 0 {
                means.insert(k, sum / (cnt as f64));
            }
        }
    }

    Ok(means)
}

