/// let result = mean_by_column_name(df).unwrap();
/// println!("{:?}", result);
/// ```
pub fn mean_by_column_name(df: DataFrame) -> Result<DataFrame, PolarsError> {
    // Get column names and their indices
    let column_names: Vec<&str> = df.get_column_names();

    // Group column indices by name
    let mut name_to_indices: HashMap<&str, Vec<usize>> = HashMap::new();
    for (idx, name) in column_names.iter().enumerate() {
        name_to_indices.entry(name).or_default().push(idx);
    }

    // Calculate mean for each group of columns
    let mut result_columns: Vec<Series> = Vec::new();

    for (name, indices) in &name_to_indices {
        if indices.len() == 1 {
            // Single column - just take the mean directly
            let series = df.column(name)?;
            let mean = series.mean();
            let mean_series = Series::new(name, &[mean]);
            result_columns.push(mean_series);
        } else {
            // Multiple columns with same name - calculate mean across them
            let mut sum_series: Option<Series> = None;

            for &idx in indices {
                let series = &df[idx];
                let series_f64 = series.cast(&DataType::Float64)?;

                match &sum_series {
                    None => sum_series = Some(series_f64),
                    Some(current_sum) => {
                        sum_series = Some(current_sum + series_f64);
                    }
                }
            }

            // Divide by number of columns to get mean
            if let Some(sum) = sum_series {
                let count = indices.len() as f64;
                let mean_series = sum / count;
                let mean_series = mean_series.with_name(name);
                result_columns.push(mean_series);
            }
        }
    }

    // Combine all result columns into a DataFrame
    let result_df = DataFrame::new(result_columns)?;
    Ok(result_df)
}

