        ("aabc", Some(2)),     // "aab" found, 'b' at index 2
        ("aaabc", Some(3)),    // "aaab" found, 'b' at index 3
        ("bc", None),          // No 'a' before 'b'
        ("cab", Some(2)),      // "ab" found, 'b' at index 2
        ("xyz", None),         // No 'b' at all
        ("aabbaaab", Some(2)), // First match is "aab", 'b' at index 2
        ("", None),            // Empty string
    ];

    for (input, expected) in test_cases {
