///     "b" => &[4, 5, 6]
/// ).unwrap();
///
/// let result = reset_and_convert_index(df);
/// ```
pub fn reset_and_convert_index(df: DataFrame) -> Result<DataFrame, PolarsError> {
    // Get the current index
    let index = df.index();

    // Convert index to a DataFrame with one column
    let index_df = DataFrame::new(vec![
        Series::new("original_index", index.to_vec())?
    ])?;

    // Reset the index of the original DataFrame
    let reset_df = df.lazy().reset_index(None)?;

    // Join the reset DataFrame with the index values
    let result = reset_df
        .join(index_df.lazy(), ["original_index"], JoinType::Inner)?
        .collect()?;

    Ok(result)
}

