///     "value" => &[10, 20, 30]
/// ].unwrap();
/// 
/// let result = reset_index(df.clone(), "id", Some("new_idx"), Some("original_id")).unwrap();
/// println!("{:?}", result);
/// ```
pub fn reset_index(
    df: DataFrame,
    index_col: &str,
    new_index_col: Option<&str>,
    old_index_col: Option<&str>,
) -> Result<DataFrame, Box<dyn Error>> {
    // Set default column names
    let new_idx_name = new_index_col.unwrap_or("index");
    let old_idx_name = old_index_col.unwrap_or("old_index");

    // Validate that the index column exists
    if !df.get_column_names().contains(&index_col) {
        return Err(format!("Column '{}' not found in DataFrame", index_col).into());
    }

    // Extract the index values and rename the column
    let mut df = df.clone();
    let index_series = df.column(index_col)?.clone();

    // Rename the original index column to preserve it
    df.rename(index_col, old_idx_name)?;

    // Create a new sequential index (0, 1, 2, ...)
    let n_rows = df.height();
    let new_index = (0u32..n_rows as u32).collect::<Vec<_>>();
    let new_index_series = Series::new(new_idx_name, new_index);

