use polars::prelude::*;
use serde::Serialize;
use std::collections::HashMap;

#[derive(Serialize)]
struct RowDict {
    index: usize,
    data: HashMap<String, String>,
}

fn dataframe_to_row_dicts(df: &DataFrame) -> Result<Vec<RowDict>, PolarsError> {
    let mut row_dicts = Vec::new();

    // Iterate over the rows of the DataFrame
    for (index, row) in df.iter_rows().enumerate() {
        let mut data_map = HashMap::new();

        // Iterate over the columns and their corresponding values in the current row
        for (column_name, value) in df.get_column_names().iter().zip(row.iter()) {
            // Convert the value to a string representation
            let value_str = match value {
                AnyValue::Null => "null".to_string(),
                AnyValue::Boolean(b) => b.to_string(),
