use polars::prelude::*;
use serde_json::{Map, Number, Value};

/// Convert a polars::AnyValue into a serde_json::Value (best-effort).
fn any_value_to_json(av: &AnyValue) -> Value {
    match av {
        AnyValue::Null => Value::Null,
        AnyValue::Boolean(b) => Value::Bool(*b),
        AnyValue::UInt8(u) => Value::Number(Number::from(*u)),
        AnyValue::UInt16(u) => Value::Number(Number::from(*u)),
        AnyValue::UInt32(u) => Value::Number(Number::from(*u)),
        AnyValue::UInt64(u) => Value::Number(Number::from(*u)),
        AnyValue::Int8(i) => Value::Number(Number::from(*i)),
        AnyValue::Int16(i) => Value::Number(Number::from(*i)),
        AnyValue::Int32(i) => Value::Number(Number::from(*i)),
        AnyValue::Int64(i) => Value::Number(Number::from(*i)),
        AnyValue::Float32(f) => Number::from_f64(*f as f64)
            .map(Value::Number)
            .unwrap_or(Value::Null),
        AnyValue::Float64(f) => Number::from_f64(*f)
            .map(Value::Number)
            .unwrap_or(Value::Null),
        AnyValue::Utf8(s) => Value::String(s.to_string()),
        AnyValue::Date(d) => Value::String(format!("{}", d)),         // best-effort representation
        AnyValue::Datetime(ts, _) => Value::String(format!("{}", ts)),
        AnyValue::Time(t) => Value::String(format!("{}", t)),
        AnyValue::Duration(dur, _) => Value::String(format!("{}", dur)),
        AnyValue::List(series) => {
            // Convert each element of the inner series recursively
            let mut arr = Vec::with_capacity(series.len());
            for i in 0..series.len() {
                let inner_av = series.get(i);
                arr.push(any_value_to_json(&inner_av));
            }
            Value::Array(arr)
        }
        // Fallback for other variants
        other => Value::String(other.to_string()),
    }
}

/// Convert a polars DataFrame into a Vec of JSON objects, each containing the row's values
/// and an "index" field for the row index.
pub fn df_to_row_dicts(df: &DataFrame) -> Vec<Value> {
    let mut rows = Vec::with_capacity(df.height());
    let cols = df.get_columns();

    for i in 0..df.height() {
        let mut map = Map::with_capacity(df.width() + 1);
        // include index
        map.insert("index".to_string(), Value::Number(Number::from(i as i64)));

        for series in cols.iter() {
            let name = series.name();
            // series.get returns an AnyValue (panics if out of bounds; i is in-bounds here)
            let av = series.get(i);
            let json_val = any_value_to_json(&av);
            map.insert(name.to_string(), json_val);
        }

        rows.push(Value::Object(map));
    }

    rows
}

fn main() -> Result<()> {
    // Example usage: build a small DataFrame
    let df = df![
        "name" => &["Alice", "Bob", "Carol"],
        "age" => &[30, 40, 25],
        "score" => &[Some(95.5f64), Some(82.0), None::<f64>]
    ]?;

    let row_dicts = df_to_row_dicts(&df);

    // Print each row-as-dictionary as pretty JSON
    for v in row_dicts {
        println!("{}", serde_json::to_string_pretty(&v).unwrap());
    }

    Ok(())
}
```

