/// * `df0` - A DataFrame with a hierarchical row index (MultiIndex) and a column named 'A'
/// 
/// # Returns
/// * A vector of tuples where each tuple contains:
///   - The hierarchical row index as a HashMap<String, AnyValue>
///   - The corresponding value from column 'A'
pub fn traverse_hierarchical_index(df0: &DataFrame) -> Vec<(HashMap<String, AnyValue>, AnyValue)> {
    // Get the column names that form the hierarchical index
    // In Polars, hierarchical indices are typically represented as multiple columns
    let index_columns: Vec<&str> = df0
        .get_column_names()
        .iter()
        .filter(|&&name| name != "A")
        .map(|&name| name)
        .collect();

    // Get the 'A' column
    let column_a = df0.column("A").expect("Column 'A' not found");

    // Create result vector
    let mut result: Vec<(HashMap<String, AnyValue>, AnyValue)> = Vec::new();

    // Iterate through each row
    for row_idx in 0..df0.height() {
        // Build the hierarchical index for this row
        let mut index_map: HashMap<String, AnyValue> = HashMap::new();

        for &col_name in &index_columns {
            let column = df0.column(col_name).expect("Column not found");
            let value = column.get(row_idx).expect("Failed to get value");
            index_map.insert(col_name.to_string(), value);
        }

        // Get the value from column 'A'
        let value_a = column_a.get(row_idx).expect("Failed to get value from column A");

        // Add to result
        result.push((index_map, value_a));
    }

    result
}

// Example usage
