    // Create a sample DataFrame with hierarchical index
    let df = df!(
        "level1" => &["A", "A", "B", "B", "C"],
        "level2" => &["X", "Y", "X", "Y", "X"],
        "A" => &[1, 2, 3, 4, 5]
    )?;

    println!("Original DataFrame:");
    println!("{:?}", df);

    // Traverse the hierarchical index
    let result = traverse_hierarchical_index(&df);

    println!("\nResult (index, value from column A):");
    for (index, value) in &result {
        println!("Index: {:?}, Value: {}", index, value);
    }

    Ok(())
}
