Rust code (complete example):
```rust
use polars::prelude::*;

/// Transpose a DataFrame `df0` by swapping rows and columns.
/// All values are converted to strings in the result so mixed-type columns are supported.
///
/// - Each original row becomes a column named "row_<index>" in the returned DataFrame.
/// - The number of rows in the returned DataFrame equals the original number of columns.
///
/// Returns a Polars Result containing the transposed DataFrame.
pub fn transpose_df0(df0: &DataFrame) -> PolarsResult<DataFrame> {
    let height = df0.height();
    let width = df0.width();

    // If df0 is empty (no rows or no columns) return an empty DataFrame
    if height == 0 || width == 0 {
        return DataFrame::new(vec![]);
    }

    // Build a row-major string matrix: rows[row_idx][col_idx] = stringified value
    let mut rows: Vec<Vec<String>> = vec![Vec::with_capacity(width); height];
    for (col_idx, s) in df0.get_columns().iter().enumerate() {
        for row_idx in 0..height {
            // series.get(row_idx) returns AnyValue; format! converts to string
            let v = s.get(row_idx);
            rows[row_idx].push(format!("{}", v));
        }
    }

    // Create a Series for each original row; each series will be length == width (original column count)
    let mut new_cols: Vec<Series> = Vec::with_capacity(height);
    for row_idx in 0..height {
        let col_name = format!("row_{}", row_idx);
        // rows[row_idx] is Vec<String> with length == width
        new_cols.push(Series::new(&col_name, rows[row_idx].clone()));
    }

    DataFrame::new(new_cols)
}

fn main() -> PolarsResult<()> {
    // Example: original df0
    let s0 = Series::new("A", &[1i32, 2, 3]);
    let s1 = Series::new("B", &["x", "y", "z"]);
    let s2 = Series::new("C", &[10.5f64, 20.5, 30.5]);
    let df0 = DataFrame::new(vec![s0, s1, s2])?;

    println!("Original df0:\n{:?}", df0);

    let transposed = transpose_df0(&df0)?;
    println!("Transposed df0:\n{:?}", transposed);

    Ok(())
}
```

Notes:
- This implementation stringifies values to handle heterogeneous column types; if your data is homogenous (all numeric) and you want to preserve numeric types, you can write a version that detects a common numeric type and converts accordingly.
- Polars provides other utilities; check your polars version's docs for native transpose helpers if you prefer type-preserving operations.

