/// // combined["a"] == 4, combined["b"] == 2, combined["c"] == 4
pub fn combine_maps<K, V, M>(maps: M) -> IndexMap<K, V>
where
    M: IntoIterator,
    M::Item: IntoIterator<Item = (K, V)>,
    K: Eq + Hash,
    V: AddAssign + Default,
{
    let mut out: IndexMap<K, V> = IndexMap::new();
    for map in maps {
        for (k, v) in map {
            // If key missing, insert default (e.g. 0 for numeric types), then add v
            let entry = out.entry(k).or_insert_with(V::default);
            *entry += v;
        }
    }
    out
}

