/// Generate a vector of i64 values starting at `start`, moving by `step` (which may be
/// positive or negative), and including values up to `limit` (inclusive).
///
/// Panics if step == 0 or on integer overflow.
fn generate_range_inclusive(start: i64, limit: i64, step: i64) -> Vec<i64> {
    if step == 0 {
        panic!("step must be non-zero");
    }

    let mut v = Vec::new();

    if step > 0 {
        let mut cur = start;
        while cur <= limit {
            v.push(cur);
            cur = cur.checked_add(step).expect("overflow while incrementing");
        }
    } else {
        let mut cur = start;
        while cur >= limit {
            v.push(cur);
            cur = cur.checked_add(step).expect("overflow while decrementing");
        }
    }

    v
}

/// Build a HashMap mapping each key to the same generated sequence of values.
/// - `keys`: any iterable of keys (cloned into the map)
/// - `start`, `limit`, `step`: define the numeric iteration (inclusive limit).
///
/// Returns a HashMap<K, Vec<i64>> where each key maps to its own Vec clone of the generated values.
pub fn map_keys_to_iterated_values<K, I>(keys: I, start: i64, limit: i64, step: i64) -> HashMap<K, Vec<i64>>
