```rust
use itertools::Itertools;
use std::collections::HashMap;

/// Generates a mapping from keys to lists of values produced by iterating
/// a numeric variable from start to limit.
///
/// # Arguments
/// * `keys` - A list of keys to map to
/// * `start` - The starting value for numeric iteration
/// * `limit` - The upper bound (exclusive) for numeric iteration
///
/// # Returns
/// A HashMap where each key maps to a Vec of integers from start to limit-1
///
/// # Example
/// ```
/// let keys = vec!["a", "b", "c"];
/// let result = generate_key_value_mapping(keys, 1, 4);
/// assert_eq!(result["a"], vec![1, 2, 3]);
/// assert_eq!(result["b"], vec![1, 2, 3]);
/// assert_eq!(result["c"], vec![1, 2, 3]);
/// ```
fn generate_key_value_mapping<T: Clone + std::hash::Hash + Eq>(
    keys: Vec<T>,
    start: i32,
    limit: i32,
) -> HashMap<T, Vec<i32>> {
    let values: Vec<i32> = (start..limit).collect();

    keys.into_iter()
        .map(|key| (key, values.clone()))
        .collect()
}

// Alternative version using itertools for more flexible iteration patterns
fn generate_key_value_mapping_itertools<T: Clone + std::hash::Hash + Eq>(
    keys: Vec<T>,
    start: i32,
    limit: i32,
) -> HashMap<T, Vec<i32>> {
    let values: Vec<i32> = (start..limit).collect();

    keys.into_iter()
        .zip(std::iter::repeat(values))
        .collect()
}

// Advanced version: each key gets unique multiplied values
fn generate_key_value_mapping_unique<T: Clone + std::hash::Hash + Eq>(
    keys: Vec<T>,
    start: i32,
    limit: i32,
) -> HashMap<T, Vec<i32>> {
    keys.into_iter()
        .enumerate()
        .map(|(idx, key)| {
            let multiplier = (idx as i32) + 1;
            let values: Vec<i32> = (start..limit)
                .map(|v| v * multiplier)
                .collect();
            (key, values)
        })
        .collect()
}

fn main() {
