use ndarray::{Array2, Array, Axis, Zip};

/// Fills missing entries in a 2D dataset with the average of the non-missing values in its column.
/// 
/// # Arguments
/// 
/// * `data` - A 2D `Array2<f64>` where missing values are represented by `std::f64::NAN`.
///
/// # Returns
///
/// A new 2D `Array2<f64>` with missing values filled.
pub fn fill_missing_with_column_mean(data: Array2<f64>) -> Array2<f64> {
    let mut filled_data = data.clone();
    let (rows, cols) = filled_data.dim();

    for col in 0..cols {
        let column_view = filled_data.slice(s![.., col]);
        let valid_values: Vec<f64> = column_view.iter()
            .filter(|&&x| !x.is_nan())
            .cloned()
            .collect();

        if !valid_values.is_empty() {
            let column_mean = valid_values.iter().sum::<f64>() / valid_values.len() as f64;
            filled_data
                .columns_mut()
                .nth(col)
                .unwrap()
                .iter_mut()
                .for_each(|x| {
                    if x.is_nan() {
                        *x = column_mean;
                    }
                });
        }
    }
    filled_data
}

