use polars::prelude::*;
use polars::frame::DataFrame;

/// Replaces missing values in each column with the mean of non-missing values in that column.
///
/// # Arguments
/// * `df` - A DataFrame containing numeric columns that may have missing values (nulls)
///
/// # Returns
/// * `Result<DataFrame>` - A new DataFrame with missing values replaced by column means,
///   or an error if the operation fails
///
/// # Example
/// ```rust
/// use polars::prelude::*;
///
/// let df = df!(
///     "A" => &[Some(1.0), None, Some(3.0)],
///     "B" => &[None, Some(5.0), Some(7.0)],
/// ).unwrap();
///
/// let result = fill_missing_with_column_means(df).unwrap();
/// println!("{:?}", result);
/// // Output:
/// // shape: (3, 2)
/// // ┌─────┬─────┐
/// // │ A   ┆ B   │
/// // │ --- ┆ --- │
/// // │ f64 ┆ f64 │
/// // ╞═════╪═════╡
/// // │ 1.0 ┆ 6.0 │
/// // │ 2.0 ┆ 5.0 │
/// // │ 3.0 ┆ 7.0 │
/// // └─────┴─────┘
/// ```
pub fn fill_missing_with_column_means(df: DataFrame) -> Result<DataFrame, PolarsError> {
    // Get all numeric columns
    let numeric_cols: Vec<&str> = df
        .get_column_names()
        .iter()
        .filter(|&&name| {
            df.column(name)
                .map(|col| col.dtype().is_numeric())
                .unwrap_or(false)
        })
        .copied()
        .collect();

    // Calculate means for each numeric column, ignoring nulls
    let means: Vec<f64> = numeric_cols
        .iter()
        .map(|&name| {
            df.column(name)
                .unwrap()
                .mean()
                .unwrap_or(f64::NAN) // If column is all null, keep as NaN
        })
        .collect();

    // Build fill expressions for each numeric column
    let fill_exprs: Vec<Expr> = numeric_cols
        .iter()
        .zip(means.iter())
        .map(|(&name, &mean)| {
            when(col(name).is_null())
                .then(lit(mean))
                .otherwise(col(name))
                .alias(name)
        })
        .collect();

    // Apply the fill operations
    let result = df
        .lazy()
        .with_columns(fill_exprs)
        .collect()?;

    Ok(result)
}

