            "B" => &[None, Some(5.0), Some(7.0)],
        ).unwrap();

        let result = fill_missing_with_column_means(df).unwrap();

        // Column A: mean = (1.0 + 3.0) / 2 = 2.0
        assert_eq!(result.column("A").unwrap().f64().unwrap().get(1), Some(2.0));

        // Column B: mean = (5.0 + 7.0) / 2 = 6.0
