///     vec!["orange".to_string(), "1".to_string(), "apple".to_string()],
///     vec!["apple".to_string(), "2".to_string(), "cherry".to_string()],
/// ];
/// let sorted = sort_table(&df, 0, 1);
/// ```
pub fn sort_table(df0: &[Vec<String>], col0: usize, col1: usize) -> Vec<Vec<String>> {
