use polars::prelude::*;

/// Return a new DataFrame containing only the rows from `df0` whose elements in each row
/// sum to a non-zero value.
///
/// - Non-numeric values are ignored (treated as zero). UTF8 strings are parsed as numbers when possible.
/// - Nulls are treated as zero.
/// - A small tolerance is used for floating point comparisons.
pub fn filter_nonzero_row_sums(df0: &DataFrame) -> PolarsResult<DataFrame> {
    let height = df0.height();
    let cols = df0.get_columns();

    // collect boolean mask: true => keep row
    let mut keep = Vec::with_capacity(height);
    for row_idx in 0..height {
        let mut sum = 0.0f64;
        for col in cols {
            match col.get(row_idx) {
                AnyValue::Int8(v) => sum += v as f64,
                AnyValue::Int16(v) => sum += v as f64,
                AnyValue::Int32(v) => sum += v as f64,
                AnyValue::Int64(v) => sum += v as f64,
                AnyValue::UInt8(v) => sum += v as f64,
                AnyValue::UInt16(v) => sum += v as f64,
                AnyValue::UInt32(v) => sum += v as f64,
                AnyValue::UInt64(v) => sum += v as f64,
                AnyValue::Float32(v) => {
                    let f = v as f64;
                    if !f.is_nan() { sum += f; }
                }
                AnyValue::Float64(v) => {
                    if !v.is_nan() { sum += v; }
                }
                AnyValue::Boolean(b) => sum += if b { 1.0 } else { 0.0 },
                AnyValue::Utf8(s) => {
                    if let Ok(x) = s.parse::<f64>() {
                        if !x.is_nan() { sum += x; }
                    }
                }
                AnyValue::Null => {} // treat as 0
                _ => {} // other types ignored / treated as 0
            }
        }
        // Use a small tolerance to avoid floating-point equality issues.
        keep.push(sum.abs() > 1e-12);
    }

    // Build a boolean mask and filter the DataFrame
    let mask = BooleanChunked::new_from_slice("mask", &keep);
    df0.filter(&mask.into_series())
}

