/// // ╞═════╪═════╡
/// // │ 1   ┆ 10  │
/// // │ 2   ┆ 20  │
/// // │ 3   ┆ 30  │
/// // │ 4   ┆ 999 │
/// // │ 5   ┆ 999 │
/// // └─────┴─────┘
/// ```
pub fn update_table_column(
    df: DataFrame,
    col_update: &str,
    new_val: i64,
    col_condition: &str,
    condition_val: i64,
) -> Result<DataFrame> {
    // Create a boolean mask for the condition
    let mask = df
        .column(col_condition)?
        .gt(condition_val)?;

    // Create the replacement series with new_val where condition is true
    let replacement = Series::new(
        col_update,
        vec![new_val; df.height()],
    );

    // Use when_then_otherwise to conditionally update values
    df.lazy()
        .with_column(
            when(mask)
                .then(replacement.lit())
                .otherwise(col(col_update))
                .alias(col_update),
        )
        .collect()
}

// Alternative implementation using eager operations (simpler but less efficient for large datasets)
pub fn update_table_column_eager(
    mut df: DataFrame,
    col_update: &str,
    new_val: i64,
    col_condition: &str,
    condition_val: i64,
) -> Result<DataFrame> {
    // Get the condition column as a ChunkedArray
    let condition_col = df.column(col_condition)?.i64()?;

    // Create a mask for rows where condition is met
    let mask: BooleanChunked = condition_col.gt(condition_val);

    // Get the update column and apply the mask
    let update_col = df.column(col_update)?.i64()?;
    let updated: Int64Chunked = update_col
        .into_iter()
        .zip(mask.into_iter())
        .map(|(val, condition)| {
            if condition.unwrap_or(false) {
                Some(new_val)
            } else {
                val
            }
        })
        .collect();

    // Replace the column in the DataFrame
    df.replace(col_update, updated.into_series())?;

    Ok(df)
}

