use std::collections::HashMap;
use std::convert::From;
use itertools::Itertools; // for the example that produces a sorted sequence

/// Transform any mapping (anything IntoIterator<Item = (K, V)>) into a Vec<E>,
/// where E is chosen by the caller and must implement From<(K, V)>.
///
/// This is zero-allocation aside from the resulting Vec and uses iterator adapters.
///
/// Example usage:
/// - E = (K, V) to get a Vec of tuples
/// - E = Pair<K, V> where Pair implements From<(K, V)>, to get Vec<Pair<..., ...>>
pub fn map_to_sequence<M, K, V, E>(map: M) -> Vec<E>
where
    M: IntoIterator<Item = (K, V)>,
    E: From<(K, V)>,
{
    map.into_iter().map(E::from).collect()
}

/// Variant that first sorts entries by key (requires K: Ord + Clone).
/// This uses itertools::Itertools for sorted_by_key() so the output order is deterministic.
pub fn map_to_sorted_sequence<M, K, V, E>(map: M) -> Vec<E>
where
    M: IntoIterator<Item = (K, V)>,
    K: Ord + Clone,
    E: From<(K, V)>,
{
    map.into_iter()
        .sorted_by_key(|(k, _v)| k.clone()) // requires itertools
        .map(E::from)
        .collect()
}

