use dashmap::DashMap;
use std::hash::Hash;

/// Set `var0` to `value` in `dict0` only when the current entry for `var0` is None or missing.
/// If an entry exists and is Some(_), it is left untouched.
///
/// - dict0: DashMap<K, Option<V>> (concurrent map whose values are Option<V>)
/// - var0: key to set
/// - value: value to store as Some(value)
///
/// The function is generic over K and V. K requires Eq + Hash.
fn set_if_null<K, V>(dict0: &DashMap<K, Option<V>>, var0: K, value: V)
where
    K: Eq + Hash,
{
    // If the key exists, get a mutable guard and update only if it's currently None.
    if let Some(mut guard) = dict0.get_mut(&var0) {
        if guard.is_none() {
            *guard = Some(value);
        }
    } else {
        // If the key doesn't exist, insert Some(value).
        dict0.insert(var0, Some(value));
    }
}

fn main() {
    let dict: DashMap<String, Option<i32>> = DashMap::new();

    // insert a key with None
    dict.insert("a".to_string(), None);
    // insert a key with Some
    dict.insert("b".to_string(), Some(10));

    // set only if current entry is None/missing
    set_if_null(&dict, "a".to_string(), 42);
    set_if_null(&dict, "b".to_string(), 99);
    set_if_null(&dict, "c".to_string(), 7); // missing — treated as null and inserted

    assert_eq!(dict.get("a").map(|g| g.value().clone()), Some(Some(42)));
    assert_eq!(dict.get("b").map(|g| g.value().clone()), Some(Some(10))); // unchanged
    assert_eq!(dict.get("c").map(|g| g.value().clone()), Some(Some(7)));

