where
    T: Clone,
{
    let mut i = 0;
    let len0 = lst0.len();
    let len1 = lst1.len();

    std::iter::from_fn(move || {
        if i < len0 + len1 {
            let idx = if i % 2 == 0 { len0 - 1 - i / 2 } else { len1 - 1 - i / 2 };
            let (lst, offset) = if i % 2 == 0 { (lst0, idx) } else { (lst1, idx) };
            Some(lst[offset].clone())
        } else {
            None
        }
    })
}
```

