use itertools::interleave;

/// Generate a new sequence by alternately taking elements from the first sequence
/// and from the second sequence in reverse order.
///
/// # Arguments
/// * `lst0` - The first input sequence (will be used in forward order)
/// * `lst1` - The second input sequence (will be used in reverse order)
///
/// # Returns
/// A new Vec containing the interleaved elements
///
/// # Example
/// ```
/// let result = alternate_forward_reverse(&[1, 2, 3], &[4, 5, 6]);
/// assert_eq!(result, vec![1, 6, 2, 5, 3, 4]);
/// ```
pub fn alternate_forward_reverse<T: Clone>(lst0: &[T], lst1: &[T]) -> Vec<T> {
    // Reverse the second sequence
    let reversed_lst1: Vec<T> = lst1.iter().rev().cloned().collect();

    // Interleave the first sequence (forward) with the reversed second sequence
    interleave(lst0.iter().cloned(), reversed_lst1.into_iter()).collect()
}

// Alternative implementation without external dependencies (using only std)
pub fn alternate_forward_reverse_std<T: Clone>(lst0: &[T], lst1: &[T]) -> Vec<T> {
    let mut result = Vec::with_capacity(lst0.len() + lst1.len());
    let mut iter0 = lst0.iter();
    let mut iter1 = lst1.iter().rev();

    // Alternate taking elements from both iterators
    loop {
        match (iter0.next(), iter1.next()) {
            (Some(item0), Some(item1)) => {
                result.push(item0.clone());
                result.push(item1.clone());
            }
            (Some(item0), None) => {
                result.push(item0.clone());
                // If there are remaining elements in lst0, add them
                result.extend(iter0.cloned());
                break;
            }
            (None, Some(item1)) => {
                result.push(item1.clone());
                // If there are remaining elements in lst1, add them
                result.extend(iter1.cloned());
                break;
            }
            (None, None) => break,
        }
    }

    result
}

