use ndarray::{Array2, Axis};

/// Replaces the elements along the main diagonal of a 2D matrix with the given value.
///
/// # Arguments
///
/// * `matrix` - A mutable 2D array (matrix).
/// * `value` - The value to replace the diagonal elements with.
///
/// # Example
///
/// ```
/// let mut matrix = ndarray::array![
///     1, 2, 3,
///     4, 5, 6,
