///     4, 0, 6,
///     7, 8, 0
/// ]);
/// ```
fn replace_diagonal(matrix: &mut Array2<i32>, value: i32) {
    // Get the size of the matrix
    let size = matrix.shape()[0].min(matrix.shape()[1]);

    // Replace the diagonal elements
    for i in 0..size {
        matrix[[i, i]] = value;
    }
}

