Code (function + small example)
```rust
use fast_float::parse as parse_float;

/// Sorts a list of strings by their floating-point values (ascending).
/// - Input: Vec<String> (or Vec<&str> converted to Vec<String>)
/// - Output: Vec<String> sorted by parsed f64 values; entries that fail to parse
///   (or produce NaN) are placed at the end in original relative order among NaNs.
pub fn sort_by_float_strings(lst0: Vec<String>) -> Vec<String> {
    // Pair each string with its parsed f64 (NaN on parse error).
    let mut pairs: Vec<(f64, usize, String)> = lst0
        .into_iter()
        .enumerate()
        .map(|(idx, s)| {
            let v = parse_float::<f64>(s.as_bytes()).unwrap_or(f64::NAN);
            (v, idx, s)
        })
        .collect();

    // Sort with explicit NaN handling:
    // - Non-NaN values compare by their f64 ordering
    // - NaNs are considered greater than any number (so they go to the end)
    // - Keep a stable tie-breaker using original index to preserve input order
    pairs.sort_by(|a, b| {
        let (va, ia, _) = a;
        let (vb, ib, _) = b;
        let a_nan = va.is_nan();
        let b_nan = vb.is_nan();

        match (a_nan, b_nan) {
            (true, true) => ia.cmp(ib), // keep original order among NaNs
            (true, false) => std::cmp::Ordering::Greater,
            (false, true) => std::cmp::Ordering::Less,
            (false, false) => {
                // safe to unwrap because neither is NaN
                va.partial_cmp(vb).unwrap_or(std::cmp::Ordering::Equal).then(ia.cmp(ib))
            }
        }
    });

    // Return sorted strings
    pairs.into_iter().map(|(_, _, s)| s).collect()
}

fn main() {
    let lst0 = vec![
        "3.14".to_string(),
        "-2".to_string(),
        "10e-1".to_string(),
        "NaN".to_string(),        // treated as NaN -> goes to end
        "abc".to_string(),        // parse error -> treated as NaN -> end
        "0.0".to_string(),
    ];

    let sorted = sort_by_float_strings(lst0);
    println!("{:?}", sorted);
    // Expected output (ascending numeric order, NaNs at end):
    // ["-2", "0.0", "10e-1", "3.14", "NaN", "abc"]
}
```

Notes
- Change the input type if you prefer &str or other containers; the core idea is to parse to f64 and sort by that value.
- fast_float is used for fast, robust parsing of floating-point text into f64. Adjust the dependency version as needed in Cargo.toml.

