```rust
use serde_json::{Value, Map};
use std::collections::HashMap;

/// Reorders a sequence of key-value maps so that entries with language != "en" appear at the end,
/// preserving their original relative order.
///
/// # Arguments
/// * `maps` - A vector of key-value maps (e.g., `serde_json::Value` or `HashMap`)
///
/// # Returns
/// A new vector with the same maps reordered as specified
pub fn reorder_by_language<M: Into<Value>>(maps: Vec<M>) -> Vec<Value> {
    // First, separate into English and non-English maps
    let mut english: Vec<Value> = Vec::new();
    let mut non_english: Vec<Value> = Vec::new();

    for map in maps {
        let value: Value = map.into();
        let map_value = if let Value::Object(map) = value {
            map
        } else {
            // If not an object, treat as non-English (or you could handle differently)
            non_english.push(value);
            continue;
        };

        // Check for language field (case-insensitive)
        let language = map_value.get("language")
            .and_then(|v| v.as_str())
            .map(|s| s.to_lowercase());

        match language {
            Some("en") => english.push(value),
            _ => non_english.push(value),
        }
    }

    // Combine the results: English first, then non-English
    english.into_iter().chain(non_english).collect()
}

// Example usage:
