use indexmap::IndexMap;

fn sort_by_position<K, V>(map: &IndexMap<K, Vec<V>>, pos: usize) -> Vec<(K, Vec<V>)>
where
    K: Clone + Eq + std::hash::Hash,
    V: Clone + Ord,
{
