        // If the position is out of bounds, we should handle it gracefully
        let a_elem = a.1.get(pos);
        let b_elem = b.1.get(pos);

        match (a_elem, b_elem) {
            (Some(a_val), Some(b_val)) => a_val.cmp(b_val), // Regular comparison
            (Some(_), None) => std::cmp::Ordering::Less,   // Treat as lesser if b has no such element
