use itertools::Itertools;

/// Sorts a key-value mapping where each value is a vector, based on the element at the specified index.
///
/// # Arguments
///
/// * `map` - A mutable reference to a HashMap with keys of type K and values of type Vec<V>.
/// * `index` - The index of the element within the vectors to sort by.
///
/// # Panics
///
/// This function will panic if any vector in the map does not have an element at the specified index.
fn sort_map_by_sequence_element<K, V>(map: &mut std::collections::HashMap<K, Vec<V>>, index: usize)
where
    K: std::cmp::Ord,
    V: std::cmp::Ord + Clone,
{
    // Create a vector of tuples (key, value) from the map
    let mut entries: Vec<(&K, &Vec<V>)> = map.iter().collect();

    // Sort the entries by the element at the specified index in the vector
    entries.sort_by(|a, b| {
        a.1.get(index).unwrap().cmp(b.1.get(index).unwrap())
    });

    // Clear the original map
    map.clear();

    // Insert the sorted entries back into the map
    for (key, value) in entries {
        map.insert(key.clone(), value.clone());
    }
