/// assert_eq!(sorted.get_index(1).unwrap().0, "a");
/// assert_eq!(sorted.get_index(2).unwrap().0, "c");
/// ```
pub fn sort_by_sequence_position<K, V>(
    kv_map: &IndexMap<K, V>,
    sequence_index: usize,
) -> IndexMap<K, V>
where
    K: Ord + Clone,
    V: Clone + PartialOrd + std::ops::Index<usize, Output = V::Output>,
    V::Output: PartialOrd,
{
    let mut sorted: IndexMap<K, V> = IndexMap::new();

    // Collect entries into a vector for sorting
    let mut entries: Vec<_> = kv_map.iter().collect();

    // Sort by the specified sequence position
