```rust
use itertools::Itertools;
use std::cmp::Reverse;

/// Sort a collection of (K, V) pairs by the element at `idx` inside each value-sequence `V`.
///
/// - `entries`: any IntoIterator<Item = (K, V)> (e.g. a HashMap::into_iter()).
/// - `idx`: index inside each value's sequence to sort by.
/// - `missing_first`: if true, entries where the sequence has no element at `idx` sort before ones that do; if false, they sort last.
///
/// Returns a Vec<(K, V)> containing the same pairs, sorted as specified.
pub fn sort_entries_by_index<I, K, V, T>(
    entries: I,
    idx: usize,
    missing_first: bool,
) -> Vec<(K, V)>
where
    I: IntoIterator<Item = (K, V)>,
    V: AsRef<[T]>,
    T: Ord + Clone,
{
    if missing_first {
        // key() produces Option<T>: None < Some(..) by default, so missing first
        entries
            .into_iter()
            .sorted_by_key(|(_, v)| v.as_ref().get(idx).cloned())
            .collect()
    } else {
        // invert ordering by wrapping present values in Reverse; None stays None and sorts before Some,
        // so to make missing last we map None -> Some(Reverse(...))? Simpler: map Option<T> -> Option<Reverse<T>> and
        // then treat None as greater than any Some: we can map None -> Some(Reverse(max_value)) but we don't know max_value.
        // Simpler approach: key is Option<Reverse<T>> but we want None > Some(...). To achieve that, map None -> Some(Reverse(sentinel))
        // is complex, so instead we sort with a comparator using sorted_by.
        entries
            .into_iter()
            .sorted_by(|(_, va), (_, vb)| {
                let a = va.as_ref().get(idx);
                let b = vb.as_ref().get(idx);
                match (a, b) {
                    (Some(x), Some(y)) => x.cmp(y),
                    (Some(_), None) => std::cmp::Ordering::Less, // present < missing => missing last
                    (None, Some(_)) => std::cmp::Ordering::Greater,
                    (None, None) => std::cmp::Ordering::Equal,
                }
            })
            .collect()
    }
}

#[cfg(test)]
