    fn sort_example_missing_first() {
        let mut m: HashMap<&str, Vec<i32>> = HashMap::new();
        m.insert("a", vec![3, 1]);
        m.insert("b", vec![2, 5]);
        m.insert("c", vec![]); // missing
        m.insert("d", vec![2, 0]);

        let sorted = sort_entries_by_index(m.into_iter(), 0, true);
        // Expect order: c (missing), b and d (2), a (3)
        let keys: Vec<_> = sorted.into_iter().map(|(k, _)| k).collect();
        assert_eq!(keys, vec!["c", "b", "d", "a"]);
    }

    #[test]
