/// // Results in: b->vec![1,5,9], c->vec![2,3,4], a->vec![3,1,2]
/// // Sorted by first element: 1, 2, 3
/// ```
fn sort_by_sequence_position<K, V>(
    map: &IndexMap<K, Vec<V>>,
    position: usize,
) -> IndexMap<K, Vec<V>>
