```rust
use polars::prelude::*;
use std::collections::HashMap;

/// Sum columns with identical headers in `df`. Returns a new DataFrame where each header appears once.
/// - Numeric columns (Int/UInt/Float) are cast to Float64 and summed element-wise.
/// - Non-numeric columns: only the first occurrence is kept.
///
/// Returns a PolarsResult<DataFrame>.
pub fn sum_duplicate_columns(df: &DataFrame) -> PolarsResult<DataFrame> {
    // Keep insertion order of headers
    let mut order: Vec<String> = Vec::new();
    let mut accum: HashMap<String, Series> = HashMap::new();

    for s in df.get_columns() {
        let name = s.name().to_string();

        // Determine if this series is numeric; if so, cast to Float64 for summation.
        let is_numeric = matches!(
            s.dtype(),
            DataType::Float32 | DataType::Float64 | DataType::Int8 | DataType::Int16
                | DataType::Int32 | DataType::Int64 | DataType::UInt8 | DataType::UInt16
                | DataType::UInt32 | DataType::UInt64
        );

        if !accum.contains_key(&name) {
            // First time we see this column name; insert either numeric-cast or original.
            if is_numeric {
                let casted = s.cast(&DataType::Float64)?;
                accum.insert(name.clone(), casted);
            } else {
                accum.insert(name.clone(), s.clone());
            }
            order.push(name);
        } else {
            // We've seen this column name before; attempt to sum if numeric.
            if is_numeric {
                // Ensure existing is numeric (cast if needed)
                let existing = accum.get_mut(&name).expect("key exists");
                let existing_numeric = if matches!(
                    existing.dtype(),
                    DataType::Float32 | DataType::Float64 | DataType::Int8 | DataType::Int16
                        | DataType::Int32 | DataType::Int64 | DataType::UInt8 | DataType::UInt16
                        | DataType::UInt32 | DataType::UInt64
                ) {
                    existing.cast(&DataType::Float64)?
                } else {
                    // If existing was non-numeric, replace it with current numeric cast (first numeric wins)
                    s.cast(&DataType::Float64)?
                };

                let rhs = s.cast(&DataType::Float64)?;
                // Element-wise addition: get f64 ChunkedArray and add
                let lhs_ca = existing_numeric.f64()?;
                let rhs_ca = rhs.f64()?;
                let summed = lhs_ca + rhs_ca; // returns ChunkedArray<f64>
                *existing = summed.into_series().rename(&name);
            } else {
                // Non-numeric duplicate: do nothing (we keep the first occurrence).
                // If you want a different behavior (e.g., concatenation), change here.
            }
        }
    }

    // Collect Series in original-first-seen order
    let mut series_out: Vec<Series> = Vec::with_capacity(order.len());
    for key in order {
        if let Some(s) = accum.remove(&key) {
            series_out.push(s);
        }
    }

    DataFrame::new(series_out)
}

fn main() -> anyhow::Result<()> {
    // Example usage: create a DataFrame with duplicate headers
    let a1 = Series::new("x", &[1_i64, 2, 3]);
    let a2 = Series::new("y", &[10_i64, 20, 30]);
    let a3 = Series::new("x", &[0.5_f64, 1.5, 2.5]); // duplicate header "x" (mixed int and float)
    let a4 = Series::new("label", &["a", "b", "c"]);
    let a5 = Series::new("label", &["z", "y", "x"]); // duplicate non-numeric header "label"

    let df = DataFrame::new(vec![a1, a2, a3, a4, a5])?;
    println!("Input DataFrame:\n{}", &df);

    let out = sum_duplicate_columns(&df)?;
    println!("\nOutput DataFrame (duplicates summed):\n{}", &out);

    Ok(())
}
