use indexmap::IndexMap;
use std::cmp::Ordering;
use std::collections::HashMap;

/// Reorder the entries of `dict0` by the value stored under the inner key `var0`.
///
/// - `dict0` is a map from K -> HashMap<IK, V>.
/// - `var0` is the inner key to sort by.
/// - If an inner map doesn't contain `var0`, that outer entry is placed after those that do.
/// - `ascending` controls sort order (true = ascending, false = descending).
///
/// Returns an `IndexMap` whose iteration order is the sorted order.
pub fn reorder_by_inner_key<K, IK, V>(
    dict0: &HashMap<K, HashMap<IK, V>>,
    var0: &IK,
    ascending: bool,
) -> IndexMap<K, HashMap<IK, V>>
where
    K: Eq + std::hash::Hash + Clone,
    IK: Eq + std::hash::Hash + Clone,
    V: Ord + Clone,
{
    // Collect (outer_key, inner_map, Option<sort_value>)
    let mut entries: Vec<(K, HashMap<IK, V>, Option<V>)> = dict0
        .iter()
        .map(|(k, inner)| {
            let sort_val = inner.get(var0).cloned();
            (k.clone(), inner.clone(), sort_val)
        })
        .collect();

    // Comparator that treats Some(x) < None (so entries with the key come first).
    fn cmp_opt<V: Ord>(a: &Option<V>, b: &Option<V>) -> Ordering {
        match (a, b) {
            (Some(x), Some(y)) => x.cmp(y),
            (Some(_), None) => Ordering::Less,
            (None, Some(_)) => Ordering::Greater,
            (None, None) => Ordering::Equal,
        }
    }

    entries.sort_by(|a, b| {
        let ord = cmp_opt(&a.2, &b.2);
        if ascending { ord } else { ord.reverse() }
    });

    let mut out = IndexMap::with_capacity(entries.len());
    for (k, inner, _) in entries {
        out.insert(k, inner);
    }
    out
}

Example usage:

