use itertools::Itertools; // itertools 0.11+ (2023)
use serde_json::{json, Value};

/// Reorders `lst0` so that objects with `key = var0` equal to `var1`
/// come first (in original order), and all others appear after (also in original order).
/// Non-object entries or objects missing the key are treated as "not equal" and go to the end.
///
/// - lst0: vector of JSON values (expected to be objects/maps)
/// - var0: key name to check
/// - var1: JSON value to compare against
///
/// Returns a new Vec<Value> with the requested stable partition.
fn reorder_by_key_value(lst0: Vec<Value>, var0: &str, var1: &Value) -> Vec<Value> {
    // partition preserves the relative order of elements in each output Vec
    let (mut keep, mut move_end): (Vec<_>, Vec<_>) = lst0
        .into_iter()
        .partition(|v| match v {
            Value::Object(map) => map.get(var0).map(|x| x == var1).unwrap_or(false),
            _ => false,
        });

    keep.append(&mut move_end);
    keep
}

