use ndarray::Array2;

/// Apply `func` to every element of the 2-D input `df0`.
/// The `var0` parameter chooses which axis to iterate along:
///  - 0: iterate down columns (column-major order)
///  - 1: iterate across rows (row-major order)
///
/// This returns a new Array2<U> with the same shape as `df0`.
pub fn apply_along_axis_var0<T, U, F>(df0: &Array2<T>, var0: usize, mut func: F) -> Array2<U>
where
    F: FnMut(&T) -> U,
    T: Clone,
    U: Clone + Default,
{
    let (rows, cols) = df0.dim();
    let mut out = Array2::<U>::default((rows, cols));

    match var0 {
        0 => {
            // iterate down columns (for each column, walk rows)
            for col in 0..cols {
                for row in 0..rows {
                    out[(row, col)] = func(&df0[(row, col)]);
                }
            }
        }
        1 => {
            // iterate across rows (for each row, walk columns)
            for row in 0..rows {
                for col in 0..cols {
                    out[(row, col)] = func(&df0[(row, col)]);
                }
            }
        }
        _ => panic!("var0 must be 0 or 1 (axis index)"),
    }

    out
}

fn main() {
    // Example usage:
    let df0 = Array2::from_shape_vec((2, 3), vec![1, 2, 3, 4, 5, 6]).unwrap();

