///
/// # Examples
/// ```
/// use std::f64;
///
/// let pairs = vec![
///     ("valid".to_string(), 5.0),
///     ("invalid".to_string(), f64::NAN),
///     ("smallest".to_string(), 1.0),
///     ("another".to_string(), f64::INFINITY),
/// ];
///
/// let result = find_smallest_valid_pair(&pairs);
/// assert_eq!(result, Some(("smallest".to_string(), 1.0)));
/// ```
pub fn find_smallest_valid_pair(pairs: &[(&str, f64)]) -> Option<(&str, f64)> {
    pairs
        .iter()
        .filter(|(_, value)| value.is_finite()) // Skip invalid (NaN or Infinity) values
        .min_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap()) // Compare valid values
        .map(|(label, value)| (*label, *value)) // Return the tuple
}
