        .map(|(label, val)| (*label, val))
}

/// Simple number parser using winnow
fn parse_number(input: &str) -> PResult<Option<f64>> {
    let mut input = input.trim();

    // Try to parse optional sign
    let sign = if input.starts_with('-') {
        input = &input[1..];
        -1.0
    } else if input.starts_with('+') {
        input = &input[1..];
        1.0
    } else {
        1.0
    };

    // Check if we have digits
    if !input.chars().next().map_or(false, |c| c.is_ascii_digit()) {
        return Ok(None);
    }

    // Parse integer part
    let mut chars = input.chars();
    let mut num_str = String::new();

    while let Some(c) = chars.next() {
        if c.is_ascii_digit() || c == '.' {
            num_str.push(c);
        } else {
            break;
        }
    }

    num_str
        .parse::<f64>()
        .ok()
        .map(|n| Some(n * sign))
        .ok_or(winnow::error::ErrMode::Cut(winnow::error::ContextError::default()))
}

