use polars::prelude::*;
use std::collections::HashMap;

/// Converts a Polars DataFrame with 'id' and 'value' columns into a HashMap
/// 
/// # Arguments
/// * `df` - A Polars DataFrame with 'id' (String/Int) and 'value' (any type) columns
///
/// # Returns
/// * `Result<HashMap<String, String>, PolarsError>` - A HashMap mapping ids to values
fn dataframe_to_hashmap(df: &DataFrame) -> Result<HashMap<String, String>, PolarsError> {
