    let id_col = df.column("id")?.str()?;
    let value_col = df.column("value")?.str()?;

    // Create a HashMap and populate it
    let mut map = HashMap::new();

    for (id, value) in id_col.iter().zip(value_col.iter()) {
        if let (Some(id_val), Some(val)) = (id, value) {
            map.insert(id_val.to_string(), val.to_string());
        }
    }

    Ok(map)
}

