use itertools::Itertools;

/// Generates a list of boolean values indicating whether elements at each position
/// are equal between two input sequences.
///
/// # Arguments
/// * `seq1` - First sequence
/// * `seq2` - Second sequence
///
/// # Returns
/// A vector of booleans where each element indicates equality at that position.
/// If sequences have different lengths, the result length matches the shorter sequence.
///
/// # Examples
/// ```
/// let result = element_wise_equality(&[1, 2, 3], &[1, 2, 4]);
/// assert_eq!(result, vec![true, true, false]);
/// ```
fn element_wise_equality<T: PartialEq>(seq1: &[T], seq2: &[T]) -> Vec<bool> {
    seq1.iter()
        .zip_longest(seq2.iter())
        .map(|pair| match pair {
            itertools::EitherOrBoth::Both(a, b) => a == b,
            _ => false, // Different lengths - mismatched positions are false
        })
        .collect()
}

