use rayon::prelude::*;
use std::collections::HashSet;

fn custom_sort(texts: &mut Vec<String>, positions: Option<&Vec<usize>>) {
    // If positions are provided, sort those positions in descending order
    if let Some(pos) = positions {
        let pos_set: HashSet<_> = pos.iter().cloned().collect();

        // Sort the specified positions in descending order
        texts.par_sort_by(|a, b| {
            let a_in_pos = pos_set.contains(&texts.iter().position(|x| x == a).unwrap_or(usize::MAX));
            let b_in_pos = pos_set.contains(&texts.iter().position(|x| x == b).unwrap_or(usize::MAX));

            match (a_in_pos, b_in_pos) {
                (true, true) => b.cmp(a), // Descending order for specified positions
                (true, false) => std::cmp::Ordering::Less, // Elements in positions come first
                (false, true) => std::cmp::Ordering::Greater, // Elements not in positions come second
                (false, false) => a.cmp(b), // Ascending order for other elements
            }
        });
    } else {
        // If no positions are provided, sort all elements in ascending order
        texts.par_sort();
    }
}

fn main() {
    let mut texts = vec![
        "apple".to_string(),
        "banana".to_string(),
        "cherry".to_string(),
        "date".to_string(),
        "elderberry".to_string(),
