use itertools::Itertools;

/// Sorts a list of text elements in ascending order by default, 
/// but sorts those at the specified positions in descending order.
///
/// If the list of positions is omitted, sort all elements in ascending order.
///
/// # Arguments
///
/// * `text_elements`: The list of text elements to sort.
/// * `positions`: An optional list of integer positions to sort in descending order.
///
/// # Returns
///
/// The sorted list of text elements.
pub fn sort_text_elements(text_elements: Vec<String>, positions: Option<Vec<usize>>) -> Vec<String> {
    let mut sorted_elements = text_elements.clone();

    match positions {
        Some(positions) => {
            let mut ascending = Vec::new();
            let mut descending = Vec::new();

            for (i, element) in text_elements.iter().enumerate() {
                if positions.contains(&i) {
                    descending.push(element.clone());
                } else {
                    ascending.push(element.clone());
                }
            }

            ascending.sort();
            descending.sort_by(|a, b| b.cmp(a));

            let mut result = Vec::new();
            let mut descending_index = 0;

            for (i, _) in text_elements.iter().enumerate() {
                if positions.contains(&i) {
                    result.push(descending[descending_index].clone());
                    descending_index += 1;
                } else {
                    result.push(ascending.pop().unwrap());
                }
            }

            sorted_elements = result;
        }
        None => {
            sorted_elements.sort();
        }
    }

    sorted_elements
}

fn main() {
