use indexmap::IndexMap;

fn top_indices<T: Ord + Clone>(lst0: &[T], var0: usize) -> Vec<usize> {
    // Handle edge cases
    if lst0.is_empty() || var0 == 0 {
        return Vec::new();
    }

    // Use a max-heap (priority queue) to track the top elements
    let mut heap = indexmap::map::RandomAccessMap::new();
    let mut indices = Vec::with_capacity(var0);

    // First pass: find the top var0 elements and their indices
    for (i, &item) in lst0.iter().enumerate() {
        if heap.len() < var0 {
            heap.insert(item.clone(), i);
        } else if item > heap.keys().next().unwrap() {
            // Replace the smallest in heap with current item
            let smallest = heap.remove(heap.keys().next().unwrap()).unwrap();
            heap.insert(item.clone(), i);
            // Keep track of the smallest index we might need to remove
            indices.push(smallest);
        }
    }

    // Second pass: collect all indices from the heap
    // We need to sort them by value in descending order
