use std::cmp::Ordering;
use itertools::Itertools;

/// Return the indices of the `k` (= `var0`) largest elements in `lst0`,
/// sorted from highest value to lowest.
/// If k >= lst0.len(), returns indices of all elements sorted by value desc.
///
/// Example:
/// let v = vec![1.0, 5.0, 3.0, 5.0];
/// let top2 = top_k_indices(&v, 2);
/// // top2 could be [1, 3] (indices of the two 5.0 values), order among ties is unspecified.
pub fn top_k_indices(lst0: &[f64], var0: usize) -> Vec<usize> {
    let k = var0.min(lst0.len());
    lst0
        .iter()
        .enumerate()
        // sort by value descending; handle possible NaN by treating as equal
        .sorted_by(|a, b| {
            // a = (idx_a, &val_a)
            // We want descending order (largest first): compare b vs a
            b.1.partial_cmp(a.1).unwrap_or(Ordering::Equal)
        })
        .take(k)
        .map(|(idx, _)| idx)
        .collect()
}

Notes:
- This implementation sorts the whole enumerated iterator, which is simple and clear. For very large lists with small k you may prefer a selection/heap-based approach to avoid O(n log n) cost.
- The code uses partial_cmp and treats incomparable values (e.g., NaN) as equal; adjust behavior if you need a specific NaN ordering.

