use ndarray::ArrayView1;

/// Returns the indices of the `k` largest elements in `arr`, sorted from highest to lowest.
///
/// # Arguments
/// * `arr` - A 1-dimensional array view
/// * `k` - Number of largest elements to find
///
/// # Returns
/// * `Vec<usize>` - Indices of the k largest elements, sorted descending by value
///
/// # Panics
/// * If `k` is greater than the length of `arr`
pub fn indices_of_largest<T: PartialOrd + Clone>(arr: ArrayView1<'_, T>, k: usize) -> Vec<usize> {
    assert!(k <= arr.len(), "k must be less than or equal to array length");

    if k == 0 {
        return Vec::new();
    }

    // Create vector of (value, index) pairs
    let mut indexed_values: Vec<(T, usize)> = arr
        .indexed_iter()
        .map(|(idx, val)| (val.clone(), idx))
        .collect();

    // Sort by value in descending order
    indexed_values.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));

    // Take the first k indices
    indexed_values
        .into_iter()
        .take(k)
        .map(|(_, idx)| idx)
        .collect()
}

