```rust
use polars::prelude::*;

/// Removes duplicate rows based on a specified identifier column, keeping only the first occurrence.
///
/// # Arguments
/// * `df` - The input DataFrame
/// * `identifier_col` - The name of the column to use as the identifier for deduplication
///
/// # Returns
/// A new DataFrame with duplicates removed
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df!(
///     "id" => &[1, 2, 2, 3, 4, 4, 4],
///     "value" => &["a", "b", "c", "d", "e", "f", "g"]
/// ).unwrap();
///
/// let result = remove_duplicates_by_id(df, "id").unwrap();
/// ```
pub fn remove_duplicates_by_id(df: DataFrame, identifier_col: &str) -> Result<DataFrame, PolarsError> {
    // Create a new DataFrame with just the identifier column
    let id_df = df.lazy()
        .select([col(identifier_col)])
        .collect()?;

    // Get the unique values from the identifier column
    let unique_ids = id_df
        .column(identifier_col)?
        .unique(true)?;

    // Filter the original DataFrame to keep only rows with unique identifiers
    let result = df.lazy()
        .filter(col(identifier_col).is_in(unique_ids))
        .collect()?;

    Ok(result)
}

#[cfg(test)]
