///     println!("After removing duplicates:\n{}", &result);
///     
///     Ok(())
/// }
/// ```
fn remove_duplicate_ids(data: &DataFrame, id_column: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Validate that the id column exists
    if !data.get_column_names().contains(&id_column) {
        return Err(format!("Column '{}' not found in DataFrame", id_column).into());
    }

    // Use unique() with the "first" strategy to keep first occurrence
    let result = data.unique(
        Some(&[id_column]),  // Subset of columns to check for uniqueness
        UniqueKeepStrategy::First  // Keep the first occurrence
    )?;

    Ok(result)
}

// Alternative implementation using group_by for more control
fn remove_duplicate_ids_alt(data: &DataFrame, id_column: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Validate that the id column exists
    if !data.get_column_names().contains(&id_column) {
        return Err(format!("Column '{}' not found in DataFrame", id_column).into());
    }

    // Group by the id column and take the first row of each group
    let result = data
        .group_by([id_column])?
        .agg([col("*").first()])?;

    Ok(result)
}

fn main() -> Result<(), Box<dyn Error>> {
    // Example usage
