/// Multiplies a vector by a matrix (matrix-vector multiplication)
///
/// # Arguments
/// * `vector` - A slice of numerical values (f32 or f64)
/// * `matrix` - A 2D slice representing a matrix (rows × columns)
///
/// # Returns
/// A new vector containing the result of the multiplication
///
/// # Panics
/// Panics if the vector length doesn't match the matrix's number of columns
fn multiply_vector_by_matrix<T>(vector: &[T], matrix: &[T]) -> Vec<T>
where
    T: Copy + std::ops::Mul<Output = T> + std::ops::Add<Output = T> + Default + std::fmt::Debug,
    f32: From<T>,
    f64: From<T>,
{
    // Convert to f64 for calculations (works for both f32 and f64)
    let vector_f64: Vec<f64> = vector.iter().map(|&x| f64::from(x)).collect();
    let matrix_f64: Vec<f64> = matrix.iter().map(|&x| f64::from(x)).collect();

    // Calculate matrix dimensions (assuming row-major order)
    let cols = vector_f64.len();
    let rows = matrix_f64.len() / cols;

    // Verify matrix dimensions are valid
    if matrix_f64.len() % cols != 0 {
        panic!("Invalid matrix dimensions: expected rows × cols");
    }

    // Perform matrix-vector multiplication
    let mut result = vec![T::default(); cols];
    for i in 0..cols {
        let mut sum = 0.0;
        for j in 0..rows {
            sum += matrix_f64[j * cols + i] * vector_f64[j];
        }
        result[i] = T::from(sum);
    }

    result
}

