```rust
/// Multiply a row vector `vec` by a matrix `mat`.
///
/// - `vec` is a slice of length m (the row vector).
/// - `mat` is a slice of m rows, each row being a Vec<f64> with the same length n.
/// - Returns a Vec<f64> of length n representing the product `vec * mat`.
///
/// Errors if:
/// - number of rows in `mat` does not equal the length of `vec`, or
/// - `mat` is not rectangular (rows have differing lengths).
///
/// Example:
/// let v = vec![1.0, 2.0];
/// let m = vec![ vec![3.0,4.0,5.0], vec![6.0,7.0,8.0] ];
/// // result = [1*3 + 2*6, 1*4 + 2*7, 1*5 + 2*8] = [15, 18, 21]
pub fn multiply_vector_by_matrix(vec: &[f64], mat: &[Vec<f64>]) -> Result<Vec<f64>, String> {
    let m = vec.len();
    if mat.len() != m {
        return Err(format!(
            "Dimension mismatch: vector length {} != matrix rows {}",
            m,
            mat.len()
        ));
    }

    // Determine number of columns (n). If there are zero rows, define n = 0.
    let n = if m == 0 { 0 } else { mat[0].len() };

    // Check rectangularity of the matrix
    for (i, row) in mat.iter().enumerate() {
        if row.len() != n {
            return Err(format!(
                "Matrix is not rectangular: row {} has length {}, expected {}",
                i,
                row.len(),
                n
            ));
        }
    }

    // Compute result vector of length n
    let mut result = vec![0.0_f64; n];
    for j in 0..n {
        let mut sum = 0.0_f64;
        for i in 0..m {
            sum += vec[i] * mat[i][j];
        }
        result[j] = sum;
    }

    Ok(result)
}

