fn multiply_vector_by_matrix(vector: &[f64], matrix: &[Vec<f64>]) -> Vec<f64> {
    // Validate inputs
    if vector.is_empty() || matrix.is_empty() {
        return Vec::new();
    }

    let vector_len = vector.len();
    let num_cols = matrix[0].len();

    // Ensure matrix is valid (all rows have same length)
    assert!(matrix.iter().all(|row| row.len() == num_cols),
            "Matrix rows must have equal length");

    // Ensure vector length matches matrix rows
    assert_eq!(vector_len, matrix.len(),
               "Vector length must match number of matrix rows");

    // Perform matrix-vector multiplication: result[j] = sum(vector[i] * matrix[i][j])
    let mut result = vec![0.0; num_cols];

    for col in 0..num_cols {
        let mut sum = 0.0;
        for row in 0..vector_len {
            sum += vector[row] * matrix[row][col];
        }
        result[col] = sum;
    }

    result
}

fn main() {
