/// Strips currency symbols from the penultimate column of a DataFrame and converts to f64.
fn strip_currency_and_convert(df: &mut DataFrame) -> Result<DataFrame, Box<dyn Error>> {
    // Get the number of columns
    let num_cols = df.get_n_columns();

    // Check if there are at least two columns
    if num_cols < 2 {
        return Err("DataFrame must have at least two columns.".into());
    }

    // Get the name of the penultimate column
    let penultimate_col = df.get_column_names()[num_cols - 2];

