```rust
use regex::Regex;

#[derive(Debug, Clone)]
pub enum Cell {
    Text(String),
    Number(f64),
}

/// Strip the currency symbol from the penultimate column of a 2D table and convert its entries to f64.
///
/// - `table`: Vec<Vec<String>> where each inner Vec is a row.
/// - Returns: Result containing a new table Vec<Vec<Cell>> where the penultimate column entries
///   have been converted to Cell::Number(f64). Non-penultimate cells are Cell::Text(String).
///
/// Behavior / parsing rules:
/// - Trims surrounding whitespace.
/// - Recognizes and removes any Unicode currency symbol (\p{Sc}) anywhere in the cell.
/// - Removes common thousands separators: comma and a variety of space characters (NBSP, thin spaces).
/// - Accepts values wrapped in parentheses as negative e.g. "(1,234.56)" -> -1234.56.
/// - If parsing fails for any entry in the penultimate column, an Err is returned with a message.
pub fn strip_penultimate_currency(
    table: Vec<Vec<String>>,
) -> Result<Vec<Vec<Cell>>, Box<dyn std::error::Error>> {
    // regex to remove Unicode currency symbols (e.g. $, €, £, ¥, ₹, ₩, etc.)
    let currency_re = Regex::new(r"\p{Sc}")?;
    // regex to remove grouping separators (commas and various whitespace types used as group separators)
    // Note: we intentionally keep the dot `.` (decimal point).
    let grouping_re = Regex::new(r"[,\u{00A0}\u{202F}\u{2009}\s]")?;

    let mut out: Vec<Vec<Cell>> = Vec::with_capacity(table.len());

    for row in table {
        // If row is too short to have a penultimate column, just copy as Text cells.
        if row.len() < 2 {
            out.push(row.into_iter().map(Cell::Text).collect());
            continue;
        }

        let penult_idx = row.len() - 2;
        let mut new_row: Vec<Cell> = Vec::with_capacity(row.len());

        for (i, cell) in row.into_iter().enumerate() {
            if i == penult_idx {
                // Process the penultimate cell:
                let mut s = cell.trim().to_string();

                // Handle parentheses for negatives: "(1,234.56)" => negative
                let negative = s.starts_with('(') && s.ends_with(')');
                if negative {
                    // remove outer parentheses
                    s = s[1..s.len() - 1].trim().to_string();
                }

                // Remove any currency symbols anywhere in the string
                s = currency_re.replace_all(&s, "").into_owned();

                // Remove grouping separators like commas and non-breaking spaces
                s = grouping_re.replace_all(&s, "").into_owned();

                if s.is_empty() {
                    return Err(format!("Empty numeric value after cleaning penultimate cell").into());
                }

                if negative {
                    s = format!("-{}", s);
                }

                // Parse as f64
                match s.parse::<f64>() {
                    Ok(n) => new_row.push(Cell::Number(n)),
                    Err(e) => {
                        return Err(format!(
                            "Failed to parse '{}' in penultimate column as float: {}",
                            s, e
                        )
                        .into())
                    }
                }
            } else {
                // Non-penultimate cell: keep as text
                new_row.push(Cell::Text(cell));
            }
        }

        out.push(new_row);
    }

    Ok(out)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Example usage:
    let table = vec![
        vec![
            "Item".to_string(),
            "$1,234.56".to_string(), // penultimate -> should become Number(1234.56)
            "In stock".to_string(),
        ],
        vec![
            "Widget".to_string(),
            "€(2 345.78)".to_string(), // penultimate -> negative Number(-2345.78), NBSP/space grouping
            "Backorder".to_string(),
        ],
        vec![
            "Gadget".to_string(),
            "¥12,345".to_string(), // penultimate -> Number(12345.0)
            "Available".to_string(),
        ],
    ];

    let converted = strip_penultimate_currency(table)?;
    for row in converted {
        println!("{:?}", row);
    }

    Ok(())
}
```

Notes and possible extensions:
- This implementation assumes decimal point is '.'; it does not handle locales that use comma as decimal separator (e.g., "1.234,56"). If you need locale-aware parsing, consider adding a small locale parser or using a crate that supports localized number parsing.
- The regex crate is used here (specify regex = "1.9" or later in Cargo.toml). If you prefer an alternative parsing library (for performance or locale handling), that can be swapped in easily.

