        .has_headers(true)
        .from_reader(input);

    // Create CSV writer
    let mut writer = WriterBuilder::new()
        .flexible(true)
        .from_writer(output);

    // Write headers (if any)
    if let Some(headers) = reader.headers()?.clone().into_byte_record().ok() {
        writer.write_record(&headers)?;
    }

    // Process each record
    for result in reader.records() {
        let record = result?;
        let mut new_record: Vec<String> = Vec::new();

        // Calculate the penultimate column index
        let num_columns = record.len();
        let penultimate_index = if num_columns >= 2 {
            num_columns - 2
        } else {
            // If there are fewer than 2 columns, just pass through
            for field in record.iter() {
                new_record.push(field.to_string());
            }
            writer.write_record(&new_record)?;
            continue;
        };

        // Process each field
        for (i, field) in record.iter().enumerate() {
            if i == penultimate_index {
                // Strip currency symbol and convert to float
                let cleaned = field
                    .trim()
                    .strip_prefix(currency_symbol)
                    .unwrap_or(field.trim())
                    .to_string();

