                    format!("Failed to parse '{}' as float after stripping '{}'", cleaned, currency_symbol)
                })?;

                new_record.push(cleaned);
            } else {
                new_record.push(field.to_string());
            }
        }

        writer.write_record(&new_record)?;
    }

    writer.flush()?;
    Ok(())
