```rust
use polars::prelude::*;
use std::collections::HashSet;

/// Unpivot (melt) the columns in `lst0` from `df0`.
/// - `var0` is the output column name that will hold the original column names (variable column).
/// - `var1` is the output column name that will hold the values.
///
/// Returns a new DataFrame in "long" format.
///
/// Example:
/// let df = df![
///     "id" => [1, 2],
///     "a" => [10, 20],
///     "b" => [100, 200]
/// ]?;
/// let long = unpivot_columns(&df, &["a", "b"], "var0", "var1")?;
pub fn unpivot_columns(
    df0: &DataFrame,
    lst0: &[&str],
    var0: &str,
    var1: &str,
) -> PolarsResult<DataFrame> {
    // If nothing to unpivot, return a clone of the input
    if lst0.is_empty() {
        return Ok(df0.clone());
    }

    // Validate that all requested columns exist
    for &col in lst0 {
        if df0.find_idx_by_name(col).is_none() {
            return Err(PolarsError::NotFound(format!(
                "column '{}' not found in dataframe",
                col
            )));
        }
    }

    // Compute id_vars = all columns in df0 that are NOT in lst0
    let all_cols = df0.get_column_names();
    let value_set: HashSet<&str> = lst0.iter().copied().collect();
    let id_vars: Vec<&str> = all_cols
        .iter()
        .map(|s| s.as_str())
        .filter(|name| !value_set.contains(*name))
        .collect();

    // Use Polars' melt to perform the unpivot
    df0.melt(&id_vars, lst0, var0, var1)
}

#[cfg(test)]
mod tests {
    use super::*;
    use polars::df;

    #[test]
    fn test_unpivot_columns() -> PolarsResult<()> {
        let df = df![
            "id" => [1, 2],
            "a" => [10, 20],
            "b" => [100, 200]
        ]?;

        let long = unpivot_columns(&df, &["a", "b"], "variable", "value")?;
        // Expect 4 rows: id 1->(a,10),(b,100); id 2->(a,20),(b,200)
        assert_eq!(long.height(), 4);

        // Check resulting column names
        assert!(long.get_column_names().contains(&"variable".to_string()));
        assert!(long.get_column_names().contains(&"value".to_string()));
        Ok(())
    }
}
```

