    if col0.is_empty() {
        return Ok(data0);
    }

    // Build expressions for each column name
    let exprs: Vec<Expr> = col0.iter().map(|name| col(name)).collect();

    // Default to ascending for all columns; set to `true` to sort descending per column.
    let reverses = vec![false; exprs.len()];

    // Use the lazy API to perform a multi-column sort, then collect back to a DataFrame
    let sorted_df = data0
        .lazy()
        .sort_by_exprs(exprs, reverses, false)
        .collect()?;

    Ok(sorted_df)
