    flags: &[bool],
    true_values: &[T],
    false_values: &[T],
) -> Vec<T> {
    flags
        .iter()
        .zip_eq(true_values)
        .zip_eq(false_values)
        .map(|((flag, true_val), false_val)| {
            if *flag {
                true_val.clone()
            } else {
                false_val.clone()
            }
        })
        .collect()
}

fn main() {
    let flags = vec![true, false, true, false];
    let true_values = vec!["yes", "yes", "yes", "yes"];
    let false_values = vec!["no", "no", "no", "no"];

    let result = conditional_select(&flags, &true_values, &false_values);
    println!("{:?}", result);
    // Output: ["yes", "no", "yes", "no"]

    let flags = vec![true, false, true];
    let true_values = vec![10, 20, 30];
    let false_values = vec![1, 2, 3];

    let result = conditional_select(&flags, &true_values, &false_values);
