use indexmap::IndexMap;
use std::hash::Hash;

/// Assign an integer label to each unique element in `items`,
/// with labels reflecting the order elements first appear.
/// Returns (labels_per_item, map_from_item_to_label).
///
/// Example:
/// let data = vec!["a", "b", "a", "c"];
/// let (labels, map) = assign_labels(&data);
/// // labels == [0, 1, 0, 2]
/// // map: "a" -> 0, "b" -> 1, "c" -> 2
pub fn assign_labels<T: Eq + Hash + Clone>(items: &[T]) -> (Vec<usize>, IndexMap<T, usize>) {
    let mut map: IndexMap<T, usize> = IndexMap::new();
    let mut labels: Vec<usize> = Vec::with_capacity(items.len());

    for item in items {
        // If the item is already in the map, get its label.
        // Otherwise insert it with the next available label (current map length).
        let label = if let Some(&lbl) = map.get(item) {
            lbl
        } else {
            let lbl = map.len();
            map.insert(item.clone(), lbl);
            lbl
        };
        labels.push(label);
    }

    (labels, map)
}

