    let expr = when(cond(col0))
        .then(new_value)
        .otherwise(col(col0))
        .alias(col0);

    // DataFrame::lazy consumes the DataFrame; clone to preserve the original referenced by caller
    let updated = df.clone().lazy().with_column(expr).collect()?;
    *df = updated;
    Ok(())
}

