```rust
use polars::prelude::*;

fn replace_dataframe_values(
    mut df: DataFrame,
    col_name: &str,
    condition: impl Fn(&Series) -> PolarsResult<Series>,
    replacement_value: i64,
) -> PolarsResult<DataFrame> {
    // Get the column and apply the condition
    let column = df.column(col_name)?;
    let mask = condition(column)?;

    // Create a new series with replaced values
    let updated_series = column.zip_with(&mask, &Series::new("", &[replacement_value]))?;

    // Replace the column in the dataframe
    df.replace(col_name, updated_series)?;

    Ok(df)
}

// Example usage
fn main() -> PolarsResult<()> {
    // Create a sample dataframe
    let df = df! {
        "col0" => &[1, 5, 3, 8, 2, 9],
        "col1" => &["a", "b", "c", "d", "e", "f"],
    }?;

    println!("Original DataFrame:");
    println!("{}", df);

    // Replace values in col0 where value > 4 with 99
    let result = replace_dataframe_values(
        df,
        "col0",
        |series| {
            series.gt(4) // condition: value > 4
        },
        99, // replacement value
    )?;

    println!("\nModified DataFrame:");
    println!("{}", result);

    Ok(())
}
```

## Alternative: More Flexible Generic Version

```rust
use polars::prelude::*;

fn replace_where<T: PolarsDataType>(
    mut df: DataFrame,
    col_name: &str,
    condition: impl Fn(&ChunkedArray<T>) -> PolarsResult<BooleanChunked>,
    replacement: T::Native,
) -> PolarsResult<DataFrame>
where
    T::Native: Copy,
{
    let column = df.column(col_name)?;
    let typed_column = column.cast(&DataType::Int64)?;
    let ca = typed_column.i64()?;

    let mask = condition(ca)?;
    let updated = ca.zip_with(&mask, replacement)?;

    df.replace(col_name, updated.into_series())?;
    Ok(df)
}
