use polars::prelude::*;

/// Splits the first column (`str0`) of a DataFrame into two new columns (`str1` and `str2`)
/// at the first space character.
///
/// # Arguments
/// * `df` - The input DataFrame containing the column to split
/// * `input_col` - Name of the column to split (default: "str0")
/// * `output_col1` - Name of the first output column (default: "str1")
/// * `output_col2` - Name of the second output column (default: "str2")
///
/// # Returns
/// A new DataFrame with the split columns added
pub fn split_first_space(df: &DataFrame, input_col: &str, output_col1: &str, output_col2: &str) -> Result<DataFrame, PolarsError> {
    // Get the input column as a String type
    let str_col = df.column(input_col)?.utf8()?;

    // Split each string at the first space character
    let split_series = str_col
        .into_series()
        .str()
        .split(" ", 1) // Split at first space only
        .unwrap_or_else(|_| {
            // Handle case where split fails (shouldn't happen with valid UTF-8)
            Series::new(output_col1, str_col.clone())
        });

    // Extract the first part (before space) and second part (after space)
    let col1 = split_series.get(0).unwrap_or_else(|_| {
        // If split fails, use empty string
        Series::new(output_col1, str_col.clone())
    });

    let col2 = split_series.get(1).unwrap_or_else(|_| {
        // If split fails, use empty string
        Series::new(output_col2, str_col.clone())
    });

    // Create new DataFrame with original columns plus the new ones
    let mut new_df = df.clone();
    new_df.with_column(col1)?;
    new_df.with_column(col2)?;

    Ok(new_df)
}

