use polars::prelude::*;

fn split_first_space(df0: &DataFrame, src_col: &str, dst_col1: &str, dst_col2: &str) -> PolarsResult<DataFrame> {
    // Get utf8 view of the source column
    let utf8 = df0.column(src_col)?.utf8()?;

    // Prepare vectors to collect parts; Option<String> so we can represent nulls
    let mut part1: Vec<Option<String>> = Vec::with_capacity(utf8.len());
    let mut part2: Vec<Option<String>> = Vec::with_capacity(utf8.len());

    for opt_val in utf8.into_iter() {
        match opt_val {
            Some(s) => {
                if let Some(idx) = s.find(' ') {
                    // split at first space
                    part1.push(Some(s[..idx].to_string()));
                    // remainder after the space
                    part2.push(Some(s[idx + 1..].to_string()));
                } else {
                    // no space -> first part is whole string, second is null
                    part1.push(Some(s.to_string()));
                    part2.push(None);
                }
            }
            None => {
                // preserve nulls
                part1.push(None);
                part2.push(None);
            }
        }
    }

    // Create new Series for each part
    let s1 = Series::new(dst_col1, part1);
    let s2 = Series::new(dst_col2, part2);

    // Build a new DataFrame by cloning and appending columns
    let mut new_df = df0.clone();
    new_df.with_column(s1)?;
    new_df.with_column(s2)?;

    Ok(new_df)
}

fn main() -> PolarsResult<()> {
