use nalgebra::DMatrix;

/// Compute the element-wise mean across multiple 2D numeric tables.
///
/// `mats` must be non-empty and all matrices must have the same dimensions.
/// Returns an error string if validation fails.
///
/// Example:
/// let a = DMatrix::from_row_slice(2, 2, &[1.0, 2.0, 3.0, 4.0]);
/// let b = DMatrix::from_row_slice(2, 2, &[5.0, 6.0, 7.0, 8.0]);
/// let mean = mean_matrices(&[a, b]).unwrap();
/// // mean is [[3.0, 4.0], [5.0, 6.0]]
pub fn mean_matrices(mats: &[DMatrix<f64>]) -> Result<DMatrix<f64>, String> {
    if mats.is_empty() {
        return Err("input list is empty".to_string());
    }

    let rows = mats[0].nrows();
    let cols = mats[0].ncols();

    // Validate shapes
    for (idx, m) in mats.iter().enumerate() {
        if m.nrows() != rows || m.ncols() != cols {
            return Err(format!(
                "matrix at index {} has shape ({}, {}), expected ({}, {})",
                idx,
                m.nrows(),
                m.ncols(),
                rows,
                cols
            ));
        }
    }

    // Sum element-wise
    let mut sum = DMatrix::<f64>::zeros(rows, cols);
    for m in mats {
        for (s, v) in sum.iter_mut().zip(m.iter()) {
            *s += *v;
        }
    }

    // Divide by count to get mean
    let count = mats.len() as f64;
    for v in sum.iter_mut() {
        *v /= count;
    }

    Ok(sum)
}

fn main() {
