pub fn slice_columns(
    df0: &DataFrame,
    start_column0: usize,
    end_column0: usize,
) -> PolarsResult<DataFrame> {
    if start_column0 > end_column0 {
        return Err(PolarsError::ComputeError(
            "start_column0 must be <= end_column0".into(),
