/// // │ 4   ┆ 7   │
/// // │ 5   ┆ 8   │
/// // │ 6   ┆ 9   │
/// // └─────┴─────┘
/// ```
fn extract_column_slice(
    df: &DataFrame,
    start_column: &str,
    end_column: &str,
) -> Result<DataFrame, PolarsError> {
    // Get all column names
    let column_names: Vec<&str> = df.get_column_names();

    // Find the indices of start and end columns
    let start_idx = column_names
        .iter()
        .position(|&name| name == start_column)
        .ok_or_else(|| PolarsError::ColumnNotFound(
            format!("Column '{}' not found in DataFrame", start_column).into()
        ))?;

    let end_idx = column_names
        .iter()
        .position(|&name| name == end_column)
        .ok_or_else(|| PolarsError::ColumnNotFound(
            format!("Column '{}' not found in DataFrame", end_column).into()
        ))?;

    // Validate that start comes before end
    if start_idx > end_idx {
        return Err(PolarsError::ComputeError(
            format!("Start column '{}' (index {}) comes after end column '{}' (index {})",
                start_column, start_idx, end_column, end_idx).into()
        ));
    }

    // Extract the slice of column names
    let selected_columns: Vec<&str> = column_names[start_idx..=end_idx].to_vec();

