use itertools::{Itertools, MinMaxResult};

/// Return the smallest f64 from the second element of each tuple in `items`,
/// ignoring any entries that are NaN. Returns `None` if there are no valid (non-NaN)
/// values.
///
/// Example:
/// let data = [("a", 3.0), ("b", f64::NAN), ("c", 1.5)];
/// assert_eq!(smallest_second_value(&data), Some(1.5));
pub fn smallest_second_value<T>(items: &[(T, f64)]) -> Option<f64> {
    // Filter out NaNs, then compute min/max in one pass using itertools' minmax_by.
    match items
        .iter()
        .filter_map(|(_, v)| if v.is_nan() { None } else { Some(*v) })
        .minmax_by(|a, b| a.partial_cmp(b).unwrap()) // `unwrap()` is safe because we filtered NaN
    {
        MinMaxResult::NoElements => None,
        MinMaxResult::OneElement(x) => Some(x),
        MinMaxResult::MinMax(min, _max) => Some(min),
    }
}

fn main() {
    let data = [
        ("x", 3.0),
        ("y", f64::NAN),
        ("z", 2.7),
        ("w", f64::INFINITY),
        ("u", -1.0),
    ];

    match smallest_second_value(&data) {
        Some(v) => println!("Smallest non-NaN value: {}", v),
        None => println!("No non-NaN values found"),
    }
}
```

Notes:
- NaNs are explicitly filtered using is_nan(), so +inf and -inf are allowed as normal values.
- minmax_by is used from itertools to find min in a single pass; partial_cmp.unwrap() is safe here because all values compared are not NaN.

