use num_bigint::BigInt;
use num_traits::{Zero, FromPrimitive};

/// Combine elements of `nums` into one integer by summing each element multiplied
/// by 10^position (index) i.e. result = sum(nums[i] * 10^i).
///
/// Examples:
/// - [3, 2, 1] -> 3*10^0 + 2*10^1 + 1*10^2 = 123
/// - [12, 34]  -> 12*10^0 + 34*10^1 = 12 + 340 = 352
///
/// Handles negative elements as well. Uses BigInt to avoid overflow for large results.
fn combine_by_position(nums: &[i64]) -> BigInt {
    let ten = BigInt::from_i64(10).unwrap();
    nums.iter().enumerate().fold(BigInt::zero(), |acc, (i, &v)| {
        let power = ten.pow(i as u32);
        acc + BigInt::from_i64(v).unwrap() * power
    })
}

fn main() {
    // Examples
    let a = [3, 2, 1];
    let b = [12, 34];
    let c = [9, 9, 9, 9]; // 9999

    println!("combine({:?}) = {}", a, combine_by_position(&a)); // 123
    println!("combine({:?}) = {}", b, combine_by_position(&b)); // 352
    println!("combine({:?}) = {}", c, combine_by_position(&c)); // 9999
}
```

Notes:
