use polars::prelude::*;

/// Filter `df0` keeping only rows where the values in column `var0` are in `lst0`,
/// then reset the row index to 0..n-1 in a column named "index".
///
/// Assumes the values in `var0` are UTF-8 strings; `lst0` is any slice of &str.
/// Returns a new DataFrame or a Polars error.
///
/// Example:
/// let df = df!["var0" => &["a","b","c","a"], "x" => &[1,2,3,4]]?; 
/// let out = filter_rows_in_list_and_reset_index(&df, "var0", &["a","c"])?;
pub fn filter_rows_in_list_and_reset_index(
    df0: &DataFrame,
    var0: &str,
    lst0: &[&str],
) -> PolarsResult<DataFrame> {
    // Build a Series from the list of allowed values
    let allowed = Series::new("allowed", lst0);

    // Compute boolean mask: var0 IN allowed
    let mask = df0.column(var0)?.is_in(&allowed)?;

    // Filter rows
    let filtered = df0.filter(&mask)?;

    // If there is already an "index" column, drop it (mimic pandas reset_index(drop=True))
    let without_old_index = if filtered.column("index").is_ok() {
        filtered.drop("index")?
    } else {
        filtered
    };

    // Add a fresh row count column named "index" starting at 0
    let result = without_old_index.with_row_count("index", Some(0))?;

    Ok(result)
}

