/// # Returns
/// * `Result<DataFrame>` - The filtered DataFrame with reset index, or an error
///
/// # Example
/// ```rust
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "var0" => &["a", "b", "c", "a", "b"],
///     "other" => &[1, 2, 3, 4, 5]
/// ).unwrap();
/// 
/// let filtered = filter_rows_by_list(&df, "var0", &["a", "c"]).unwrap();
/// println!("{:?}", filtered);
/// // Output:
/// // shape: (3, 2)
/// // ┌──────┬───────┐
/// // │ var0 ┆ other │
/// // ╞══════╪═══════╡
/// // │ a    ┆ 1     │
/// // │ c    ┆ 3     │
/// // │ a    ┆ 4     │
/// // └──────┴───────┘
/// ```
pub fn filter_rows_by_list<T: AsRef<str>>(
    df0: &DataFrame,
    var0: &str,
    lst0: &[T],
) -> Result<DataFrame> {
    // Convert the list to a Series for comparison
    let filter_values = Series::new("filter_values", lst0.iter().map(|s| s.as_ref()).collect::<Vec<&str>>());

    // Filter the DataFrame using is_in operation
    let mask = df0
        .column(var0)?
        .str()?
        .is_in(&filter_values)
        .map_err(|e| PolarsError::ComputeError(format!("Filter failed: {}", e).into()))?;

    // Apply the filter and reset the index
    let filtered = df0.filter(&mask)?;
    let result = filtered.new_from_index(0, filtered.height())?;

    Ok(result)
}

// Alternative version that works with any data type (not just strings)
pub fn filter_rows_by_list_typed<T: PolarsDataType>(
    df0: &DataFrame,
    var0: &str,
    lst0: &[T::Native],
) -> Result<DataFrame>
where
    ChunkedArray<T>: IntoSeries,
{
    let filter_series = Series::new("filter_values", lst0);
    let mask = df0
        .column(var0)?
        .is_in(&filter_series)?;

    let filtered = df0.filter(&mask)?;
    let result = filtered.new_from_index(0, filtered.height())?;

    Ok(result)
}

