use polars::prelude::*;
use std::error::Error;

/// Groups rows by the specified column and sums all other numeric columns.
///
/// # Arguments
/// * `df` - Input DataFrame
/// * `group_by_col` - Name of the column to group by
///
/// # Returns
/// Result containing the aggregated DataFrame or an error
///
/// # Example
/// ```
/// use polars::prelude::*;
/// let df = df!(
///     "A" => &[1, 2, 3, 1, 2],
///     "B" => &[10.0, 20.0, 30.0, 40.0, 50.0],
///     "C" => &[100, 200, 300, 400, 500]
/// ).unwrap();
///
/// let result = group_and_sum(&df, "A").unwrap();
/// println!("{:?}", result);
/// ```
pub fn group_and_sum(df: &DataFrame, group_by_col: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Create a copy of the original DataFrame to avoid modifying it
    let mut df = df.clone();

    // Check if the group by column exists
    if !df.column(group_by_col).is_ok() {
        return Err(format!("Column '{}' not found", group_by_col).into());
    }

    // Get all numeric columns except the group by column
    let mut numeric_cols: Vec<String> = Vec::new();
    for col_name in df.get_column_names() {
        if col_name != group_by_col {
            if let Ok(col) = df.column(col_name) {
                if col.dtype().is_numeric() {
                    numeric_cols.push(col_name.to_string());
                }
            }
        }
    }

    if numeric_cols.is_empty() {
        return Err("No numeric columns found to aggregate".into());
    }

    // Create aggregation expressions
    let mut agg_exprs = Vec::new();
    for col in numeric_cols {
        agg_exprs.push(colars::expr::sum(col));
    }

    // Perform the aggregation
    let agg_df = df
        .lazy()
        .group_by([colars::expr::col(group_by_col)])
        .agg(agg_exprs)
        .collect()?;

    Ok(agg_df)
}

