    let mut to_drop: Vec<String> = Vec::new();

    for s in df.get_columns() {
        let name = s.name().to_string();
        let max_opt: Option<f64> = match s.dtype() {
            DataType::Int8 => s.i8().and_then(|ca| ca.max()).map(|v| v as f64),
            DataType::Int16 => s.i16().and_then(|ca| ca.max()).map(|v| v as f64),
            DataType::Int32 => s.i32().and_then(|ca| ca.max()).map(|v| v as f64),
            DataType::Int64 => s.i64().and_then(|ca| ca.max()).map(|v| v as f64),

