        .map(|s| s.to_string())
        .collect();

    // Identify columns to keep
    let columns_to_keep: Vec<String> = column_names
        .iter()
        .filter(|col_name| {
            // Get the column
            match df.column(col_name) {
                Ok(column) => {
                    // Try to find the maximum value
                    match column.max() {
                        Ok(max_val) => {
                            // Check if max is not greater than zero
                            match max_val {
                                AnyValue::Float64(Some(v)) => v <= 0.0,
                                AnyValue::Int64(Some(v)) => v <= 0,
                                AnyValue::Int32(Some(v)) => v <= 0,
                                AnyValue::UInt32(Some(v)) => v == 0,
                                AnyValue::UInt64(Some(v)) => v == 0,
                                AnyValue::Null => true,
                                _ => true,
                            }
                        }
                        Err(_) => true, // Keep column if max() fails
                    }
                }
                Err(_) => true, // Keep column if it can't be accessed
            }
        })
        .cloned()
        .collect();

    // Select only the columns to keep
    df.select(&columns_to_keep)
}

fn main() -> Result<()> {
