use polars::prelude::*;
use std::error::Error;

/// Groups a DataFrame by `var0`, applies `agg_function` to each group,
/// and returns the result as a 2D table (DataFrame).
///
/// # Arguments
/// * `df` - Input DataFrame containing the data to group
/// * `var0` - The column name to group by
/// * `agg_function` - A function that takes a Series and returns a Series of aggregated values
///
/// # Returns
/// A Result containing the aggregated DataFrame or an error
///
/// # Example
/// ```
/// use polars::prelude::*;
/// use std::error::Error;
///
/// fn main() -> Result<(), Box<dyn Error>> {
///     let df = df!(
///         "var0" => &[1, 1, 2, 2, 3],
///         "value" => &[10.0, 20.0, 15.0, 25.0, 30.0]
///     )?;
///
///     let result = group_and_aggregate(&df, "var0", |s| s.sum())?;
///     println!("{:?}", result);
///     Ok(())
/// }
/// ```
pub fn group_and_aggregate(
    df: &DataFrame,
    var0: &str,
    agg_function: impl Fn(Series) -> Series,
) -> Result<DataFrame, Box<dyn Error>> {
    // Group the DataFrame by var0
    let grouped = df.lazy()
        .group_by([var0])?
        .collect()?;

    // Apply the aggregation function to each group
    let mut aggregated = grouped.clone();

    // Get all non-group columns (assuming they're numeric for aggregation)
    let non_group_cols: Vec<String> = df
        .columns()
        .iter()
        .filter(|col| col != var0)
        .map(|col| col.to_string())
        .collect();

    // Apply aggregation to each non-group column
    for col in non_group_cols {
        let series = aggregated.column(col)?;
        let aggregated_series = agg_function(series);
        aggregated = aggregated.with_column(
            col.clone(),
            aggregated_series,
        )?;
    }

    Ok(aggregated)
}

// Example usage with a specific aggregation function
pub fn sum_aggregation(series: Series) -> Series {
    series.sum()
}

