Cargo.toml (add dependency)
- Add to your Cargo.toml:
  polars = "0.28"

Rust code:

use polars::prelude::*;
use std::sync::Arc;

/// Group df0 by `group_col`, aggregate `value_col` using `agg_function` (one of
/// "sum", "mean", "count", "min", "max", "median", "std"), then reshape the
/// resulting 1-D aggregated values into a 2-D table with `ncols` columns.
/// The result DataFrame has columns named "c0", "c1", ...
///
/// Returns a DataFrame of Float64 columns (with nulls for padding).
pub fn group_agg_to_table(
    df0: &DataFrame,
    group_col: &str,
    value_col: &str,
    agg_function: &str,
    ncols: usize,
) -> PolarsResult<DataFrame> {
    if ncols == 0 {
        return Err(PolarsError::ComputeError(
            "ncols must be >= 1".into(),
        ));
    }

    // Map user's agg_function string to a Polars Expr
    let agg_expr = match agg_function.to_lowercase().as_str() {
        "sum" => col(value_col).sum(),
        "mean" | "avg" => col(value_col).mean(),
        "count" => col(value_col).count(),
        "min" => col(value_col).min(),
        "max" => col(value_col).max(),
        "median" => col(value_col).median(),
        "std" | "stddev" => col(value_col).std(),
        other => {
            return Err(PolarsError::ComputeError(
                format!("unsupported agg_function: {}", other).into(),
            ))
        }
    }
    .alias("agg");

    // Perform groupby aggregation
    let grouped = df0
        .groupby([group_col])?
        .agg(&[agg_expr])?;

    // Extract the aggregated Series (named "agg")
    let agg_series = grouped.column("agg")?;

    // Cast to Float64 to make reshaping straightforward (count/int -> float)
    let agg_series = agg_series.cast(&DataType::Float64)?;
    let ca = agg_series.f64()?;

    // Collect aggregated values as Vec<Option<f64>>
    let values: Vec<Option<f64>> = ca.into_iter().map(|opt| opt.map(|v| v)).collect();
    let len = values.len();

    // Compute output row count for the 2D table (row-major fill)
    let nrows = (len + ncols - 1) / ncols;

    // Build columns c0..c{ncols-1}, each being Vec<Option<f64>> length nrows
    let mut cols: Vec<Series> = Vec::with_capacity(ncols);
    for col_idx in 0..ncols {
        let mut col_vals: Vec<Option<f64>> = Vec::with_capacity(nrows);
        for row_idx in 0..nrows {
            let idx = row_idx * ncols + col_idx;
            if idx < len {
                col_vals.push(values[idx]);
            } else {
                col_vals.push(None);
            }
        }
        cols.push(Series::new(&format!("c{}", col_idx), col_vals));
    }

    DataFrame::new(cols)
}

Example usage (conceptual):
- Suppose df0 has columns "group" and "value". To group by "group", compute the sum of "value" per group, then reshape those sums into 3 columns:

let result = group_agg_to_table(&df0, "group", "value", "sum", 3)?;

The returned DataFrame `result` will have columns c0, c1, c2 with Float64 data and nulls where needed.

