                    series.get(0).ok().and_then(|v| v.try_extract::<f64>().ok())
                } else {
                    None
                };
                pivot_data.get_mut(*col_name).unwrap().push(val);
            }
        }
    }

    // Step 6: Build the result DataFrame
    let mut result_columns: Vec<Series> = Vec::new();

    // Add the grouping column as the first column
    let group_series = Series::new(var0, unique_values);
    result_columns.push(group_series);

    // Add aggregated columns
    for col_name in &agg_columns {
        if let Some(values) = pivot_data.get(*col_name) {
            let series = Series::new(col_name, values.clone());
            result_columns.push(series);
        }
