    agg_function: &str,
    target_column: Option<&str>,
) -> PolarsResult<DataFrame> {
    let agg_expr = match target_column {
        Some(col) => {
            let col_expr = col(col);
            match agg_function.to_lowercase().as_str() {
                "sum" => col_expr.sum(),
                "mean" => col_expr.mean(),
