            // Aggregate all numeric columns
            match agg_function.to_lowercase().as_str() {
                "sum" => all().sum(),
                "mean" => all().mean(),
                "count" => all().count(),
                "min" => all().min(),
                "max" => all().max(),
                "std" => all().std(1),
                _ => return Err(PolarsError::ComputeError(
                    format!("Unknown aggregation function: {}", agg_function).into(),
                )),
