/// assert_eq!(result, Some((0.5, 1.0))); // (0+1)/2 = 0.5, (1+0+2)/3 = 1.0
/// ```
pub fn average_nonzero_indices(df0: &Array2<f64>) -> Option<(f64, f64)> {
    let mut row_sum = 0.0;
    let mut col_sum = 0.0;
    let mut count = 0u64;

    // Iterate over all elements with their indices
    for ((row, col), &value) in df0.indexed_iter() {
        if value != 0.0 {
            row_sum += row as f64;
            col_sum += col as f64;
            count += 1;
        }
    }

    if count == 0 {
        None
    } else {
        Some((row_sum / count as f64, col_sum / count as f64))
    }
}

