/// Replace all entries in column `col_name` of `df` that are equal to `cond` with `replacement`.
///
/// This function:
/// - casts the column to Utf8 if needed,
/// - compares values as strings,
/// - builds a new Utf8 column with replacements,
/// - replaces the column in-place in the DataFrame.
///
/// Parameters:
/// - df: mutable reference to the DataFrame to modify
/// - col_name: column to operate on
/// - cond: the string value to compare against (cond0)
/// - replacement: the string to use for matches (var1)
///
/// Returns:
/// - PolarsResult<()> — Ok(()) on success, an error otherwise.
pub fn replace_eq_in_column(
    df: &mut DataFrame,
    col_name: &str,
    cond: &str,
    replacement: &str,
) -> PolarsResult<()> {
    // Get the series (error if column not found)
    let s = df.column(col_name)?;
    // Ensure we are working with Utf8 data; cast if necessary
    let s_utf8_series = if s.dtype() == &DataType::Utf8 {
        s.clone()
    } else {
        s.cast(&DataType::Utf8)?
    };
    // Work with the Utf8Chunked representation
    let ca = s_utf8_series.utf8()?;
    // Map each option to either the replacement (if equals cond) or the original string.
    // We produce owned Strings to avoid lifetime issues.
    let iter = ca.into_iter().map(|opt| {
        opt.map(|v| {
            if v == cond {
                replacement.to_string()
            } else {
                v.to_string()
            }
        })
    });
    // Build a new Utf8Chunked from the iterator and convert to Series
    let new_col = Utf8Chunked::from_iter_options(col_name, iter).into_series();
    // Replace the column in the DataFrame
    df.replace(col_name, new_col)?;
    Ok(())
}

