Rust code:
```rust
use itertools::Itertools;

/// Given a nested sequence `x` (an outer iterable of inner iterables), returns
/// the inner sequence whose elements have the highest cumulative sum as a
/// Vec<f64>. Returns None if the outer sequence is empty.
///
/// Generic over any `I` (outer iterable), `J` (inner iterable) and element type `N`
/// that can be converted into f64 via `Into<f64>`.
///
/// Example:
/// let v = vec![vec![1.0, 2.0], vec![3.0], vec![1.5, 1.6]];
/// assert_eq!(max_inner_by_sum(v).unwrap(), vec![1.5, 1.6]);
fn max_inner_by_sum<I, J, N>(x: I) -> Option<Vec<f64>>
where
    I: IntoIterator<Item = J>,
    J: IntoIterator<Item = N>,
    N: Into<f64>,
{
    x.into_iter()
        // For each inner iterable, collect it into a Vec<f64> and compute its sum.
        .map(|inner| {
            let v: Vec<f64> = inner.into_iter().map(|n| n.into()).collect();
            let s: f64 = v.iter().copied().sum();
            (s, v)
        })
        // Choose the inner Vec with the maximum sum. We use partial_cmp to handle floats.
        .max_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal))
        .map(|(_s, v)| v)
}

fn main() {
    // Example usages
    let nested = vec![vec![1, 2, 3], vec![10], vec![4, 4]];
    let best = max_inner_by_sum(nested).unwrap();
    println!("Best inner sequence: {:?}", best); // prints [10]

    let nested_f = vec![vec![1.5, 2.5], vec![2.0, 3.0], vec![6.0]];
    println!("Best: {:?}", max_inner_by_sum(nested_f)); // Some([6.0]) or the equal-sum case
}
```

Notes:
- The function consumes the outer iterable and each inner iterable (it does not take references). If you want to work with borrowed slices and return a reference to one of the inner slices, change the signature to accept a slice like &[Vec<f64>] and return Option<&Vec<f64>>.
- Floating-point NaN values will make partial_cmp return None; in that case this implementation treats them as equal (so they won't beat a normal numeric sum). Adjust handling if you need a different NaN policy.

