            println!("Row means (rows {:?}, over cols {:?}): {:?}", row_indices, col_indices, row_means);
            println!("Col means (cols {:?}, over rows {:?}): {:?}", col_indices, row_indices, col_means);
        }
        Err(err) => {
            eprintln!("Error: {}", err);
        }
    }

    // Expected output:
    // Row means (rows [0, 2], over cols [1, 2]): [2.5, 8.5]
    // Col means (cols [1, 2], over rows [0, 2]): [5.0, 6.0]
}
