///
/// # Example
/// ```
/// use indexmap::IndexMap;
///
/// let lists = vec![
///     vec!["banana", "apple", "pear"],
///     vec!["orange", "grape", "kiwi"]
/// ];
/// let mapping = IndexMap::from([
///     ("apple", 1),
///     ("banana", 2),
///     ("pear", 3),
///     ("orange", 1),
///     ("grape", 2),
///     ("kiwi", 3)
/// ]);
///
/// let sorted = sort_lists_by_mapping(lists, &mapping);
/// assert_eq!(sorted[0], vec!["apple", "banana", "pear"]);
/// assert_eq!(sorted[1], vec!["orange", "grape", "kiwi"]);
/// ```
pub fn sort_lists_by_mapping<T, K>(lists: Vec<Vec<T>>, mapping: &IndexMap<T, usize>)
where
    T: Ord + Clone + std::hash::Hash + Eq,
