pub fn df0_to_map_by_var0(
    df0: &DataFrame,
    var0: &str,
) -> Result<HashMap<String, JsonMap<String, JsonValue>>, PolarsError> {
    // Ensure var0 exists
    let id_series = df0.column(var0).map_err(|_| {
        PolarsError::NotFound(format!("Identifier column '{}' not found in DataFrame", var0).into())
    })?;

    let mut out: HashMap<String, JsonMap<String, JsonValue>> = HashMap::with_capacity(df0.height());

    for idx in 0..df0.height() {
        // build key from identifier value (use its string form for non-text types)
        let id_av = id_series.get(idx);
        let key = match id_av {
            AnyValue::Utf8(s) => s.to_string(),
            AnyValue::Boolean(b) => b.to_string(),
            AnyValue::Int64(i) => i.to_string(),
            AnyValue::Int32(i) => i.to_string(),
            AnyValue::Int16(i) => i.to_string(),
            AnyValue::Int8(i) => i.to_string(),
            AnyValue::UInt64(u) => u.to_string(),
            AnyValue::UInt32(u) => u.to_string(),
            AnyValue::UInt16(u) => u.to_string(),
            AnyValue::UInt8(u) => u.to_string(),
            AnyValue::Float64(f) => f.to_string(),
            AnyValue::Float32(f) => f.to_string(),
            AnyValue::Null => "null".to_string(),
            other => other.to_string(), // fallback
        };

        if out.contains_key(&key) {
            return Err(PolarsError::ComputeError(
                format!("duplicate identifier '{}' found in column '{}'", key, var0).into(),
            ));
        }

        // build the row map: column name -> json value
        let mut row_map: JsonMap<String, JsonValue> = JsonMap::with_capacity(df0.width());
        for s in df0.get_columns() {
            let col_name = s.name().to_string();
            let av = s.get(idx);
            let jv = anyvalue_to_json(av);
            row_map.insert(col_name, jv);
        }

        out.insert(key, row_map);
    }

    Ok(out)
}

fn anyvalue_to_json(av: AnyValue) -> JsonValue {
    match av {
        AnyValue::Null => JsonValue::Null,
        AnyValue::Boolean(b) => JsonValue::Bool(b),
        AnyValue::Utf8(s) => JsonValue::String(s.to_string()),
        AnyValue::UInt8(u) => json!(u),
        AnyValue::UInt16(u) => json!(u),
        AnyValue::UInt32(u) => json!(u),
        AnyValue::UInt64(u) => json!(u),
        AnyValue::Int8(i) => json!(i),
        AnyValue::Int16(i) => json!(i),
        AnyValue::Int32(i) => json!(i),
        AnyValue::Int64(i) => json!(i),
        AnyValue::Float32(f) => json!(f),
        AnyValue::Float64(f) => json!(f),
        // Dates, times, datetimes, durations, lists, binary etc.:
        // fall back to string representation (safe general approach)
