    for (row_idx, row_id) in var0_col.iter().enumerate() {
        let mut row_data: HashMap<String, String> = HashMap::new();

        // Iterate through each column
        for col_name in df0.get_column_names() {
            let col = df0.column(col_name)?;

            // Convert column value to string representation
            let value = match col.dtype() {
                DataType::String => col
                    .str()?
