use polars::prelude::*;
use anyhow::Result;

/// For each distinct value of "var1" in `df0`, return the full row
/// where "var0" is maximal for that "var1".
///
/// If a group is empty this returns an error; if multiple rows tie for the
/// maximum, this returns the first occurrence within that group.
pub fn rows_with_max_var0_per_var1(df0: &DataFrame) -> PolarsResult<DataFrame> {
    // Group by "var1" and apply a function to each group's DataFrame:
    // find the index of the max in "var0" and slice out that single row.
    df0.groupby(&["var1"])?
        .apply(|group_df| {
            // get the series for "var0" and find its argmax (index within the group)
            let s = group_df.column("var0")?;
            let idx = s.arg_max().ok_or_else(|| {
                PolarsError::NoData("group has no rows (unexpected)".into())
            })?;
            // slice out the single row as a DataFrame and return it
            Ok(group_df.slice(idx as i64, 1))
        })
}

fn main() -> Result<()> {
