/// ```
pub fn group_max_row(df0: DataFrame) -> Result<DataFrame, Box<dyn Error>> {
    // Validate that required columns exist
    if !df0.column("var0").is_ok() || !df0.column("var1").is_ok() {
        return Err("DataFrame must contain columns 'var0' and 'var1'".into());
    }

    // Step 1: Find the index of the maximum var0 within each group
    let max_indices = df0
        .lazy()
        .group_by([col("var1")])
        .agg([
            // Get the index of the maximum value in var0 for each group
            col("var0").arg_max().alias("__max_idx"),
        ])
        .collect()?;

    // Step 2: Join back with original dataframe to get full rows
    // First, add a row index to the original dataframe
    let df_with_idx = df0
        .lazy()
        .with_row_index("__row_idx", None)
        .collect()?;

    // Step 3: Explode the max indices and join
    let result = max_indices
        .lazy()
        .explode([col("__max_idx")])
        .join(
            df_with_idx.lazy(),
            [col("__max_idx")],
            [col("__row_idx")],
            JoinArgs::new(JoinType::Inner),
        )
        .select([
            // Select all original columns (exclude our temporary columns)
            col("*").exclude(["__max_idx", "__row_idx"]),
        ])
        .collect()?;

    Ok(result)
}

// Alternative implementation using group_by_stable for deterministic ordering
pub fn group_max_row_stable(df0: DataFrame) -> Result<DataFrame, Box<dyn Error>> {
