```rust
/// Checks if a value lies between 4 and 10, inclusive.
/// 
/// # Arguments
/// * `value` - A numeric value to check
/// 
/// # Returns
/// * `true` if the value is between 4 and 10 (inclusive), `false` otherwise
fn is_between_4_and_10<T: PartialOrd + From<i32>>(value: T) -> bool {
    value >= T::from(4) && value <= T::from(10)
}

fn main() {
    // Test cases
    println!("3: {}", is_between_4_and_10(3));      // false
    println!("4: {}", is_between_4_and_10(4));      // true
    println!("7: {}", is_between_4_and_10(7));      // true
    println!("10: {}", is_between_4_and_10(10));    // true
    println!("11: {}", is_between_4_and_10(11));    // false

    // Works with floats too
    println!("4.5: {}", is_between_4_and_10(4.5));  // true
    println!("10.1: {}", is_between_4_and_10(10.1)); // false
}
```

