use unicode_segmentation::UnicodeSegmentation;

/// Return the portion of `s` that begins at grapheme index `start`
/// and spans up to `count` graphemes.
/// 
/// - If `start` is past the end of the string, returns an empty &str.
/// - If `count` extends past the end, returns as many graphemes as available.
/// - This returns a borrowed &str slice of the original input (no allocation).
pub fn slice_graphemes(s: &str, start: usize, count: usize) -> &str {
    if count == 0 {
        return "";
    }

    let mut start_byte: Option<usize> = None;
    let mut end_byte: usize = s.len();

    for (i, (byte_idx, _g)) in s.grapheme_indices(true).enumerate() {
        if i == start {
            start_byte = Some(byte_idx);
        }
        if i == start + count {
            end_byte = byte_idx;
            break;
        }
    }

    let sb = match start_byte {
        Some(b) => b,
        // start was past end -> return empty
        None => return "",
    };

    &s[sb..end_byte]
}

fn main() {
    let text = "a̐éö̲हλ😊"; // contains combining marks and an emoji
    // graphemes (visual characters) are:
    // ["a̐", "é", "ö̲", "ह", "λ", "😊"]

    assert_eq!(slice_graphemes(text, 0, 3), "a̐éö̲");
    assert_eq!(slice_graphemes(text, 3, 2), "हλ");
    assert_eq!(slice_graphemes(text, 5, 10), "😊"); // count extends past end -> truncated
    assert_eq!(slice_graphemes(text, 10, 1), ""); // start past end -> empty

    println!("All examples succeeded.");
}
```

Notes:
- This works on grapheme clusters (so diacritics and multi-codepoint emoji are treated as single "characters").
- The function returns a &str slice, so no allocation is performed; it borrows from the original string. If you prefer an owned String, wrap the result with .to_string().

