```rust
use unicode_width::UnicodeWidthStr;

/// Returns a substring starting at `start` position spanning `length` characters.
/// 
/// This function correctly handles multi-byte Unicode characters and grapheme clusters.
/// Positions are based on Unicode character boundaries, not byte indices.
///
/// # Arguments
/// * `text` - The input text to extract from
/// * `start` - The starting character position (0-based)
/// * `length` - The number of characters to extract
///
/// # Returns
/// * `Some(&str)` containing the extracted substring if valid
/// * `None` if the start position is out of bounds or length is invalid
///
/// # Examples
/// ```
/// use unicode_substring::extract_substring;
///
/// let text = "Hello, 世界!";
/// assert_eq!(extract_substring(text, 0, 5), Some("Hello"));
/// assert_eq!(extract_substring(text, 7, 2), Some("世界"));
/// assert_eq!(extract_substring(text, 10, 1), Some("!"));
/// assert_eq!(extract_substring(text, 20, 1), None);
/// ```
pub fn extract_substring(text: &str, start: usize, length: usize) -> Option<&str> {
    if length == 0 {
        return Some("");
    }

    // Get the total character count (not byte count)
    let char_count = text.chars().count();

    // Validate start position
    if start >= char_count {
        return None;
    }

    // Find the byte position for the start character
    let start_byte = text.char_indices()
        .nth(start)
        .map(|(pos, _)| pos)?;

    // Calculate end position (character-based)
    let end_char = start.checked_add(length)?;
    if end_char > char_count {
        return None;
    }

    // Find the byte position for the end character
    let end_byte = text.char_indices()
        .nth(end_char)
        .map(|(pos, _)| pos)
        .unwrap_or(text.len());

    // Return the substring slice
    Some(&text[start_byte..end_byte])
}

