use polars::prelude::*;
use std::f64;

fn normalize_columns(df0: &DataFrame) -> Result<DataFrame, PolarsError> {
    // Create a new empty DataFrame to store the normalized columns
    let mut normalized_df = DataFrame::new(vec![])?;

    // Iterate over each column in the input DataFrame
    for series in df0.get_columns() {
        // Convert the Series to a f64 type for normalization
        let mut float_series = series.cast(&DataType::Float64)?;

        // Get the minimum and maximum values of the column
        let min_value = float_series.f64().unwrap().min().unwrap_or(f64::NAN);
        let max_value = float_series.f64().unwrap().max().unwrap_or(f64::NAN);

        // Normalize the column if min and max are valid and not equal
        if !min_value.is_nan() && !max_value.is_nan() && min_value != max_value {
            float_series = float_series.apply(|value| (value - min_value) / (max_value - min_value));
        }

        // Add the normalized column to the new DataFrame
        normalized_df.with_column(float_series)?;
    }

    Ok(normalized_df)
}

fn main() -> Result<(), PolarsError> {
    // Example DataFrame
