```rust
use ndarray::{Array2, ArrayView2, Data, Ix2};
use std::f64;

/// Normalizes each column of a 2D array to [0, 1] range.
///
/// # Arguments
/// * `df` - Input 2D array (must contain numeric types)
///
/// # Returns
/// A new 2D array with each column normalized to [0, 1]
///
/// # Panics
/// Panics if the input contains non-numeric types or empty columns
pub fn normalize_columns<T>(df: &Array2<T>) -> Array2<f64>
where
    T: Data + Copy + Into<f64> + PartialOrd + PartialEq + std::fmt::Debug,
    f64: From<T>,
{
    let rows = df.nrows();
    let cols = df.ncols();

    // Create output array initialized to NaN
    let mut normalized = Array2::from_elem((rows, cols), f64::NAN);

    for col in 0..cols {
        // Extract column view
        let col_view: ArrayView2<T> = df.column(col);

        // Find min and max values
        let min_val = col_view.iter().fold(f64::INFINITY, |acc, &x| {
            let val: f64 = x.into();
            acc.min(val)
        });

        let max_val = col_view.iter().fold(f64::NEG_INFINITY, |acc, &x| {
            let val: f64 = x.into();
            acc.max(val)
        });

        // Handle constant columns (min == max)
        if min_val == max_val {
            // Set all values to 0.5 if constant (arbitrary choice)
            normalized.column_mut(col).fill(0.5);
        } else {
            // Normalize column
            for (i, &val) in col_view.iter().enumerate() {
                let normalized_val = (val.into() - min_val) / (max_val - min_val);
                normalized[[i, col]] = normalized_val;
            }
        }
    }

    normalized
}

