// anyhow = "1.0"

use polars::prelude::*;

/// Normalize each numeric column of df0 to range [0, 1].
/// Non-numeric columns are left unchanged.
///
/// Input:
/// - df0: reference to a DataFrame
/// Returns:
/// - PolarsResult<DataFrame> with normalized numeric columns
pub fn normalize_columns(df0: &DataFrame) -> PolarsResult<DataFrame> {
    let mut normalized_cols: Vec<Series> = Vec::with_capacity(df0.width());

    for s in df0.get_columns() {
        // If the column is numeric, cast to Float64 and normalize
        if s.dtype().is_numeric() {
            let s_f64 = s.cast(&DataType::Float64)?; // cast ints -> floats
            // Work with the Float64 ChunkedArray
            if let Ok(ca) = s_f64.f64() {
                let min_opt = ca.min();
                let max_opt = ca.max();

                let new_series = match (min_opt, max_opt) {
                    (Some(minv), Some(maxv)) => {
                        if (maxv - minv).abs() < std::f64::EPSILON {
                            // constant column -> zeros (preserve length and name)
                            Series::new(s.name(), vec![0.0_f64; s.len()])
                        } else {
                            // (ca - min) / (max - min)
                            let ca_norm = (ca - minv) / (maxv - minv);
                            ca_norm.into_series().rename(s.name())
                        }
                    }
                    // if min or max is None (e.g., all nulls), keep as float casted column
                    _ => s_f64.rename(s.name()),
                };

                normalized_cols.push(new_series);
                continue;
            } else {
                // unexpected: fallback to original column
                normalized_cols.push(s.clone());
                continue;
            }
        } else {
            // non-numeric: keep as-is
            normalized_cols.push(s.clone());
        }
    }

    DataFrame::new(normalized_cols)
}

