```rust
use polars::prelude::*;

fn normalize_columns(df: DataFrame) -> PolarsResult<DataFrame> {
    let mut normalized_df = df.clone();

    for col_name in df.get_column_names() {
        let series = df.column(col_name)?;

        // Skip non-numeric columns
        if !series.dtype().is_numeric() {
            continue;
        }

        // Convert to f64 for normalization
        let values = series.cast(&DataType::Float64)?;
        let ca = values.f64()?;

        // Find min and max
        let min_val = ca.min().unwrap_or(0.0);
        let max_val = ca.max().unwrap_or(1.0);
        let range = max_val - min_val;

        // Normalize: (x - min) / (max - min)
        let normalized = ca.apply(|x| {
            match x {
                Some(val) if range != 0.0 => Some((val - min_val) / range),
                Some(_) => Some(0.0),
                None => None,
            }
        });

        normalized_df.replace(col_name, normalized.into_series())?;
    }

    Ok(normalized_df)
}

fn main() -> PolarsResult<()> {
