fn extract_key_value_pairs_with_sequence<'a>(
    map: &'a IndexMap<String, String>,
    sequence: &str,
) -> IndexMap<String, String> {
    let filtered_pairs: IndexMap<String, String> = map
        .iter()
        .filter(|(key, _)| key.contains(sequence))
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect();

    filtered_pairs
}

