///     "col0" => &[vec![1, 2], vec![3, 4]]
/// )?;
///
/// let result = split_tuple_column(df, "col0", "A", "B")?;
/// println!("{:?}", result);
/// ```
pub fn split_tuple_column(
    df0: DataFrame,
    col0: &str,
    a: &str,
    b: &str,
) -> Result<DataFrame, Box<dyn Error>> {
    // Check if the column exists
    if !df0.column(col0).is_ok() {
