///
/// let df = df!(
///     "A" => &[1, 1, 2, 2, 3],
///     "B" => &["x", "x", "y", "y", "z"]
/// ).unwrap();
///
/// let result = remove_consecutive_duplicates(df);
/// assert_eq!(result.height(), 3);
/// ```
pub fn remove_consecutive_duplicates(df: DataFrame) -> Result<DataFrame, PolarsError> {
    // Create a boolean mask where True indicates rows to keep
    let mask = df.lazy()
        .with_column(
            lit(true).alias("keep_first")
        )
        .with_column(
            // Compare each row with the previous row
            df.lazy()
                .row(0..df.height())
                .with_column(
                    // Shift the entire row down by 1
                    df.lazy()
                        .row(1..df.height())
                        .select(df.columns())
                        .alias("prev_row")
                )
                .with_column(
                    // Compare current row with previous row
                    col("prev_row")
                        .eq(df.lazy().select(df.columns()))
                        .all()
                        .alias("is_duplicate")
                )
                .select([
                    col("keep_first"),
                    col("is_duplicate")
                ])
                .with_column(
                    // Keep first row (true) or only keep if not duplicate (not is_duplicate)
                    col("keep_first") & !col("is_duplicate").alias("keep")
                )
                .select([
