                .utf8()?
                .into_iter()
                .map(|s| s.parse::<bool>().unwrap())
                .collect::<Vec<_>>()
        )
        .filter(col("keep"))
        .collect()?;

    // Apply the mask to filter the original DataFrame
    Ok(df.filter(&mask)?)
