use polars::prelude::*;

/// Remove rows that are identical to the immediately previous row.
/// Keeps the first row of each run of consecutive duplicates.
///
/// Returns a new DataFrame with consecutive duplicate rows removed.
pub fn drop_consecutive_duplicate_rows(df: &DataFrame) -> PolarsResult<DataFrame> {
    let h = df.height();
    if h <= 1 {
        return Ok(df.clone());
    }

    // Collect indices of rows to keep
    let mut keep: Vec<u32> = Vec::with_capacity(h);
    // get_row returns Vec<AnyValue<'_>>
    let mut prev = df.get_row(0);
    keep.push(0);

    for i in 1..h {
        let row = df.get_row(i);
        if row != prev {
            keep.push(i as u32);
            prev = row;
        }
    }

    let idx = UInt32Chunked::from_vec("idx", keep);
    df.take(&idx)
}

