/// Compares two sequences element-wise and returns a vector of booleans
/// indicating whether elements at each index refer to the same object instance.
/// 
/// # Arguments
/// * `seq1` - First sequence of references
/// * `seq2` - Second sequence of references
/// 
/// # Returns
/// A vector of booleans where each position indicates if elements refer to
/// the same object instance (same memory address).
/// 
/// # Example
/// ```
/// let a = vec![Box::new(42), Box::new(43)];
/// let b = vec![Box::new(42), Box::new(43)];
/// let c = vec![&a[0], &a[1]];
/// let d = vec![&a[0], &b[1]];
/// let result = compare_identities(&c, &d);
/// assert_eq!(result, vec![true, false]);
/// ```
fn compare_identities<'a, T>(seq1: &[&'a T], seq2: &[&'a T]) -> Vec<bool> {
    use std::ptr;

    seq1.iter()
        .zip(seq2.iter())
        .map(|(a, b)| ptr::eq(*a, *b))
        .collect()
}

fn main() {
    // Example 1: Boxing heap values
    let box1 = Box::new(String::from("hello"));
    let box2 = Box::new(String::from("hello"));
    let box3 = &box1;

    let seq1: Vec<&String> = vec![&box1, &box2];
    let seq2: Vec<&String> = vec![box3, &box2];

    let result = compare_identities(&seq1, &seq2);
    println!("Example 1 - Same object comparison:");
    println!("  Result: {:?}", result);
    println!("  Expected: [true, true]\n");

    // Example 2: Different objects with same value
    let obj1 = vec![1, 2, 3];
    let obj2 = vec![1, 2, 3];
    let obj3 = &obj1;

    let seq1: Vec<&Vec<i32>> = vec![&obj1, &obj2];
    let seq2: Vec<&Vec<i32>> = vec![obj3, &obj2];

    let result = compare_identities(&seq1, &seq2);
    println!("Example 2 - Vector identity comparison:");
    println!("  Result: {:?}", result);
    println!("  Expected: [true, true]\n");

    // Example 3: Detecting actual different instances
    let x = Box::new(100);
    let y = Box::new(100);
    let z = &x;

    let seq1: Vec<&Box<i32>> = vec![&x, &y];
    let seq2: Vec<&Box<i32>> = vec![z, &y];

    let result = compare_identities(&seq1, &seq2);
    println!("Example 3 - Distinguishing different instances:");
    println!("  Result: {:?}", result);
    println!("  Expected: [true, true]");
    println!("  (y and y point to the same instance)\n");
}
```

## Key Features

1. **Library Used**: `std::ptr` - Standard library module for pointer operations (available in all Rust versions)
2. **Function Signature**: Generic over type `T`, accepts slices of references
3. **Core Logic**: Uses `std::ptr::eq()` to compare memory addresses (identity), not values (equality)
4. **Return Type**: `Vec<bool>` where each position indicates identity match

## How It Works

- `ptr::eq(*a, *b)` compares the actual memory addresses of the referenced objects
- Two references point to the same object if they have identical memory addresses
- This works with any type `T` and properly handles lifetimes with generics

## Important Notes

- This compares **object identity** (same memory location), not value equality
- Works with boxed values, vectors, strings, and any reference type
- Returns a vector matching the length of the shorter input sequence (via `zip`)

