use polars::prelude::*;

/// Divide each column in `columns_list` in-place in `df` by the column `column_name`.
/// Both numerator and denominator columns are cast to Float64 before division.
/// Returns a PolarsResult<()>; errors if any column does not exist or casting fails.
pub fn divide_columns_by_column(
    df: &mut DataFrame,
    columns_list: &[&str],
    column_name: &str,
) -> PolarsResult<()> {
    // Ensure denominator column exists
    if !df.get_column_names().contains(&column_name) {
        return Err(PolarsError::NotFound(
            format!("Denominator column '{}' not found", column_name).into(),
        ));
    }

    // Cast denominator to Float64 once
    let denom = df.column(column_name)?.cast(&DataType::Float64)?;

    for &col in columns_list {
        if !df.get_column_names().contains(&col) {
            return Err(PolarsError::NotFound(
                format!("Column '{}' not found", col).into(),
            ));
        }

        // Cast numerator to Float64 to ensure floating point division
        let numer = df.column(col)?.cast(&DataType::Float64)?;
        // Perform element-wise division (Series / Series -> Result<Series>)
        let divided = &numer / &denom?;
        // Replace the original column with the result
        df.replace(col, divided)?;
    }

    Ok(())
}

fn main() -> PolarsResult<()> {
