use itertools::Itertools;
use std::collections::HashMap;

/// Counts occurrences of tuples in a sequence with support for filtering, ordering, and limiting.
///
/// # Arguments
/// * `tuples` - A sequence of tuples to count
/// * `filter_fn` - Optional filter function (returns true to keep the tuple)
/// * `sort_by` - How to sort results: "count_asc", "count_desc", "key_asc", "key_desc", or "none"
/// * `limit` - Optional limit on number of results (None for unlimited)
///
/// # Example
/// ```
/// let tuples = vec![("a", 1), ("b", 2), ("a", 1), ("c", 3), ("a", 1)];
/// let result = count_tuples(
///     tuples,
///     Some(Box::new(|t| t.0 != "b")),
///     "count_desc",
///     Some(2)
/// );
/// // Returns: {("a", 1): 3, ("c", 3): 1}
/// ```
fn count_tuples<T: Eq + std::hash::Hash + Clone + std::fmt::Debug + Ord>(
    tuples: Vec<T>,
    filter_fn: Option<Box<dyn Fn(&T) -> bool>>,
    sort_by: &str,
    limit: Option<usize>,
) -> HashMap<T, usize> {
    // Count occurrences
    let mut counts: HashMap<T, usize> = HashMap::new();

    for tuple in tuples {
        // Apply filter if provided
        if let Some(ref filter) = filter_fn {
            if !filter(&tuple) {
                continue;
            }
        }

        *counts.entry(tuple).or_insert(0) += 1;
    }

    // Sort based on sort_by parameter
    let sorted: Vec<(T, usize)> = match sort_by {
        "count_asc" => counts
            .into_iter()
            .sorted_by_key(|(_, count)| *count)
            .collect(),
        "count_desc" => counts
            .into_iter()
            .sorted_by(|(_, a), (_, b)| b.cmp(a))
            .collect(),
        "key_asc" => counts
            .into_iter()
            .sorted_by(|(a, _), (b, _)| a.cmp(b))
            .collect(),
        "key_desc" => counts
            .into_iter()
            .sorted_by(|(a, _), (b, _)| b.cmp(a))
            .collect(),
        _ => counts.into_iter().collect(), // "none" or default
    };

    // Apply limit and convert back to HashMap
    sorted
        .into_iter()
        .take(limit.unwrap_or(usize::MAX))
        .collect()
}

fn main() {
    // Example 1: Basic counting
    let tuples = vec![
        ("a", 1),
        ("b", 2),
        ("a", 1),
        ("c", 3),
        ("a", 1),
        ("b", 2),
    ];

    println!("=== Example 1: Basic Counting ===");
    let result = count_tuples(tuples.clone(), None, "none", None);
    for (tuple, count) in &result {
