use polars::prelude::*;
use polars::df;

/// One-hot encode a column in a DataFrame.
///
/// This function creates a new DataFrame where each distinct value in the specified column
/// is expanded into its own binary indicator column.
///
/// # Arguments
///
/// * `df`: The input DataFrame.
/// * `column_name`: The name of the column to one-hot encode.
///
/// # Returns
///
/// A new DataFrame with one-hot encoded columns.
fn one_hot_encode(df: &DataFrame, column_name: &str) -> DataFrame {
    // Get the unique values in the column
    let unique_values = df.column(column_name).unwrap().unique().unwrap();

    // Create a new DataFrame with one-hot encoded columns
    let mut new_df = df.clone();
    for value in unique_values {
