            .unwrap()
            .eq(value)
            .unwrap()
            .cast(&DataType::Int64)
            .unwrap();
        new_df = new_df.with_column(new_column.rename(format!("{}_{}", column_name, value)));
    }

    // Drop the original column
    new_df = new_df.drop(column_name).unwrap();

    new_df
}

