pub fn expand_one_hot(df: &DataFrame, col_name: &str) -> PolarsResult<DataFrame> {
    // Get the column as Utf8Chunked (returns error if not utf8)
    let s = df.column(col_name)?;
    let utf8 = s.utf8()?;

    // Collect values as Option<&str>, preserving row order
    let vals: Vec<Option<&str>> = utf8.into_iter().collect();

    // Determine unique categories preserving first-seen order
    let mut seen: HashSet<String> = HashSet::new();
    let mut categories: Vec<String> = Vec::new();
    for opt in &vals {
        let key = match opt {
            Some(v) => v.to_string(),
            None => "<NULL>".to_string(),
        };
        if !seen.contains(&key) {
            seen.insert(key.clone());
            categories.push(key);
        }
    }

    // Build one Series per category with 1/0 integers
    let mut cols: Vec<Series> = Vec::with_capacity(categories.len());
    for cat in categories {
        let col_label = if cat == "<NULL>" {
            format!("{}_null", col_name)
        } else {
            // keep original value in column name; you may sanitize if needed
            format!("{}_{}", col_name, cat)
        };

        let mut indicator: Vec<i32> = Vec::with_capacity(vals.len());
        if cat == "<NULL>" {
            for v in &vals {
                indicator.push(if v.is_none() { 1 } else { 0 });
            }
        } else {
            for v in &vals {
                indicator.push(if v.map(|s| s == cat).unwrap_or(false) { 1 } else { 0 });
            }
        }

        cols.push(Series::new(&col_label, indicator));
    }

    DataFrame::new(cols)
}

