/// Items in A that don't appear in B are placed at the beginning.
/// 
/// # Arguments
/// * `a` - The list to be sorted (will be modified in place)
/// * `b` - The reference list defining the sort order (already sorted)
///
/// # Efficiency
/// O(n + m) time complexity where n = len(A), m = len(B)
/// O(m) additional memory for the index map
pub fn sort_by_order<T: Clone + Eq + std::hash::Hash>(a: &mut [T], b: &[T]) {
    // Build a lookup map from element to its position in B
    // Using IndexSet for O(1) lookups and maintaining insertion order
    let order_map: IndexSet<&T> = b.iter().collect();

    // Partition: move items not in B to the front
    let split_point = {
        let mut write_idx = 0;
        for read_idx in 0..a.len() {
            if !order_map.contains(&a[read_idx]) {
                a.swap(read_idx, write_idx);
                write_idx += 1;
            }
        }
        write_idx
    };

    // Sort the remaining items (those in B) according to B's order
    // We only need to sort the portion from split_point to end
    if split_point < a.len() {
        let in_b_slice = &mut a[split_point..];

        // Use a stable sort with a custom comparator based on B's order
        in_b_slice.sort_by(|x, y| {
            let x_pos = order_map.get_index_of(x).unwrap_or(usize::MAX);
            let y_pos = order_map.get_index_of(y).unwrap_or(usize::MAX);
            x_pos.cmp(&y_pos)
        });
    }
}

