        sort_by_order(&mut a, &b);
        // Items not in B (1, 4, 9, 6) should be at the beginning
        // Items in B (3, 5, 2) should be in B's order: 2, 3, 5
        assert_eq!(a, vec![1, 4, 9, 6, 2, 3, 5]);
