# Rust Function for Sorting A by Order in B

```rust
use indexmap::IndexMap;

/// Sorts list A according to the order defined in sorted list B.
/// Items in A not in B are placed at the beginning, maintaining their original order.
/// 
/// # Arguments
/// * `a` - The list to be sorted
/// * `b` - The sorted list defining the desired order
/// 
/// # Returns
/// A new vector with items from A sorted according to B's order
/// 
/// # Example
/// ```
/// let a = vec![3, 1, 4, 1, 5, 9, 2, 6];
/// let b = vec![1, 2, 3, 4, 5, 6, 7, 8, 9];
/// let result = sort_by_order(&a, &b);
/// assert_eq!(result, vec![1, 1, 2, 3, 4, 5, 6, 9]);
/// ```
fn sort_by_order<T: Clone + Eq + std::hash::Hash + std::fmt::Debug>(
    a: &[T],
    b: &[T],
) -> Vec<T> {
    // Create a map from B with position indices for O(1) lookup
    // This remains efficient even when B is very large
    let order_map: IndexMap<&T, usize> = b
        .iter()
        .enumerate()
        .map(|(idx, item)| (item, idx))
        .collect();

    let mut items_in_b = Vec::new();
    let mut items_not_in_b = Vec::new();

    // Partition items: those in B vs those not in B
    for item in a {
        if order_map.contains_key(item) {
            items_in_b.push(item.clone());
        } else {
            items_not_in_b.push(item.clone());
        }
    }

    // Sort items found in B according to their order in B
    items_in_b.sort_by_key(|item| {
        order_map
            .get(item)
            .copied()
            .unwrap_or(usize::MAX)
    });

    // Concatenate: items not in B first, then items in B order
    let mut result = items_not_in_b;
    result.extend(items_in_b);
    result
}

fn main() {
