use polars::prelude::*;

pub fn split_var0_into_two(df0: DataFrame) -> PolarsResult<DataFrame> {
    // If var0 doesn't exist, just return the input unchanged
    if !df0.get_column_names().iter().any(|s| s == "var0") {
        return Ok(df0);
    }

    // Inspect the column dtype
    let dtype = df0.column("var0")?.dtype().clone();

    match dtype {
        // If var0 is a Struct, unnest it (this expands struct fields as separate columns)
        DataType::Struct(_) => {
            // unnest returns a new DataFrame with the struct fields expanded.
            // It typically removes the original struct column and appends the field columns.
            let out = df0.unnest(&["var0"])?;
            Ok(out)
        }

        // If var0 is a List (e.g. each row is a list/tuple of length 2), extract element 0 and 1
        DataType::List(_) => {
            // Use expression API to create two new columns from the list elements.
            // col("var0").arr().get(lit(0)) extracts the first element of each list, likewise for index 1.
            let lf = df0.lazy().with_columns(vec![
                col("var0").arr().get(lit(0)).alias("var0_0"),
                col("var0").arr().get(lit(1)).alias("var0_1"),
            ]);

            let mut out = lf.collect()?;

            // Optionally drop the original var0 column if it still exists
            if out.find_idx_by_name("var0").is_some() {
                out.drop_in_place("var0")?;
            }

            Ok(out)
        }

        // Otherwise, it's not a tuple-like column we can split
        _ => Err(PolarsError::ComputeError(
            "column 'var0' must be a Struct or List of length-2 tuples".into(),
        )),
    }
}

