/// ).unwrap();
///
/// let sum = sum_filtered_column(&df, "C", "B").unwrap();
/// assert_eq!(sum, 40.0); // Sum of C where B is true (10 + 30)
/// ```
pub fn sum_filtered_column(df: &DataFrame, column: &str, condition: &str) -> Result<f64> {
    // Create a boolean mask based on the condition
    let mask = df.lazy()
        .filter(col(condition))
        .collect()?
        .column(condition)?
        .bool()?
        .into_iter()
        .collect::<Vec<_>>();

    // Apply the mask to the target column and sum
