        .f64()?
        .into_iter()
        .zip(mask.into_iter())
        .filter(|(_, &mask)| mask)
        .map(|(val, _)| val.unwrap_or(0.0)) // Handle NaN as 0
        .collect::<Vec<_>>();

    Ok(values.iter().sum())
}

