    let filtered_df = df.filter(
        &df.column(filter_column)?
            .equal(condition_value)?
    )?;

    // Get the column and calculate sum
    let sum = filtered_df
        .column(column_name)?
        .sum::<f64>()
        .ok_or_else(|| PolarsError::ComputeError("Failed to compute sum".into()))?;

    Ok(sum)
}

