fn create_sequences(input: Array1<i32>) -> Array2<i32> {
    let length = input.len();
    let mut seq1 = Array1::zeros(length);
    let mut seq2 = Array1::zeros(length);
    let mut seq3 = Array1::zeros(length);

    for i in 0..length {
        if i % 2 == 0 {
            // Even index, set to zero
            seq1[i] = 0;
            seq2[i] = 0;
            seq3[i] = 0;
