fn create_modified_sequences(input: &[i32]) -> Vec<Vec<i32>> {
    // Create three vectors to hold the modified sequences
    let mut seq_minus_1 = Vec::new();
    let mut seq_zero = Vec::new();
    let mut seq_plus_1 = Vec::new();

    // Iterate over the input sequence with indices
    for (index, &value) in input.iter().enumerate() {
        if index % 2 == 0 {
            // Even index: replace with zero
            seq_minus_1.push(0);
            seq_zero.push(0);
