use itertools::Itertools;

/// Create three new sequences from `input` by:
/// - For each delta in [1, 0, -1]:
///     - subtract delta from elements at odd positions (1-based: indices 0,2,4,...)
///     - set elements at even positions (1-based: indices 1,3,5,...) to zero
///
/// Returns a Vec of three Vec<i32> in the order [delta=1, delta=0, delta=-1].
///
/// Example:
/// let v = vec![10, 11, 12, 13];
/// let out = split_with_deltas(&v);
/// // out[0] = [9, 0, 11, 0]   (delta = 1)
/// // out[1] = [10, 0, 12, 0]  (delta = 0)
/// // out[2] = [11, 0, 13, 0]  (delta = -1)
pub fn split_with_deltas(input: &[i32]) -> Vec<Vec<i32>> {
    let deltas = [1, 0, -1];
    deltas
        .iter()
        .map(|&d| {
            input
                .iter()
                .enumerate()
                .map(|(idx, &val)| {
                    if idx % 2 == 0 {
                        val - d
                    } else {
                        0
                    }
                })
                .collect_vec()
        })
        .collect_vec()
}

