/// * `var0` - The key in the associative maps whose values should be used for sorting
/// 
/// # Returns
/// A new Vec<HashMap<String, Value>> sorted according to the order in lst1
pub fn sort_by_order(
    lst0: Vec<HashMap<String, Value>>,
    lst1: Vec<Value>,
    var0: &str,
) -> Vec<HashMap<String, Value>> {
    // Create a lookup map for the order of values in lst1
    let order_map: HashMap<&Value, usize> = lst1
        .iter()
        .enumerate()
        .map(|(index, value)| (value, index))
        .collect();

    // Separate items that are in lst1 from those that aren't
    let mut sorted_items: Vec<HashMap<String, Value>> = Vec::new();
    let mut unsorted_items: Vec<HashMap<String, Value>> = Vec::new();

    for item in lst0 {
        if let Some(value) = item.get(var0) {
            if order_map.contains_key(value) {
                sorted_items.push(item);
            } else {
                unsorted_items.push(item);
            }
        } else {
            unsorted_items.push(item);
        }
    }

    // Sort items that have a defined order using an inline closure
    sorted_items.sort_by(|a, b| {
        let key_a = a.get(var0).and_then(|v| order_map.get(v)).unwrap_or(&usize::MAX);
        let key_b = b.get(var0).and_then(|v| order_map.get(v)).unwrap_or(&usize::MAX);
        key_a.cmp(key_b)
    });

    // Append unsorted items at the end
    sorted_items.extend(unsorted_items);
    sorted_items
