```rust
use itertools::Itertools;

/// Converts multiple lists into a 2D table with given column headers.
///
/// # Arguments
/// * `rows` - A list of lists (each inner list must have the same length)
/// * `headers` - A list of column headers (must match the number of columns)
///
/// # Returns
/// A 2D table as a vector of strings, where each row is a formatted line
///
/// # Examples
/// ```
/// let rows = vec![
///     vec!["A", "B", "C"],
///     vec!["1", "2", "3"],
///     vec!["X", "Y", "Z"]
/// ];
/// let headers = vec!["Col1", "Col2", "Col3"];
/// let table = convert_to_table(rows, headers);
/// // Returns a table with headers and data rows
/// ```
fn convert_to_table<T: ToString>(rows: Vec<Vec<T>>, headers: Vec<&str>) -> Vec<String> {
    // Validate input
    if rows.is_empty() {
        return Vec::new();
    }

    let num_columns = headers.len();
    if num_columns == 0 {
        return Vec::new();
    }

    let row_length = rows[0].len();
    if row_length != num_columns {
        panic!("Number of columns in rows must match number of headers");
    }

    // Create header row
    let header_row = headers.iter()
        .map(|h| format!("{:<10}", h)) // Left-aligned with 10 char width
        .join(" | ")
        .trim_end_matches(" | ")
        .to_string();

    // Create data rows
    let data_rows: Vec<String> = rows.iter()
        .map(|row| {
            row.iter()
                .map(|val| format!("{:<10}", val.to_string()))
                .join(" | ")
                .trim_end_matches(" | ")
        })
        .collect();

    // Combine header and data
    let mut table = vec![header_row];
    table.extend(data_rows);

    table
}

#[cfg(test)]
