            vec!["1", "2", "3"],
            vec!["X", "Y", "Z"]
        ];
        let headers = vec!["Col1", "Col2", "Col3"];

        let table = convert_to_table(rows, headers);
        assert_eq!(table.len(), 4); // 1 header + 3 data rows
        assert!(table[0].contains("Col1 | Col2 | Col3"));
        assert!(table[1].contains("A | B | C"));
    }

