pub fn sort_by_numeric_value<S: AsRef<str>>(lst0: &[S]) -> Vec<String> {
    // Parse each element into a BigInt and keep the original string
    let mut pairs: Vec<(BigInt, String)> = lst0
        .iter()
        .map(|s| {
