/// Sorts a list of two-element items first by the value of the first element,
/// and for items with equal first elements, by the length of the second element.
///
/// # Arguments
/// * `items` - A mutable slice of tuples where the first element implements `Ord`
///   and the second element has a `.len()` method (like String, &str, Vec, etc.)
///
/// # Example
/// ```
/// use rayon::prelude::*;
///
/// let mut data = vec![
///     (3, "hello"),
///     (1, "world"),
///     (3, "hi"),
///     (2, "test"),
///     (1, "a"),
/// ];
///
