///     (1, "a"),
///     (1, "world"),
///     (2, "test"),
///     (3, "hi"),
///     (3, "hello"),
/// ]);
/// ```
pub fn sort_by_first_then_second_len<T, U>(items: &mut [(T, U)])
where
    T: Ord + Send,
    U: AsRef<str> + Send,
{
    items.par_sort_by(|a, b| {
        // First compare by the first element
        match a.0.cmp(&b.0) {
            // If equal, compare by length of the second element
            std::cmp::Ordering::Equal => {
                let len_a = a.1.as_ref().len();
                let len_b = b.1.as_ref().len();
                len_a.cmp(&len_b)
            }
            other => other,
        }
    });
}

