use polars::prelude::*;
use std::collections::HashMap;

fn combine_tables(table1: &DataFrame, table2: &DataFrame) -> HashMap<String, String> {
    // Ensure both DataFrames include the required columns
    let col0_1 = table1.column("col0").expect("col0 not found in table1");
    let var0 = table1.column("var0").expect("var0 not found in table1");
    let col0_2 = table2.column("col0").expect("col0 not found in table2");
    let var1 = table2.column("var1").expect("var1 not found in table2");

    let mut result = HashMap::new();

    // Create a hash map for the second table to facilitate fast lookups
    let mut table2_map = HashMap::new();
    for i in 0..table2.height() {
        let key = col0_2.get(i).unwrap().to_string();
        let value = var1.get(i).unwrap().to_string();
        table2_map.insert(key, value);
    }

    // Combine the tables based on the "col0" field
    for i in 0..table1.height() {
        let key = col0_1.get(i).unwrap().to_string();
