use serde_json::Value;

/// Extract the first element from every innermost subcollection within a nested collection `lst0`.
///
/// - `lst0` is expected to be a JSON value representing nested arrays (e.g. arrays of arrays ...).
/// - Returns a Vec<Value> containing a clone of the first element of each innermost array.
/// - An "innermost array" is an array whose elements are not themselves arrays.
///   Empty arrays are ignored.
///
/// Example:
///  Input (as JSON): [[["a","b"],["c"]], [["d","e"], ["f","g"]]]
///  Output: ["a","c","d","f"]
pub fn first_from_innermost(lst0: &Value) -> Vec<Value> {
    let mut out = Vec::new();
    fn collect(v: &Value, out: &mut Vec<Value>) {
        match v {
            Value::Array(arr) => {
                if arr.is_empty() {
                    // ignore empty arrays as they have no first element
                    return;
                }
                // If any element is an array, this is not innermost: recurse into elements.
                let has_array = arr.iter().any(|e| matches!(e, Value::Array(_)));
                if has_array {
                    for e in arr {
                        collect(e, out);
                    }
                } else {
                    // Innermost array: take its first element
                    out.push(arr[0].clone());
                }
            }
            _ => {
                // Non-array encountered at top level: ignore (task is about subcollections/arrays).
            }
        }
    }
    collect(lst0, &mut out);
    out
}

