/// assert_eq!(result, vec![Some(&1), Some(&4), Some(&6), Some(&7)]);
/// ```
pub fn extract_first_from_innermost<T: Clone>(lst0: &[Vec<Vec<T>>]) -> Vec<Option<T>> {
