    let frequency_counter = Counter::from_iter(input.iter().cloned());

    // Create a vector of tuples (element, frequency) and sort it by frequency in descending order
    let mut frequency_sorted: Vec<_> = frequency_counter.into_iter().collect();
    frequency_sorted.sort_by(|a, b| b.1.cmp(&a.1));

    // Create a queue for each unique element to retain the original order within the same frequency
    let mut element_queues: std::collections::HashMap<T, VecDeque<T>> = HashMap::new();
    for &item in input {
