use std::collections::HashMap;
use std::hash::Hash;
use std::cmp::Reverse;
use itertools::Itertools;

/// Reorders the elements by frequency (most frequent first), preserving all elements.
/// Elements with equal frequency preserve their original relative order.
///
/// Accepts any IntoIterator of clonable, hashable, comparable-for-equality items.
/// Returns a Vec<T> containing all original elements reordered by frequency.
fn reorder_by_frequency<T>(input: impl IntoIterator<Item = T>) -> Vec<T>
where
    T: Eq + Hash + Clone,
{
    let v: Vec<T> = input.into_iter().collect();

    // Build frequency map
    let mut freq: HashMap<T, usize> = HashMap::new();
    for item in &v {
        *freq.entry(item.clone()).or_default() += 1;
    }

    // Enumerate to capture original index; sort by (frequency desc, original index asc)
    v.into_iter()
        .enumerate()
        .sorted_by_key(|(idx, item)| {
            // Reverse to get highest frequency first; idx ensures stable original order for ties
            (Reverse(*freq.get(item).unwrap()), *idx)
        })
        .map(|(_, item)| item)
        .collect()
}

