use polars::prelude::*;
use std::collections::HashSet;

/// Counts distinct combinations of specified columns in a Polars DataFrame
///
/// # Arguments
/// * `df0` - The input DataFrame
/// * `lst0` - List of column names to consider for combinations
///
/// # Returns
/// Number of distinct combinations
///
/// # Example
/// ```
/// use polars::prelude::*;
/// let df = df!(
///     "a" => &[1, 2, 1, 3],
///     "b" => &["x", "y", "x", "z"],
///     "c" => &[true, false, true, false]
/// );
/// let combinations = count_distinct_combinations(&df, &["a", "b"]);
/// assert_eq!(combinations, 3);
/// ```
pub fn count_distinct_combinations(df0: &DataFrame, lst0: &[&str]) -> usize {
    // Select only the specified columns
    let selected_df = df0.clone().lazy().select(lst0).collect().unwrap();

    // Collect all rows as a vector of tuples
    let rows: Vec<_> = selected_df
        .rows()
        .into_iter()
        .map(|row| {
            lst0.iter()
                .map(|col_name| {
                    // Get the value for each column
                    let col = selected_df.column(col_name).unwrap();
                    col.get(row.index()).unwrap()
                })
                .collect::<Vec<_>>()
        })
        .collect();

    // Convert to a HashSet to count distinct combinations
    let mut distinct_combinations = HashSet::new();
    for row in rows {
        // Convert each row to a tuple of values for hashing
        let tuple = row.into_iter().map(|v| match v {
            Value::Int64(i) => *i,
            Value::Float64(f) => *f,
            Value::Boolean(b) => *b,
            Value::Utf8(s) => s.as_str(),
            _ => panic!("Unsupported value type for combination counting"),
        }).collect::<Vec<_>>();

        // Convert to a tuple for hashing
        let key = tuple.as_slice();
