```rust
use polars::prelude::*;

/// Supported comparison / string operators for filtering.
#[derive(Debug, Clone)]
pub enum Operator {
    Eq,
    Ne,
    Lt,
    Lte,
    Gt,
    Gte,
    Contains,     // string contains
    StartsWith,   // string starts with
    EndsWith,     // string ends with
    IsNull,
    IsNotNull,
}

/// Concrete filter value types we support
#[derive(Debug, Clone)]
pub enum FilterValue {
    Int(i64),
    Float(f64),
    Str(String),
    Bool(bool),
}

/// One filter condition: column name, operator, and optional value (value ignored for IsNull/IsNotNull)
#[derive(Debug, Clone)]
pub struct FilterCondition {
    pub column: String,
    pub operator: Operator,
    pub value: Option<FilterValue>,
}

/// Apply a series of filter conditions (var0) to rows of df0.
/// Conditions are combined with logical AND. Returns an error if a condition is invalid.
pub fn apply_filters(df0: &DataFrame, var0: &[FilterCondition]) -> PolarsResult<DataFrame> {
    if var0.is_empty() {
        // Nothing to filter; return a clone of the original DataFrame
        return Ok(df0.clone());
    }

    // Helper to build a literal Expr from FilterValue
    fn make_lit_expr(v: &FilterValue) -> Expr {
        match v {
            FilterValue::Int(i) => lit(*i),
            FilterValue::Float(f) => lit(*f),
            FilterValue::Str(s) => lit(s.clone()),
            FilterValue::Bool(b) => lit(*b),
        }
    }

    // Build a combined Expr by AND-ing all condition expressions
    let mut combined: Option<Expr> = None;

    for cond in var0 {
        let col_expr = col(cond.column.as_str());
        let expr = match cond.operator {
            Operator::Eq => {
                let v = cond.value.as_ref().ok_or_else(|| {
                    PolarsError::ComputeError("Eq operator requires a value".into())
                })?;
                col_expr.eq(make_lit_expr(v))
            }
            Operator::Ne => {
                let v = cond.value.as_ref().ok_or_else(|| {
                    PolarsError::ComputeError("Ne operator requires a value".into())
                })?;
                col_expr.neq(make_lit_expr(v))
            }
            Operator::Lt => {
                let v = cond.value.as_ref().ok_or_else(|| {
                    PolarsError::ComputeError("Lt operator requires a value".into())
                })?;
                col_expr.lt(make_lit_expr(v))
            }
            Operator::Lte => {
                let v = cond.value.as_ref().ok_or_else(|| {
                    PolarsError::ComputeError("Lte operator requires a value".into())
                })?;
                col_expr.lt_eq(make_lit_expr(v))
            }
            Operator::Gt => {
                let v = cond.value.as_ref().ok_or_else(|| {
                    PolarsError::ComputeError("Gt operator requires a value".into())
                })?;
                col_expr.gt(make_lit_expr(v))
            }
            Operator::Gte => {
                let v = cond.value.as_ref().ok_or_else(|| {
                    PolarsError::ComputeError("Gte operator requires a value".into())
                })?;
                col_expr.gt_eq(make_lit_expr(v))
            }
            Operator::Contains => {
                let v = cond.value.as_ref().ok_or_else(|| {
                    PolarsError::ComputeError("Contains operator requires a string value".into())
                })?;
                match v {
                    FilterValue::Str(s) => col_expr.str().contains(lit(s.clone())),
                    _ => {
                        return Err(PolarsError::ComputeError(
                            "Contains requires a string value".into(),
                        ))
                    }
                }
            }
            Operator::StartsWith => {
                let v = cond.value.as_ref().ok_or_else(|| {
                    PolarsError::ComputeError("StartsWith operator requires a string value".into())
                })?;
                match v {
                    FilterValue::Str(s) => col_expr.str().starts_with(lit(s.clone())),
                    _ => {
                        return Err(PolarsError::ComputeError(
                            "StartsWith requires a string value".into(),
                        ))
                    }
                }
            }
            Operator::EndsWith => {
                let v = cond.value.as_ref().ok_or_else(|| {
                    PolarsError::ComputeError("EndsWith operator requires a string value".into())
                })?;
                match v {
                    FilterValue::Str(s) => col_expr.str().ends_with(lit(s.clone())),
                    _ => {
                        return Err(PolarsError::ComputeError(
                            "EndsWith requires a string value".into(),
                        ))
                    }
                }
            }
            Operator::IsNull => col_expr.is_null(),
            Operator::IsNotNull => col_expr.is_not_null(),
        };

        combined = Some(if let Some(prev) = combined {
            prev.and(expr)
        } else {
            expr
        });
    }

    let filter_expr = combined.expect("there is at least one condition");
    // Use lazy filtering for performance and expressive expressions, then collect the result
    let lf = df0.clone().lazy().filter(filter_expr);
    lf.collect()
}

//////////////////////////////////////////////////////////
// Example usage:
//
// fn main() -> PolarsResult<()> {
//     use polars::prelude::*;
