use polars::prelude::*;
use std::collections::HashMap;

/// Apply a series of filter conditions to a DataFrame
/// 
/// # Arguments
/// * `df0` - The input DataFrame to filter
/// * `var0` - A vector of filter conditions, where each condition is a tuple of:
///   - column name (String)
///   - operator (String): "==", "!=", ">", ">=", "<", "<=", "contains", "starts_with", "ends_with"
///   - value (String): The value to compare against
/// 
/// # Returns
/// * Result containing the filtered DataFrame or an error
fn apply_filters(
    df0: &DataFrame,
    var0: Vec<(String, String, String)>,
) -> Result<DataFrame, PolarsError> {
    let mut filtered_df = df0.clone();

    for (column, operator, value) in var0 {
        // Create the filter expression based on the operator
        let expr = match operator.as_str() {
            "==" => col(&column).eq(lit(&value)),
            "!=" => col(&column).neq(lit(&value)),
            ">" => col(&column).gt(lit(&value)),
            ">=" => col(&column).gt_eq(lit(&value)),
            "<" => col(&column).lt(lit(&value)),
            "<=" => col(&column).lt_eq(lit(&value)),
            "contains" => col(&column).str().contains(lit(&value), false),
            "starts_with" => col(&column).str().starts_with(lit(&value)),
            "ends_with" => col(&column).str().ends_with(lit(&value)),
            _ => return Err(PolarsError::ComputeError(
                format!("Unsupported operator: {}", operator).into()
            )),
        };

        // Apply the filter
        filtered_df = filtered_df.filter(&expr)?;
    }

    Ok(filtered_df)
}

// Example usage
