```rust
use polars::prelude::*;

/// Applies a series of filter conditions to a DataFrame
/// 
/// # Arguments
/// * `df0` - The input DataFrame to filter
/// * `var0` - A vector of tuples containing (column_name, operator, value)
///           where operator is "eq", "gt", "lt", "gte", "lte", "neq"
///           and value is the comparison value as a string
///
/// # Returns
/// * `Result<DataFrame, PolarsError>` - Filtered DataFrame or error
fn apply_filters(
    df0: &DataFrame,
    var0: Vec<(&str, &str, &str)>,
) -> Result<DataFrame, PolarsError> {
    let mut result = df0.clone();

    for (column, operator, value) in var0 {
        let col = col(column);

        let mask = match operator {
            "eq" => col.eq(lit(value)),
            "neq" => col.neq(lit(value)),
            "gt" => col.gt(lit(value.parse::<f64>().unwrap_or(0.0))),
            "lt" => col.lt(lit(value.parse::<f64>().unwrap_or(0.0))),
