            "lte" => col.lt_eq(lit(value.parse::<f64>().unwrap_or(0.0))),
            _ => return Err(PolarsError::ComputeError("Unknown operator".into())),
        };

        result = result.filter(&mask)?;
    }

    Ok(result)
}

