///     vec![1.0, 2.0, 3.0, 4.0],
///     vec![5.0, 6.0, 7.0, 8.0],
/// ];
/// let labels = vec!["A", "B", "A", "C"];
/// let result = group_columns_and_sum(&data, &labels);
/// assert_eq!(result.get("A"), Some(&16.0)); // (1+3) + (5+7) = 16
/// assert_eq!(result.get("B"), Some(&8.0));  // 2 + 6 = 8
/// assert_eq!(result.get("C"), Some(&12.0)); // 4 + 8 = 12
/// ```
fn group_columns_and_sum(data: &[Vec<f64>], column_labels: &[&str]) -> HashMap<String, f64> {
    // Validate input dimensions
    if data.is_empty() || column_labels.is_empty() {
        return HashMap::new();
    }

    let num_cols = column_labels.len();
    for row in data {
        assert_eq!(row.len(), num_cols, "Each row must have the same number of columns as labels");
    }

    // Create a Polars DataFrame from the data
    let mut columns = Vec::with_capacity(num_cols);

    for (i, &label) in column_labels.iter().enumerate() {
        let col_data: Vec<f64> = data.iter().map(|row| row[i]).collect();
        columns.push(Series::new(label, col_data));
    }

    let df = DataFrame::new(columns).expect("Failed to create DataFrame");

    // Group by column names and sum
    let mut result: HashMap<String, f64> = HashMap::new();

    // Get unique column labels
    let unique_labels: Vec<&str> = {
        let mut seen = std::collections::HashSet::new();
        column_labels.iter().filter(|&l| seen.insert(l)).copied().collect()
    };

    for &label in &unique_labels {
        // Select all columns with this label
        let cols_with_label: Vec<&str> = column_labels
            .iter()
            .enumerate()
            .filter(|(_, &l)| l == label)
            .map(|(_, &l)| l)
            .collect();

        // Sum across selected columns
        let sum: f64 = cols_with_label
            .iter()
            .flat_map(|&col_name| {
                df.column(col_name)
                    .expect("Column should exist")
                    .f64()
                    .expect("Column should be f64")
                    .into_no_null_iter()
            })
            .sum();

        result.insert(label.to_string(), sum);
    }

    result
}

// Alternative implementation without Polars (pure Rust, no external dependencies)
fn group_columns_and_sum_pure(data: &[Vec<f64>], column_labels: &[&str]) -> HashMap<String, f64> {
