# Rust Function: Group and Sum Table Columns

```rust
use polars::prelude::*;

/// Groups columns of a 2D table by their labels and computes the sum of values in each group.
/// 
/// # Arguments
/// * `data` - A vector of vectors representing the table (each inner vec is a row)
/// * `column_labels` - Labels for each column
/// * `group_mapping` - A mapping of group names to their column indices
/// 
/// # Returns
/// A DataFrame with grouped sums
/// 
/// # Example
/// ```
/// let data = vec![
///     vec![1.0, 2.0, 3.0, 4.0],
///     vec![5.0, 6.0, 7.0, 8.0],
///     vec![9.0, 10.0, 11.0, 12.0],
/// ];
/// let column_labels = vec!["A", "B", "A", "B"];
/// let result = group_and_sum_columns(data, column_labels);
/// ```
fn group_and_sum_columns(
    data: Vec<Vec<f64>>,
    column_labels: Vec<&str>,
) -> Result<DataFrame, PolarsError> {
    use std::collections::BTreeMap;

    if data.is_empty() {
        return Err(PolarsError::ComputeError("Empty data".into()));
    }

    // Validate input consistency
    let num_cols = data[0].len();
    if column_labels.len() != num_cols {
        return Err(PolarsError::ComputeError(
            "Column labels length must match data width".into(),
        ));
    }

    // Group column indices by their labels
    let mut groups: BTreeMap<&str, Vec<usize>> = BTreeMap::new();
    for (idx, label) in column_labels.iter().enumerate() {
        groups.entry(label).or_insert_with(Vec::new).push(idx);
    }

    // Compute sums for each group across all rows
    let mut result_data: BTreeMap<&str, Vec<f64>> = BTreeMap::new();

    for (group_name, col_indices) in &groups {
        let mut group_sums = vec![0.0; data.len()];

        for row_idx in 0..data.len() {
            for col_idx in col_indices {
                group_sums[row_idx] += data[row_idx][*col_idx];
            }
        }

        result_data.insert(group_name, group_sums);
    }

    // Build the DataFrame
    let mut series_vec: Vec<Series> = Vec::new();

    for (group_name, sums) in result_data {
        let series = Series::new(group_name, sums);
        series_vec.push(series);
    }

    DataFrame::new(series_vec)
}

fn main() -> Result<(), PolarsError> {
    // Example usage
    let data = vec![
        vec![1.0, 2.0, 3.0, 4.0],
        vec![5.0, 6.0, 7.0, 8.0],
        vec![9.0, 10.0, 11.0, 12.0],
    ];

    let column_labels = vec!["Sales", "Profit", "Sales", "Profit"];

    let result = group_and_sum_columns(data, column_labels)?;

    println!("Original data grouped and summed by column label:");
    println!("{}", result);

    Ok(())
}
