use itertools::Itertools;

/// Sort items (each an inner collection with at least two elements) by their second element.
///
/// - `items`: any iterable of items implementing `AsRef<[T]>` (e.g. Vec<Vec<T>>, Vec<&[T]>, Vec<[T; N]>).
/// - Returns `Ok(Vec<C>)` sorted ascending by the second element, or `Err(String)` if any item has fewer than 2 elements.
///
/// T must implement `Ord + Clone` because the second element is used as the sort key and cloned.
///
/// Example:
/// let v = vec![vec![1, 5], vec![2, 3], vec![0, 4]];
/// let sorted = sort_by_second(v).unwrap();
/// assert_eq!(sorted, vec![vec![2,3], vec![0,4], vec![1,5]]);
pub fn sort_by_second<T, C, I>(items: I) -> Result<Vec<C>, String>
where
    I: IntoIterator<Item = C>,
    C: AsRef<[T]>,
    T: Ord + Clone,
{
    // Collect so we can both validate and sort
    let collected: Vec<C> = items.into_iter().collect();

    // Validate that every inner collection has at least two elements
    for (idx, item) in collected.iter().enumerate() {
        if item.as_ref().len() < 2 {
            return Err(format!("item at index {} has fewer than 2 elements", idx));
        }
    }

    // Sort by a clone of the second element
    let sorted: Vec<C> = collected
        .into_iter()
        .sorted_by_key(|c| c.as_ref()[1].clone())
        .collect();

    Ok(sorted)
}

