use itertools::Itertools;

/// Return the indices of the `n` largest values in `data`.
/// If `n` >= data.len(), returns all indices sorted by descending value.
///
/// Complexity: O(m log m) where m = data.len() (uses sorting).
///
/// Example:
/// let a = vec![3.0, 1.0, 4.0, 2.0];
/// assert_eq!(top_n_indices(&a, 2), vec![2, 0]); // indices of 4.0 and 3.0
pub fn top_n_indices<T: PartialOrd>(data: &[T], n: usize) -> Vec<usize> {
    data.iter()
        .enumerate()
        // sort by values descending; if partial_cmp returns None (e.g., NaN), treat as equal
        .sorted_by(|a, b| b.1.partial_cmp(a.1).unwrap_or(std::cmp::Ordering::Equal))
        .take(n.min(data.len()))
        .map(|(idx, _)| idx)
        .collect()
}

fn main() {
    let nums = vec![10, 3, 7, 14, 9];
    let top3 = top_n_indices(&nums, 3);
    println!("Top 3 indices: {:?}", top3); // e.g. [3, 0, 4] corresponds to values 14, 10, 9

    let floats = vec![std::f64::NAN, 1.0, 2.0, 2.0];
    // NaN is treated as incomparable and won't disrupt the ordering (treated equal here)
    println!("Top 2 indices (floats): {:?}", top_n_indices(&floats, 2));
}
```

