use serde_json::{json, Value};
use std::collections::HashSet;

/// Remove from `lst0` all mapping objects whose value for the key `var0`
/// appears among the values in `lst1`.
///
/// - lst0: a mutable Vec<Value> where each Value is expected to be a JSON object.
/// - var0: the key name to check inside each object in lst0.
/// - lst1: a slice of Values; if an object's value for `var0` serializes equal to any value in lst1,
///         that object is removed from lst0.
///
/// Objects in lst0 that do not have key `var0` are kept.
fn remove_objects_with_key_values(lst0: &mut Vec<Value>, var0: &str, lst1: &[Value]) {
    // Serialize lst1 values to strings and build a HashSet for fast lookup.
    // We serialize because serde_json::Value does not implement Hash.
    let forbidden: HashSet<String> = lst1
        .iter()
        .filter_map(|v| serde_json::to_string(v).ok())
        .collect();

    lst0.retain(|obj| {
        // Only consider objects; if not an object, keep it.
        match obj.get(var0) {
            Some(val) => match serde_json::to_string(val) {
                Ok(s) => !forbidden.contains(&s), // keep only if value not in lst1
                Err(_) => true,                   // if serialization fails, keep the object conservatively
            },
            None => true, // keep objects without the key
        }
    });
}

fn main() {
    // Example usage:
    let mut lst0 = vec![
        json!({"id": "a", "name": "Alice"}),
        json!({"id": "b", "name": "Bob"}),
        json!({"id": "c", "name": "Carol"}),
        json!({"name": "NoId"}), // has no id -> will be kept
