use itertools::Itertools;
use std::collections::HashSet;

/// Sum the products of every unique subset (by value) of size `k`.
///
/// - `values`: slice of i64 values
/// - `k`: size of each subset
///
/// Returns the sum as i128 to reduce overflow risk for moderate inputs.
///
/// Behavior:
/// - If k == 0, returns 1 (the product of an empty set).
/// - If k > values.len(), returns 0.
pub fn sum_unique_k_products(values: &[i64], k: usize) -> i128 {
    if k == 0 {
        return 1; // empty product
    }
    if k > values.len() {
        return 0;
    }

    let mut seen: HashSet<Vec<i64>> = HashSet::new();
    let mut total: i128 = 0;

    for comb in values.iter().copied().combinations(k) {
        // combinations() produces combinations in the order of `values`.
        // Use a HashSet to ensure we count each unique value-combination only once.
        if seen.insert(comb.clone()) {
            let prod: i128 = comb.into_iter().map(|v| v as i128).product();
            total += prod;
        }
    }

    total
}

fn main() {
