use itertools::Itertools;

/// Iterates over two sequences of 2-element tuples in parallel and appends
/// the element-wise sum of each tuple pair to a third sequence.
///
/// # Arguments
/// * `seq1` - First sequence of 2-element tuples
/// * `seq2` - Second sequence of 2-element tuples
/// * `result` - Mutable reference to a vector where results will be appended
///
/// # Example
/// ```
/// let seq1 = vec![(1, 2), (3, 4)];
/// let seq2 = vec![(5, 6), (7, 8)];
/// let mut result = Vec::new();
/// sum_tuples_parallel(&seq1, &seq2, &mut result);
/// assert_eq!(result, vec![(6, 8), (10, 12)]);
/// ```
fn sum_tuples_parallel(
    seq1: &[(i32, i32)],
    seq2: &[(i32, i32)],
    result: &mut Vec<(i32, i32)>,
) {
    // Use itertools' zip_longest to handle sequences of different lengths
    // (stops when the shorter sequence ends)
    for (a, b) in seq1.iter().zip_longest(seq2.iter()) {
        match (a, b) {
            (EitherOrBoth::Both(x, y), _) => {
                result.push((x.0 + y.0, x.1 + y.1));
            }
            // If one sequence is shorter, we stop (no partial sums)
            _ => break,
        }
    }
}

