/// ).unwrap();
///
/// let result = remove_zero_only_columns(&mut df);
/// assert_eq!(result.get_column_names(), vec!["A", "D"]);
/// ```
pub fn remove_zero_only_columns(df: &mut DataFrame) -> DataFrame {
    // Check if the DataFrame is empty
    if df.height() == 0 {
        return df.clone();
    }

    // Get column names
    let column_names = df.get_column_names();

    // Filter out columns that are all zeros
    let filtered_columns: Vec<_> = column_names
        .into_iter()
        .filter(|col_name| {
            let col = df.column(col_name).unwrap();
