            });

            // Check if all values are zero
            !series.iter().all(|x| x.is_none() || x.unwrap() == 0.0)
        })
        .collect();

    // Create a new DataFrame with only the non-zero columns
    df.select(&filtered_columns)
        .unwrap_or_else(|_| df.clone())
}
