/// - Columns with any nulls/NaNs are NOT considered "all zero" (they are kept).
/// - Non-numeric columns are kept unchanged.
///
/// Returns a new DataFrame with zero-only numeric columns removed.
pub fn drop_all_zero_columns(df: DataFrame) -> PolarsResult<DataFrame> {
    let mut keep: Vec<Series> = Vec::with_capacity(df.width());
    for s in df.get_columns() {
        match s.dtype() {
            // Integer/unsigned: cast to Int64 and test equality to 0
            DataType::Int8
            | DataType::Int16
            | DataType::Int32
            | DataType::Int64
            | DataType::UInt8
            | DataType::UInt16
            | DataType::UInt32
            | DataType::UInt64 => {
                let s_cast = s.cast(&DataType::Int64)?;
                if let Some(ca) = s_cast.i64() {
                    // ca.eq(0).all() returns Option<bool>; Some(true) only if every value is true and no nulls
                    if ca.eq(0).all().unwrap_or(false) {
                        // skip (drop) this column
                        continue;
                    }
                }
                keep.push(s.clone());
            }

            // Float: cast to Float64 and test equality to 0.0
            DataType::Float32 | DataType::Float64 => {
                let s_cast = s.cast(&DataType::Float64)?;
                if let Some(ca) = s_cast.f64() {
