///
/// # Arguments
/// * `lst0` - A collection of sublists (Vec<Vec<T>>) where each sublist has at least 4 elements
///
/// # Returns
/// A new `IndexMap` where the keys are the original indices and values are the sorted sublists
///
/// # Example
/// ```
/// let lst0 = vec![
///     vec![1, 2, 3, 5],
