    let mut indexed: IndexMap<usize, Vec<T>> = lst0
        .iter()
        .enumerate()
        .map(|(i, v)| (i, v.clone()))
        .collect();

    // Sort by the element at index 3
    indexed.values_mut()
        .sort_by(|a, b| a[3].cmp(&b[3]));

    indexed
