use indexmap::IndexMap;

fn assign_unique_integers<T: Eq + std::hash::Hash + Clone>(values: &[T]) -> Vec<usize> {
    let mut map = IndexMap::new();
    let mut result = Vec::with_capacity(values.len());

    for value in values {
        // If the value is not already in the map, insert it with the next available integer
        if !map.contains_key(value) {
            map.insert(value.clone(), map.len());
        }
        // Get the integer assigned to the value and push it to the result vector
        result.push(*map.get(value).unwrap());
    }

    result
}

fn main() {
    let values = vec!["apple", "banana", "apple", "orange", "banana", "grape"];
    let unique_integers = assign_unique_integers(&values);
    println!("{:?}", unique_integers); // Output: [0, 1, 0, 2, 1, 3]
}
