/// Assigns a unique integer to each distinct value in the order they first appear.
///
/// # Arguments
/// * `values` - A slice of values to process
///
/// # Returns
/// A vector of integers where each integer corresponds to the index of the first occurrence
/// of that value in the original list.
///
/// # Example
/// ```
/// let values = vec!["apple", "banana", "apple", "cherry", "banana"];
/// let result = assign_unique_ids(&values);
/// assert_eq!(result, vec![0, 1, 0, 2, 1]);
/// ```
pub fn assign_unique_ids<T: std::hash::Hash + Eq + Clone>(values: &[T]) -> Vec<usize> {
    let mut seen: IndexSet<T> = IndexSet::new();
    let mut result = Vec::with_capacity(values.len());

    for value in values {
        let (index, _) = seen.insert_full(value.clone());
        result.push(index);
    }

    result
}

