use polars::prelude::*;

/// Replace nulls in `target_col` with the corresponding values from `source_col`.
///
/// Returns a new DataFrame with `target_col` updated. Errors if columns are missing
/// or if the lazy plan fails to execute.
pub fn fill_missing_from(df: &DataFrame, target_col: &str, source_col: &str) -> PolarsResult<DataFrame> {
    // Validate column existence early for clearer error messages.
    if df.column(target_col).is_err() {
        return Err(PolarsError::NotFound(format!("target column '{}' not found", target_col).into()));
