    // Use a lazy expression: replace nulls in target_col with values from source_col
    let lazy = df.clone().lazy().with_column(
        col(target_col)
            .fill_null(col(source_col))
            .alias(target_col),
    );

    // Execute the lazy plan and collect the resulting DataFrame
    lazy.collect()
}

