// polars = { version = "0.31", features = ["temporal"] }
use polars::prelude::*;
use std::borrow::Cow;

/// Compute the sample Pearson correlation coefficient between columns "var0" and "var1"
/// in the given DataFrame `df0`.
///
/// Returns Ok(Some(r)) when the correlation is defined (at least 2 non-null paired values
/// and non-zero variance), Ok(None) when the result is undefined (too few pairs or zero
/// variance), or an Err if DataFrame column access / casts fail.
///
/// This uses an online (Welford) algorithm to compute mean, variance and covariance in one pass.
pub fn pearson_correlation_var0_var1(df0: &DataFrame) -> PolarsResult<Option<f64>> {
    // Extract columns and cast to Float64
    let s0 = df0.column("var0")?.cast(&DataType::Float64)?;
    let s1 = df0.column("var1")?.cast(&DataType::Float64)?;
    let ca0 = s0.f64().ok_or_else(|| PolarsError::ComputeError(Cow::from("failed to get var0 as f64")))?;
    let ca1 = s1.f64().ok_or_else(|| PolarsError::ComputeError(Cow::from("failed to get var1 as f64")))?;

    if ca0.len() != ca1.len() {
        return Err(PolarsError::ShapeMisMatch("var0 and var1 have different lengths".into()));
    }

    // Welford online algorithm for mean, variance and covariance
    let mut n: usize = 0;
    let mut mean_x = 0.0_f64;
    let mut mean_y = 0.0_f64;
    let mut c = 0.0_f64; // covariance accumulator * n-1
    let mut sx = 0.0_f64; // variance accumulator * n-1 for x
    let mut sy = 0.0_f64; // variance accumulator * n-1 for y

    for i in 0..ca0.len() {
        match (ca0.get(i), ca1.get(i)) {
            (Some(x), Some(y)) => {
                n += 1;
                let dx = x - mean_x;
                let dy = y - mean_y;
                let n_f = n as f64;
                mean_x += dx / n_f;
                mean_y += dy / n_f;
                // update accumulators using new means
                c += dx * (y - mean_y);
                sx += dx * (x - mean_x);
                sy += dy * (y - mean_y);
            }
            _ => {
                // skip pairs with any null
            }
        }
    }

    if n < 2 {
        return Ok(None);
    }

    let denom = (n - 1) as f64;
    let var_x = sx / denom;
    let var_y = sy / denom;

    // If either variance is zero (constant column), correlation is undefined
    if var_x == 0.0 || var_y == 0.0 {
        return Ok(None);
    }

    let cov = c / denom;
    let corr = cov / (var_x.sqrt() * var_y.sqrt());
    Ok(Some(corr))
}

