```rust
use serde_json::{Map, Value};
use ordered_float::OrderedFloat;

/// Sorts `items` in place by numeric "weight" ascending, breaking ties by numeric "factor" ascending.
///
/// Behavior notes:
/// - If "weight" or "factor" is missing or not a number, that field is treated as +infinity (so those items go last).
/// - Uses OrderedFloat to get a total ordering for f64 and sort_unstable_by_key for efficiency.
///
/// Example item shape:
///   { "name": "A", "weight": 1.5, "factor": 2.0 }
pub fn sort_items_by_weight_and_factor(items: &mut [Map<String, Value>]) {
    fn num_field(map: &Map<String, Value>, key: &str) -> OrderedFloat<f64> {
        map.get(key)
            .and_then(|v| v.as_f64())
            // treat missing / non-number / NaN as +infinity so they sort last
            .filter(|v| v.is_finite())
            .map(OrderedFloat)
            .unwrap_or_else(|| OrderedFloat(f64::INFINITY))
    }

    items.sort_unstable_by_key(|m| (num_field(m, "weight"), num_field(m, "factor")));
}

