            json!({"name": "a", "weight": 3, "factor": 1}).as_object().unwrap().clone(),
            json!({"name": "b", "weight": 1, "factor": 9}).as_object().unwrap().clone(),
            json!({"name": "c", "weight": 2, "factor": 2}).as_object().unwrap().clone(),
            json!({"name": "d", "weight": 1, "factor": 1}).as_object().unwrap().clone(),
