use indexmap::IndexMap;

/// Sorts a list of items (represented as IndexMaps with "weight" and "factor" fields)
/// in ascending numeric order by weight, breaking ties by factor.
///
/// # Arguments
/// * `items` - A vector of IndexMaps, each containing at minimum "weight" and "factor" keys
///
/// # Returns
/// A sorted vector of the same items
///
/// # Example
/// ```
/// use indexmap::IndexMap;
///
/// let mut item1 = IndexMap::new();
/// item1.insert("name", "item1");
/// item1.insert("weight", "10");
/// item1.insert("factor", "5");
///
/// let mut item2 = IndexMap::new();
/// item2.insert("name", "item2");
/// item2.insert("weight", "10");
/// item2.insert("factor", "3");
///
/// let mut item3 = IndexMap::new();
/// item3.insert("name", "item3");
/// item3.insert("weight", "5");
/// item3.insert("factor", "8");
///
/// let items = vec![item1, item2, item3];
/// let sorted = sort_by_weight_and_factor(items);
/// // Result: item3, item2, item1 (sorted by weight, then factor)
/// ```
fn sort_by_weight_and_factor(
    mut items: Vec<IndexMap<&str, &str>>,
) -> Vec<IndexMap<&str, &str>> {
    items.sort_by(|a, b| {
        let weight_a = a.get("weight")
            .and_then(|w| w.parse::<f64>().ok())
            .unwrap_or(f64::MAX);
        let weight_b = b.get("weight")
            .and_then(|w| w.parse::<f64>().ok())
            .unwrap_or(f64::MAX);

        match weight_a.partial_cmp(&weight_b).unwrap_or(std::cmp::Ordering::Equal) {
            std::cmp::Ordering::Equal => {
                let factor_a = a.get("factor")
                    .and_then(|f| f.parse::<f64>().ok())
                    .unwrap_or(f64::MAX);
                let factor_b = b.get("factor")
                    .and_then(|f| f.parse::<f64>().ok())
                    .unwrap_or(f64::MAX);
                factor_a.partial_cmp(&factor_b).unwrap_or(std::cmp::Ordering::Equal)
            }
            other => other,
        }
    });
    items
}

fn main() {
    let mut item1 = IndexMap::new();
    item1.insert("id", "1");
    item1.insert("weight", "10");
    item1.insert("factor", "5");

    let mut item2 = IndexMap::new();
    item2.insert("id", "2");
    item2.insert("weight", "10");
    item2.insert("factor", "3");

    let mut item3 = IndexMap::new();
    item3.insert("id", "3");
    item3.insert("weight", "5");
    item3.insert("factor", "8");

    let items = vec![item1, item2, item3];
    let sorted = sort_by_weight_and_factor(items);

    for item in sorted {
        println!("id: {}, weight: {}, factor: {}",
                 item.get("id").unwrap_or(&"N/A"),
                 item.get("weight").unwrap_or(&"N/A"),
                 item.get("factor").unwrap_or(&"N/A"));
    }
    // Output:
