    fn parse_date_flexible(s: &str) -> Option<NaiveDate> {
        let fmts = &[
            "%Y-%m-%d",
            "%Y/%m/%d",
            "%d-%m-%Y",
            "%d/%m/%Y",
            // ISO-like datetimes without timezone (will take date part)
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%dT%H:%M:%S",
            "%+",
        ];
        for fmt in fmts {
            if let Ok(d) = NaiveDate::parse_from_str(s, fmt) {
                return Some(d);
            }
        }
        // As a last resort try to parse just the leading YYYY-MM-DD if the string contains a 'T'
        if let Some(idx) = s.find('T') {
            if let Ok(d) = NaiveDate::parse_from_str(&s[..idx], "%Y-%m-%d") {
                return Some(d);
            }
        }
        None
    }

