            let ca = col.utf8()?;
            let epoch = NaiveDate::from_ymd_opt(1970, 1, 1).expect("valid epoch");
            let mut v: Vec<Option<i32>> = Vec::with_capacity(ca.len());
            for opt in ca.into_iter() {
                match opt {
                    Some(s) => match parse_date_flexible(s) {
                        Some(d) => {
                            let days = (d - epoch).num_days() as i32;
                            v.push(Some(days));
