use polars::prelude::*;
use std::error::Error;

/// Replaces missing values (NaN) in a 2D numeric dataset with the mean of their respective column.
///
/// # Arguments
/// * `data` - A 2D vector of f64 values, where None represents missing data
///
/// # Returns
/// * A 2D vector with missing values replaced by column means
///
/// # Example
/// ```
/// use your_crate::fill_missing_with_column_mean;
///
/// let data = vec![
///     vec![Some(1.0), Some(2.0), None],
///     vec![Some(4.0), None, Some(6.0)],
///     vec![Some(7.0), Some(8.0), Some(9.0)],
/// ];
///
/// let result = fill_missing_with_column_mean(&data).unwrap();
/// assert_eq!(result[0][2], 7.5); // (6.0 + 9.0) / 2 = 7.5
/// ```
pub fn fill_missing_with_column_mean(
    data: &[Vec<Option<f64>>],
) -> Result<Vec<Vec<f64>>, Box<dyn Error>> {
    if data.is_empty() || data[0].is_empty() {
        return Ok(vec![]);
    }

    // Convert to Polars DataFrame
    let num_cols = data[0].len();
    let mut series_vec: Vec<Series> = Vec::with_capacity(num_cols);

    for col_idx in 0..num_cols {
        let col_data: Vec<f64> = data
            .iter()
            .map(|row| row[col_idx].unwrap_or(f64::NAN))
            .collect();
        series_vec.push(Series::new(&format!("col_{}", col_idx), &col_data));
    }

    let df = DataFrame::new(series_vec)?;

    // Fill NaN values with column means
    let filled_df = df
        .lazy()
        .fill_null(FillNullStrategy::Mean)
        .collect()?;

    // Convert back to 2D vector
    let mut result = Vec::with_capacity(data.len());
    for row_idx in 0..data.len() {
        let mut row = Vec::with_capacity(num_cols);
        for col_idx in 0..num_cols {
            let series = filled_df.column(&format!("col_{}", col_idx))?;
            let value = series.f64()?.get(row_idx).unwrap_or(f64::NAN);
            row.push(value);
        }
        result.push(row);
    }

    Ok(result)
}

