use std::hash::Hash;
use indexmap::IndexMap;

/// Reorder `lst0` in-place so items follow the order given by `lst1`.
///
/// - `lst0` is the sequence to reorder (e.g. Vec of tuples).
/// - `lst1` is the desired ordering (any IntoIterator of keys).
/// - `key_fn` extracts the key from an item of `lst0` that is compared to entries in `lst1`.
///
/// Items whose key does not appear in `lst1` are placed after the listed keys,
/// preserving their original relative order.
///
/// This uses IndexMap to build an ordering map and then performs a stable sort
/// by that order index.
pub fn reorder_by_key<T, K, I, F>(lst0: &mut Vec<T>, lst1: I, key_fn: F)
where
    K: Eq + Hash + Clone,
    I: IntoIterator<Item = K>,
    F: Fn(&T) -> K,
{
    // Map each key in lst1 to its index (first occurrence wins).
    let mut order: IndexMap<K, usize> = IndexMap::new();
    for (idx, key) in lst1.into_iter().enumerate() {
        order.entry(key).or_insert(idx);
    }

    // Use usize::MAX for keys not present so they go to the end.
    lst0.sort_by_key(|item| {
        order
            .get(&key_fn(item))
            .cloned()
            .unwrap_or(usize::MAX)
    });
}

fn main() {
