/// Rename DataFrame columns in `df0` according to mapping pairs in `lst0`.
///
/// - df0: mutable reference to a polars DataFrame.
/// - lst0: slice of (old_name, new_name) pairs. Both are owned Strings here, but you can easily adapt types.
///
/// Behavior:
/// - If an `old_name` does not exist in df0, it's skipped.
/// - If `new_name` already exists in df0, that mapping is skipped and a warning is printed.
pub fn rename_columns_in_df0(
    df0: &mut DataFrame,
    lst0: &[(String, String)],
) -> PolarsResult<()> {
    let current_names = df0.get_column_names();
    for (old, new) in lst0 {
        // only attempt to rename if the old column exists
        if current_names.iter().any(|c| c == old) {
            // if new name already exists, skip to avoid duplicate column names
            if current_names.iter().any(|c| c == new) {
                eprintln!(
                    "rename_columns_in_df0: target column name '{}' already exists, skipping rename of '{}'",
