use ndarray::Array1;

fn moving_average(lst0: &Vec<f64>, window_size: usize) -> Vec<f64> {
    if window_size == 0 || lst0.is_empty() {
        return vec![];
    }

    let n = lst0.len();
    let mut averages = Vec::with_capacity(n - window_size + 1);

    for i in 0..=n - window_size {
