```rust
use num::Float;

/// Compute the moving average of a numeric sequence.
///
/// # Arguments
///
/// * `lst0`: The input numeric sequence.
/// * `window_size`: The size of the moving average window.
///
/// # Returns
///
/// A vector of moving averages.
///
/// # Panics
///
/// If `window_size` is larger than the length of `lst0`.
pub fn moving_average<T: Float>(lst0: &[T], window_size: usize) -> Vec<T> {
    assert!(window_size <= lst0.len(), "Window size cannot be larger than the input sequence.");

    let mut moving_averages = Vec::new();
    for i in 0..lst0.len() - window_size + 1 {
        let window: &[T] = &lst0[i..i + window_size];
        let sum: T = window.iter().sum();
        let average = sum / T::from(window_size).unwrap();
        moving_averages.push(average);
    }

    moving_averages
}

