/// ]);
///
/// reorder_map_by_key(&mut map, "a", 1);
/// assert_eq!(map.keys().collect::<Vec<_>>(), vec!["c", "a", "b"]);
/// ```
pub fn reorder_map_by_key<K, V>(map: &mut IndexMap<K, V>, key: &K, target: &V)
where
    K: std::hash::Hash + Eq + Clone,
    V: PartialEq,
{
    // Split the map into two parts: matching and non-matching
    let (matching, non_matching): (Vec<_>, Vec<_>) = map
        .iter()
        .partition(|(k, v)| {
