                existing_val == target
            } else {
                false
            }
        });

    // Clear the original map and reinsert the matching entries first
    map.clear();
    for (k, v) in matching {
        map.insert(k.clone(), v);
    }
    for (k, v) in non_matching {
        map.insert(k.clone(), v);
    }
}

