use std::collections::HashMap;
use itertools::Itertools;
use itertools::Either::{Left, Right};

/// Reorder `lst0` in-place: keep all maps where map[var0] == var1 at the front
/// (in their original order) and move all others to the end (also preserving order).
///
/// - lst0: mutable vector of HashMap<String, String>
/// - var0: key to check in each map
/// - var1: value to compare against
fn reorder_by_key_value(
    lst0: &mut Vec<HashMap<String, String>>,
    var0: &str,
    var1: &str,
) {
    // Drain the vector and partition into two vectors using partition_map:
    // Left(..) are the maps to keep at front, Right(..) are moved to the end.
    let (keep, move_to_end): (Vec<_>, Vec<_>) = lst0
        .drain(..)
        .partition_map(|m| {
            if m.get(var0).map(|v| v == var1).unwrap_or(false) {
                Left(m)
            } else {
                Right(m)
            }
        });

    // Rebuild lst0: matching first, then non-matching
    lst0.extend(keep);
    lst0.extend(move_to_end);
}

fn main() {
    // Example usage
    let mut v: Vec<HashMap<String, String>> = Vec::new();

    let mut a = HashMap::new();
    a.insert("type".to_string(), "keep".to_string());
    a.insert("id".to_string(), "1".to_string());

    let mut b = HashMap::new();
    b.insert("type".to_string(), "move".to_string());
    b.insert("id".to_string(), "2".to_string());

    let mut c = HashMap::new();
    c.insert("type".to_string(), "keep".to_string());
    c.insert("id".to_string(), "3".to_string());

    v.push(a);
    v.push(b);
    v.push(c);

