use serde_json::Value;
use std::collections::HashMap;

/// Reorders elements in a list of JSON objects by moving items where
/// the value for a given key doesn't match a specified value to the end.
///
/// # Arguments
/// * `lst0` - A mutable reference to a vector of JSON objects (as serde_json::Value)
/// * `var0` - The key to check in each object
/// * `var1` - The expected value for the key
///
/// # Example
/// ```
/// use serde_json::json;
/// use std::collections::HashMap;
///
/// let mut data = vec![
///     json!({"name": "Alice", "active": true}),
///     json!({"name": "Bob", "active": false}),
///     json!({"name": "Charlie", "active": true}),
/// ];
///
/// reorder_by_key_value(&mut data, "active", &json!(true));
/// // Now: Alice, Charlie, Bob (active=true items first)
/// ```
pub fn reorder_by_key_value(lst0: &mut Vec<Value>, var0: &str, var1: &Value) {
    // Partition the list: matching items stay, non-matching go to end
    let mut matching = Vec::new();
    let mut non_matching = Vec::new();

    for item in lst0.drain(..) {
        match item.get(var0) {
            Some(value) if value == var1 => matching.push(item),
            _ => non_matching.push(item),
        }
    }

    // Rebuild the list with matching items first, then non-matching
    lst0.extend(matching);
    lst0.extend(non_matching);
}

// Alternative implementation using stable partition (more efficient for large lists)
pub fn reorder_by_key_value_stable(lst0: &mut Vec<Value>, var0: &str, var1: &Value) {
    // Use stable partition to maintain relative order within each group
    let split_point = lst0.iter().position(|item| {
        match item.get(var0) {
            Some(value) => value != var1,
            None => true,
        }
    }).unwrap_or(lst0.len());

    // Rotate the non-matching elements to the end
    lst0.rotate_left(split_point);
}

