Function code:

use polars::prelude::*;

/// Add a new column "max_value" to `df` where each row's value is the maximum across `cols`.
/// `cols` is a slice of column names to consider. Numeric columns are cast to Float64; nulls are ignored.
/// Returns the modified DataFrame or a Polars error.
/// Example:
/// let df = df! [ "a" => &[1, 2, 3], "b" => &[Some(4.0), None, Some(2.5)] ]?; 
/// let df2 = add_max_value_column(df, &["a", "b"])?;
pub fn add_max_value_column(mut df: DataFrame, cols: &[&str]) -> PolarsResult<DataFrame> {
    if cols.is_empty() {
        return Err(PolarsError::ComputeError(
            "cols list is empty; provide at least one column".into(),
        ));
    }

    // Collect the selected columns, cast to Float64, and store as owned ChunkedArray<Float64Type>
    let mut float_cols: Vec<ChunkedArray<Float64Type>> = Vec::with_capacity(cols.len());
    for &col_name in cols {
        // get a reference to the column (returns &Series)
        let s = df.column(col_name).map_err(|e| {
            PolarsError::NotFound(format!("column '{}' not found: {}", col_name, e).into())
        })?;
        // cast the series to Float64 (will convert ints -> floats, keep nulls)
        let s_f64 = s.cast(&DataType::Float64)?;
        // get the ChunkedArray reference and clone it to own it
        let ca = s_f64.f64().ok_or_else(|| {
            PolarsError::SchemaMisMatch("failed to convert column to Float64".into())
        })?;
        float_cols.push(ca.clone());
    }

    let height = df.height();
    // compute row-wise max (ignoring nulls)
    let mut max_vals: Vec<Option<f64>> = Vec::with_capacity(height);
    for row_idx in 0..height {
        let mut row_max: Option<f64> = None;
        for ca in &float_cols {
            if let Some(v) = ca.get(row_idx) {
                row_max = Some(match row_max {
                    None => v,
                    Some(curr) => if v > curr { v } else { curr },
                });
            }
        }
        max_vals.push(row_max);
    }

    // Build a Float64Chunked from the Option<f64> iterator and add it as a new column
    let max_ca = Float64Chunked::from_iter_options("max_value", max_vals.into_iter());
    df.with_column(max_ca.into_series())
}

Notes:
- If any of the specified columns are not present, the function returns an error.
- Non-numeric columns that cannot be cast to Float64 will cause a cast error.
- If you prefer a different behavior (e.g., treat missing columns as zeros or return 0 when all null), modify the loop accordingly.

