///     "a" => &[1, 2, 3],
///     "b" => &[4, 5, 6],
///     "c" => &[7, 8, 9]
/// ).unwrap();
///
/// let new_cols = HashMap::from([
///     ("d".to_string(), df!("d" => &[10, 11, 12]).unwrap()),
///     ("e".to_string(), df!("e" => &[13, 14, 15]).unwrap())
/// ]);
///
/// let result = concatenate_with_priority_order(base, new_cols, vec!["a", "d", "b", "e", "c"]);
/// ```
pub fn concatenate_with_priority_order(
    base_table: DataFrame,
    new_columns: HashMap<String, DataFrame>,
    priority_order: Vec<String>,
) -> Result<DataFrame, PolarsError> {
    // Verify all new columns have the same number of rows as the base table
    let base_row_count = base_table.height();
    for (_, df) in &new_columns {
        if df.height() != base_row_count {
            return Err(PolarsError::ComputeError(
                "New columns must have the same number of rows as the base table".to_string(),
            ));
        }
    }

    // Create a map of column names to their DataFrames (including base columns)
    let mut all_columns = HashMap::new();
    for col in base_table.column_names() {
        all_columns.insert(col.to_string(), base_table.column(col)?);
    }

    // Add new columns
    for (name, df) in new_columns {
        all_columns.insert(name, df.column(&name)?);
    }

    // Verify all priority columns exist
    for col in &priority_order {
        if !all_columns.contains_key(col) {
            return Err(PolarsError::ComputeError(format!(
                "Column '{}' not found in either base table or new columns",
                col
            )));
        }
    }

    // Create new DataFrame with columns in priority order
    let mut new_df = DataFrame::default();
    for col_name in priority_order {
        let col = all_columns.get(col_name).unwrap();
        new_df = new_df.with_column(col.clone());
    }

    Ok(new_df)
}

