/// * `base_df` - The base DataFrame to add columns to
/// * `new_df` - The DataFrame containing new columns to add
/// * `priority_columns` - Ordered list of column names that should appear first
///
/// # Returns
/// * `Result<DataFrame>` - The merged DataFrame with preserved column order
///
/// # Example
/// ```rust
/// use polars::prelude::*;
///
/// let base_df = df!(
///     "A" => &[1, 2, 3],
///     "B" => &[4, 5, 6],
///     "C" => &[7, 8, 9],
/// )?;
///
/// let new_df = df!(
///     "X" => &[10, 11, 12],
///     "Y" => &[13, 14, 15],
///     "Z" => &[16, 17, 18],
/// )?;
///
/// let result = preserve_column_order_concat(&base_df, &new_df, &["Y", "X"])?;
/// // Result columns: Y, X, A, B, C, Z
/// # Ok::<(), PolarsError>(())
/// ```
pub fn preserve_column_order_concat(
    base_df: &DataFrame,
    new_df: &DataFrame,
    priority_columns: &[&str],
) -> Result<DataFrame, PolarsError> {
    // Validate inputs
    if priority_columns.is_empty() {
        return Err(PolarsError::ComputeError(
            "Priority columns list cannot be empty".into(),
        ));
    }

    // Get all columns from both DataFrames
    let base_columns: Vec<&str> = base_df.get_column_names().into_iter().collect();
    let new_columns: Vec<&str> = new_df.get_column_names().into_iter().collect();

    // Validate that all priority columns exist in new_df
    for &col in priority_columns {
        if !new_columns.contains(&col) {
            return Err(PolarsError::ComputeError(
                format!("Priority column '{}' not found in new DataFrame", col).into(),
            ));
        }
    }

    // Create a set of priority columns for O(1) lookup
    let priority_set: std::collections::HashSet<&str> = 
        priority_columns.iter().cloned().collect();

    // Build the final column order
    let mut final_columns: Vec<&str> = Vec::with_capacity(
        base_columns.len() + new_columns.len()
    );

    // 1. Add priority columns in specified order
    for &col in priority_columns {
        final_columns.push(col);
    }

    // 2. Add remaining new columns (not in priority list) preserving their order
    for &col in &new_columns {
        if !priority_set.contains(col) {
            final_columns.push(col);
        }
    }

    // 3. Add base columns that aren't already included (preserving original order)
    for &col in &base_columns {
        if !final_columns.contains(&col) {
            final_columns.push(col);
        }
    }

    // Concatenate the DataFrames horizontally
    let mut merged_df = base_df.hstack(new_df)?;

    // Reorder columns according to our computed order
    merged_df = merged_df.select(final_columns)?;

    Ok(merged_df)
}

