use polars::prelude::*;

/// Given a DataFrame `df0` and a grouping column name `var0`,
/// produce a new DataFrame that represents the grouping as a hierarchical
/// (multi-level) index by adding two index columns:
///   - level_0: the group key (duplicate of var0)
///   - level_1: the original row number (row id)
///
/// The returned DataFrame has `level_0` and `level_1` as the first two columns.
/// This effectively represents a multi-level index in Polars (which does not have
/// a native MultiIndex type).
///
/// Example:
/// let out = group_to_multiindex(&df, "group_col")?;
pub fn group_to_multiindex(df0: &DataFrame, var0: &str) -> PolarsResult<DataFrame> {
    // Ensure the grouping column exists
    if df0.find_idx_by_name(var0).is_none() {
        return Err(PolarsError::NotFound(format!("column '{}' not found", var0).into()));
    }

    // 1) Add a row-number column (level_1) to preserve original row order/identity.
    //    with_row_count returns a new DataFrame.
    let df_with_rownum = df0.clone().with_row_count("level_1", Some(0usize))?;

    // 2) Duplicate the grouping column into level_0.
    //    We clone the Series for var0 and rename the clone to "level_0".
    let level0_series = df_with_rownum.column(var0)?.clone().rename("level_0");
    let df_with_levels = df_with_rownum.with_column(level0_series)?;

    // 3) Optionally drop the original grouping column `var0` to avoid duplication.
    //    If you prefer to keep it, comment out the next line.
    let df_clean = df_with_levels.drop(var0)?;

    // 4) Reorder columns to put level_0 and level_1 first.
    let mut order: Vec<String> = vec!["level_0".to_string(), "level_1".to_string()];
    for name in df_clean.get_column_names() {
        if name != "level_0" && name != "level_1" {
            order.push(name.clone());
        }
    }
    let order_refs: Vec<&str> = order.iter().map(|s| s.as_str()).collect();
    let result = df_clean.select(&order_refs)?;

    Ok(result)
}

