use polars::prelude::*;
use std::collections::HashMap;

/// Groups a DataFrame by a specified column and returns a new DataFrame with a hierarchical (multi-level) index.
/// 
/// # Arguments
/// * `df0` - The input DataFrame to be grouped
/// * `var0` - The name of the column to group by
/// 
/// # Returns
/// * `Result<DataFrame>` - A new DataFrame with a hierarchical index where:
///   - The first level is the grouped column values
///   - The second level is the original row index within each group
/// 
/// # Example
/// ```ignore
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "var0" => &["A", "B", "A", "B", "A"],
///     "value" => &[1, 2, 3, 4, 5],
///     "other" => &[10, 20, 30, 40, 50]
/// ).unwrap();
/// 
/// let result = group_by_hierarchical_index(df, "var0").unwrap();
/// println!("{:?}", result);
/// ```
pub fn group_by_hierarchical_index(df0: DataFrame, var0: &str) -> Result<DataFrame> {
    // Get the grouping column
    let group_col = df0.column(var0)?;

    // Create a mapping from group values to their indices
    let mut group_indices: HashMap<AnyValue, Vec<usize>> = HashMap::new();

    // Iterate through the grouping column and collect indices for each group
    for (idx, val) in group_col.iter().enumerate() {
        group_indices.entry(val.clone()).or_default().push(idx);
    }

    // Create the hierarchical index columns
    let mut group_values = Vec::new();
    let mut original_indices = Vec::new();

    // Sort groups by their first occurrence to maintain order
    let mut sorted_groups: Vec<_> = group_indices.into_iter().collect();
    sorted_groups.sort_by(|a, b| a.1[0].cmp(&b.1[0]));

    for (group_val, indices) in sorted_groups {
        for &idx in &indices {
            group_values.push(group_val.clone());
            original_indices.push(idx as u32);
        }
    }

    // Create the hierarchical index as a DataFrame
    let index_df = DataFrame::new(vec![
        Series::new("group", group_values),
        Series::new("original_index", original_indices),
    ])?;

    // Reorder the original DataFrame rows according to the grouped order
    let reordered_df = df0.take(
        &original_indices.iter().map(|&x| x as usize).collect::<Vec<_>>()
    )?;

    // Combine the index with the reordered data
    let result = index_df.hstack(&reordered_df)?;

    Ok(result)
}

