/// * `key` - The key in each record to sort by
/// * `order` - A sequence of values defining the desired order
///
/// # Returns
/// A new vector of records sorted according to the custom order
pub fn sort_by_custom_order(
    records: Vec<Map<String, Value>>,
    key: &str,
    order: Vec<Value>,
) -> Vec<Map<String, Value>> {
    // Create a mapping from each value in the order to its position
    let mut value_to_position = HashMap::new();
    for (position, value) in order.iter().enumerate() {
        value_to_position.insert(value.clone(), position);
    }

    // Sort the records using the custom order
    let mut sorted_records = records;
    sorted_records.sort_by(|a, b| {
        let a_value = a.get(key).unwrap_or(&Value::Null);
        let b_value = b.get(key).unwrap_or(&Value::Null);

