use ordered_float::OrderedFloat;
use serde_json::{Value, Map};
use std::collections::HashMap;

pub fn sort_numeric_by_custom_order(
    records: Vec<Map<String, Value>>,
    key: &str,
    order: Vec<f64>,
) -> Vec<Map<String, Value>> {
    let mut value_to_position = HashMap::new();
    for (position, value) in order.iter().enumerate() {
        value_to_position.insert(OrderedFloat(*value), position);
    }

    let mut sorted_records = records;
    sorted_records.sort_by(|a, b| {
        let a_value = a.get(key).unwrap_or(&Value::Null);
        let b_value = b.get(key).unwrap_or(&Value::Null);

        match (a_value.as_f64(), b_value.as_f64()) {
            (Some(a_num), Some(b_num)) => {
                let a_ord = OrderedFloat(a_num);
                let b_ord = OrderedFloat(b_num);
                match (value_to_position.get(&a_ord), value_to_position.get(&b_ord)) {
                    (Some(a_pos), Some(b_pos)) => a_pos.cmp(b_pos),
                    (Some(_), None) => std::cmp::Ordering::Less,
                    (None, Some(_)) => std::cmp::Ordering::Greater,
                    (None, None) => std::cmp::Ordering::Equal,
                }
            }
            _ => std::cmp::Ordering::Equal,
        }
    });

    sorted_records
}
