src/main.rs
-----------
use indexmap::IndexMap;
use std::collections::HashMap;

/// Where to place records whose key value is not present in the precedence list.
#[derive(Clone, Copy, Debug)]
pub enum MissingPlacement {
    Start,
    End,
}

/// Sort records by the string value at `key` according to the order specified by `precedence`.
/// - `records`: a Vec of HashMap<String, String> -- records to be sorted (consumed).
/// - `key`: the key to look up in each record to determine precedence.
/// - `precedence`: ordered slice of values. The earlier an item appears here, the earlier its records appear.
/// - `missing`: whether records whose value for `key` is absent from `precedence` should go to Start or End.
///
/// Returns a new Vec with records sorted according to precedence (stable with respect to equal precedence).
pub fn sort_records_by_precedence(
    mut records: Vec<HashMap<String, String>>,
    key: &str,
    precedence: &[String],
    missing: MissingPlacement,
) -> Vec<HashMap<String, String>> {
    // Build a mapping from value -> rank (lower rank sorts earlier).
    // If missing records are to be placed at Start, we give unknowns rank 0 and shift all known ranks by +1.
    // If missing records are to be placed at End, we give unknowns rank = precedence.len() (after all known).
    let mapping: IndexMap<String, usize> = match missing {
        MissingPlacement::Start => precedence
            .iter()
            .cloned()
            .enumerate()
            .map(|(i, v)| (v, i + 1)) // shift by +1 so unknowns can be 0
            .collect(),
        MissingPlacement::End => precedence
            .iter()
            .cloned()
            .enumerate()
            .map(|(i, v)| (v, i)) // ranks 0..precedence.len()-1; unknowns will be precedence.len()
            .collect(),
    };

    let unknown_rank = match missing {
        MissingPlacement::Start => 0usize,
        MissingPlacement::End => precedence.len(),
    };

    // Stable sort by computed rank
    records.sort_by_key(|rec| {
        rec.get(key)
            .and_then(|v| mapping.get(v).cloned())
            .unwrap_or(unknown_rank)
    });

    records
}

fn main() {
    // Example usage
    let mut records: Vec<HashMap<String, String>> = vec![];

    let mut a = HashMap::new();
    a.insert("id".to_string(), "1".to_string());
    a.insert("priority".to_string(), "medium".to_string());
    a.insert("name".to_string(), "Task A".to_string());

    let mut b = HashMap::new();
    b.insert("id".to_string(), "2".to_string());
    b.insert("priority".to_string(), "high".to_string());
    b.insert("name".to_string(), "Task B".to_string());

    let mut c = HashMap::new();
    c.insert("id".to_string(), "3".to_string());
    c.insert("priority".to_string(), "low".to_string());
    c.insert("name".to_string(), "Task C".to_string());

    let mut d = HashMap::new();
    d.insert("id".to_string(), "4".to_string());
    // missing priority -> will be placed according to `missing`
    d.insert("name".to_string(), "Task D".to_string());

    records.push(a);
    records.push(b);
    records.push(c);
    records.push(d);

    // Define precedence order (high -> medium -> low)
    let precedence = vec![
        "high".to_string(),
        "medium".to_string(),
        "low".to_string(),
    ];

    let sorted = sort_records_by_precedence(records, "priority", &precedence, MissingPlacement::End);

    println!("Sorted (unknowns to End):");
    for r in &sorted {
        println!(
            "- id={} priority={}",
            r.get("id").unwrap_or(&"<no id>".to_string()),
            r.get("priority").unwrap_or(&"<missing>".to_string())
        );
    }

    // If you want unknowns first:
    let mut records2 = sorted.clone();
    let sorted2 = sort_records_by_precedence(records2, "priority", &precedence, MissingPlacement::Start);
    println!("\nSorted (unknowns to Start):");
    for r in &sorted2 {
        println!(
            "- id={} priority={}",
            r.get("id").unwrap_or(&"<no id>".to_string()),
            r.get("priority").unwrap_or(&"<missing>".to_string())
        );
    }
}

Notes:
- This example uses HashMap<String,String> records for simplicity; you can adapt it to your own record type (e.g., serde_json::Map or custom structs) by computing a comparable rank for each record.
- The sort is stable (records with equal precedence preserve their relative order).
- indexmap is used here to construct the precedence->rank mapping while preserving the input order semantics; you could also use std::collections::HashMap if you prefer.

