use indexmap::IndexMap;
use std::cmp::Ordering;

/// Sorts a list of associative records by a specified key according to the order
/// defined in a separate sequence of values.
///
/// # Arguments
/// * `records` - A mutable slice of associative records (IndexMaps)
/// * `key` - The key to sort by
/// * `order_sequence` - A slice defining the desired order of values
///
/// # Type Parameters
/// * `K` - The type of keys (must be hashable and comparable)
/// * `V` - The type of values (must be hashable, comparable, and cloneable)
///
/// # Panics
/// Panics if a record doesn't contain the specified key
pub fn sort_records_by_key_order<K, V>(
    records: &mut [IndexMap<K, V>],
    key: &K,
    order_sequence: &[V],
) where
    K: std::hash::Hash + Eq + Clone + std::fmt::Debug,
    V: std::hash::Hash + Eq + Clone + std::fmt::Debug,
{
    // Create a mapping from each value to its position in the order sequence
    let order_map: IndexMap<&V, usize> = order_sequence
        .iter()
        .enumerate()
        .map(|(index, value)| (value, index))
        .collect();

    // Sort the records using the order map
    records.sort_by(|a, b| {
        let a_value = a.get(key).expect("Record missing specified key");
        let b_value = b.get(key).expect("Record missing specified key");

        let a_order = order_map.get(a_value);
        let b_order = order_map.get(b_value);

        match (a_order, b_order) {
            (Some(a_pos), Some(b_pos)) => a_pos.cmp(b_pos),
            (Some(_), None) => Ordering::Less,  // Values in order sequence come first
            (None, Some(_)) => Ordering::Greater,
            (None, None) => a_value.cmp(b_value), // Fall back to natural ordering
        }
    });
}

