```rust
use itertools::Itertools;

/// Combines a variable number of lists into a single list following a provided sequence.
///
/// # Arguments
/// * `lists` - A slice of iterators (or collections that can be iterated) to combine
/// * `sequence` - A sequence of indices specifying which input list to draw from next
///
/// # Examples
/// ```
/// use itertools::Itertools;
///
/// let lists = vec![vec![1, 2], vec![3, 4], vec![5]];
/// let sequence = vec![0, 1, 2, 0, 1];
/// let result = combine_lists(&lists, &sequence);
/// assert_eq!(result, vec![1, 3, 5, 2, 4]);
/// ```
pub fn combine_lists<I, T>(lists: &[I], sequence: &[usize]) -> Vec<T>
where
    I: Iterator<Item = T> + Clone,
    T: Clone,
{
    let mut result = Vec::with_capacity(sequence.len());

    for &index in sequence {
        // Get the iterator for the specified list
        let list = lists.get(index)
            .expect(&format!("Index {} out of bounds for lists", index));

        // Take the next element from the iterator
        let next = list.clone().next()
            .expect(&format!("List at index {} is empty", index));

        result.push(next);
    }

    result
}

