use std::collections::VecDeque;
use itertools::Itertools; // used for join in error messages

/// Combine multiple input lists into a single list according to `sequence`.
///
/// `lists` is an owned Vec of input Vecs (we consume/move them).
/// `sequence` contains indices into `lists`; at each step we pop the next
/// element from the specified input list and append it to the result.
///
/// Returns Err if `sequence` contains an out-of-bounds index or tries to
/// draw from an already-empty list.
///
/// Example:
/// let lists = vec![vec![1,2], vec![10,20,30]];
/// let sequence = vec![0,1,1,0,1];
/// combine_by_sequence(lists, &sequence) -> Ok(vec![1,10,20,2,30])
pub fn combine_by_sequence<T>(
    lists: Vec<Vec<T>>,
    sequence: &[usize],
) -> Result<Vec<T>, String> {
    // Convert each Vec into a VecDeque for efficient pop_front.
    let mut deques: Vec<VecDeque<T>> = lists.into_iter().map(VecDeque::from).collect();

    // Validate indices early for a clearer error if there is an out-of-bounds index.
    if let Some(&idx) = sequence.iter().find(|&&i| i >= deques.len()) {
        let idxs = sequence.iter().map(|i| i.to_string()).join(", ");
        return Err(format!(
            "Sequence contains index {idx} but there are only {} lists. Sequence: [{}]",
            deques.len(),
            idxs
        ));
    }

    let mut out: Vec<T> = Vec::with_capacity(sequence.len());

    for &which in sequence {
        match deques[which].pop_front() {
            Some(val) => out.push(val),
            None => {
                // Build a helpful error message showing which list ran out.
                let idxs = sequence.iter().map(|i| i.to_string()).join(", ");
                return Err(format!(
                    "Input list {} is empty when trying to draw an element. Sequence: [{}]",
                    which, idxs
                ));
            }
        }
    }

    Ok(out)
}

