use nalgebra::{Vector2, DVector};
use ndarray::Array1;

pub fn coupled_nonlinear_solver<F>(
    func: F,
    initial_guess: Vector2<f64>,
    max_iter: usize,
    tolerance: f64,
) -> Option<Vector2<f64>>
where
    F: Fn(Vector2<f64>) -> Vector2<f64>,
{
    let mut x = initial_guess;

    for _ in 0..max_iter {
        let fx = func(x);

        // Check for convergence
        if fx.norm() < tolerance {
            return Some(x);
        }

        // Compute Jacobian (numerically)
        let h = 1e-6; // Small step for numerical differentiation
        let mut jacobian = vec![vec![0.0; 2]; 2];

        for i in 0..2 {
            let mut x_plus_h = x;
            x_plus_h[i] += h;
            let f_plus_h = func(x_plus_h);

            for j in 0..2 {
                jacobian[j][i] = (f_plus_h[j] - fx[j]) / h;
            }
        }

        // Convert the jacobian to a DMatrix for solving
        let jacobian_matrix = DMatrix::from_row_slice(2, 2, &jacobian.concat());

        // Newton's method step (x_new = x - J^{-1} * f)
        let jacobian_inv = jacobian_matrix.try_inverse().unwrap();

        // Update x
        let f_scalar: DVector<f64> = DVector::from_vec(fx.as_slice().to_vec());
        let delta = jacobian_inv * f_scalar;

        x -= Vector2::new(delta[0], delta[1]);
    }

    None
}

