        Vector2::new(
            x[0].powi(2) + x[1] - 11.0, // f1
            x[0] + x[1].powi(2) - 7.0   // f2
        )
    };

    let initial_guess = Vector2::new(1.0, 1.0);
    let result = coupled_nonlinear_solver(equations, initial_guess, 100, 1e-6);

    match result {
        Some(roots) => println!("Roots found: x = {}, y = {}", roots[0], roots[1]),
        None => println!("No convergence"),
    }
}
