use nalgebra::{Vector2, Matrix2};

/// Computes the roots of two coupled nonlinear equations using Newton's method.
///
/// # Arguments
/// * `f` - A function that takes a 2D vector [x, y] and returns the residual [f1, f2]
/// * `jacobian` - A function that takes a 2D vector [x, y] and returns the 2x2 Jacobian matrix
/// * `initial_guess` - The starting point [x0, y0]
/// * `tolerance` - Convergence tolerance (default suggested: 1e-9)
/// * `max_iterations` - Maximum number of iterations (default suggested: 100)
///
/// # Returns
/// A `Result` containing either the solution vector or an error message
///
/// # Example
/// ```
/// let f = |v: Vector2<f64>| {
///     let x = v[0];
///     let y = v[1];
///     Vector2::new(
///         x*x + y*y - 1.0,  // Circle equation
///         x - y              // Line equation
///     )
/// };
///
/// let jacobian = |v: Vector2<f64>| {
///     let x = v[0];
///     let y = v[1];
///     Matrix2::new(
///         2.0*x, 2.0*y,
///         1.0,   -1.0
///     )
/// };
///
/// let initial = Vector2::new(0.5, 0.5);
/// let result = solve_nonlinear_system(&f, &jacobian, initial, 1e-9, 100);
/// ```
pub fn solve_nonlinear_system<F, J>(
    f: F,
    jacobian: J,
    mut current: Vector2<f64>,
    tolerance: f64,
    max_iterations: usize,
) -> Result<Vector2<f64>, String>
where
    F: Fn(Vector2<f64>) -> Vector2<f64>,
    J: Fn(Vector2<f64>) -> Matrix2<f64>,
{
    for iteration in 0..max_iterations {
        let residual = f(current);
        let residual_norm = residual.norm();

        // Check for convergence
        if residual_norm < tolerance {
            return Ok(current);
        }

        // Compute Jacobian
        let jac = jacobian(current);

        // Solve the linear system: J * delta = -f
        let delta = match jac.lu().solve(&(-residual)) {
            Some(delta) => delta,
            None => return Err(format!(
                "Singular Jacobian at iteration {}. Determinant: {}",
                iteration,
                jac.determinant()
            )),
        };

        // Update the solution
        current += delta;

        // Optional: Check for stagnation
        if delta.norm() < 1e-15 {
            return Err(format!(
                "Iteration stagnated at iteration {}",
                iteration
            ));
        }
    }

    Err(format!(
        "Failed to converge after {} iterations. Final residual norm: {}",
        max_iterations,
        f(current).norm()
    ))
}

