use polars::prelude::*;
use std::cmp::Ordering;

fn segment_entries(df0: &DataFrame, lst0: &[f64]) -> Result<DataFrame, PolarsError> {
    // Convert the "str0" column to f64
    let str0_series = df0.column("str0")?;
    let float_series = str0_series.f64()?;

    // Define a function to determine the interval index
    let determine_interval = |value: Option<f64>| -> Option<u32> {
        value.and_then(|v| {
            lst0.binary_search_by(|probe| probe.partial_cmp(&v).unwrap_or(Ordering::Less))
