    // Apply the function to create a new series with interval indices
    let interval_indices = float_series.apply(|v| determine_interval(Some(v)));

    // Create a new dataframe with the original data and the interval indices
    let mut df = df0.clone();
    df.with_column(Series::new("interval_index", interval_indices))?;

    Ok(df)
}

