Example code:

```rust
// Cargo.toml (add these lines):
// [dependencies]
// polars = { version = "0.31", features = ["lazy", "temporal"] }

use polars::prelude::*;
use std::cmp::Ordering;

/// Segment values from column `col_name` in `df` into intervals defined by `boundaries`.
/// - `boundaries` must have at least two elements. They will be sorted if not already.
/// - Returns a new DataFrame with an added column named `new_col` containing interval labels
///   like "[low, high)" (last interval is "[low, high]") or null for out-of-range / unparseable.
///
/// Supports numeric columns (f64/i64) and UTF8 columns containing parseable numbers.
pub fn segment_intervals(
    df: &DataFrame,
    col_name: &str,
    boundaries: &[f64],
    new_col: &str,
) -> PolarsResult<DataFrame> {
    if boundaries.len() < 2 {
        return Err(PolarsError::ComputeError(
            "Need at least two boundaries to form intervals".into(),
        ));
    }

    // Copy and sort boundaries (keeping NaNs aside)
    let mut b: Vec<f64> = boundaries.to_vec();
    // Use partial_cmp to handle floats; treat NaN as greater (this keeps them at the end)
    b.sort_by(|a, c| a.partial_cmp(c).unwrap_or(Ordering::Greater));

    // Helper closure to compute the interval label for a value
    let label_for = |v: f64| -> Option<String> {
        if v.is_nan() {
            return None;
        }
        if v < b[0] {
            return None;
        }
        let last = b.len() - 1;
        for i in 0..last {
            let low = b[i];
            let high = b[i + 1];
            let in_bin = if i + 1 == last {
                // last bin: include right endpoint
                (v >= low && v <= high)
            } else {
                // left-inclusive, right-exclusive
                (v >= low && v < high)
            };
            if in_bin {
                return Some(if i + 1 == last {
                    format!("[{}, {}]", low, high)
                } else {
                    format!("[{}, {})", low, high)
                });
            }
        }
        // if v > last boundary and didn't match last inclusive bin, treat as None
        None
    };

    // Get the series and produce an iterator of Option<f64>
    let s = df.column(col_name)?;
    let values_iter: Box<dyn Iterator<Item = Option<f64>>> = if let Ok(ca) = s.f64() {
        Box::new(ca.into_iter())
    } else if let Ok(ca) = s.i64() {
        Box::new(ca.into_iter().map(|opt| opt.map(|v| v as f64)))
    } else if let Ok(ca) = s.utf8() {
        // parse strings to f64; unparseable -> None
        Box::new(ca.into_iter().map(|opt_s| {
            opt_s.and_then(|st| match st.parse::<f64>() {
                Ok(v) => Some(v),
                Err(_) => None,
            })
        }))
    } else {
        return Err(PolarsError::ComputeError(
            "Unsupported column type: expected f64, i64, or Utf8".into(),
        ));
    };

    // Build labels (owned Strings) keeping ownership so we can later create &str slices
    let mut labels_owned: Vec<Option<String>> = Vec::with_capacity(values_iter.size_hint().0);
    for opt_v in values_iter {
        if let Some(v) = opt_v {
            labels_owned.push(label_for(v));
        } else {
            labels_owned.push(None);
        }
    }

    // Convert Vec<Option<String>> -> Vec<Option<&str>> so Series::new will copy strings
    let labels_slices: Vec<Option<&str>> = labels_owned
        .iter()
        .map(|o| o.as_deref())
        .collect();

    // Create the new Series and return a DataFrame with the appended column
    let new_series = Series::new(new_col, labels_slices);
    let mut out = df.clone();
    out.with_column(new_series)?;
    Ok(out)
}

fn main() -> PolarsResult<()> {
    // Example usage:
    let df = df![
        "str0" => &["0.5", "1.2", "2.9", "5.0", "nan", "10"],
        "other" => &[1, 2, 3, 4, 5, 6]
    ]?;

    let boundaries = vec![0.0, 1.0, 3.0, 10.0]; // intervals: [0,1), [1,3), [3,10]
    let out = segment_intervals(&df, "str0", &boundaries, "interval")?;
    println!("{}", out);
    Ok(())
}
```

