pub fn segment_column(df0: &DataFrame, lst0: &[&str]) -> HashMap<String, Vec<String>> {
    // Extract the "str0" column as a Series
    let str0_series = df0
        .column("str0")
        .expect("Column 'str0' not found in DataFrame")
        .str()
        .expect("Column 'str0' is not a string type");

    // Collect all string values from the column
    let values: Vec<String> = str0_series
        .into_iter()
        .filter_map(|opt| opt.map(|s| s.to_string()))
        .collect();

    // Sort the boundaries for consistent interval definition
    let mut sorted_boundaries = lst0.to_vec();
    sorted_boundaries.sort();

    // Create interval labels
    let mut interval_labels: Vec<String> = Vec::new();

    // First interval: values less than first boundary
    if !sorted_boundaries.is_empty() {
        interval_labels.push(format!("< {}", sorted_boundaries[0]));

        // Middle intervals
        for i in 0..sorted_boundaries.len() - 1 {
            interval_labels.push(format!(
                "{} to {}", 
                sorted_boundaries[i], 
                sorted_boundaries[i + 1]
            ));
        }

        // Last interval: values greater than or equal to last boundary
        interval_labels.push(format!(">= {}", sorted_boundaries[sorted_boundaries.len() - 1]));
    } else {
        // If no boundaries, all values go into a single interval
        interval_labels.push("All values".to_string());
    }

    // Initialize result HashMap
    let mut result: HashMap<String, Vec<String>> = HashMap::new();
    for label in &interval_labels {
        result.insert(label.clone(), Vec::new());
    }

    // Segment each value into appropriate interval
    for value in &values {
        if sorted_boundaries.is_empty() {
            result.get_mut("All values").unwrap().push(value.clone());
        } else {
            // Find which interval this value belongs to
            let mut assigned = false;

            // Check if value is less than first boundary
            if value.as_str() < sorted_boundaries[0] {
                result.get_mut(&interval_labels[0]).unwrap().push(value.clone());
                assigned = true;
            }

            // Check middle intervals
            if !assigned {
                for i in 0..sorted_boundaries.len() - 1 {
                    if value.as_str() >= sorted_boundaries[i] && value.as_str() < sorted_boundaries[i + 1] {
                        result.get_mut(&interval_labels[i + 1]).unwrap().push(value.clone());
                        assigned = true;
                        break;
                    }
                }
            }

            // If not assigned yet, it belongs to the last interval
            if !assigned {
                result.get_mut(&interval_labels[interval_labels.len() - 1]).unwrap().push(value.clone());
            }
        }
    }

    result
}

