use regex::Regex;
use std::collections::HashMap;

fn sort_keys(data_mapping: HashMap<String, String>) -> Vec<String> {
    // Define a regex to capture sequences of letters and digits
    let re = Regex::new(r"([A-Za-z0-9]+)").unwrap();

    // Create a sorting key function that extracts sequences
    let mut keys: Vec<String> = data_mapping.keys().cloned().collect();

    keys.sort_by(|a, b| {
        // Create a tuple for each key based on the regex matches
        let a_parts: Vec<&str> = re.find_iter(a).map(|m| m.as_str()).collect();
        let b_parts: Vec<&str> = re.find_iter(b).map(|m| m.as_str()).collect();

        // Compare the vectors tuple-wise
        a_parts.cmp(&b_parts)
    });

    keys
}

