use std::collections::BTreeMap;

/// Sorts the keys of a HashMap based on alphanumeric (natural) sorting.
/// Returns a BTreeMap with keys sorted in natural order.
///
/// # Arguments
/// * `data_mapping` - A HashMap or similar key-value mapping
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let mut map = HashMap::new();
/// map.insert("item10", 1);
/// map.insert("item2", 2);
/// map.insert("item1", 3);
///
/// let sorted = sort_keys_alphanumeric(&map);
/// let keys: Vec<_> = sorted.keys().collect();
/// assert_eq!(keys, vec![&"item1", &"item2", &"item10"]);
/// ```
fn sort_keys_alphanumeric<K, V>(
    data_mapping: &std::collections::HashMap<K, V>,
) -> BTreeMap<String, V>
where
    K: std::hash::Hash + Eq + AsRef<str> + Clone,
    V: Clone,
{
    use regex::Regex;

    // Compile regex to split strings into letters and digits
    let re = Regex::new(r"(\d+|[a-zA-Z]+)").expect("Invalid regex");

    let mut entries: Vec<_> = data_mapping.iter().collect();

    // Sort using natural sorting algorithm
    entries.sort_by(|a, b| {
        let key_a = a.0.as_ref();
        let key_b = b.0.as_ref();

        let parts_a: Vec<&str> = re
            .find_iter(key_a)
            .map(|m| m.as_str())
            .collect();
        let parts_b: Vec<&str> = re
            .find_iter(key_b)
            .map(|m| m.as_str())
            .collect();

        for (part_a, part_b) in parts_a.iter().zip(parts_b.iter()) {
            // Try to parse both as numbers
            match (part_a.parse::<u64>(), part_b.parse::<u64>()) {
                (Ok(num_a), Ok(num_b)) => {
                    if num_a != num_b {
                        return num_a.cmp(&num_b);
                    }
                }
                _ => {
                    if part_a != part_b {
                        return part_a.cmp(part_b);
                    }
                }
            }
        }

        parts_a.len().cmp(&parts_b.len())
    });

    // Build the sorted BTreeMap
    entries
        .into_iter()
        .map(|(k, v)| (k.as_ref().to_string(), v.clone()))
        .collect()
}

