use polars::prelude::*;
use std::collections::HashSet;

fn filter_rows_by_column<T>(
    df: &DataFrame, 
    col_name: &str, 
    lst: &[T]
) -> Result<DataFrame>
where
    T: std::hash::Hash + Eq + Clone + Into<DataType>,
{
