            if let Some(val) = opt_val {
                lst_set.contains(&val.to_string()) // Adjust if dealing with non-string types
            } else {
                false
            }
        })
        .collect::<BooleanChunked>() // Collect into a BooleanChunked
        .into_series();

    // Use the mask to filter the DataFrame
    let filtered_df = df.filter(&mask)?;

    Ok(filtered_df)
}

fn main() -> Result<()> {
