use polars::prelude::*;

/// Filters rows from a DataFrame where values in `col_name` appear in `lst0`.
///
/// # Arguments
/// * `df0` - The input DataFrame to filter
/// * `col_name` - Name of the column to check against `lst0`
/// * `lst0` - Collection of values to match against the column
///
/// # Returns
/// A new DataFrame containing only rows where the column's value is in `lst0`
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df!(
///     "a" => &[1, 2, 3, 4],
///     "b" => &["x", "y", "x", "z"]
/// );
///
/// let filtered = filter_rows_in_collection(df, "b", &["x", "y"]);
/// ```
pub fn filter_rows_in_collection(
    df0: &DataFrame,
    col_name: &str,
    lst0: &[&str],
) -> Result<DataFrame, PolarsError> {
    // Convert the list to a set for efficient lookup
    let lookup_set: HashSet<_> = lst0.iter().map(|s| s.to_string()).collect();

    // Create a boolean mask where the column values are in the set
    let mask = df0
        .column(col_name)?
        .utf8()?
        .into_iter()
        .map(|s| lookup_set.contains(&s.to_string()))
        .collect::<Vec<_>>();

    // Apply the mask to filter the DataFrame
    Ok(df0.lazy().filter(&mask)?.collect()?)
}
```

### Alternative Version (More Efficient for Large DataFrames)

For better performance with large DataFrames, you can use Polars' native filtering capabilities:

