use tabled::{Table, Tabled};

#[derive(Tabled)]
struct Row {
    List1: String,
    List2: String,
}

fn lists_to_table(lst0: Vec<&str>, lst1: Vec<&str>) -> String {
    // Ensure both lists have the same length by padding the shorter one with empty strings
    let max_len = lst0.len().max(lst1.len());
    let padded_lst0: Vec<String> = lst0.into_iter().map(String::from).chain(std::iter::repeat(String::new()).take(max_len - lst0.len())).collect();
    let padded_lst1: Vec<String> = lst1.into_iter().map(String::from).chain(std::iter::repeat(String::new()).take(max_len - lst1.len())).collect();

    // Create rows from the padded lists
    let rows: Vec<Row> = padded_lst0.into_iter().zip(padded_lst1.into_iter())
        .map(|(list1, list2)| Row { List1: list1, List2: list2 })
        .collect();

    // Create and return the table as a string
    Table::new(rows).to_string()
}

fn main() {
    let lst0 = vec!["Item1", "Item2", "Item3"];
    let lst1 = vec!["Value1", "Value2"];

    let table = lists_to_table(lst0, lst1);
    println!("{}", table);
}
