use itertools::Itertools;
use std::cmp::Ord;

/// Reorders `lst0` so its elements follow the order defined by the corresponding values in `lst1`.
///
/// Returns Err if the two input vectors have different lengths.
///
/// Example:
/// let items = vec!["a", "b", "c"];
/// let keys  = vec![2, 1, 3];
/// let reordered = reorder_by_keys(items, keys).unwrap();
/// assert_eq!(reordered, vec!["b", "a", "c"]);
pub fn reorder_by_keys<T, K>(lst0: Vec<T>, lst1: Vec<K>) -> Result<Vec<T>, &'static str>
where
    K: Ord,
{
    if lst0.len() != lst1.len() {
        return Err("lst0 and lst1 must have the same length");
    }

    // Zip keys and items, sort pairs by key, then extract the items in the new order.
    let pairs = lst1.into_iter().zip(lst0.into_iter());
    let sorted_pairs: Vec<(K, T)> = pairs.sorted_by(|a, b| a.0.cmp(&b.0)).collect();
    Ok(sorted_pairs.into_iter().map(|(_k, v)| v).collect())
}

fn main() {
    let items = vec!["a", "b", "c", "d"];
    let keys  = vec![3, 1, 2, 2];

    let reordered = reorder_by_keys(items, keys).unwrap();
    println!("{:?}", reordered);
    // Because keys 2 appear twice, their relative order is preserved (stable sort):
    // Output: ["b", "c", "d", "a"]
}
