use itertools::Itertools;
use std::cmp::Ordering;

/// Reorder elements of lst0 based on the order defined by corresponding values in lst1.
/// 
/// Elements in lst0 are sorted according to the values in lst1 at the same index.
/// If lst1 contains duplicate values, the original relative order from lst0 is preserved (stable sort).
/// 
/// # Arguments
/// * `lst0` - A mutable slice of elements to be reordered
/// * `lst1` - A slice of ordering values corresponding to elements in lst0
/// 
/// # Panics
/// Panics if lst0 and lst1 have different lengths
/// 
/// # Example
/// ```
/// let mut items = vec!["apple", "banana", "cherry", "date"];
/// let order = vec![3, 1, 4, 2];
/// reorder_by(&mut items, &order);
/// assert_eq!(items, vec!["banana", "date", "apple", "cherry"]);
/// ```
pub fn reorder_by<T, U>(lst0: &mut [T], lst1: &[U])
where
    U: Ord,
{
    assert_eq!(
        lst0.len(),
        lst1.len(),
        "Both slices must have the same length"
    );

    // Create indices and sort them based on corresponding values in lst1
    let mut indices: Vec<usize> = (0..lst0.len()).collect();
    indices.sort_by(|&i, &j| lst1[i].cmp(&lst1[j]));

    // Apply the permutation to lst0
    apply_permutation(lst0, &indices);
}

/// Apply a permutation to a slice in-place using cycle decomposition
fn apply_permutation<T>(slice: &mut [T], permutation: &[usize]) {
    let mut visited = vec![false; slice.len()];

    for i in 0..slice.len() {
        if !visited[i] {
            let mut current = i;
            let mut temp: Option<T> = None;

            // Follow the cycle
            while !visited[current] {
                visited[current] = true;
                let next = permutation[current];

                // Swap elements
                if let Some(val) = temp.take() {
                    std::mem::swap(&mut slice[current], &mut slice[next]);
                    temp = Some(std::mem::replace(&mut slice[current], val));
                } else {
                    std::mem::swap(&mut slice[current], &mut slice[next]);
                    temp = Some(std::mem::replace(&mut slice[current], unsafe {
                        // Safe because we're reading from a valid index
                        std::ptr::read(&slice[current])
                    }));
                }

                current = next;
            }
        }
    }
}

