# Rust Function to Reorder Elements Based on Another List

```rust
use itertools::Itertools;

/// Reorders elements of lst0 according to the order defined by indices in lst1.
/// 
/// # Arguments
/// * `lst0` - Vector of elements to reorder
/// * `lst1` - Vector of indices defining the desired order
/// 
/// # Returns
/// A new vector with elements from lst0 reordered according to lst1
/// 
/// # Example
/// ```
/// let lst0 = vec!['a', 'b', 'c', 'd'];
/// let lst1 = vec![3, 0, 2, 1];
/// let result = reorder_by_indices(lst0, lst1);
/// assert_eq!(result, vec!['d', 'a', 'c', 'b']);
/// ```
fn reorder_by_indices<T: Clone>(lst0: Vec<T>, lst1: Vec<usize>) -> Vec<T> {
    lst1.iter()
        .map(|&idx| lst0[idx].clone())
        .collect()
}

/// Alternative implementation using zip with sort_by_key
/// Reorders lst0 elements by sorting them according to corresponding values in lst1.
/// 
/// # Example
/// ```
/// let lst0 = vec!["apple", "banana", "cherry", "date"];
/// let lst1 = vec![3, 1, 2, 0];
/// let result = reorder_by_sort(lst0, lst1);
/// assert_eq!(result, vec!["date", "banana", "cherry", "apple"]);
/// ```
fn reorder_by_sort<T: Clone>(lst0: Vec<T>, lst1: Vec<usize>) -> Vec<T> {
    lst0.into_iter()
        .zip(lst1.iter())
        .sorted_by_key(|(_item, &order_idx)| order_idx)
        .map(|(item, _)| item)
        .collect()
}

