    fn test_reorder_by_indices_numbers() {
        let lst0 = vec![10, 20, 30, 40];
        let lst1 = vec![2, 0, 3, 1];
        assert_eq!(reorder_by_indices(lst0, lst1), vec![30, 10, 40, 20]);
