        let lst0 = vec!["apple", "banana", "cherry", "date"];
        let lst1 = vec![3, 1, 2, 0];
        assert_eq!(reorder_by_sort(lst0, lst1), vec!["date", "banana", "cherry", "apple"]);
    }

