/// // ╞═════════╪═════╪═════════╡
/// // │ Alice   ┆ 25  ┆ NYC     │
/// // │ Charlie ┆ 35  ┆ Chicago │
/// // └─────────┴─────┴─────────┘
/// ```
pub fn remove_rows_where_equal(
    df0: &DataFrame,
    var0: &str,
    var1: &str,
) -> Result<DataFrame> {
    // Get the column and determine its data type
    let col = df0.column(var0)?;
    let dtype = col.dtype();

    // Create the filter condition based on data type
    let mask = match dtype {
        DataType::Utf8 => {
            col.utf8()?
                .into_iter()
                .map(|opt_val| opt_val.map(|v| v != var1).unwrap_or(true))
                .collect::<BooleanChunked>()
        }
        DataType::Int32 => {
            let val: i32 = var1.parse().map_err(|_| {
                PolarsError::ComputeError("Failed to parse var1 as Int32".into())
            })?;
            col.i32()?
                .into_iter()
                .map(|opt_val| opt_val.map(|v| v != val).unwrap_or(true))
                .collect::<BooleanChunked>()
        }
        DataType::Int64 => {
            let val: i64 = var1.parse().map_err(|_| {
                PolarsError::ComputeError("Failed to parse var1 as Int64".into())
            })?;
            col.i64()?
                .into_iter()
                .map(|opt_val| opt_val.map(|v| v != val).unwrap_or(true))
                .collect::<BooleanChunked>()
        }
        DataType::Float64 => {
            let val: f64 = var1.parse().map_err(|_| {
                PolarsError::ComputeError("Failed to parse var1 as Float64".into())
            })?;
            col.f64()?
                .into_iter()
                .map(|opt_val| opt_val.map(|v| v != val).unwrap_or(true))
                .collect::<BooleanChunked>()
        }
        DataType::Boolean => {
            let val: bool = var1.parse().map_err(|_| {
                PolarsError::ComputeError("Failed to parse var1 as Boolean".into())
            })?;
            col.bool()?
                .into_iter()
                .map(|opt_val| opt_val.map(|v| v != val).unwrap_or(true))
                .collect::<BooleanChunked>()
        }
        _ => {
            return Err(PolarsError::ComputeError(
                format!("Unsupported data type: {:?}", dtype).into(),
            ));
        }
    };

    // Apply the filter
    df0.filter(&mask)
}

