use ndarray::{Array2, ArrayView2, ArrayViewMut2, Axis, Data};
use std::marker::PhantomData;

/// Replaces `None` entries in a 2D table with the column mean.
///
/// # Arguments
/// * `table` - A mutable view of the 2D table containing `Option<T>` values.
/// * `default` - A default value to use for the mean calculation (to avoid division by zero).
///
/// # Returns
/// A new table with `None` entries replaced by their column mean.
///
/// # Example
/// ```
/// use ndarray::{array, Array2};
/// use std::num::NonZeroF64;
///
/// let mut table: Array2<Option<f64>> = array![
///     [Some(1.0), Some(2.0), None],
///     [Some(3.0), None, Some(5.0)],
///     [None, Some(4.0), Some(6.0)],
/// ];
