/// let filled_table = fill_missing_with_column_mean(&mut table, 0.0);
/// assert_eq!(filled_table[[0, 2]], Some(3.3333333333333335));
/// assert_eq!(filled_table[[1, 1]], Some(3.0));
/// assert_eq!(filled_table[[2, 0]], Some(2.0));
/// ```
pub fn fill_missing_with_column_mean<T>(
    table: &mut ArrayViewMut2<Option<T>>,
    default: T,
) -> Array2<Option<T>>
where
    T: std::ops::Add<Output = T> + std::ops::Div<Output = T> + Copy + PartialOrd + std::fmt::Debug,
    T: From<f64>,
    f64: From<T>,
{
    // Create a new array to store the results
    let mut result = Array2::zeros(table.shape());

    // Calculate column sums and counts for non-None values
    let mut column_sums = Array2::zeros(table.shape()[1]);
    let mut column_counts = Array2::zeros(table.shape()[1]);

    // First pass: compute column sums and counts
    for (i, row) in table.axis_iter(Axis(0)).enumerate() {
        for (j, &val) in row.iter().enumerate() {
            if let Some(v) = val {
                column_sums[[j]] += f64::from(v);
                column_counts[[j]] += 1;
            }
        }
    }

    // Second pass: fill in missing values with column mean
    for (i, row) in table.axis_iter_mut(Axis(0)).enumerate() {
        for (j, val) in row.iter_mut().enumerate() {
            if val.is_none() {
                let count = column_counts[[j]];
                if count == 0 {
                    // If column has no valid values, use the default
                    *val = Some(default);
                } else {
                    let sum = column_sums[[j]];
                    let mean = sum / count as f64;
                    *val = Some(T::from(mean));
                }
            }
        }
    }

    // Return a copy of the filled table
    result.assign(table)
}

