/// Removes rows with duplicate values across specified columns from a DataFrame.
///
/// # Arguments
/// * `df` - Input DataFrame
/// * `columns` - List of column names to check for duplicates
///
/// # Returns
/// A new DataFrame with duplicate rows removed based on the specified columns
///
/// # Example
/// ```
/// use polars::prelude::*;
/// let df = df!(
///     "A" => &[1, 2, 2, 3],
///     "B" => &["x", "y", "x", "z"]
/// ).unwrap();
/// let result = remove_duplicate_rows(df, &["A", "B"]);
/// ```
pub fn remove_duplicate_rows(df: DataFrame, columns: &[&str]) -> Result<DataFrame, PolarsError> {
    // Create a unique key for each row based on the specified columns
    let key_expr = columns.iter()
        .map(|col| df.column(col).unwrap().to_expr())
        .collect::<Expr>();

    // Create a tuple of the specified columns
