use polars::prelude::*;
use std::collections::HashSet;

pub fn remove_duplicate_rows(df: DataFrame, columns: &[&str]) -> Result<DataFrame, PolarsError> {
    let mut seen = HashSet::new();
    let mut result_rows = Vec::new();

    for row in df.iter_rows()? {
        let mut key = Vec::new();
        for col in columns {
            key.push(row.get(*col).unwrap());
        }
        let key_tuple = key.as_slice();

        if !seen.contains(&key_tuple) {
            seen.insert(key_tuple);
            result_rows.push(row);
        }
    }

    let schema = df.schema();
    let mut result_df = DataFrame::new(schema.clone())?;
    for row in result_rows {
        result_df.append(row)?;
    }

    Ok(result_df)
}
```

The first implementation using the lazy API is generally preferred for better performance with large datasets.

