/// println!("{:?}", result);
/// ```
pub fn remove_duplicate_rows(df: &DataFrame, columns: &[&str]) -> Result<DataFrame, PolarsError> {
    // Validate that all specified columns exist
    for col in columns {
        if !df.get_column_names().contains(col) {
            return Err(PolarsError::ColumnNotFound(
                format!("Column '{}' not found in DataFrame", col).into(),
            ));
        }
    }

    // Create a HashSet to track seen combinations
    let mut seen: HashSet<Vec<AnyValue>> = HashSet::new();

    // Collect indices of rows to keep
    let mut keep_indices: Vec<usize> = Vec::new();

    // Iterate through rows
    for idx in 0..df.height() {
        // Extract values for specified columns
        let row_values: Vec<AnyValue> = columns
            .iter()
            .map(|col| df.column(col).unwrap().get(idx).unwrap())
            .collect();

        // Check if this combination has been seen
        if seen.insert(row_values) {
            keep_indices.push(idx);
        }
    }

    // Filter the DataFrame to keep only unique rows
    df.take(&keep_indices)
}

