use polars::prelude::*;
use chrono::{DateTime, Utc, NaiveDateTime};
use std::str::FromStr;

fn reformat_datetime_column(df0: DataFrame, col_name: &str, format_str: &str) -> Result<DataFrame, PolarsError> {
    // Extract the series from the DataFrame
    let datetime_series = df0.column(col_name)?;

    // Ensure the series is of datetime type
    if !datetime_series.dtype().is_date() && !datetime_series.dtype().is_datetime() {
        return Err(PolarsError::ComputeError(
            format!("Column {} is not of datetime type", col_name).into(),
        ));
    }

    // Convert the series to a datetime type if it's not already
    let datetime_series = if datetime_series.dtype().is_date() {
        datetime_series.cast(&DataType::Datetime(TimeUnit::Milliseconds, None))?
    } else {
        datetime_series.clone()
    };

    // Map each datetime value to a formatted string
    let formatted_series = datetime_series
        .datetime()?
        .into_iter()
        .map(|opt_naive_datetime| {
            opt_naive_datetime.map(|naive_datetime| {
                let naive_datetime = NaiveDateTime::from_timestamp_millis(naive_datetime).unwrap();
                let datetime: DateTime<Utc> = DateTime::<Utc>::from_utc(naive_datetime, Utc);
                datetime.format(format_str).to_string()
            })
        })
        .collect::<Utf8Chunked>()
        .into_series();

    // Replace the original column with the formatted column
    let mut df = df0.clone();
    df.replace_or_add_column(formatted_series)?;

    Ok(df)
}

