use polars::prelude::*;

/// Reformat the date-time values in column `col_name` of `df0` so they follow `output_format`.
/// If `input_format` is Some(fmt), the column is first parsed from string to datetime using that format.
/// If `input_format` is None, the function assumes the column is already a datetime type and
/// only applies the output formatting.
///
/// Returns a new DataFrame with the reformatted column (replaces the original column).
///
/// Example:
/// let df2 = reformat_datetime_column(&df, "timestamp", Some("%Y-%m-%d %H:%M:%S"), "%Y/%m/%d %H:%M")?;
pub fn reformat_datetime_column(
    df0: &DataFrame,
    col_name: &str,
    input_format: Option<&str>,
    output_format: &str,
) -> PolarsResult<DataFrame> {
    // Build an expression: either parse then format, or just format existing datetime column.
    // Use milliseconds time unit for parsing by default; adjust if your timestamps use seconds/nanoseconds.
    let tu = TimeUnit::Milliseconds;

    let expr: Expr = match input_format {
        Some(in_fmt) => {
            // Parse strings in col_name according to in_fmt into a Datetime, then format.
            // strptime signature (Expr): .strptime(dtype, fmt, strict, exact)
            // then .dt().strftime(output_format)
            col(col_name)
                .strptime(DataType::Datetime(tu, None), in_fmt, false, false)?
                .dt()
                .strftime(output_format)
                .alias(col_name)
        }
        None => {
            // Assume column is already datetime-like; just apply strftime.
            col(col_name)
                .dt()
                .strftime(output_format)
                .alias(col_name)
        }
    };

    // Use lazy with_column to replace the column with the formatted strings, then collect back to eager DataFrame.
    let out = df0.clone().lazy().with_column(expr).collect()?;
    Ok(out)
}

