                .or_else(|_| NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S"))
                .or_else(|_| NaiveDateTime::parse_from_str(s, "%Y/%m/%d %H:%M:%S"))
                .or_else(|_| NaiveDateTime::parse_from_str(s, "%d-%m-%Y %H:%M:%S"))
                .or_else(|_| NaiveDateTime::parse_from_str(s, "%m/%d/%Y %H:%M:%S"))
                .or_else(|_| NaiveDateTime::parse_from_str(s, "%Y-%m-%d"))
                .or_else(|_| NaiveDateTime::parse_from_str(s, "%d/%m/%Y"))
                .or_else(|_| NaiveDateTime::parse_from_str(s, "%m/%d/%Y"));

