use time::macros::format_description;

/// Combine the values of the col0 (date string "YYYY-MM-DD") and col1 (time string "HH:MM:SS" or "HH:MM:SS.sss")
/// of each row in `rows` into a single UTC date-time value.
///
/// Input:
/// - rows: slice of tuples (&str, &str) where .0 is date, .1 is time
///
/// Returns:
/// - Ok(Vec<OffsetDateTime>) on success (each datetime is assumed UTC)
/// - Err(time::error::Parse) if any row fails to parse
pub fn combine_col0_col1_to_datetimes(
    rows: &[(&str, &str)],
) -> Result<Vec<OffsetDateTime>, time::error::Parse> {
    // Pre-constructed format descriptions
    let date_fmt = format_description!("[year]-[month]-[day]");
    let time_fmt_no_sub = format_description!("[hour]:[minute]:[second]");
    let time_fmt_sub = format_description!("[hour]:[minute]:[second].[subsecond]");

    let mut result = Vec::with_capacity(rows.len());

    for &(date_str, time_str) in rows {
        // parse date
        let date = Date::parse(date_str, &date_fmt)?;

        // try parse time without fractional seconds, otherwise try with fractional seconds
        let time = match Time::parse(time_str, &time_fmt_no_sub) {
            Ok(t) => t,
            Err(_) => Time::parse(time_str, &time_fmt_sub)?,
        };

        // combine into primitive datetime and assume UTC
        let pdt = PrimitiveDateTime::new(date, time);
        let odt = pdt.assume_utc();
        result.push(odt);
    }

    Ok(result)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
