/// Compute the average for each key in `dict0`.
/// Returns a HashMap mapping each key to `Some(average)` if the list was non-empty,
/// or `None` if the list for that key was empty or all elements failed to convert.
fn averages<K, T>(dict0: &HashMap<K, Vec<T>>) -> HashMap<K, Option<f64>>
where
    K: Eq + Hash + Clone,
    T: ToPrimitive,
