use regex::Regex;
use std::error::Error;

/// Find all case-insensitive occurrences of `needle` inside `haystack`.
/// Returns a Vec of (start_byte, end_byte) pairs for each match.
/// This finds overlapping matches as well (e.g., "ana" in "banana" -> matches at 1..4 and 3..6).
///
/// Uses a lookahead-based regex with a capturing group:
///   (?i)(?=(escaped_needle))
/// which is Unicode-aware case-insensitive (regex crate).
pub fn find_case_insensitive_occurrences(
    haystack: &str,
    needle: &str,
) -> Result<Vec<(usize, usize)>, Box<dyn Error>> {
    if needle.is_empty() {
        return Ok(Vec::new()); // no meaningful occurrences for empty needle
    }

    // Escape the needle so we search for it literally.
    let escaped = regex::escape(needle);

    // Use a lookahead with a capturing group so overlapping matches are found.
    // (?i) - case-insensitive
    // (?=(...)) - zero-length lookahead; the capturing group contains the actual matched span.
    let pattern = format!("(?i)(?=({}))", escaped);

    let re = Regex::new(&pattern)?; // may return regex::Error

    let mut matches = Vec::new();
    for caps in re.captures_iter(haystack) {
        if let Some(m) = caps.get(1) {
            matches.push((m.start(), m.end()));
        }
    }
    Ok(matches)
}

fn main() -> Result<(), Box<dyn Error>> {
    let haystack = "Hello\nBANana\nBaNana and bAnAnA";
    let needle = "ana";

    let matches = find_case_insensitive_occurrences(haystack, needle)?;

    println!("Found {} matches:", matches.len());
    for (i, (s, e)) in matches.iter().enumerate() {
        // Show the matched substring and a simple line:col for readability
        let matched = &haystack[*s..*e];
        let line = haystack[..*s].lines().count(); // 0-based -> number of lines before match
        let last_line_start = haystack[..*s].rfind('\n').map(|p| p + 1).unwrap_or(0);
        let col = *s - last_line_start;
        println!(
            "{}: bytes {}..{} (line {}, col {}): {:?}",
            i + 1,
            s,
            e,
            line + 1,
            col + 1,
            matched
        );
    }

    Ok(())
}

