/// Errors if any index is out of bounds or too large to fit in u32.
pub fn reorder_rows(df0: &DataFrame, lst0: &[usize]) -> PolarsResult<DataFrame> {
    let n_rows = df0.height();
    if lst0.is_empty() {
        // empty index list -> empty DataFrame with same schema
