        if float_a.is_nan() && float_b.is_nan() {
            std::cmp::Ordering::Equal
        } else if float_a.is_nan() {
            std::cmp::Ordering::Greater
        } else if float_b.is_nan() {
            std::cmp::Ordering::Less
        } else {
            float_a.partial_cmp(&float_b).unwrap_or(std::cmp::Ordering::Equal)
        }
    });
