use std::cmp::Ordering;

/// Return the indices that would sort `arr` in descending order.
///
/// Example:
/// let arr = [3.0, 1.0, 4.0, 2.0];
/// let idx = argsort_desc(&arr);
/// // idx == [2, 0, 3, 1] because arr[2]=4.0, arr[0]=3.0, arr[3]=2.0, arr[1]=1.0
pub fn argsort_desc<T: PartialOrd>(arr: &[T]) -> Vec<usize> {
    // Create index vector 0..n
    let mut idx: Vec<usize> = (0..arr.len()).collect();

    // Sort indices by comparing arr values in reverse (j before i) to get descending order.
    // For types where partial_cmp returns None (e.g. NaN for floats), we treat them as equal.
    idx.sort_by(|&i, &j| match arr[j].partial_cmp(&arr[i]) {
        Some(ord) => ord,
        None => Ordering::Equal,
    });

    idx
}

