use itertools::Itertools;

/// Ensures each inner group in a nested collection has exactly `target_size` elements
/// by appending `fill_element` to groups that are shorter.
///
/// # Arguments
/// * `nested_collection` - A vector of vectors to be padded
/// * `target_size` - The desired size for each inner group
/// * `fill_element` - The element to append to shorter groups
///
/// # Returns
