        .into_iter()
        .map(|mut group| {
            let current_len = group.len();
            if current_len < target_size {
                // Append fill_element until we reach target_size
                group.extend(itertools::repeat_n(fill_element.clone(), target_size - current_len));
            }
            group
        })
        .collect()
}

