use polars::prelude::*;
use serde_json::{Number, Value};
use std::collections::HashMap;

/// Convert a polars DataFrame into a Vec<HashMap<String, serde_json::Value>>
/// where each map is a row mapping column name -> cell value.
///
/// Returns a PolarsResult for convenient error propagation from polars.
pub fn dataframe_to_vec_map(df: &DataFrame) -> PolarsResult<Vec<HashMap<String, Value>>> {
    let height = df.height();
    let cols = df.get_columns();
    let mut rows: Vec<HashMap<String, Value>> = Vec::with_capacity(height);

    for row_idx in 0..height {
        let mut map = HashMap::with_capacity(cols.len());
        for s in cols {
            let key = s.name().to_string();
            let any = s.get(row_idx);

            let json_value = match any {
                AnyValue::Null => Value::Null,

                // Strings
                AnyValue::Utf8(v) => Value::String(v.to_string()),
                AnyValue::Utf8Owned(v) => Value::String(v),

                // Booleans
                AnyValue::Boolean(b) => Value::Bool(b),

                // Signed integers
                AnyValue::Int8(v) => Value::Number(Number::from(v as i64)),
                AnyValue::Int16(v) => Value::Number(Number::from(v as i64)),
                AnyValue::Int32(v) => Value::Number(Number::from(v as i64)),
                AnyValue::Int64(v) => Value::Number(Number::from(v)),

                // Unsigned integers
                AnyValue::UInt8(v) => Value::Number(Number::from(v as u64)),
                AnyValue::UInt16(v) => Value::Number(Number::from(v as u64)),
                AnyValue::UInt32(v) => Value::Number(Number::from(v as u64)),
                AnyValue::UInt64(v) => Value::Number(Number::from(v)),

                // Floats
                AnyValue::Float32(f) => {
                    // from_f64 expects f64; handle NaN/Inf by falling back to string
                    let f64v = f as f64;
                    if let Some(n) = Number::from_f64(f64v) {
                        Value::Number(n)
                    } else {
                        Value::String(f64v.to_string())
                    }
                }
                AnyValue::Float64(f) => {
                    if let Some(n) = Number::from_f64(f) {
                        Value::Number(n)
                    } else {
                        Value::String(f.to_string())
                    }
                }

                // Date/time/duration and other typed values: fall back to string
                AnyValue::Date32(v) => Value::String(v.to_string()),
                AnyValue::Date64(v) => Value::String(v.to_string()),
                AnyValue::Time64(v) => Value::String(v.to_string()),
                AnyValue::Duration(v, _) => Value::String(v.to_string()),

                // Lists, Structs, Objects, Categorical etc. -> string representation
                // (You can extend handling here to produce nested JSON for lists/structs.)
                _ => Value::String(any.to_string()),
            };

            map.insert(key, json_value);
        }
        rows.push(map);
    }

    Ok(rows)
}

