/// Replace entries that consist only of whitespace in string columns of `df`
/// with the designated missing-value indicator.
///
/// - `df`: mutable reference to a polars::DataFrame
/// - `missing`: if `Some(s)`, whitespace-only entries are replaced with that string;
///              if `None`, they are replaced with a true null value.
///
/// Returns PolarsResult<()>.
pub fn replace_whitespace_with_missing(df: &mut DataFrame, missing: Option<&str>) -> PolarsResult<()> {
    let mut new_cols: Vec<Series> = Vec::with_capacity(df.width());

    for s in df.get_columns() {
        match s.dtype() {
            DataType::Utf8 => {
                // Safe to unwrap because dtype is Utf8
                let utf8 = s.utf8()?;
                // Map each Option<&str> to Option<String>, turning whitespace-only to missing
                let mapped: Vec<Option<String>> = utf8
                    .into_iter()
                    .map(|opt| match opt {
                        Some(v) if v.trim().is_empty() => missing.map(|m| m.to_string()),
                        Some(v) => Some(v.to_string()),
                        None => None,
                    })
                    .collect();

                let new_series = Series::new(s.name(), mapped);
                new_cols.push(new_series);
            }
            _ => {
                // Non-string column: keep as-is
                new_cols.push(s.clone());
            }
        }
    }

    // Rebuild dataframe from new columns and replace the input df
    *df = DataFrame::new(new_cols)?;
    Ok(())
