    for key_item in keys {
        let kref = key_item.borrow();
        // preserve first occurrence order; skip if already inserted
        if out.contains_key(kref) {
            continue;
        }
        if let Some(v) = src.get(kref) {
            out.insert(kref.clone(), v.clone());
        }
    }
    out
}

