use itertools::Itertools;

/// Checks whether each element of the first sequence is smaller than
/// the corresponding element of the second sequence at the same index.
/// 
/// Returns true if all elements satisfy: seq1[i] < seq2[i]
/// Returns false if sequences have different lengths or any element fails the comparison.
fn all_smaller<T: PartialOrd>(seq1: &[T], seq2: &[T]) -> bool {
    seq1.iter()
        .zip_longest(seq2.iter())
        .all(|pair| match pair {
            itertools::EitherOrBoth::Both(a, b) => a < b,
            _ => false, // Different lengths
        })
}

