pub fn count_unique_values(df: &DataFrame, column_name: &str) -> PolarsResult<DataFrame> {
    // Get the column as a Series
    let series = df.column(column_name)?.clone();

    // Count occurrences: map stringified value -> count
    let mut counts: HashMap<String, u32> = HashMap::new();
    for val in series.iter() {
        let key = match val {
            AnyValue::Null => "__NULL__".to_string(),
            other => other.to_string(),
        };
        *counts.entry(key).or_insert(0) += 1;
    }

    // Build sorted vectors for deterministic output
    let mut keys: Vec<String> = counts.keys().cloned().collect();
    keys.sort();
    let counts_vec: Vec<u32> = keys.iter().map(|k| counts[k]).collect();

    // Create Series and DataFrame
    let s_values = Series::new(column_name, keys);
    let s_counts = Series::new("count", counts_vec);

    DataFrame::new(vec![s_values, s_counts])
}
