use smallvec::SmallVec;

/// Efficiently removes elements from an ordered collection where the predicate returns true.
/// Uses SmallVec for stack allocation of small collections, avoiding heap allocation.
/// 
/// # Arguments
/// * `collection` - A mutable reference to a SmallVec containing elements
/// * `predicate` - A function that returns true for elements to be removed
///
/// # Example
/// ```
/// use smallvec::smallvec;
/// 
/// let mut numbers = smallvec![1, 2, 3, 4, 5, 6];
/// remove_if(&mut numbers, |x| *x % 2 == 0);
/// assert_eq!(numbers.as_slice(), &[1, 3, 5]);
/// ```
pub fn remove_if<T, F>(collection: &mut SmallVec<[T; 8]>, mut predicate: F)
where
    F: FnMut(&T) -> bool,
{
    let mut write_idx = 0;

    for read_idx in 0..collection.len() {
        if !predicate(&collection[read_idx]) {
            if write_idx != read_idx {
                collection.swap(write_idx, read_idx);
            }
            write_idx += 1;
        }
    }

    collection.truncate(write_idx);
}

