use itertools::Itertools;

/// Efficiently removes elements from a Vec based on a predicate function.
/// 
/// Returns a new Vec containing only elements that DON'T match the predicate.
/// This is useful when removing a small number of elements from a large collection.
///
/// # Arguments
/// * `collection` - The ordered collection to filter
/// * `predicate` - A function that returns true for elements to remove
///
/// # Example
/// ```
/// let numbers = vec![1, 2, 3, 4, 5, 6];
/// let result = remove_elements(numbers, |&x| x % 2 == 0);
/// assert_eq!(result, vec![1, 3, 5]);
/// ```
fn remove_elements<T, F>(collection: Vec<T>, predicate: F) -> Vec<T>
where
    F: Fn(&T) -> bool,
{
    collection
        .into_iter()
        .filter(|item| !predicate(item))
        .collect()
}

/// In-place removal variant for even better performance with Vec.
/// Removes elements that match the predicate and returns the count removed.
///
/// # Arguments
/// * `collection` - The ordered collection to filter in-place
/// * `predicate` - A function that returns true for elements to remove
///
/// # Returns
