/// let removed = remove_elements_in_place(&mut numbers, |&x| x % 2 == 0);
/// assert_eq!(removed, 3);
/// assert_eq!(numbers, vec![1, 3, 5]);
/// ```
fn remove_elements_in_place<T, F>(collection: &mut Vec<T>, predicate: F) -> usize
where
    F: Fn(&T) -> bool,
{
    let original_len = collection.len();
    collection.retain(|item| !predicate(item));
    original_len - collection.len()
}

