use polars::prelude::*;

/// Group df0 by `var0` and `var1`, and for each group retain only rows where
/// `filter_col` equals `filter_val` (filter_val provided as string).
///
/// - df0: input DataFrame
/// - var0, var1: grouping column names
/// - filter_col: the column to compare against filter_val
/// - filter_val: the value to match (as &str). The function will attempt to compare using
///   the column's native dtype (Utf8, i64, f64) and fall back to casting to Utf8 if needed.
///
/// Returns a new DataFrame containing only the retained rows.
pub fn filter_group_by_equals(
    df0: &DataFrame,
    var0: &str,
    var1: &str,
    filter_col: &str,
    filter_val: &str,
) -> PolarsResult<DataFrame> {
    let gb = df0.groupby(&[var0, var1])?;
    gb.apply(|group| {
        let series = group.column(filter_col)?;

        // Try utf8 comparison first
        if let Ok(utf8) = series.utf8() {
            let mask = utf8.equal(filter_val);
            group.filter(&mask)
        }
        // Try integer (i64) compare if column is integer
        else if let Ok(ca) = series.i64() {
            match filter_val.parse::<i64>() {
                Ok(v) => {
                    let mask = ca.equal(v);
                    group.filter(&mask)
                }
                Err(_) => Ok(group.head(Some(0))), // can't parse filter_val -> no rows match
            }
        }
        // Try float (f64) compare
        else if let Ok(ca) = series.f64() {
            match filter_val.parse::<f64>() {
                Ok(v) => {
                    let mask = ca.equal(v);
                    group.filter(&mask)
                }
                Err(_) => Ok(group.head(Some(0))),
            }
        }
        // Fallback: cast column to Utf8 and compare as string
        else {
            let s = series.cast(&DataType::Utf8)?;
            let utf8 = s.utf8()?;
            let mask = utf8.equal(filter_val);
            group.filter(&mask)
        }
    })
}

fn main() -> PolarsResult<()> {
