use polars::prelude::*;
use std::collections::HashSet;

/// Reorder the columns of `df0` using the names in `var0` and the ordering defined by indices in `var1`.
/// 
/// - `df0`: input DataFrame (not modified).
/// - `var0`: slice of column names (these must be present in `df0` if referenced).
/// - `var1`: slice of indices into `var0` defining the desired order.
/// 
/// Returns a new DataFrame with the new column order, or a Polars error.
pub fn reorder_df_columns(
    df0: &DataFrame,
    var0: &[&str],
    var1: &[usize],
) -> PolarsResult<DataFrame> {
    // Validate indices in var1
    if var1.iter().any(|&i| i >= var0.len()) {
        return Err(PolarsError::ShapeMisMatch(
            "var1 contains an index out of range of var0".into(),
        ));
    }

    // Build ordered list of column names according to var1 (skip duplicates)
    let mut seen: HashSet<String> = HashSet::new();
    let mut ordered: Vec<String> = Vec::with_capacity(df0.width());

    for &idx in var1 {
        let name = var0[idx];
        if seen.insert(name.to_string()) {
            // Ensure the column exists in df0
            if df0.column(name).is_err() {
                return Err(PolarsError::NotFound(format!(
                    "column '{}' (from var0[var1]) not found in DataFrame",
                    name
                )));
            }
            ordered.push(name.to_string());
        }
    }

    // Append remaining columns from df0 that were not listed in var0
    for col_name in df0.get_column_names() {
        if !seen.contains(&col_name) {
            ordered.push(col_name.clone());
        }
    }

    // Select columns in the new order
    df0.select(ordered)
}

