use serde_json::{Map, Value};

/// Transform a Vec<Map<String, Value>> (list of maps) into a Map<String, Map<String, Value>>
/// using each map's "key" entry as the key in the resulting map.
///
/// Rules:
/// - If a map has a "key" entry that is a string, that string becomes the result key.
/// - If "key" exists but is not a string, the Value::to_string() result is used as the key.
/// - If a map has no "key" entry, that map is skipped.
///
/// The function removes the "key" entry from the inner maps so it does not appear twice.
fn list_to_map_of_maps(lst0: Vec<Map<String, Value>>) -> Map<String, Map<String, Value>> {
    let mut out: Map<String, Map<String, Value>> = Map::new();

    for mut obj in lst0 {
        match obj.remove("key") {
            Some(Value::String(s)) => {
                out.insert(s, obj);
            }
            Some(v) => {
                // fallback: use the JSON textual form of the value as the key
                out.insert(v.to_string(), obj);
            }
            None => {
                // skip objects without a "key" entry; you could alternatively log or collect them
            }
        }
    }

    out
}

