    let mask0 = df0.column(var0)?.eq(val0.into())?;
    let mask1 = df0.column(var1)?.eq(val1.into())?;

    // Combine the masks with AND operation
    let combined_mask = mask0.and(&mask1)?;

    // Apply the combined mask to filter the DataFrame
    Ok(df0.lazy().filter(&combined_mask).collect()?)
}
