/// Partitions a 1D data sequence into k clusters using k-means algorithm.
/// Returns a vector of integer labels (0 to k-1) for each element.
///
/// # Arguments
/// * `arr0` - A slice of f64 values representing the 1D data sequence
/// * `k` - Number of clusters to partition into
/// * `max_iterations` - Maximum number of k-means iterations
/// * `seed` - Random seed for reproducibility
///
/// # Returns
/// * `Vec<usize>` - Cluster labels for each element (0-indexed)
pub fn kmeans_1d(
    arr0: &[f64],
    k: usize,
    max_iterations: usize,
    seed: u64,
) -> Vec<usize> {
    let n = arr0.len();
    if n == 0 || k == 0 || k > n {
        return vec![0; n]; // Edge case: return all zeros
    }

    // Convert to 2D array (n x 1) for compatibility with ndarray operations
    let data = Array2::from_shape_vec((n, 1), arr0.to_vec()).unwrap();

    // Initialize centroids using k-means++ style initialization
    let mut rng = Xoshiro256Plus::seed_from_u64(seed);
    let mut centroids: Vec<f64> = Vec::with_capacity(k);

    // First centroid: random data point
    let first_idx = rng.gen_range(0..n);
    centroids.push(data[[first_idx, 0]]);

    // Select remaining centroids with probability proportional to distance squared
    for _ in 1..k {
        let mut distances: Vec<f64> = Vec::with_capacity(n);
        for i in 0..n {
            let point = data[[i, 0]];
            let min_dist = centroids
                .iter()
                .map(|&c| (point - c).powi(2))
                .fold(f64::INFINITY, f64::min);
            distances.push(min_dist);
        }

        let total_dist: f64 = distances.iter().sum();
        let threshold = rng.gen::<f64>() * total_dist;
        let mut cumulative = 0.0;
        let mut selected_idx = 0;
        for (i, &dist) in distances.iter().enumerate() {
            cumulative += dist;
            if cumulative >= threshold {
                selected_idx = i;
                break;
            }
        }
        centroids.push(data[[selected_idx, 0]]);
    }

    // K-means iteration
    let mut labels: Vec<usize> = vec![0; n];
    let mut prev_centroids: Vec<f64>;

    for _iteration in 0..max_iterations {
        // Assignment step: assign each point to nearest centroid
        for i in 0..n {
            let point = data[[i, 0]];
            let mut min_dist = f64::INFINITY;
            let mut best_cluster = 0;

            for (j, &centroid) in centroids.iter().enumerate() {
                let dist = (point - centroid).abs();
                if dist < min_dist {
                    min_dist = dist;
                    best_cluster = j;
                }
            }
            labels[i] = best_cluster;
        }

        // Update step: recalculate centroids
        prev_centroids = centroids.clone();
        for j in 0..k {
            let cluster_points: Vec<f64> = labels
                .iter()
                .enumerate()
                .filter(|(_, &label)| label == j)
                .map(|(idx, _)| data[[idx, 0]])
                .collect();

            if !cluster_points.is_empty() {
                centroids[j] = cluster_points.iter().sum::<f64>() / cluster_points.len() as f64;
            }
        }

        // Check for convergence
        let has_converged = centroids
            .iter()
            .zip(prev_centroids.iter())
            .all(|(&new, &old)| (new - old).abs() < 1e-10);

        if has_converged {
            break;
        }
    }

    labels
}

