use polars::prelude::*;
use std::error::Error;

fn calculate_time_difference(df: &DataFrame) -> Result<DataFrame, Box<dyn Error>> {
    // Ensure col0 and col1 are of the correct type (Datetime or Time)
    let col0 = df.column("col0")?.cast(&DataType::Datetime(TimeUnit::Microseconds, None))?;
    let col1 = df.column("col1")?.cast(&DataType::Datetime(TimeUnit::Microseconds, None))?;

    // Calculate the difference between the two columns
    let duration = col1 & -col0;  // Note: The minus operator in Polars for time difference

    // Convert duration to hours and minutes
    let hours: Series = duration
        .cast::<Int64Type>()?
        .into_no_null_iter()
        .map(|diff| diff / 3600) // Convert seconds to hours
        .collect::<Vec<_>>()
        .into_series();

    let minutes: Series = duration
        .cast::<Int64Type>()?
        .into_no_null_iter()
        .map(|diff| (diff % 3600) / 60) // Calculate remaining minutes
        .collect::<Vec<_>>()
        .into_series();

    // Create a new DataFrame to hold the result
    let result_df = DataFrame::new(vec![hours.rename("hours"), minutes.rename("minutes")])?;
    Ok(result_df)
}

