fn calculate_time_difference(df0: &DataFrame, col0: &str, col1: &str) -> Result<DataFrame> {
    // Extract the time columns as Series
    let time_col0 = df0.column(col0)?;
    let time_col1 = df0.column(col1)?;

    // Ensure both columns are of type Time64Nanosecond
    if !time_col0.dtype().is_time() || !time_col1.dtype().is_time() {
        return Err(PolarsError::ComputeError("Both columns must be of time type".into()));
    }

    // Convert the Series to Vec<NaiveTime>
    let time_col0: Vec<Option<NaiveTime>> = time_col0.time64_nanosecond()?.into_iter().collect();
    let time_col1: Vec<Option<NaiveTime>> = time_col1.time64_nanosecond()?.into_iter().collect();

    // Calculate the duration between the two times for each row
    let mut durations = Vec::new();
    for (time0, time1) in time_col0.iter().zip(time_col1.iter()) {
        match (time0, time1) {
            (Some(t0), Some(t1)) => {
                let duration = if t0 > t1 {
                    Duration::seconds(86400) - (*t0 - *t1)
                } else {
                    *t1 - *t0
                };
                let hours = duration.num_hours();
