use polars::prelude::*;
use chrono::{NaiveTime, DateTime, FixedOffset};

/// Parse a time-like string into seconds (i64).
/// Supports:
/// - "HH:MM" and "HH:MM:SS[.fraction]" (parsed as time-of-day -> seconds since midnight)
/// - RFC3339 / ISO-8601 datetimes (parsed to epoch seconds)
fn parse_time_to_seconds(s: &str) -> Option<i64> {
    // Try time-of-day (no date) first
    if let Ok(t) = NaiveTime::parse_from_str(s, "%H:%M:%S%.f") {
        return Some(t.num_seconds_from_midnight() as i64);
    }
    if let Ok(t) = NaiveTime::parse_from_str(s, "%H:%M") {
        return Some(t.num_seconds_from_midnight() as i64);
    }

    // Try RFC3339 / ISO-8601 datetime with offset
    if let Ok(dt) = DateTime::parse_from_rfc3339(s) {
        return Some(dt.timestamp());
    }

    // Try a few common datetime formats without TZ (NaiveDateTime -> treat as local-like)
    // e.g. "2023-04-01 15:04:05" or "2023-04-01T15:04:05"
    if let Ok(naive) = chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S") {
        // treat as naive UTC
        return Some(naive.timestamp());
    }
    if let Ok(naive) = chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S") {
        return Some(naive.timestamp());
    }

    None
}

/// Add a new column "diff_h_m" to df0 containing the difference (col1 - col0)
/// expressed in "H:MM" with a leading "-" for negative intervals. Accepts
/// columns that are Utf8 strings representing either times of day ("HH:MM",
/// "HH:MM:SS") or datetimes (RFC3339 / ISO-8601). Missing or unparsable
/// values produce nulls in the output.
///
/// Example output: "2:05", "-1:30", "0:00"
pub fn add_time_diff_hm(mut df0: DataFrame) -> PolarsResult<DataFrame> {
    // Ensure columns exist
    let col0_series = df0.column("col0")?;
    let col1_series = df0.column("col1")?;

    // We'll work with Utf8 representations. If columns are not Utf8, cast them.
    let col0_utf8 = if col0_series.dtype() == &DataType::Utf8 {
        col0_series.utf8()?
    } else {
        df0.apply_at_idx(
            df0.find_idx_by_name("col0").unwrap(),
            |s| s.cast(&DataType::Utf8),
        )?;
        df0.column("col0")?.utf8()?
    };

    let col1_utf8 = if col1_series.dtype() == &DataType::Utf8 {
        col1_series.utf8()?
    } else {
        df0.apply_at_idx(
            df0.find_idx_by_name("col1").unwrap(),
            |s| s.cast(&DataType::Utf8),
        )?;
        df0.column("col1")?.utf8()?
    };

    let len = col0_utf8.len();
    let mut out: Vec<Option<String>> = Vec::with_capacity(len);

    for i in 0..len {
        match (col0_utf8.get(i), col1_utf8.get(i)) {
            (Some(a), Some(b)) => {
                if let (Some(sec0), Some(sec1)) = (parse_time_to_seconds(a), parse_time_to_seconds(b)) {
                    let diff = sec1 - sec0;
                    let sign = if diff < 0 { "-" } else { "" };
                    let abs = diff.abs();

                    let hours = abs / 3600;
                    let minutes = (abs % 3600) / 60;

                    out.push(Some(format!("{}{}:{:02}", sign, hours, minutes)));
                } else {
                    // parsing failed for one or both values -> null
                    out.push(None);
                }
            }
            _ => {
                // any null input -> null output
                out.push(None);
            }
        }
    }

    let diff_series = Series::new("diff_h_m", out);
    df0.with_column(diff_series)
}

