use polars::prelude::*;

/// Extract row identifiers from a labeled 2D table (Polars DataFrame).
///
/// Behavior:
/// - If the DataFrame contains a column called "index", "idx", "id", "row_id" or "row",
///   returns that column's values converted to strings (preserving order).
/// - Otherwise returns the row numbers "0", "1", ..., as strings.
///
/// Returns a Vec<String> or a Polars error.
pub fn extract_row_identifiers(input_table: &DataFrame) -> Result<Vec<String>, PolarsError> {
    // candidate column names that commonly hold an index
    let candidates = ["index", "idx", "id", "row_id", "row"];

    for &name in &candidates {
        if input_table.get_column_names().iter().any(|n| n == name) {
            let s = input_table.column(name)?;
            // Convert all values in the series to strings
            // We handle common text/int/datetime types but fall back to AnyValue::to_string
            let mut ids = Vec::with_capacity(s.len());
            match s.dtype() {
                DataType::Utf8 => {
                    let ca = s.utf8()?;
                    for opt in ca.into_iter() {
                        ids.push(opt.unwrap_or("").to_string());
                    }
                }
                DataType::Int8
                | DataType::Int16
                | DataType::Int32
                | DataType::Int64
                | DataType::UInt8
                | DataType::UInt16
                | DataType::UInt32
                | DataType::UInt64
                | DataType::Float32
                | DataType::Float64
                | DataType::Boolean
                | DataType::Date
                | DataType::Datetime(_, _) => {
                    // For numeric/boolean/date-like, simply iterate and to_string each value
                    for val in s.iter() {
                        ids.push(val.to_string());
                    }
                }
                _ => {
                    // Generic fallback for other/complex types
                    for val in s.iter() {
                        ids.push(val.to_string());
                    }
                }
            }
            return Ok(ids);
        }
    }

    // No index-like column found: fall back to row numbers as identifiers
    let n = input_table.height();
    Ok((0..n).map(|i| i.to_string()).collect())
}

