/// ```
fn remove_duplicates<T: Eq + std::hash::Hash>(lst0: Vec<T>) -> Vec<T> {
    let mut seen = IndexSet::new();
    lst0.into_iter()
        .filter(|item| seen.insert(item.clone()))
        .collect()
}

