/// Processes a nested dictionary and returns a mapping of top-level keys to their inner keys.
///
/// # Arguments
/// * `dict0` - A nested dictionary (serde_json::Value) where each top-level key maps to another dictionary.
///
/// # Returns
/// A new dictionary where each top-level key maps to a list of its inner keys.
///
/// # Example
/// ```
/// use serde_json::json;
/// let input = json!({
///     "a": {"x": 1, "y": 2},
///     "b": {"p": 3, "q": 4, "r": 5},
///     "c": {"single": 6}
/// });
/// let output = flatten_dict_keys(&input);
/// assert_eq!(output, json!({
///     "a": ["x", "y"],
///     "b": ["p", "q", "r"],
///     "c": ["single"]
/// }));
/// ```
pub fn flatten_dict_keys(dict0: &Value) -> Value {
    // First validate that the input is a Map (object)
    let dict = if let Value::Object(map) = dict0 {
        map
    } else {
        return Value::Object(Map::new());
    };

    // Process each top-level key-value pair
    let mut result_map = Map::new();

    for (top_key, inner_value) in dict {
        // Only process if the inner value is also an object
        if let Value::Object(inner_map) = inner_value {
            // Collect all keys from the inner map
            let inner_keys: Vec<String> = inner_map.keys().cloned().collect();

            // Add to the result map
            result_map.insert(top_key.clone(), Value::Array(inner_keys.into()));
        }
    }

    Value::Object(result_map)
}

