///     let df = df!(
///         "A" => &[1, 2, 1, 3, 2],
///         "B" => &[10, 20, 15, 5, 18],
///         "C" => &["x", "y", "x", "z", "y"]
///     )?;
///
///     let result = group_by_max(&df, "C", "B")?;
///     println!("{:?}", result);
///     Ok(())
/// }
/// ```
pub fn group_by_max(df: &DataFrame, group_by_col: &str, max_col: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Check if columns exist
    if !df.column(group_by_col).is_ok() {
        return Err(format!("Column '{}' not found", group_by_col).into());
    }
    if !df.column(max_col).is_ok() {
        return Err(format!("Column '{}' not found", max_col).into());
    }

    // Group by the specified column
    let grouped = df.lazy()
        .group_by([group_by_col])
        .agg([col(max_col).max()])
        .collect()?;

    // Join back with the original data to get the full rows
    let max_values = grouped.column(max_col).unwrap();

    // Create a temporary DataFrame with just the group key and max values
    let temp_df = DataFrame::new(vec![
        Series::new(group_by_col, grouped.column(group_by_col).unwrap().clone()),
        Series::new(max_col, max_values),
    ])?;

    // Filter the original DataFrame to find rows that match the max values
    let filtered = df.lazy()
        .join(
            temp_df.lazy(),
            [group_by_col],
            [group_by_col],
            JoinType::Inner,
        )
        .filter(col(max_col).eq(col(max_col).alias("max_val")))
        .select([col(group_by_col), col(max_col).alias("max_val"), col("max_val")])
        .collect()?;

    // Keep only the first occurrence of each group (which will be the max)
    let result = filtered.lazy()
        .group_by([group_by_col])
        .first()
        .collect()?;

    Ok(result)
}

