use itertools::izip;

/// Computes the sum of the element-wise products of two sequences.
///
/// # Arguments
///
/// * `seq1` - A slice of integers representing the first sequence.
/// * `seq2` - A slice of integers representing the second sequence.
///
/// # Returns
///
/// The sum of the element-wise products of the two sequences.
///
/// # Examples
///
/// ```
/// let seq1 = [1, 2, 3];
/// let seq2 = [4, 5, 6];
/// assert_eq!(sum_of_elementwise_products(&seq1, &seq2), 32);
/// ```
fn sum_of_elementwise_products(seq1: &[i32], seq2: &[i32]) -> i32 {
    izip!(seq1, seq2)
        .map(|(&a, &b)| a * b)
        .sum()
}

fn main() {
    let seq1 = [1, 2, 3];
    let seq2 = [4, 5, 6];
    println!("The sum of element-wise products is: {}", sum_of_elementwise_products(&seq1, &seq2));
}
```

