use polars::prelude::*;
use anyhow::Result;

/// Append a new row to `df0` using string representations in `lst0` and
/// assign the new row the label `str0` by placing that label in a column named "label".
/// If "label" does not exist in df0 it will be created (existing rows get null label).
///
/// Parameters:
/// - df0: input DataFrame (consumed)
/// - lst0: values for the new row as strings; must match number of columns excluding "label"
/// - str0: label to assign to the new row (stored as Utf8 in column "label")
///
/// Returns: a new DataFrame with the appended row.
///
/// Example usages are in main().
fn append_row_with_label_from_strings(
    mut df0: DataFrame,
    lst0: Vec<&str>,
    str0: &str,
) -> PolarsResult<DataFrame> {
    // name of the label column we use
    let label_col = "label";

    // Ensure label column exists and is Utf8; if missing, create it with nulls.
    if let Ok(idx) = df0.find_idx_by_name(label_col) {
        // Ensure it's Utf8
        let dtype = df0.dtypes()[idx].clone();
        if dtype != DataType::Utf8 && dtype != DataType::Utf8 {
            return Err(PolarsError::SchemaMisMatch(
                format!("Existing '{}' column must be Utf8", label_col).into(),
            ));
        }
    } else {
        // Create a Utf8 column of nulls with length df0.height()
        let n = df0.height();
        let null_label_series = Series::full_null(label_col, n, &DataType::Utf8)?;
        // with_column consumes self and returns a new DataFrame
        df0 = df0.with_column(null_label_series)?;
    }

    // Now column order and dtypes
    let col_names = df0.get_column_names();
    // The values in lst0 should correspond to all columns except the label column.
    let num_expected = col_names.len() - 1; // excluding label
    if lst0.len() != num_expected {
        return Err(PolarsError::ShapeMisMatch(
            format!(
                "Number of provided values ({}) does not match number of data columns ({})",
                lst0.len(),
                num_expected
            )
            .into(),
        ));
    }

    // Build a vector of Series that each contain the single value for the new row,
    // in the same order as df0's columns.
    let mut new_row_series: Vec<Series> = Vec::with_capacity(col_names.len());
    let mut val_iter = lst0.into_iter();

    for cname in col_names.iter() {
        if cname == &label_col {
            // label column: use provided label (Utf8)
            let s = Series::new(label_col, &[str0]);
            new_row_series.push(s);
            continue;
        }

        // get dtype of this column
        let dtype = df0.column(cname)?.dtype().clone();

        // get next string value
        let sval = val_iter.next().expect("checked lengths above");

        // create a one-element Series matching the dtype
        let s = match dtype {
            DataType::Utf8 => Series::new(cname.as_str(), &[sval]),
            DataType::Int64 => {
                let v = sval.parse::<i64>().map_err(|e| {
                    PolarsError::ComputeError(format!("Cannot parse '{}' as i64: {}", sval, e).into())
                })?;
                Series::new(cname.as_str(), &[v])
            }
            DataType::Int32 => {
                let v = sval.parse::<i32>().map_err(|e| {
                    PolarsError::ComputeError(format!("Cannot parse '{}' as i32: {}", sval, e).into())
                })?;
                Series::new(cname.as_str(), &[v])
            }
            DataType::UInt64 => {
                let v = sval.parse::<u64>().map_err(|e| {
                    PolarsError::ComputeError(format!("Cannot parse '{}' as u64: {}", sval, e).into())
                })?;
                Series::new(cname.as_str(), &[v])
            }
            DataType::UInt32 => {
                let v = sval.parse::<u32>().map_err(|e| {
