                    AnyValue::String(v) => Series::new(name, &[*v]),
                    AnyValue::Int32(v) => Series::new(name, &[*v]),
                    AnyValue::Int64(v) => Series::new(name, &[*v]),
                    AnyValue::Float32(v) => Series::new(name, &[*v]),
                    AnyValue::Float64(v) => Series::new(name, &[*v]),
