use std::collections::HashMap;
use std::hash::Hash;
use indexmap::IndexMap;

/// Return an IndexMap containing the entries of `dict0` ordered ascending by the second
/// element of each value pair.
///
/// K: key type (Eq + Hash + Clone)
/// V1: first element of value pair (Clone)
/// V2: second element of value pair (Ord + Clone) -- used for sorting
fn sort_by_second<K, V1, V2>(
    dict0: &HashMap<K, (V1, V2)>
) -> IndexMap<K, (V1, V2)>
where
    K: Eq + Hash + Clone,
    V1: Clone,
    V2: Ord + Clone,
{
    // Collect entries, clone them (don't mutate original)
    let mut entries: Vec<(K, (V1, V2))> = dict0
        .iter()
        .map(|(k, (a, b))| (k.clone(), (a.clone(), b.clone())))
        .collect();

    // Sort by the second element of the value tuple (ascending)
    entries.sort_by(|x, y| x.1 .1.cmp(&y.1 .1));

    // Insert into an IndexMap in sorted order to preserve that order
    let mut ordered = IndexMap::with_capacity(entries.len());
    for (k, v) in entries {
        ordered.insert(k, v);
    }
    ordered
}

