use anyhow::{Context, Result};
use regex::Regex;

fn replace_nth_occurrence(sentence: &str, target_word: &str, replacement_word: &str, n: usize) -> Result<String> {
    // Create a regex pattern to match the target word
    let pattern = Regex::new(&format!(r"\b{}\b", regex::escape(target_word)))
        .context("Failed to create regex pattern")?;

    // Find all occurrences of target_word in the sentence
    let mut occurrences = 0;
    let result = pattern.replace_all(sentence, |caps: &regex::Captures| {
        occurrences += 1;
        if occurrences == n {
            replacement_word.to_string() // Replace on the n-th occurrence
        } else {
            caps[0].to_string() // Keep other occurrences unchanged
        }
    });

    // If the n-th occurrence does not exist, return an error
    if occurrences < n {
        anyhow::bail!("The {}-th occurrence of the word '{}' does not exist.", n, target_word);
    }

    Ok(result.to_string())
}

fn main() -> Result<()> {
