/// with `replacement`. If the specified occurrence doesn't exist, returns the original string.
///
/// - `sentence` (var0): the input text
/// - `target`   (var1): the word to find (matched as a whole word)
/// - `replacement` (var2): the text to replace the matched occurrence with
/// - `occurrence` (var3): 1-based index of which occurrence to replace
///
/// Note: matching is case-sensitive. `occurrence == 0` returns the original string.
pub fn replace_nth_occurrence(
    sentence: &str,
    target: &str,
    replacement: &str,
    occurrence: usize,
) -> String {
    if target.is_empty() || occurrence == 0 {
        return sentence.to_string();
    }

    // Build a regex that matches the target as a whole word.
    // We escape target to treat any regex metacharacters literally.
    let pattern = format!(r"\b{}\b", regex::escape(target));
    let re = match Regex::new(&pattern) {
        Ok(r) => r,
        Err(_) => return sentence.to_string(), // fallback: invalid regex (should not happen)
