/// ).unwrap();
/// 
/// let result = check_value_in_list_column(&df, "lst0", &3).unwrap();
/// assert_eq!(result, true);
/// ```
pub fn check_value_in_list_column<T: PolarsNumericType>(
    df: &DataFrame,
    list_column: &str,
    value: T::Native,
) -> PolarsResult<bool> {
    // Get the list column as a Series
    let list_series = df.column(list_column)?;

    // Convert to ListChunked
    let list_chunked = list_series.list()?;

    // Check if the value is present in any of the lists
    let result = list_chunked
        .into_iter()
        .flatten() // Flatten Option<Series> to Series
        .any(|series| {
            // Check if the value exists in this particular list
            series
                .as_ref()
                .ok()
                .and_then(|s| {
                    // For numeric types, we can use the contains method
                    s.contiguous()
                        .ok()
                        .and_then(|arr| {
                            let arr = arr.as_any().downcast_ref::<PrimitiveArray<T>>()?;
                            Some(arr.values().iter().any(|&x| x == value))
                        })
                })
                .unwrap_or(false)
        });

    Ok(result)
}

// Alternative implementation using expression API (more idiomatic Polars)
pub fn check_value_in_list_column_expr<T: PolarsNumericType>(
    df: &DataFrame,
    list_column: &str,
    value: T::Native,
) -> PolarsResult<bool> {
    // Create an expression that checks if the value is in any list
    let expr = col(list_column).list().contains(lit(value));

