Rust code:

```rust
use itertools::Itertools;

/// Result for a single position when comparing two lists.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CompareResult {
    Equal,      // both lists have an element at this position and they are equal
    NotEqual,   // both lists have an element at this position and they differ
    LeftOnly,   // only list0 has an element at this position
    RightOnly,  // only list1 has an element at this position
}

/// Compare two slices by iterating them in parallel and returning per-position results.
///
/// - If both slices have an element at a position, returns Equal or NotEqual depending on PartialEq.
/// - If only one slice has an element at a position (different lengths), returns LeftOnly or RightOnly.
///
/// Generic over T: T must implement PartialEq.
pub fn compare_lists<T: PartialEq>(list0: &[T], list1: &[T]) -> Vec<CompareResult> {
    list0
        .iter()
        .zip_longest(list1.iter())
        .map(|pair| match pair {
            itertools::EitherOrBoth::Both(a, b) => {
                if a == b {
                    CompareResult::Equal
                } else {
                    CompareResult::NotEqual
                }
            }
            itertools::EitherOrBoth::Left(_) => CompareResult::LeftOnly,
            itertools::EitherOrBoth::Right(_) => CompareResult::RightOnly,
        })
        .collect()
}

fn main() {
    let a = vec![1, 2, 3, 4];
    let b = vec![1, 9, 3];

    let result = compare_lists(&a, &b);
    println!("{:?}", result);
    // Output: [Equal, NotEqual, Equal, LeftOnly]
}

