    fn test_same_length() {
        let a = [1, 2, 3];
        let b = [1, 0, 3];
        assert_eq!(
            compare_lists(&a, &b),
            vec![CompareResult::Equal, CompareResult::NotEqual, CompareResult::Equal]
        );
    }

    #[test]
    fn test_different_lengths() {
        let a = [1, 2];
        let b = [1, 2, 3, 4];
        assert_eq!(
            compare_lists(&a, &b),
            vec![
                CompareResult::Equal,
                CompareResult::Equal,
                CompareResult::RightOnly,
                CompareResult::RightOnly
            ]
        );
    }

    #[test]
    fn test_empty() {
        let a: [i32; 0] = [];
        let b = [1, 2];
        assert_eq!(
