use itertools::Itertools;
use std::collections::HashMap;

fn reorder_list<T: Eq + std::hash::Hash + Clone>(lst0: &[T], lst1: &[T]) -> Vec<T> {
    // Create a mapping from values in lst1 to their indices
    let index_map: HashMap<_, _> = lst1.iter().enumerate().map(|(index, value)| (value.clone(), index)).collect();

    // Sort lst0 based on the indices in lst1, keeping elements not found in lst1 at the end
    let mut sorted_lst0: Vec<_> = lst0.iter().cloned().collect();
    sorted_lst0.sort_by(|a, b| {
        let index_a = index_map.get(a).unwrap_or(&usize::MAX);
        let index_b = index_map.get(b).unwrap_or(&usize::MAX);
        index_a.cmp(index_b)
