use std::collections::HashMap;

/// Reorders elements of `lst0` to follow the ordering defined by `lst1`.
/// Elements not present in `lst1` are appended at the end in their original relative order.
/// Optimized for cases where `lst1` (the reference list) is very large.
///
/// # Arguments
/// * `lst0` - The list to reorder
/// * `lst1` - The reference list defining the desired order (assumed to be sorted)
///
/// # Returns
/// A new Vec containing the reordered elements
pub fn reorder_by_reference<T: Clone + Eq + std::hash::Hash>(
    lst0: &[T],
    lst1: &[T],
) -> Vec<T> {
    // Build a position map from lst1 for O(1) lookups
    // This is the key optimization for large reference lists
    let position_map: HashMap<&T, usize> = lst1
        .iter()
        .enumerate()
        .map(|(i, item)| (item, i))
        .collect();

    // Separate elements into those found in lst1 and those not found
    let mut found: Vec<(&T, usize)> = Vec::with_capacity(lst0.len().min(lst1.len()));
    let mut not_found: Vec<&T> = Vec::with_capacity(lst0.len());

    for item in lst0 {
        match position_map.get(item) {
            Some(&position) => found.push((item, position)),
            None => not_found.push(item),
        }
    }

    // Sort found elements by their position in lst1
    found.sort_by_key(|&(_, position)| position);

    // Combine results: sorted found elements first, then not-found elements
    let mut result: Vec<T> = Vec::with_capacity(lst0.len());
    result.extend(found.into_iter().map(|(item, _)| item.clone()));
    result.extend(not_found.into_iter().cloned());

    result
}

