/// ```
pub fn reorder_by_reference<T: Eq + std::hash::Hash + Clone>(
    lst0: &[T],
    lst1: &[T],
) -> Vec<T> {
    // Create a position map for O(1) lookups
    let position_map: IndexMap<&T, usize> = lst1
        .iter()
        .enumerate()
        .map(|(idx, item)| (item, idx))
