    if let Some(order) = lst0 {
        // Build expressions for selection in requested order.
        // If any name in `order` doesn't exist, polars' select will return an error.
        let exprs: Vec<Expr> = order.iter().map(|s| col(s.as_str())).collect();
        df = df.select(&exprs)?;
    }

    Ok(df)
}

