use polars::prelude::*;
use std::collections::HashMap;

/// Rename column headers of a DataFrame according to a mapping or ordered sequence.
///
/// # Arguments
/// * `df0` - The input DataFrame to rename columns on
/// * `dict0` - Optional HashMap mapping old column names to new column names
/// * `lst0` - Optional ordered sequence of new column names (must match number of columns)
///
/// # Returns
/// * `Result<DataFrame>` - The renamed DataFrame or an error
///
/// # Behavior
/// - If `dict0` is provided, columns are renamed according to the mapping
/// - If `lst0` is provided, columns are renamed in order (must have same length as columns)
/// - If both are provided, `dict0` takes precedence
/// - If neither is provided, returns the original DataFrame unchanged
pub fn rename_columns(
    df0: &DataFrame,
    dict0: Option<&HashMap<String, String>>,
    lst0: Option<&[String]>,
) -> PolarsResult<DataFrame> {
    // If dict0 is provided, use it for renaming
    if let Some(mapping) = dict0 {
        let mut renamed_df = df0.clone();
        for (old_name, new_name) in mapping {
            if renamed_df.get_column_names().contains(&old_name.as_str()) {
                renamed_df = renamed_df.rename(old_name, new_name)?;
            }
        }
        return Ok(renamed_df);
    }

    // If lst0 is provided, rename columns in order
    if let Some(new_names) = lst0 {
        let current_names = df0.get_column_names();

        // Validate length matches
        if new_names.len() != current_names.len() {
            return Err(PolarsError::ComputeError(
                format!(
                    "Number of new names ({}) doesn't match number of columns ({})",
                    new_names.len(),
                    current_names.len()
                )
                .into(),
            ));
        }

        let mut renamed_df = df0.clone();
        for (i, new_name) in new_names.iter().enumerate() {
            let old_name = current_names[i];
            renamed_df = renamed_df.rename(old_name, new_name)?;
        }
        return Ok(renamed_df);
    }

    // If neither is provided, return original
    Ok(df0.clone())
}

// Example usage
