/// Rename DataFrame columns using a mapping dictionary
fn rename_columns_by_mapping(
    df: &mut DataFrame,
    mapping: &HashMap<String, String>,
) -> Result<DataFrame, PolarsError> {
    let new_names: Vec<String> = df
        .get_column_names()
        .iter()
        .map(|name| {
            mapping
                .get(&name.to_string())
                .cloned()
                .unwrap_or_else(|| name.to_string())
