    df: &mut DataFrame,
    new_names: &[String],
) -> Result<DataFrame, PolarsError> {
    if new_names.len() != df.width() {
        return Err(PolarsError::ComputeError(
            "Number of new names must match number of columns".into(),
        ));
    }

    df.rename(new_names)
}

