```rust
use datafusion::arrow::array::Float64Array;
use datafusion::datasource::file_format::csv::CsvFormat;
use datafusion::datasource::listing::ListingOptions;
use datafusion::error::DataFusionError;
use datafusion::prelude::*;
use std::sync::Arc;

/// Synchronously compute the sum of `column` for rows in CSV `csv_path` that satisfy SQL `filter`.
///
/// `filter` should be a SQL WHERE-style expression (e.g. "age > 30 AND country = 'US'").
/// The function casts the column to DOUBLE for summation; non-numeric values will cause query error.
///
/// Returns the sum as f64. If there are no matching rows or the sum is NULL, returns 0.0.
///
/// Example:
/// let s = sum_column_from_csv("data.csv", "salary", "age > 30")?;
pub fn sum_column_from_csv(
    csv_path: &str,
    column: &str,
    filter: &str,
) -> Result<f64, Box<dyn std::error::Error + Send + Sync>> {
    // Use a tokio runtime to run the async DataFusion calls
    let rt = tokio::runtime::Runtime::new()?;
    rt.block_on(sum_column_from_csv_async(csv_path, column, filter))
}

async fn sum_column_from_csv_async(
    csv_path: &str,
    column: &str,
    filter: &str,
) -> Result<f64, Box<dyn std::error::Error + Send + Sync>> {
    // Create session context
    let ctx = SessionContext::new();

    // Register the CSV file as a table named "t".
    // Adjust CsvReadOptions as needed (delimiter, header presence, schema inference, etc.)
    let read_options = CsvReadOptions::new()
        .has_header(true)
        .infer_schema(Some(100)); // inspect up to 100 rows to infer schema; tune as desired

    ctx.register_csv("t", csv_path, read_options).await?;

    // Quote the column name to avoid SQL injection or syntax issues (double-quote as SQL identifier)
    // This naive quoting doubles any internal double quotes to escape them.
    let quoted_col = format!("\"{}\"", column.replace('"', "\"\""));

    // Build SQL: cast column to DOUBLE and compute SUM
    // The filter is expected to be a valid SQL WHERE expression.
    let sql = format!(
        "SELECT SUM(CAST({} AS DOUBLE)) AS sum_value FROM t WHERE {}",
        quoted_col, filter
    );

    // Execute the query
    let df = ctx.sql(&sql).await?;
    let batches = df.collect().await?;

    // If no batches or no rows, return 0.0
    if batches.is_empty() {
        return Ok(0.0);
    }
    let batch = &batches[0];
    if batch.num_rows() == 0 || batch.num_columns() == 0 {
        return Ok(0.0);
    }

    // Expect the first column to be a Float64Array (SUM(CAST(... AS DOUBLE)) -> Double)
    let array_any = batch.column(0);
    let float_array = array_any
        .as_any()
        .downcast_ref::<Float64Array>()
        .ok_or_else(|| {
            DataFusionError::Execution(
                "unexpected result type: expected Float64Array from SUM(...)".to_string(),
            )
        })?;

    // SUM returns a single scalar (one row). If it's NULL, return 0.0.
    if float_array.is_null(0) {
        Ok(0.0)
    } else {
        Ok(float_array.value(0))
    }
}
```

Notes and tips:
- The filter must be a valid SQL WHERE expression (DataFusion SQL). For example:
  - "age > 30 AND country = 'US'"
  - "score >= 50"
  - Use single quotes for string literals in the filter.
- If your data is in another format (Parquet, Arrow IPC, in-memory record batches), DataFusion can register those sources as well.
- If you want to treat NULLs differently (e.g., propagate NULL instead of returning 0.0), adjust the logic accordingly.
- If your column name contains special characters, the function quotes it as an SQL identifier. If you need more advanced identifier handling, refine the quoting to match your schema.

