use ndarray::Array2;

/// Return true if `row0` is present as a row in `arr0`.
///
/// - `row0` is a slice representing the target row.
/// - `arr0` is a slice of `Vec<T>` representing the 2D sequence (each inner Vec is a row).
/// - The elements type `T` must implement `PartialEq` and `Clone`.
///
/// Rows in `arr0` that have a different length than `row0` make the function return false
/// (you can change this behavior to skip such rows if you prefer).
pub fn row_present<T: PartialEq + Clone>(row0: &[T], arr0: &[Vec<T>]) -> bool {
    if arr0.is_empty() || row0.is_empty() {
        return false;
    }

    let rows = arr0.len();
    let cols = row0.len();

    // Ensure all rows have the same length as the target row.
    if arr0.iter().any(|r| r.len() != cols) {
        return false;
    }

    // Flatten arr0 into a single Vec<T> and build an Array2.
    let flat: Vec<T> = arr0.iter().flat_map(|r| r.clone()).collect();
    let matrix = match Array2::from_shape_vec((rows, cols), flat) {
        Ok(m) => m,
        Err(_) => return false,
    };

    // Build a 1-row Array2 from row0 and get a row view for comparison.
    let target_row = match Array2::from_shape_vec((1, cols), row0.to_vec()) {
        Ok(m) => m.row(0),
        Err(_) => return false,
    };

    // Check each row for equality with target_row
    for r in matrix.rows() {
        if r == target_row {
            return true;
        }
    }
    false
}

