```rust
use unicode_segmentation::UnicodeSegmentation;

/// Center `text` to a total length of `total` grapheme clusters,
/// padding both sides with `pad` (a single `char`). If `text` is longer
/// than `total`, it will be truncated on the right to fit.
///
/// Examples:
/// - center_pad("hi", 6, '*') -> "***hi*"
/// - center_pad("🙂", 3, '-') -> "-🙂-"
pub fn center_pad(text: &str, total: usize, pad: char) -> String {
    if total == 0 {
        return String::new();
    }

    // Count grapheme clusters in the input text
    let graphemes: Vec<&str> = UnicodeSegmentation::graphemes(text, true).collect();
    let text_len = graphemes.len();

    if text_len >= total {
        // Truncate to the desired length (take the first `total` graphemes)
        return graphemes.into_iter().take(total).collect();
    }

    let extra = total - text_len;
    let left = extra / 2;
    let right = extra - left;

    let pad_str = pad.to_string();
    let left_pad = pad_str.repeat(left);
    let right_pad = pad_str.repeat(right);

    // Reassemble: left padding + original text (as-is) + right padding
    let mut out = String::with_capacity(total * pad_str.len().max(1));
    out.push_str(&left_pad);
    out.push_str(text);
    out.push_str(&right_pad);
    out
}

