# Rust Text Centering Function

Here's a self-contained function using the `unicode-width` crate (2023+) to properly handle Unicode characters:

```rust
use unicode_width::UnicodeWidthStr;

fn center_text(text: &str, total_length: usize, pad_char: char) -> String {
    let text_width = text.width();

    // If text is already longer than or equal to desired length, return as-is
    if text_width >= total_length {
        return text.to_string();
    }

    let total_padding = total_length - text_width;
    let left_padding = total_padding / 2;
    let right_padding = total_padding - left_padding;

    let mut result = String::with_capacity(total_length * 4); // Account for multi-byte chars

    // Add left padding
    for _ in 0..left_padding {
        result.push(pad_char);
    }

    // Add original text
    result.push_str(text);

    // Add right padding
    for _ in 0..right_padding {
        result.push(pad_char);
    }

    result
}

// Example usage
fn main() {
    println!("{}", center_text("Hello", 15, '*'));
    // Output: *****Hello*****

    println!("{}", center_text("Rust", 20, '-'));
    // Output: --------Rust--------

    println!("{}", center_text("X", 10, '#'));
    // Output: ####X#####

    println!("{}", center_text("Already long text", 10, ' '));
    // Output: Already long text (unchanged, too long)
}
```

