use std::collections::HashMap;
use indexmap::IndexMap;

/// Sort `dict0` in place according to positions in `lst0`.
///
/// - `dict0`: Vec of records, each record is a HashMap<String, String>.
/// - `lst0`: reference sequence providing the desired order for values.
/// - `var0`: key in each record whose value is looked up in `lst0`.
///
/// Records whose `var0` value does not appear in `lst0` are placed at the end,
/// preserving relative order among them and among equal-position items (stable sort).
fn sort_by_reference(
    dict0: &mut Vec<HashMap<String, String>>,
    lst0: &[String],
    var0: &str,
) {
    // Build a value -> position map from lst0
    let mut pos: IndexMap<String, usize> = IndexMap::new();
    for (i, v) in lst0.iter().enumerate() {
        // Only the first occurrence sets the position (duplicate entries in lst0 ignored).
        pos.entry(v.clone()).or_insert(i);
    }

    // Stable sort by position (missing values -> usize::MAX so they go to the end)
    dict0.sort_by_key(|rec| {
        rec.get(var0)
            .and_then(|val| pos.get(val))
            .cloned()
            .unwrap_or(usize::MAX)
    });
}

