/// let lst0 = vec!["banana".to_string(), "apple".to_string()];
/// let result = sort_records_by_sequence(dict0, lst0, "name");
/// ```
fn sort_records_by_sequence(
    mut dict0: Vec<IndexMap<String, String>>,
    lst0: Vec<String>,
    var0: &str,
) -> Vec<IndexMap<String, String>> {
    // Create a map of value -> sort position for O(1) lookup
    let position_map: std::collections::HashMap<&String, usize> = lst0
        .iter()
        .enumerate()
        .map(|(idx, val)| (val, idx))
        .collect();

    // Sort the records based on the position of their var0 value in lst0
    dict0.sort_by_key(|record| {
        record
            .get(var0)
            .and_then(|val| position_map.get(val))
            .copied()
            .unwrap_or(usize::MAX) // Place records with missing values at the end
    });

    dict0
}

fn main() {
    // Example usage
    let dict0 = vec![
        {
            let mut m = IndexMap::new();
            m.insert("id".to_string(), "1".to_string());
            m.insert("fruit".to_string(), "apple".to_string());
            m
        },
        {
            let mut m = IndexMap::new();
            m.insert("id".to_string(), "2".to_string());
            m.insert("fruit".to_string(), "banana".to_string());
            m
        },
        {
