use unicode_segmentation::UnicodeSegmentation;

/// Insert `insert` into `base` so that the inserted text starts immediately after
/// the first grapheme (user-perceived character) of `base` and the original
/// seventh grapheme (if present) becomes immediately after the inserted text.
///
/// Behavior notes:
/// - If `base` has no graphemes, the result is `insert + base`.
/// - If `base` has fewer than 7 graphemes but at least 1, `insert` is inserted
///   after the first grapheme and the rest of `base` follows unchanged.
pub fn insert_between_first_and_seventh(base: &str, insert: &str) -> String {
    // Split into grapheme clusters so we don't break multi-codepoint characters.
    let graphemes: Vec<&str> = UnicodeSegmentation::graphemes(base, true).collect();

    // byte-wise concatenation using grapheme slices:
    let prefix = if !graphemes.is_empty() {
        graphemes[0]
    } else {
        ""
    };

    // index of the seventh grapheme (0-based index 6). If not present, use end.
    let seventh_index = if graphemes.len() > 6 { 6 } else { graphemes.len() };

    // build suffix by joining graphemes from seventh_index..end
    let suffix = graphemes[seventh_index..].concat();

    // If there was no first grapheme, prefix is empty and we place `insert` at the front.
    format!("{}{}{}", prefix, insert, suffix)
}

Examples:
- base = "1234567890", insert = "X" -> "1X7890"
- base = "A", insert = "foo" -> "Afoo"
- base = "", insert = "hello" -> "hello"

This function preserves proper Unicode grapheme boundaries (so emoji, accents, etc., are treated as single user-visible characters).

