use polars::prelude::*;
use std::collections::HashMap;

// Define a type alias for our result type
type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

/// Transforms a 2D dataset into a dictionary (HashMap) based on an orientation variable.
///
/// # Arguments
/// * `df0` - The input DataFrame containing the data
/// * `orientation_var` - The column name to use as dictionary keys
/// * `value_columns` - Optional: Vector of column names to include as values.
///   If None, all non-orientation columns will be included.
///
/// # Returns
/// A HashMap where keys are values from `orientation_var` and values are
/// HashMaps of the remaining columns' data.
///
/// # Example
/// ```
/// use polars::prelude::*;
/// use std::collections::HashMap;
///
/// let df = df!(
///     "a" => &[1, 2, 3],
///     "b" => &["x", "y", "z"],
///     "c" => &[true, false, true]
/// ).unwrap();
///
/// let result = transform_to_dict(&df, "b", None).unwrap();
/// // result will contain entries like: "x" => {"a": [1], "c": [true]}
/// ```
pub fn transform_to_dict(
    df0: &DataFrame,
    orientation_var: &str,
    value_columns: Option<Vec<String>>,
) -> Result<HashMap<String, HashMap<String, Vec<Series>>>>
{
    // Validate the orientation column exists
    if !df0.column(orientation_var).is_ok() {
        return Err(format!("Column '{}' not found in DataFrame", orientation_var).into());
    }

    // Get the orientation column
    let orientation_series = df0.column(orientation_var)?.unwrap();

    // Determine which columns to include as values
    let mut columns_to_include = Vec::new();
    if let Some(cols) = value_columns {
        columns_to_include = cols;
    } else {
        // Include all columns except the orientation column
        for col_name in df0.get_column_names() {
            if col_name != orientation_var {
                columns_to_include.push(col_name.to_string());
            }
        }
    }

    // Create the result HashMap
    let mut result = HashMap::new();

    // Group by the orientation variable
    let grouped = df0.lazy()
        .group_by([orientation_var])
        .agg(&columns_to_include)
        .collect()?;

    // Convert to the desired format
    for row in grouped.iter() {
        let key = row.get(orientation_var).unwrap().as_str().unwrap().to_string();

        let mut value_map = HashMap::new();
        for col_name in &columns_to_include {
            let series = row.get(col_name).unwrap();
            value_map.insert(col_name.clone(), series.clone());
        }

        result.insert(key, value_map);
    }

    Ok(result)
}

