Below is a self-contained Rust function (with a small usage example) that transforms a 2D dataset represented as a polars::DataFrame (df0) into a JSON-like dictionary according to an orientation string (var0). The function returns a serde_json::Value so you can easily serialize, inspect or convert it to other representations.

This implementation uses the polars crate (a modern Rust DataFrame library actively developed in 2023+) and serde_json. It implements common pandas-like orientations: "records", "list", "dict", "index", "split", "values". Unknown orientations return a JSON null.

Example Cargo.toml dependencies (put into your Cargo.toml):
- polars = "0.31" (or a compatible 2023+ release)
- serde_json = "1.0"

Code:

```rust
use polars::prelude::*;
use serde_json::{Map, Number, Value};

/// Convert a polars DataFrame (`df0`) into a JSON-like dictionary according to `var0` orientation.
///
/// Supported orientations (similar to pandas.DataFrame.to_dict):
/// - "records": Vec< {col: value, ...} >
/// - "list": { col: [values...] , ... }
/// - "dict": { col: { index: value, ... }, ... }
/// - "index": { index: { col: value, ... }, ... }
/// - "split": { "index": [indices], "columns": [colnames], "data": [[...], ...] }
/// - "values": [[row values], ...]
///
/// Returns serde_json::Value so you can easily serialize or inspect the result.
pub fn df0_to_dict(df0: &DataFrame, var0: &str) -> Value {
    // helper to convert polars AnyValue -> serde_json::Value
    fn any_value_to_json(v: AnyValue<'_>) -> Value {
        match v {
            AnyValue::Null => Value::Null,
            AnyValue::Boolean(b) => Value::Bool(b),
            // integers
            AnyValue::UInt8(u) => Value::Number(Number::from(u)),
            AnyValue::UInt16(u) => Value::Number(Number::from(u)),
            AnyValue::UInt32(u) => Value::Number(Number::from(u)),
            AnyValue::UInt64(u) => {
                // serde_json::Number doesn't have from(u64) directly; try i64 fallback or string
                if let Ok(n) = Number::from_f64(u as f64) {
                    Value::Number(n)
                } else {
                    Value::String(u.to_string())
                }
            }
            AnyValue::Int8(i) => Value::Number(Number::from(i)),
            AnyValue::Int16(i) => Value::Number(Number::from(i)),
            AnyValue::Int32(i) => Value::Number(Number::from(i)),
            AnyValue::Int64(i) => Value::Number(Number::from(i)),
            // floats
            AnyValue::Float32(f) => {
                Number::from_f64(f as f64).map_or(Value::Null, Value::Number)
            }
            AnyValue::Float64(f) => {
                Number::from_f64(f).map_or(Value::Null, Value::Number)
            }
            // strings
            AnyValue::Utf8(s) => Value::String(s.to_string()),
            AnyValue::Utf8Owned(s) => Value::String(s),
            // Dates / datetimes etc. — fall back to string representation
            other => Value::String(other.to_string()),
        }
    }

    let cols = df0.get_columns();
    let nrows = df0.height();
    let col_names: Vec<String> = cols.iter().map(|s| s.name().to_string()).collect();

    match var0 {
        "records" => {
            let mut rows = Vec::with_capacity(nrows);
            for i in 0..nrows {
                let mut map = Map::with_capacity(cols.len());
                for s in cols.iter() {
                    let val = s.get(i);
                    map.insert(s.name().to_string(), any_value_to_json(val));
                }
                rows.push(Value::Object(map));
            }
            Value::Array(rows)
        }

        "list" => {
            let mut out = Map::with_capacity(cols.len());
            for s in cols.iter() {
                let mut arr = Vec::with_capacity(nrows);
                for i in 0..nrows {
                    arr.push(any_value_to_json(s.get(i)));
                }
                out.insert(s.name().to_string(), Value::Array(arr));
            }
            Value::Object(out)
        }

        "dict" => {
            // { column_name: { index_str: value, ... }, ... }
            let mut out = Map::with_capacity(cols.len());
            for s in cols.iter() {
                let mut inner = Map::with_capacity(nrows);
                for i in 0..nrows {
                    inner.insert(i.to_string(), any_value_to_json(s.get(i)));
                }
                out.insert(s.name().to_string(), Value::Object(inner));
            }
            Value::Object(out)
        }

        "index" => {
            // { index_str: { col: value, ... }, ... }
            let mut out = Map::with_capacity(nrows);
            for i in 0..nrows {
                let mut inner = Map::with_capacity(cols.len());
                for s in cols.iter() {
                    inner.insert(s.name().to_string(), any_value_to_json(s.get(i)));
                }
                out.insert(i.to_string(), Value::Object(inner));
            }
            Value::Object(out)
        }

        "split" => {
            // { index: [0,1,...], columns: [...], data: [[row], ...] }
            let mut data = Vec::with_capacity(nrows);
            for i in 0..nrows {
                let mut row = Vec::with_capacity(cols.len());
                for s in cols.iter() {
                    row.push(any_value_to_json(s.get(i)));
                }
                data.push(Value::Array(row));
            }
            let index_arr = (0..nrows).map(|i| Value::Number(Number::from(i))).collect();
            let columns_arr = col_names.iter().map(|c| Value::String(c.clone())).collect();

            let mut out = Map::with_capacity(3);
            out.insert("index".to_string(), Value::Array(index_arr));
            out.insert("columns".to_string(), Value::Array(columns_arr));
            out.insert("data".to_string(), Value::Array(data));
            Value::Object(out)
        }

        "values" => {
            let mut data = Vec::with_capacity(nrows);
            for i in 0..nrows {
                let mut row = Vec::with_capacity(cols.len());
                for s in cols.iter() {
                    row.push(any_value_to_json(s.get(i)));
                }
                data.push(Value::Array(row));
            }
            Value::Array(data)
        }

        _ => Value::Null,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use polars::prelude::*;

    #[test]
    fn example_usage() {
        // Build a simple DataFrame
        let s0 = Series::new("id", &[1i64, 2, 3]);
        let s1 = Series::new("name", &["alice", "bob", "carol"]);
        let s2 = Series::new("score", &[10.5f64, 8.0, 9.25]);

        let df = DataFrame::new(vec![s0, s1, s2]).unwrap();

        // records
        let rec = df0_to_dict(&df, "records");
        println!("records: {}", serde_json::to_string_pretty(&rec).unwrap());

        // list
        let lst = df0_to_dict(&df, "list");
        println!("list: {}", serde_json::to_string_pretty(&lst).unwrap());

        // split
        let spl = df0_to_dict(&df, "split");
        println!("split: {}", serde_json::to_string_pretty(&spl).unwrap());

        // assert some structure
        assert!(rec.is_array());
        assert!(lst.is_object());
        assert!(spl.is_object());
    }
}
```

Notes:
- If you need additional dtype support (dates, nested lists, structs), extend the any_value_to_json match to handle more AnyValue variants (Date, Datetime, List, Struct).
- The function uses numeric row indices as the "index" because polars DataFrame doesn't carry an explicit row index like pandas by default. If you have a specific index column, pass it separately or set it as the first column and adapt the code to use its values as indices.

