    match var0 {
        "columns" => {
            // Convert each column to a list
            for column in df0.get_column_names() {
                let series = df0.column(column).unwrap();
                let values: Vec<AnyValue> = series.iter().collect();
                result.insert(column.to_string(), values);
            }
