                    let value = series.get(row_idx).unwrap();
                    row_values.push(value);
                }
                result.insert(row_idx.to_string(), row_values);
            }
        }
        _ => {
            panic!("Invalid orientation. Use 'columns' or 'rows'.");
        }
    }

    result
}

