use polars::prelude::*;
use std::collections::HashMap;

/// Transforms a 2D Polars DataFrame into a HashMap according to the specified orientation.
/// 
/// # Arguments
/// * `df` - The Polars DataFrame to transform
/// * `orientation` - The orientation for transformation:
///   - "columns": Keys are column names, values are Vec of column data
///   - "index": Keys are row indices (as strings), values are Vec of row data
///   - "records": Vec of HashMaps, each representing a row
/// 
/// # Returns
/// * `Result<HashMap<String, Vec<String>>, Box<dyn std::error::Error>>`
/// 
/// # Example
/// ```
/// use polars::prelude::*;
/// 
/// let df = df! {
///     "A" => &[1, 2, 3],
///     "B" => &[4, 5, 6],
/// }?;
/// 
/// let result = transform_dataframe(&df, "columns")?;
/// ```
pub fn transform_dataframe(
    df: &DataFrame,
    orientation: &str,
) -> Result<HashMap<String, Vec<String>>, Box<dyn std::error::Error>> {
    let mut result: HashMap<String, Vec<String>> = HashMap::new();

    match orientation {
        "columns" => {
            // Transform by columns: each column name is a key
            for col_name in df.get_column_names() {
                let series = df.column(col_name)?;
                let values: Vec<String> = series
                    .iter()
                    .map(|v| format!("{}", v))
                    .collect();
                result.insert(col_name.to_string(), values);
            }
        }
        "index" => {
            // Transform by rows: each row index is a key
            for (row_idx, _) in df.iter_rows().enumerate() {
                let row_values: Vec<String> = df
                    .get_column_names()
                    .iter()
                    .map(|col_name| {
                        let series = df.column(col_name).unwrap();
                        format!("{}", series.get(row_idx).unwrap())
                    })
                    .collect();
                result.insert(row_idx.to_string(), row_values);
            }
        }
        "records" => {
            // Transform into records: returns Vec of row HashMaps as strings
            for (row_idx, _) in df.iter_rows().enumerate() {
                let mut row_map: HashMap<String, String> = HashMap::new();
                for col_name in df.get_column_names() {
                    let series = df.column(col_name)?;
                    let value = format!("{}", series.get(row_idx)?);
                    row_map.insert(col_name.to_string(), value);
                }
                // Store serialized record
                let serialized = format!("{:?}", row_map);
                result.insert(format!("record_{}", row_idx), vec![serialized]);
            }
        }
        _ => {
            return Err(format!(
                "Unknown orientation: '{}'. Use 'columns', 'index', or 'records'",
                orientation
            )
            .into())
        }
    }

    Ok(result)
}

// Example usage
