            let after = caps.get(2).map_or("", |m| m.as_str()).trim();

            let before_words: Vec<Option<String>> = before.split_whitespace()
                .rev() // Get words in reverse to access the last num_words first
                .take(num_words)
                .map(|word| Some(word.to_string()))
                .collect::<Vec<_>>();

            let after_words: Vec<Option<String>> = after.split_whitespace()
                .take(num_words)
                .map(|word| Some(word.to_string()))
