/// - right_context[0] is the nearest word after the term, right_context[n-1] is the farthest.
/// - If the term is not found, both vectors contain only None.
pub fn extract_context_words(text: &str, term: &str, n: usize) -> (Vec<Option<String>>, Vec<Option<String>>) {
