use ndarray::Array1;

fn mean_of_non_zero_indices(arr: &Array1<i32>) -> Option<f64> {
    let non_zero_indices: Vec<usize> = arr
        .iter()
        .enumerate()
        .filter_map(|(idx, &value)| if value != 0 { Some(idx) } else { None })
        .collect();

