/// Computes the mean of the indices at which the specified column in df0 contains non-zero values.
///
/// # Arguments
///
/// * `df0` - A reference to a Polars DataFrame.
/// * `column_name` - The name of the column to check for non-zero values.
///
/// # Returns
///
/// * `Option<f64>` - The mean of the indices with non-zero values, or None if there are no such indices.
fn mean_of_non_zero_indices(df0: &DataFrame, column_name: &str) -> Option<f64> {
    // Get the column as a Series
    let series = df0.column(column_name).ok()?;

    // Filter indices where the value is non-zero
    let non_zero_indices: Vec<usize> = series
        .i64()?
        .into_iter()
        .enumerate()
        .filter_map(|(idx, val)| val.map(|v| if v != 0 { Some(idx) } else { None }))
        .flatten()
        .collect();

    // Calculate the mean of the indices
    if non_zero_indices.is_empty() {
        None
    } else {
        let sum: usize = non_zero_indices.iter().sum();
        let count = non_zero_indices.len();
        Some(sum as f64 / count as f64)
    }
}

