use serde_json::{Value, Map};
use std::cmp::Ordering;

/// Sorts a sequence of key-value maps by the value associated with `var0`.
///
/// # Arguments
/// * `lst0` - A vector of maps (each map is a dictionary/key-value pairs)
/// * `var0` - The key whose associated value will be used for sorting
///
/// # Returns
/// A new vector containing the sorted maps
///
/// # Example
/// ```
/// use serde_json::{json, Value};
///
/// let lst0 = vec![
///     json!({"a": 3, "b": 1}),
///     json!({"a": 1, "b": 2}),
///     json!({"a": 2, "b": 3}),
/// ];
/// let sorted = sort_by_key(lst0, "a");
/// assert_eq!(sorted[0]["a"], 1);
/// assert_eq!(sorted[1]["a"], 2);
/// assert_eq!(sorted[2]["a"], 3);
/// ```
pub fn sort_by_key(lst0: Vec<Value>, var0: &str) -> Vec<Value> {
    let mut sorted: Vec<Value> = lst0
        .into_iter()
        .map(|mut item| {
            // Ensure the item is a Map (Object) for easy access
            if let Value::Object(map) = &mut item {
                item
            } else {
                // If not a map, we can't sort by this key - return as-is
                item
            }
        })
        .collect();

    // Custom comparator for sorting
    sorted.sort_by(|a, b| {
        // Get the values for comparison
        let a_val = match a.get(var0) {
            Some(Value::Number(n)) => n.as_f64(),
            Some(Value::String(s)) => Some(s.parse().ok()),
            Some(Value::Bool(b)) => Some(*b as f64),
            _ => None,
        };

        let b_val = match b.get(var0) {
            Some(Value::Number(n)) => n.as_f64(),
            Some(Value::String(s)) => Some(s.parse().ok()),
            Some(Value::Bool(b)) => Some(*b as f64),
            _ => None,
        };

        // Handle cases where the key might not exist or values can't be compared
        match (a_val, b_val) {
            (Some(a), Some(b)) => a.partial_cmp(&b).unwrap_or(Ordering::Equal),
            (Some(_), None) => Ordering::Less,
            (None, Some(_)) => Ordering::Greater,
            (None, None) => Ordering::Equal,
        }
    });

    sorted
}
```

