use std::collections::HashMap;

/// Computes the frequency of each distinct element in a collection
/// and returns the result as a 2D table (Vec of [element, count] pairs).
///
/// # Arguments
/// * `var0` - A slice of comparable and hashable elements
///
/// # Returns
/// A vector of [element, count] pairs sorted by element
fn compute_frequency<T: Eq + std::hash::Hash + Clone + Ord>(var0: &[T]) -> Vec<(T, usize)> {
    let mut frequency_map: HashMap<T, usize> = HashMap::new();

    // Count occurrences of each element
    for element in var0 {
        *frequency_map.entry(element.clone()).or_insert(0) += 1;
    }

    // Convert to vector and sort by element
    let mut result: Vec<(T, usize)> = frequency_map.into_iter().collect();
    result.sort_by(|a, b| a.0.cmp(&b.0));

    result
}

