    let column = df0.column(var0)
        .map_err(|e| PolarsError::ComputeError(
            format!("Column '{}' not found: {}", var0, e).into()
        ))?;

    // Convert to string series and filter
    let str_column = column.utf8()
        .map_err(|e| PolarsError::ComputeError(
            format!("Column '{}' is not a string type: {}", var0, e).into()
        ))?;

    // Create a boolean mask: True for rows we want to KEEP (don't match regex)
    let mask: Vec<bool> = str_column
        .into_iter()
