/// Filters a Polars DataFrame to only include rows where the specified column matches the given regex pattern.
///
/// # Arguments
/// * `df` - The input DataFrame to filter
/// * `column_name` - Name of the column to check against the regex
/// * `pattern` - Regular expression pattern to match against the column values
///
/// # Returns
/// A new DataFrame containing only rows that match the regex pattern
///
/// # Example
/// ```
/// use polars::prelude::*;
/// use regex::Regex;
///
/// let df = df![
///     "var0" => &[1, 2, 3, 4],
///     "var1" => &["1a", "2b", "3c", "4d"]
/// ]?;
///
/// let filtered = filter_matching_regex(df, "var1", r"^[0-9]+[a-z]$")?;
/// ```
pub fn filter_matching_regex(
    df: DataFrame,
    column_name: &str,
    pattern: &str,
) -> Result<DataFrame, Box<dyn std::error::Error>> {
    // Compile the regex pattern
    let re = Regex::new(pattern)?;

    // Get the column from the DataFrame
    let column = df.column(column_name)
        .ok_or_else(|| format!("Column '{}' not found", column_name))?;

    // Convert the column to a String array for regex matching
    let string_col = match column {
        Series::String(s) => s,
        Series::Utf8(s) => s,
        _ => {
            // Try to convert other types to strings
            let string_series = column
                .try_downcast::<String>()
                .map_err(|_| format!("Column '{}' cannot be converted to string", column_name))?;
            string_series
        }
    };

    // Create a boolean mask where the pattern matches
    let mask = string_col
        .into_iter()
        .map(|s| re.is_match(&s.unwrap_or("")))
        .collect::<Vec<_>>();

    // Convert the mask to a Polars boolean series
    let mask_series = Series::new(
        column_name.to_string() + "_mask",
        mask.into_iter().map(|b| b.into()).collect::<Vec<_>>(),
    );

    // Filter the DataFrame using the mask
    let filtered_df = df.lazy()
        .filter(&mask_series)
        .collect()?;

    Ok(filtered_df)
}
