    dict1: &IndexMap<String, f64>,
) -> IndexMap<String, f64> {
    dict0
        .iter()
        .filter_map(|(key, value0)| {
            dict1.get(key).map(|value1| {
                assert!(*value1 != 0.0, "Division by zero for key: {}", key);
                (key.clone(), value0 / value1)
            })
        })
        .collect()
}

