/// let encoded = encode_categories(&df, "col0");
/// ```
pub fn encode_categories(df0: &DataFrame, col0: &str) -> Result<DataFrame, PolarsError> {
    // Get the unique values from the column
    let col = df0.column(col0)?;
    let unique_values = col.unique(true)?;

    // Create a mapping from value to integer code
    let mut value_to_code = HashMap::new();
    for (i, value) in unique_values.iter().enumerate() {
        value_to_code.insert(value.clone(), i as i32);
    }

