use polars::prelude::*;
use std::collections::HashMap;

/// Replace the values in `col` of `df` by integer codes assigned to each unique category.
/// Codes start at 0 and are assigned in the order of first appearance.
/// Nulls in the original column remain nulls in the output integer column.
fn encode_col0_to_int_codes(mut df: DataFrame, col: &str) -> PolarsResult<DataFrame> {
    // Clone the column Series so we can cast if necessary
    let s_series = df.column(col)?.clone();

    // Ensure we have an Utf8 series to iterate categories as strings
    let utf_series = if s_series.dtype() == &DataType::Utf8 {
        s_series
    } else {
        s_series.cast(&DataType::Utf8)?
    };
    let utf = utf_series.utf8()?;

    // Build a mapping from category string -> integer code (preserve first-seen order)
    let mut map: HashMap<String, i32> = HashMap::new();
    let mut next_code: i32 = 0;

    // Prepare a Vec<Option<i32>> to preserve nulls
    let mut codes: Vec<Option<i32>> = Vec::with_capacity(utf.len());

    for opt_val in utf.into_iter() {
        if let Some(v) = opt_val {
            if let Some(&c) = map.get(v) {
                codes.push(Some(c));
            } else {
                let c = next_code;
                map.insert(v.to_string(), c);
                next_code += 1;
                codes.push(Some(c));
            }
        } else {
            // original was null -> keep null
            codes.push(None);
        }
    }

    // Create a new Int32 series with the same column name
    let codes_series = Series::new(col, codes);

    // Replace the original column with the codes
    df.replace(col, codes_series)?;

    Ok(df)
}

