use polars::prelude::*;

/// Reorders the columns of a DataFrame so that column names are sorted alphabetically.
///
/// # Arguments
/// * `df` - The input DataFrame to reorder
///
/// # Returns
/// * `Result<DataFrame>` - A new DataFrame with columns sorted alphabetically, or an error
///
/// # Example
/// ```rust
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "z" => &[1, 2, 3],
///     "a" => &[4, 5, 6],
///     "m" => &[7, 8, 9],
/// ).unwrap();
///
/// let sorted_df = reorder_columns_alphabetically(df).unwrap();
/// // Columns will be in order: "a", "m", "z"
/// ```
pub fn reorder_columns_alphabetically(df: DataFrame) -> Result<DataFrame> {
    // Get the column names and sort them alphabetically
    let mut column_names: Vec<&str> = df.get_column_names().iter().map(|s| s.as_str()).collect();
    column_names.sort();

    // Select columns in the sorted order
    df.select(column_names)
}

