use polars::prelude::*;

/// Sort `df0` by the specified columns `cols`. At least two columns should be provided.
/// `descending` can be:
/// - None: all columns sorted ascending
/// - Some(&[bool]): either a single bool (applied to all columns) or a bool per column
///
/// Returns a new DataFrame with rows in the requested sorted order.
pub fn sort_df_by_columns(
    df0: &DataFrame,
    cols: &[&str],
    descending: Option<&[bool]>,
) -> PolarsResult<DataFrame> {
    assert!(
        cols.len() >= 2,
        "sort_df_by_columns requires two or more column names"
    );

    // Build expressions for each column name
    let exprs: Vec<Expr> = cols.iter().map(|&c| col(c)).collect();

    // Build the vector of reverse flags matching columns
    let reverse: Vec<bool> = match descending {
        Some(flags) => {
            if flags.len() == cols.len() {
                flags.to_vec()
            } else if flags.len() == 1 {
                vec![flags[0]; cols.len()]
            } else {
                panic!("`descending` must be length 1 or equal to the number of columns");
            }
        }
        None => vec![false; cols.len()],
    };

    // Use the lazy API to sort by multiple expressions, then collect back to a DataFrame
    df0.lazy().sort_by_exprs(exprs, reverse).collect()
}

fn main() -> PolarsResult<()> {
    // Example DataFrame
    let s1 = Series::new("group", &["b", "a", "b", "a", "c"]);
    let s2 = Series::new("value", &[5i32, 2, 3, 1, 4]);
    let s3 = Series::new("sub", &[10i32, 20, 5, 30, 0]);

    let df = DataFrame::new(vec![s1, s2, s3])?;
    println!("Original:\n{}", &df);

    // Sort by 'group' ascending then by 'value' descending
    let sorted = sort_df_by_columns(&df, &["group", "value"], Some(&[false, true]))?;
    println!("Sorted by group ASC, value DESC:\n{}", &sorted);

    // Sort by 'group' ascending, then by 'sub' ascending (demonstrates default ascending)
    let sorted2 = sort_df_by_columns(&df, &["group", "sub"], None)?;
    println!("Sorted by group ASC, sub ASC:\n{}", &sorted2);

    Ok(())
}
```

Notes:
- The function expects at least two columns as per your requirement. It asserts if fewer are provided. You can adapt to allow one column by removing that assertion.
- The function uses the lazy API's sort_by_exprs which supports multi-key sorting with independent ascending/descending flags.
- If you prefer error returns instead of panics for bad `descending` lengths, replace the panic/assert with early Err(...) returns (using PolarsError or a custom error type).

