/// println!("{:?}", normalized);
/// ```
pub fn zscore_normalize(df: &DataFrame) -> PolarsResult<DataFrame> {
    // Collect expressions for each numeric column
    let expressions: Vec<Expr> = df
        .get_column_names()
        .iter()
        .map(|name| {
            let col = col(name);

            // Only apply z-score to numeric columns
            when(col.clone().cast(DataType::Float64).is_not_null())
                .then(
                    // z = (x - mean) / std
                    (col.clone() - col.clone().mean()) / col.clone().std(1) // ddof=1 for sample std
                )
                .otherwise(col) // Keep non-numeric columns unchanged
                .alias(name)
        })
        .collect();

    // Apply all transformations at once
    df.lazy()
        .select(expressions)
        .collect()
}

// Alternative implementation using explicit column type checking
pub fn zscore_normalize_explicit(df: &DataFrame) -> PolarsResult<DataFrame> {
    let mut normalized_cols = Vec::new();

    for col_name in df.get_column_names() {
        let series = df.column(col_name)?;

        // Check if column is numeric
        if series.dtype().is_numeric() {
            // Convert to f64 for computation
            let numeric = series.cast(&DataType::Float64)?;
            let mean = numeric.mean().unwrap_or(0.0);
            let std = numeric.std(1).unwrap_or(1.0); // ddof=1 for sample std

            // Handle edge case where std is 0 (constant column)
            let normalized = if std == 0.0 {
                // Return zeros for constant columns
                Series::new(col_name, vec![0.0_f64; numeric.len()])
            } else {
                // Apply z-score: (x - mean) / std
                (numeric - mean) / std
            };

            normalized_cols.push(normalized.with_name(col_name));
        } else {
            // Keep non-numeric columns as-is
            normalized_cols.push(series.clone());
        }
    }

