/// * `df0` - Input DataFrame
///
/// # Returns
/// * Result containing normalized DataFrame or error
fn z_score_normalize(df0: &DataFrame) -> PolarsResult<DataFrame> {
    let mut df = df0.clone();

    // Iterate through each column
    for col_name in df.get_column_names() {
        let col = df.column(col_name)?;

        // Only process numeric columns
        if col.dtype().is_numeric() {
            let series = col.cast(&DataType::Float64)?;

            // Calculate mean
            let mean = series.mean().unwrap_or(0.0);

            // Calculate standard deviation
            let std_dev = series.std(1); // Using sample standard deviation (ddof=1)

            if let Some(std) = std_dev {
                if std > 0.0 {
                    // Apply z-score formula: (x - mean) / std
                    let normalized = (series.f64()?
                        .into_iter()
                        .map(|opt_val| opt_val.map(|v| (v - mean) / std)))
                        .collect::<Float64Chunked>();

                    df = df.with_columns([normalized.with_name(col_name).into()])?;
