Code:

```rust
use polars::prelude::*;

/// Filter a DataFrame to keep only groups (by `group_col`) that have more than one row,
/// and return the resulting DataFrame with a reset integer row index named "index".
///
/// - `df`: input DataFrame.
/// - `group_col`: the name of the column used to determine groups.
///
/// The resulting DataFrame will contain the original columns plus a new "index" column
/// (u32/i64 depending on Polars) containing 0..n-1 for the kept rows. If the input already
/// has a column named "index", it will be dropped and replaced.
pub fn filter_groups_with_multiple_entries(
    df: &DataFrame,
    group_col: &str,
) -> PolarsResult<DataFrame> {
    // Ensure the group column exists (df.column will error if not)
    let group_series = df.column(group_col)?;

    // Compute value counts for the group column: a DataFrame with two columns:
    // - the group values (named as `group_col`)
    // - "counts" with the frequency of each value
    let vc = group_series.value_counts(false, false)?;

    // The counts column is named "counts" in the value_counts result.
    // Get it as an Int64Chunked and build a boolean mask for counts > 1.
    let counts_chunked = vc.column("counts")?.i64()?;
    let multi_mask = counts_chunked.gt(1);

    // Filter the value_counts DataFrame to keep only group values whose count > 1
    let keep_vals_df = vc.filter(&multi_mask)?;

    // Extract the series of group values to keep
    let keep_vals_series = keep_vals_df.column(group_col)?.clone();

    // Build a boolean mask on the original df: group_col.is_in(keep_vals_series)
    let in_mask = df.column(group_col)?.is_in(&keep_vals_series)?;

    // Filter original df to keep only rows where group value is in the keep set
    let mut result = df.filter(&in_mask)?;

    // If the original data had a column named "index", drop it to avoid collision
    if result.get_column_names().iter().any(|&c| c == "index") {
        result.drop_in_place("index")?;
    }

    // Add a new row count column named "index" starting at 0 (continuous sequence)
    // with_row_count takes (name, offset). Use Some(0) to start at zero explicitly.
    let result = result.with_row_count("index", Some(0))?;

    Ok(result)
}
```

Example usage:

```rust
use polars::prelude::*;

fn main() -> PolarsResult<()> {
    // Build example DataFrame
    let df = df![
        "group" => &["a", "a", "b", "c", "d", "d", "e"],
        "value" => &[1, 2, 3, 4, 5, 6, 7]
    ]?;

    let filtered = filter_groups_with_multiple_entries(&df, "group")?;
    println!("{}", filtered);

    // Expected: only groups "a" and "d" survive (since they have counts > 1).
    // The printed DataFrame will include an "index" column with values 0..(n-1).
    Ok(())
}
```

If you prefer the result to omit an explicit "index" column (because Polars uses implicit positional indexing), you can remove the with_row_count step and simply return the filtered DataFrame — it will already have contiguous row positions internally.

