///
/// let df = df! {
///     "group" => &["A", "B", "A", "C", "B"],
///     "value" => &[1, 2, 3, 4, 5],
/// }.unwrap();
///
/// let result = filter_groups_with_multiple_entries(df, "group").unwrap();
/// // Result contains only groups A and B (C appears only once)
/// ```
fn filter_groups_with_multiple_entries(
    df: DataFrame,
    group_col: &str,
) -> PolarsResult<DataFrame> {
    // Count occurrences of each group
    let group_counts = df
        .clone()
        .lazy()
        .groupby([group_col])
        .agg([col("*").count().alias("count")])
        .collect()?;

