use polars::prelude::*;

/// Replace every occurrence of `target` in column `col_name` of `df` with `replacement`.
///
/// Returns an updated DataFrame on success or a PolarsError if the column doesn't exist
/// or is not a Utf8 (string) column.
pub fn replace_in_column(
    mut df: DataFrame,
    target: &str,      // var0: value to replace
    col_name: &str,    // var1: column name
    replacement: &str, // var2: new value
) -> Result<DataFrame, PolarsError> {
    // get the column (returns error if column not found)
    let series = df.column(col_name)?;

    // ensure it is a string column
    if series.dtype() != &DataType::Utf8 {
        return Err(PolarsError::Other(
            format!("column '{}' is not Utf8 (string) type", col_name).into(),
        ));
    }

    // iterate over values and build a new Vec<Option<&str>> with replacements
    let utf8 = series.utf8()?;
    let replaced: Vec<Option<&str>> = utf8
        .into_iter()
        .map(|opt| opt.map(|v| if v == target { replacement } else { v }))
        .collect();

    // create a new Series and put it back into the DataFrame
    let new_series = Series::new(col_name, replaced);
    df = df.with_column(new_series)?;

    Ok(df)
}

// Example usage:
fn main() -> Result<(), PolarsError> {
    // build a small example DataFrame
    let s1 = Series::new("name", &["alice", "bob", "alice", "carol"]);
    let s2 = Series::new("age", &[30i32, 40, 30, 25]);
    let df = DataFrame::new(vec![s1, s2])?;

    // replace all occurrences of "alice" in column "name" with "ALICE"
    let updated = replace_in_column(df, "alice", "name", "ALICE")?;
    println!("{:?}", updated);
    Ok(())
}
```

