fn filter_rows_value_zero(df: &DataFrame) -> PolarsResult<DataFrame> {
    // Simple: return only rows where "value" == 0
    // Uses the lazy API so the call is efficient on larger tables.
    df.lazy()
      .filter(col("value").eq(lit(0)))
      .collect()
