    let groups = df
        .lazy()
        .groupby([col("var0"), col("var1")])
        .agg([col("value").sum().alias("sum_value")]);

    let zero_groups = groups
        .filter(col("sum_value").eq(lit(0)))
        .select([col("var0"), col("var1")]);

    // Join the filtered groups back to the original frame to get original rows for those groups.
    df.lazy()
      .join(zero_groups, 
            JoinType::Inner, 
            (vec!["var0", "var1"], vec!["var0", "var1"]))
      .collect()
}

