use polars::prelude::*;
use polars::lazy::dsl::*;
use polars::lazy::prelude::*;
use anyhow::Result;

/// Replace specified columns in `df0` with values from `df1` when `df1` has a non-null value
/// for the same row (rows are aligned by the `on` key).
///
/// - df0: left DataFrame (will be the base; rows with no matching key in df1 remain as-is)
/// - df1: right DataFrame providing replacement values
/// - on: column name used as join key (must exist in both)
/// - cols: list of column names to consider for replacement (must exist in df0 and df1)
/// - right_suffix: suffix to append to df1 column names during the join (so they don't collide)
///
/// Returns a new DataFrame with the specified columns updated.
pub fn replace_cells_from_df(
    df0: DataFrame,
    df1: DataFrame,
    on: &str,
    cols: &[&str],
    right_suffix: &str,
) -> PolarsResult<DataFrame> {
    // quick validations
    if !df0.get_column_names().contains(&on) {
        return Err(PolarsError::NotFound(format!("key column '{}' not found in df0", on).into()));
    }
    if !df1.get_column_names().contains(&on) {
        return Err(PolarsError::NotFound(format!("key column '{}' not found in df1", on).into()));
    }

    // prepare a renamed clone of df1 so that its columns won't collide with df0's names after join
    let mut df1_renamed = df1.clone();
    for col_name in df1_renamed.get_column_names() {
        if col_name != on {
            let new_name = format!("{col_name}{right_suffix}");
            // rename returns Result<()>
            df1_renamed.rename(&col_name, &new_name)?;
        }
    }

    // build lazy frames and left-join df1_renamed into df0 so df1 values are aligned to df0 rows
    let l0 = df0.lazy();
    let l1 = df1_renamed.lazy();
    let mut joined = l0.join(l1, vec![on], vec![on], JoinType::Left, None);

    // For each column to replace, if the corresponding right-side column is not null use it,
    // otherwise keep the left-side (original) value.
    // Example expression: when(col("val_r").is_not_null()).then(col("val_r")).otherwise(col("val")).alias("val")
    for &col in cols {
        let right_col = format!("{col}{right_suffix}");
        // validate presence in joined schema would be lazy; do a runtime check on the eager df1 header
        if !df1.get_column_names().contains(&col) {
            return Err(PolarsError::NotFound(format!("column '{}' not found in df1", col).into()));
        }
        if !df0.get_column_names().contains(&col) {
            return Err(PolarsError::NotFound(format!("column '{}' not found in df0", col).into()));
        }

        // create the conditional expression
        let expr = when(col(&right_col).is_not_null())
            .then(col(&right_col))
            .otherwise(col(col))
            .alias(col);
        joined = joined.with_column(expr);
    }

    // collect the resulting DataFrame
    joined.collect()
}

Example usage (main)

fn main() -> Result<()> {
    // Example df0
    let df0 = df![
        "id" => &["a", "b", "c", "d"],
        "score" => &[Some(10i64), Some(20), Some(30), None],
        "note" => &["oldA", "oldB", "oldC", "oldD"]
    ]?;

    // Example df1 with replacement values for some rows/columns
    let df1 = df![
        "id" => &["a", "c", "x"],          // 'x' doesn't match df0; 'b' and 'd' missing
        "score" => &[Some(100i64), None, Some(999)],
        "note" => &["newA", "newC", "newX"]
    ]?;

    // Replace df0's "score" and "note" where df1 has non-null values
    let out = replace_cells_from_df(df0, df1, "id", &["score", "note"], "_r")?;

    println!("{:?}", out);
    // Expected output DataFrame:
    // - id:     ["a",  "b",   "c",   "d"]
    // - score:  [100,  20,   30,   null]   // 'a' replaced by 100 from df1, 'c' had NULL in df1 so keep 30
    // - note:   ["newA","oldB","newC","oldD"] // 'a' and 'c' replaced where df1 had non-null note

    Ok(())
}

Notes and extensions
- This example uses polars' LazyFrame join + conditional expressions, which is efficient and expressive.
- You can change the replacement rule easily: e.g., replace only when df1 value satisfies some other predicate (greater than, non-empty string, etc.) by adjusting the when(...) condition.
