use polars::prelude::*;

/// Return a Vec containing the lengths of the list in each row of the "col0" column of df0.
///
/// - df0: reference to a polars::prelude::DataFrame
/// - Returns: PolarsResult<Vec<usize>> where each element is the length of the list in that row.
///   Null values are treated as length 0. Non-list non-null values produce an error.
pub fn col0_list_lengths(df0: &DataFrame) -> PolarsResult<Vec<usize>> {
    // get the series for column "col0"
    let s = df0.column("col0")?;
    let mut lengths = Vec::with_capacity(s.len());

    for i in 0..s.len() {
        match s.get(i) {
            AnyValue::List(list_series) => {
                // list_series is a Series representing the list for this row
                lengths.push(list_series.len());
            }
            AnyValue::Null => {
                // treat null as length 0; change behavior if you prefer Option or skip
                lengths.push(0);
            }
            other => {
                return Err(PolarsError::Other(
                    format!("Expected list or null in col0 at row {}, found {:?}", i, other).into(),
                ));
            }
        }
    }

    Ok(lengths)
}

