use itertools::izip;

/// For each i, find j such that var1[i][j] == var0[i].
/// Returns a Vec<Option<usize>> (None if no match for that row).
///
/// Example:
/// let var0 = vec![1, 2, 3];
/// let var1 = vec![vec![0,1,2], vec![2,1,3], vec![3,2,1]];
/// let idxs = match_indices(&var0, &var1).unwrap();
/// assert_eq!(idxs, vec![Some(1), Some(0), Some(0)]);
pub fn match_indices<T: PartialEq>(var0: &[T], var1: &[Vec<T>]) -> Result<Vec<Option<usize>>, &'static str> {
    if var0.len() != var1.len() {
        return Err("length mismatch between var0 and var1");
    }

    let mut out = Vec::with_capacity(var0.len());
    for (val, row) in izip!(var0, var1) {
        out.push(row.iter().position(|x| x == val));
    }
    Ok(out)
}

