use polars::prelude::*;
use std::collections::HashSet;

/// Count distinct combinations of values for the specified columns in `df`.
///
/// # Arguments
/// * `df`   - reference to a Polars DataFrame
/// * `cols` - slice of column names whose combinations we want to count
///
/// # Returns
/// * `PolarsResult<usize>` - number of distinct combinations, or an error if a column is missing
///
/// Example:
/// let n = count_distinct_combinations(&df, &["col1", "col2"])?;
pub fn count_distinct_combinations(df: &DataFrame, cols: &[&str]) -> PolarsResult<usize> {
    // Gather references to the requested Series (fails early if a column missing)
    let series_refs: Vec<&Series> = cols
        .iter()
        .map(|&name| df.column(name))
        .collect::<PolarsResult<Vec<_>>>()?;

    let height = df.height();
    let mut seen: HashSet<String> = HashSet::with_capacity(height);

    // Use a non-printable delimiter to reduce accidental collisions when joining values
    const DELIM: char = '\x1F';

    for row_idx in 0..height {
        // Build a compact string key for this row across the chosen columns
        let mut key = String::new();
        for (i, s) in series_refs.iter().enumerate() {
            if i > 0 {
                key.push(DELIM);
            }
            // `get` returns an AnyValue; format it to a string
            let v = s.get(row_idx);
            // Use Display formatting (handles Null, numbers, strings, etc.)
            key.push_str(&format!("{}", v));
        }
        seen.insert(key);
    }

    Ok(seen.len())
}

