use itertools::izip;
use std::ops::Add;

/// Append element-wise sums of two sequences of 2-element tuples into `out`.
/// Iteration stops when either input sequence is exhausted (shortest wins).
pub fn append_elementwise_sum<T, A, B>(a: A, b: B, out: &mut Vec<(T, T)>)
where
    A: IntoIterator<Item = (T, T)>,
    B: IntoIterator<Item = (T, T)>,
    T: Add<Output = T> + Copy,
{
    for ((x1, y1), (x2, y2)) in izip!(a, b) {
        out.push((x1 + x2, y1 + y2));
    }
}

