    let seq1 = vec![(1, 2), (3, 4), (5, 6)];
    let seq2 = vec![(10, 20), (30, 40)]; // shorter: only two pairs
    let mut out = Vec::new();

    append_elementwise_sum(seq1, seq2, &mut out);

    // out contains sums for the first two pairs; third pair is ignored because seq2 is shorter
    assert_eq!(out, vec![(11, 22), (33, 44)]);
    println!("{:?}", out);
