use hashbrown::HashSet;
use std::hash::Hash;

/// Return all indices i in `seq0` where `seq0[i]` is also present in `seq1`.
///
/// Both sequences can contain duplicates; every index in `seq0` whose element is
/// a member of `seq1` will be included in the output. Time complexity is
/// roughly O(n0 + n1) on average due to hash-set membership checks.
pub fn common_indices<T>(seq0: &[T], seq1: &[T]) -> Vec<usize>
where
    T: Eq + Hash,
{
