    let set: HashSet<&T> = seq1.iter().collect();

    // For each element in seq0, keep the index if the element is in the set.
    seq0
        .iter()
        .enumerate()
        .filter_map(|(i, v)| if set.contains(v) { Some(i) } else { None })
        .collect()
}

